import { GoogleGenAI } from "@google/genai";

export const getTroubleshootingAdvice = async (issue: string, context?: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are the 'SatExpert Tactical Intelligence Agent' (STIA).
    You work for a high-stakes global satellite security firm.
    MISSION_OBJECTIVE: Provide technical, field-ready SatCom intelligence.

    CURRENT_ENVIRONMENT:
    - LATITUDE: ${context?.lat ?? 'N/A'}
    - LONGITUDE: ${context?.lng ?? 'N/A'}
    - TARGET_ASSET: ${context?.satName ?? 'N/A'}
    - DEFCON_STATUS: ${context?.defcon ?? 5}

    TONE: Professional, concise, military-grade technical depth. Use codes like [ROOT_CAUSE], [FIELD_RESOLUTION], and [STEALTH_ADVICE].

    SPECIAL_CAPABILITIES:
    - If user mentions interference, use Google Search for regional solar flares, space weather, or local signal jamming news.
    - If user mentions ground stations, search for regional teleports or fiber landing points.
    - If DEFCON < 3, suggest aggressive carrier-shielding and modem-hardening.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: "USER_COMMAND: " + issue,
      config: {
        systemInstruction,
        tools: [{ googleSearch: {} }]
      },
    });

    let output = response.text || "";

    // Process and format references
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0) {
      output += "\n\n[TACTICAL_SOURCES_IDENTIFIED]:\n";
      chunks.forEach((chunk: any) => {
        if (chunk.web) output += `- ${chunk.web.title}: ${chunk.web.uri}\n`;
      });
    }

    return output;
  } catch (error) {
    console.error("STIA_SYSTEM_ERROR", error);
    return "SYSTEM_HALT: COMM_TIMEOUT. Verify API uplink.";
  }
};

import * as React from 'react';
import { useState } from 'react';
import { GoogleGenAI } from "@google/genai";

interface Props {
  userLoc: { lat: number, lng: number };
  selectedSatName: string;
}

export const SecurityTools: React.FC<Props> = ({ userLoc, selectedSatName }) => {
  const [activeTab, setActiveTab] = useState<string>('overview');
  const [outputs, setOutputs] = useState<Record<string, string>>({});
  const [intelLoading, setIntelLoading] = useState(false);

  const fetchThreatIntel = async (hardware: string) => {
    if (!hardware) return;
    setIntelLoading(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const systemInstruction = "You are a senior satellite security researcher. Provide technical briefs on hardware vulnerabilities, CVEs, and hardening steps.";
      const prompt = `Provide a professional technical security brief for VSAT hardware: ${hardware}. Search for latest CVEs, default credentials, and hardening guides.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction,
          tools: [{ googleSearch: {} }] 
        }
      });

      let content = response.text || "No intel found.";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const links = chunks.map((c: any) => c.web ? `- [${c.web.title}](${c.web.uri})` : '').filter(Boolean).join('\n');
        if (links) content += "\n\n[INTEL_SOURCES]:\n" + links;
      }
      setOutputs(prev => ({ ...prev, intel: content }));
    } catch (e) {
      setOutputs(prev => ({ ...prev, intel: 'Error querying database.' }));
    } finally {
      setIntelLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="mb-2">
        <h2 className="text-2xl font-bold flex items-center text-white uppercase tracking-tight">
          <span className="mr-3">🛡️</span> Security <span className="text-cyan-400 ml-2">Intelligence</span>
        </h2>
      </header>

      <div className="flex flex-wrap gap-2 border-b border-slate-800 pb-px">
        {['overview', 'attack', 'intel', 'detection', 'hardening'].map((id) => (
          <button
            key={id}
            onClick={() => setActiveTab(id)}
            className={`px-4 py-2 text-[10px] font-bold uppercase tracking-widest transition-all border-b-2 ${
              activeTab === id ? 'border-cyan-500 text-cyan-400 bg-cyan-500/5' : 'border-transparent text-slate-500 hover:text-slate-300'
            }`}
          >
            {id}
          </button>
        ))}
      </div>

      <div className="py-4">
        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="glass p-6 rounded-2xl hover:border-cyan-500 transition-all cursor-pointer" onClick={() => setActiveTab('attack')}>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Electronic Warfare</h3>
              <p className="text-xs text-slate-400">Simulation scripts for jamming/spoofing research.</p>
            </div>
            <div className="glass p-6 rounded-2xl hover:border-cyan-500 transition-all cursor-pointer" onClick={() => setActiveTab('intel')}>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Asset Intel</h3>
              <p className="text-xs text-slate-400">CVE database and firmware vulnerability lookup.</p>
            </div>
          </div>
        )}

        {activeTab === 'intel' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-2xl border-slate-800">
              <input 
                id="hw-search"
                placeholder="Enter Hardware (e.g. iDirect Evolution)" 
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-white outline-none mb-4"
              />
              <button 
                onClick={() => fetchThreatIntel((document.getElementById('hw-search') as HTMLInputElement).value)}
                className="bg-cyan-600 hover:bg-cyan-500 text-slate-950 font-bold px-6 py-2 rounded-xl text-xs transition-all w-full"
              >
                {intelLoading ? 'SYNCHRONIZING...' : 'SCAN INTEL'}
              </button>
            </div>
            {outputs.intel && (
              <pre className="bg-slate-950 p-6 rounded-2xl border border-slate-800 text-cyan-400 text-[11px] font-mono overflow-auto max-h-[500px] whitespace-pre-wrap">
                {outputs.intel}
              </pre>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Coordinates, Satellite } from '../types.ts';
import { COMMON_SATELLITES } from '../constants.ts';

interface Props {
  loc: Coordinates;
  sat: Satellite;
  onLocChange: (loc: Coordinates) => void;
  onSatChange: (sat: Satellite) => void;
}

export const TacticalHUD: React.FC<Props> = ({ loc, sat, onLocChange, onSatChange }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const filteredSatellites = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return COMMON_SATELLITES;
    return COMMON_SATELLITES.filter(
      s => s.name.toLowerCase().includes(query) || 
           s.orbitalSlot.toLowerCase().includes(query)
    );
  }, [searchQuery]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (s: Satellite) => {
    onSatChange(s);
    setSearchQuery('');
    setIsOpen(false);
  };

  return (
    <div className="glass rounded-2xl p-6 border-slate-800 relative z-50">
      <div className="space-y-4">
        <div className="relative" ref={dropdownRef}>
          <label className="block text-[9px] font-bold text-slate-500 uppercase mb-1 tracking-widest">
            Target Acquisition / Search
          </label>

          <div className="relative">
            <input
              type="text"
              placeholder={isOpen ? "ENTER SATELLITE NAME OR SLOT..." : sat.name}
              className={`w-full bg-slate-950 border ${isOpen ? 'border-cyan-500 shadow-[0_0_10px_rgba(34,211,238,0.2)]' : 'border-slate-800'} rounded-lg p-2.5 pl-9 text-xs text-white outline-none transition-all mono placeholder:text-slate-600`}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setIsOpen(true);
              }}
              onFocus={() => setIsOpen(true)}
            />
            <div className="absolute left-3 top-1/2 -translate-y-1/2">
              <svg className={`w-4 h-4 ${isOpen ? 'text-cyan-400' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
            {!isOpen && (
              <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center space-x-2 pointer-events-none">
                <span className="text-[10px] text-cyan-500 font-bold mono">{sat.orbitalSlot}</span>
                <svg className="w-3 h-3 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                </svg>
              </div>
            )}
          </div>

          {isOpen && (
            <div className="absolute mt-2 w-full glass bg-slate-950/95 border border-cyan-500/30 rounded-xl shadow-2xl overflow-hidden max-h-[300px] flex flex-col z-[100]">
              <div className="bg-cyan-500/5 px-4 py-2 border-b border-slate-800/50">
                <span className="text-[8px] font-bold text-cyan-400 uppercase tracking-widest">Results Found: {filteredSatellites.length}</span>
              </div>
              <div className="overflow-y-auto scrollbar-hide py-1">
                {filteredSatellites.length > 0 ? (
                  filteredSatellites.map((s) => (
                    <button
                      key={s.id}
                      onClick={() => handleSelect(s)}
                      className={`w-full text-left px-4 py-3 hover:bg-cyan-500/10 transition-colors flex items-center justify-between group border-b border-slate-900/50 last:border-none ${s.id === sat.id ? 'bg-cyan-500/5' : ''}`}
                    >
                      <div className="flex flex-col">
                        <span className={`text-[11px] font-bold tracking-wide ${s.id === sat.id ? 'text-cyan-400' : 'text-slate-300 group-hover:text-cyan-200'}`}>{s.name}</span>
                        <span className="text-[9px] text-slate-500 mono group-hover:text-slate-400">{s.operator || 'UNKNOWN OPERATOR'}</span>
                      </div>
                      <div className="flex flex-col items-end">
                        <span className="text-[10px] text-cyan-500 font-mono font-bold tracking-tighter">{s.orbitalSlot}</span>
                        {s.id === sat.id && <span className="text-[8px] text-cyan-400/50 font-bold uppercase tracking-tighter">Current Target</span>}
                      </div>
                    </button>
                  ))
                ) : (
                  <div className="px-4 py-8 text-center">
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">No matching assets found</p>
                    <p className="text-[8px] text-slate-700 mono mt-1">VERIFY ORBITAL_PARAMETERS</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        <div className="grid grid-cols-2 gap-3 mt-4">
           <div className="group">
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-1 tracking-widest group-hover:text-cyan-500 transition-colors">Deployment Lat</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  className="w-full bg-slate-950 p-2.5 text-xs rounded-lg border border-slate-800 text-cyan-400 focus:border-cyan-500/50 outline-none mono transition-all" 
                  value={loc.lat} 
                  onChange={e => onLocChange({...loc, lat: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-700 font-bold">N/S</span>
              </div>
           </div>
           <div className="group">
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-1 tracking-widest group-hover:text-cyan-500 transition-colors">Deployment Lng</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  className="w-full bg-slate-950 p-2.5 text-xs rounded-lg border border-slate-800 text-cyan-400 focus:border-cyan-500/50 outline-none mono transition-all" 
                  value={loc.lng} 
                  onChange={e => onLocChange({...loc, lng: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-700 font-bold">E/W</span>
              </div>
           </div>
        </div>

        <div className="flex items-center justify-between pt-2 border-t border-slate-800/50">
          <div className="flex space-x-1">
            <div className="w-1.5 h-1.5 rounded-full bg-cyan-500 shadow-[0_0_5px_rgba(34,211,238,0.5)]"></div>
            <div className="w-1.5 h-1.5 rounded-full bg-slate-800"></div>
            <div className="w-1.5 h-1.5 rounded-full bg-slate-800"></div>
          </div>
          <span className="text-[8px] text-slate-600 font-bold uppercase tracking-widest">Orbital Tracking: Enabled</span>
        </div>
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useEffect } from 'react';
import { Layout } from './components/Layout.tsx';
import { LookAngleCard } from './components/LookAngleCard.tsx';
import { AITechnician } from './components/AITechnician.tsx';
import { SecurityTools } from './components/SecurityTools.tsx';
import { LinkBudgetCalculator } from './components/LinkBudgetCalculator.tsx';
import { SignalVisualizer } from './components/SignalVisualizer.tsx';
import { TacticalHUD } from './components/TacticalHUD.tsx';
import { RSSReader } from './components/RSSReader.tsx';
import { Coordinates, Satellite, LookAngles } from './types.ts';
import { COMMON_SATELLITES } from './constants.ts';
import { calculateLookAngles } from './utils/geoUtils.ts';

type MainView = 'tactical' | 'intelligence' | 'calculations' | 'news';

const STORAGE_KEY = 'satexpert_tactical_v5';

export const App: React.FC = () => {
  const [userLoc, setUserLoc] = useState<Coordinates>({ lat: 51.5074, lng: -0.1278 });
  const [selectedSat, setSelectedSat] = useState<Satellite>(COMMON_SATELLITES[0]);
  const [lookAngles, setLookAngles] = useState<LookAngles | null>(null);
  const [view, setView] = useState<MainView>('tactical');
  const [defcon, setDefcon] = useState<number>(5);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.loc) setUserLoc(parsed.loc);
      if (parsed.satId) {
        const sat = COMMON_SATELLITES.find(s => s.id === parsed.satId);
        if (sat) setSelectedSat(sat);
      }
      if (parsed.defcon) setDefcon(parsed.defcon);
    }
  }, []);

  useEffect(() => {
    const angles = calculateLookAngles(userLoc, selectedSat.longitude);
    setLookAngles(angles);
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ loc: userLoc, satId: selectedSat.id, defcon }));
  }, [userLoc, selectedSat, defcon]);

  const defconColors: Record<number, string> = {
    5: 'text-blue-400 border-blue-500/30 shadow-blue-500/5',
    4: 'text-green-400 border-green-500/30 shadow-green-500/5',
    3: 'text-yellow-400 border-yellow-500/30 shadow-yellow-500/5',
    2: 'text-orange-400 border-orange-500/30 shadow-orange-500/5',
    1: 'text-red-500 border-red-500/50 shadow-red-500/20'
  };

  const defconLabels: Record<number, string> = {
    5: 'FADE OUT // NORMAL READINESS',
    4: 'DOUBLE TAKE // INCREASED INTELLIGENCE',
    3: 'ROUND HOUSE // FORCE MOBILIZATION',
    2: 'FAST PACE // MAXIMUM READINESS',
    1: 'COCKED PISTOL // COMBAT IMMINENT'
  };

  const activeDefconColor = defconColors[defcon].split(' ')[0];

  return (
    <Layout>
      <div className={`flex flex-col space-y-6 max-w-7xl mx-auto pb-12 transition-all duration-1000 ${defcon === 1 ? 'brightness-[1.1]' : ''}`}>

        {/* TOP STATUS BAR */}
        <div className={`flex flex-col md:flex-row items-center justify-between gap-4 glass p-4 rounded-2xl border-slate-800 shadow-2xl relative overflow-hidden ${defcon === 1 ? 'defcon-alert' : ''}`}>
          <div className="scanline"></div>
          <div className="flex items-center space-x-6 z-20">
            <div className="flex flex-col">
              <span className="text-[10px] font-bold text-cyan-500 uppercase tracking-[0.2em] mb-1">Mission Module</span>
              <div className="flex space-x-1 bg-slate-950/50 p-1 rounded-lg border border-slate-800">
                {(['tactical', 'intelligence', 'calculations', 'news'] as MainView[]).map((v) => (
                  <button
                    key={v}
                    onClick={() => setView(v)}
                    className={`px-4 py-1.5 rounded text-[9px] font-bold uppercase tracking-widest transition-all ${
                      view === v 
                        ? 'bg-cyan-500 text-slate-950 shadow-lg' 
                        : 'text-slate-500 hover:text-cyan-400'
                    }`}
                  >
                    {v}
                  </button>
                ))}
              </div>
            </div>
            <div className="h-10 w-px bg-slate-800 hidden md:block"></div>
            <div className="flex flex-col">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Threat Protocol</span>
              <div className="flex space-x-2">
                {[5, 4, 3, 2, 1].map(lvl => (
                  <button 
                    key={lvl}
                    onClick={() => setDefcon(lvl)}
                    className={`w-7 h-7 rounded flex items-center justify-center text-[10px] font-bold transition-all border ${
                      defcon === lvl 
                        ? `bg-opacity-20 ${defconColors[lvl].split(' ').slice(0,2).join(' ')} bg-current` 
                        : 'bg-slate-900 border-slate-800 text-slate-600'
                    }`}
                  >
                    {lvl}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="flex items-center space-x-6 z-20">
            <div className="text-right">
              <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Global Uplink</p>
              <p className={`text-xs font-bold mono ${defcon === 1 ? 'text-red-500' : 'text-green-400'}`}>
                {defcon === 1 ? 'CRITICAL_JAMMING_DETECTED' : 'ENCRYPTED // LINK ACTIVE'}
              </p>
            </div>
            <div className="flex -space-x-2">
              <div className={`w-9 h-9 rounded-full border-2 border-slate-800 bg-slate-900 flex items-center justify-center ${defcon === 1 ? 'border-red-500 animate-pulse' : ''}`}>
                <span className="text-[9px] font-bold text-cyan-500">EW</span>
              </div>
              <div className="w-9 h-9 rounded-full border-2 border-slate-800 bg-slate-900 flex items-center justify-center">
                <span className="text-[9px] font-bold text-amber-500">SIG</span>
              </div>
            </div>
          </div>
        </div>

        {/* PROMINENT DEFCON DISPLAY */}
        <div className={`glass p-6 rounded-2xl border-2 transition-all duration-500 flex flex-col md:flex-row items-center justify-between overflow-hidden relative ${defconColors[defcon]}`}>
           {defcon === 1 && <div className="absolute inset-0 bg-red-600/5 animate-pulse pointer-events-none"></div>}
           <div className="flex items-center space-x-8 z-10">
              <div className="flex flex-col items-center justify-center">
                <span className="text-[10px] font-black uppercase tracking-[0.5em] opacity-60 mb-1">System State</span>
                <div className="text-6xl font-black mono leading-none tracking-tighter">
                  DEFCON <span className="underline decoration-4 underline-offset-8">{defcon}</span>
                </div>
              </div>
              <div className="h-16 w-px bg-current opacity-20 hidden md:block"></div>
              <div className="flex flex-col">
                <span className="text-[11px] font-bold uppercase tracking-[0.3em] opacity-70 mb-1">Authorization Protocol</span>
                <div className="text-xl md:text-2xl font-bold tracking-tight uppercase">
                  {defconLabels[defcon]}
                </div>
                <div className="flex items-center mt-2 space-x-4">
                  <div className="flex items-center space-x-1">
                    <div className={`w-2 h-2 rounded-full bg-current ${defcon <= 2 ? 'animate-ping' : ''}`}></div>
                    <span className="text-[10px] font-bold mono uppercase opacity-80">Link_{defcon === 1 ? 'SECURED_HARDENED' : 'ENCRYPTED'}</span>
                  </div>
                  <div className="text-[10px] font-bold mono uppercase opacity-50">NODE_ID: 0x{((defcon * 7234) % 65535).toString(16).toUpperCase()}</div>
                </div>
              </div>
           </div>
           <div className="mt-6 md:mt-0 flex space-x-2 z-10">
              {Array.from({length: 5}).map((_, i) => (
                <div 
                  key={i} 
                  className={`h-12 w-3 rounded-sm transition-all duration-300 ${5-i <= defcon ? 'bg-current opacity-20' : 'bg-current shadow-[0_0_15px_rgba(var(--current-rgb),0.5)]'}`}
                />
              ))}
           </div>
        </div>

        <div className="min-h-[70vh]">
          {view === 'tactical' && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
              <div className="lg:col-span-4 space-y-6">
                <TacticalHUD 
                  loc={userLoc} 
                  sat={selectedSat} 
                  onLocChange={setUserLoc} 
                  onSatChange={setSelectedSat}
                />
                {lookAngles && <LookAngleCard angles={lookAngles} satellite={selectedSat} />}
                <SignalVisualizer quality={lookAngles?.elevation && lookAngles.elevation > 0 ? (defcon === 1 ? 42 : 88) : 0} />
              </div>
              <div className="lg:col-span-8">
                <AITechnician 
                  context={{ 
                    lat: userLoc.lat, 
                    lng: userLoc.lng, 
                    satName: selectedSat.name,
                    defcon: defcon 
                  }} 
                />
              </div>
            </div>
          )}

          {view === 'intelligence' && (
            <div className="animate-in zoom-in-95 duration-500">
              <SecurityTools userLoc={userLoc} selectedSatName={selectedSat.name} />
            </div>
          )}

          {view === 'calculations' && lookAngles && (
            <div className="animate-in fade-in duration-500">
              <LinkBudgetCalculator distance={lookAngles.distance} />
            </div>
          )}

          {view === 'news' && (
            <div className="animate-in slide-in-from-right-4 duration-500">
              <RSSReader />
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
};

export default App;

import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";

interface Props {
  userLoc: { lat: number, lng: number };
  selectedSatName: string;
}

export const SecurityTools: React.FC<Props> = ({ userLoc, selectedSatName }) => {
  const [activeTab, setActiveTab] = useState<string>('overview');
  const [outputs, setOutputs] = useState<Record<string, string>>({});
  const [intelLoading, setIntelLoading] = useState(false);

  // Attack States
  const [isJamming, setIsJamming] = useState(false);
  const [jammingPower, setJammingPower] = useState(50);
  const [bruteForceLog, setBruteForceLog] = useState<string[]>([]);
  const [isBruteForcing, setIsBruteForcing] = useState(false);
  const [spoofFrame, setSpoofFrame] = useState('');

