import * as React from 'react';
import { useEffect, useRef } from 'react';

interface Props {
  quality: number; 
  isJamming?: boolean;
  jammingPower?: number;
}

export const SignalVisualizer: React.FC<Props> = ({ quality, isJamming = false, jammingPower = 0 }) => {
  const spectrumRef = useRef<HTMLCanvasElement>(null);
  const constellationRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const specCtx = spectrumRef.current?.getContext('2d');
    const constCtx = constellationRef.current?.getContext('2d');
    if (!specCtx || !constCtx) return;

    let frame = 0;
    const animate = () => {
      frame++;

      // Clear
      specCtx.clearRect(0, 0, 400, 150);

      // Add a slight jitter to the entire coordinate system if jamming is extreme
      specCtx.save();
      if (isJamming && jammingPower > 80 && Math.random() > 0.9) {
        specCtx.translate((Math.random() - 0.5) * 4, (Math.random() - 0.5) * 4);
      }

      // Base Noise Floor
      specCtx.strokeStyle = 'rgba(51, 65, 85, 0.4)';
      specCtx.lineWidth = 1;
      specCtx.beginPath();
      for (let i = 0; i < 400; i++) {
        const y = 135 + (Math.random() * 4);
        if (i === 0) specCtx.moveTo(i, y); else specCtx.lineTo(i, y);
      }
      specCtx.stroke();

      // Jamming Noise Floor (If Active)
      if (isJamming) {
        specCtx.strokeStyle = `rgba(239, 68, 68, ${0.4 + (jammingPower / 200)})`;
        specCtx.lineWidth = 1;
        specCtx.beginPath();
        for (let i = 0; i < 400; i++) {
          const jammingLevel = (jammingPower / 100) * 80; // More aggressive
          const y = 135 - (Math.random() * jammingLevel);
          if (i === 0) specCtx.moveTo(i, y); else specCtx.lineTo(i, y);
        }
        specCtx.stroke();
      }

      // Main Signal
      specCtx.strokeStyle = isJamming ? '#ef4444' : '#22d3ee';
      specCtx.lineWidth = 2;
      specCtx.beginPath();
      for (let i = 0; i < 400; i++) {
        const distToCenter = Math.abs(200 - i);
        // Degrade quality if jamming
        const effectiveQuality = isJamming ? Math.max(0, quality - (jammingPower * 1.5)) : quality;

        let signal = distToCenter < 60 ? Math.pow(60 - distToCenter, 1.4) * (effectiveQuality / 100) : 0;

        // Add extreme jitter to the signal peak if jamming
        if (isJamming && distToCenter < 20) {
           signal += (Math.random() - 0.5) * (jammingPower / 10);
        }

        const y = 135 - (signal + Math.random() * 2);
        if (i === 0) specCtx.moveTo(i, y); else specCtx.lineTo(i, y);
      }
      specCtx.stroke();

      // Anomaly Visuals
      if ((quality > 0 && quality < 90 && frame % 200 < 50) || isJamming) {
        specCtx.strokeStyle = '#ef4444';
        specCtx.lineWidth = 1;
        specCtx.beginPath();
        const anomalyX = isJamming ? 200 + (Math.sin(frame/5) * (jammingPower * 2)) : 280;
        specCtx.moveTo(anomalyX, 150); specCtx.lineTo(anomalyX, 20);
        specCtx.stroke();

        specCtx.fillStyle = '#ef4444';
        specCtx.font = 'bold 8px JetBrains Mono';
        const label = isJamming ? `JAM_LVL_${jammingPower}%` : "ANOMALY";
        specCtx.fillText(label, anomalyX + 5, 30 + (isJamming ? Math.random()*2 : 0));
      }

      specCtx.restore();

      // Constellation
      constCtx.clearRect(0, 0, 200, 200);
      constCtx.fillStyle = isJamming || quality < 30 ? '#ef4444' : '#22d3ee';
      const spread = isJamming ? (jammingPower / 2) : (100 - quality) / 5;
      for(let i=0; i<40; i++) {
        const quadrants = [[50, 50], [150, 50], [50, 150], [150, 150]];
        quadrants.forEach(([qx, qy]) => {
          constCtx.fillRect(qx + (Math.random()-0.5)*spread, qy + (Math.random()-0.5)*spread, 1.5, 1.5);
        });
      }

      requestAnimationFrame(animate);
    };

    const handle = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(handle);
  }, [quality, isJamming, jammingPower]);

  return (
    <div className={`glass p-4 rounded-2xl border-slate-800 transition-all ${isJamming ? 'border-red-500/30 bg-red-950/5 tactical-glow' : ''}`}>
      <div className="flex items-center justify-between mb-2">
        <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">Spectrum Engine</p>
        {isJamming && <span className="text-[8px] font-bold text-red-500 animate-pulse">EW_OVERRIDE_ACTIVE</span>}
      </div>
      <canvas ref={spectrumRef} width="400" height="150" className={`w-full h-32 bg-slate-950 rounded-xl mb-4 border border-slate-900 shadow-inner ${isJamming && jammingPower > 90 ? 'animate-pulse' : ''}`} />
      <div className="grid grid-cols-2 gap-4">
         <div className="relative">
            <canvas ref={constellationRef} width="200" height="200" className="w-full h-24 bg-slate-950 rounded-xl border border-slate-900" />
            <div className="absolute inset-0 flex items-center justify-center opacity-10 pointer-events-none">
              <div className="w-full h-px bg-slate-500"></div>
              <div className="h-full w-px bg-slate-500 absolute"></div>
            </div>
         </div>
         <div className={`bg-slate-900 p-2 rounded-xl flex flex-col items-center justify-center border ${isJamming ? 'border-red-900/50' : 'border-slate-800'}`}>
            <span className="text-[8px] font-bold text-slate-500 uppercase mb-1">Link Margin</span>
            <span className={`text-xl font-bold mono ${isJamming ? 'text-red-500' : 'text-cyan-400'}`}>
              {Math.max(0, (quality/10) - (isJamming ? jammingPower/10 : 0)).toFixed(1)} dB
            </span>
            <span className="text-[7px] text-slate-600 mono mt-1">LOCK_{isJamming ? 'CRITICAL' : (quality > 50 ? 'STABLE' : 'WEAK')}</span>
         </div>
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Coordinates, Satellite } from '../types.ts';
import { COMMON_SATELLITES } from '../constants.ts';

interface Props {
  loc: Coordinates;
  sat: Satellite;
  onLocChange: (loc: Coordinates) => void;
  onSatChange: (sat: Satellite) => void;
  isTracking?: boolean;
  onTrackingChange?: (val: boolean) => void;
}

export const TacticalHUD: React.FC<Props> = ({ 
  loc, sat, onLocChange, onSatChange, isTracking, onTrackingChange 
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [animateLabel, setAnimateLabel] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const filteredSatellites = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return COMMON_SATELLITES;
    return COMMON_SATELLITES.filter(
      s => s.name.toLowerCase().includes(query) || 
           s.orbitalSlot.toLowerCase().includes(query)
    );
  }, [searchQuery]);

  // Trigger animation when satellite changes
  useEffect(() => {
    setAnimateLabel(true);
    const timer = setTimeout(() => setAnimateLabel(false), 600);
    return () => clearTimeout(timer);
  }, [sat.id]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (s: Satellite) => {
    onSatChange(s);
    setSearchQuery('');
    setIsOpen(false);
  };

  return (
    <div className="glass rounded-2xl p-6 border-slate-800 relative z-50">
      <div className="space-y-4">
        <div className="relative" ref={dropdownRef}>
          <div className="flex items-center justify-between mb-1">
            <label className={`block text-[9px] font-bold uppercase tracking-widest transition-all duration-300 transform ${
              animateLabel 
                ? 'text-cyan-400 scale-105 drop-shadow-[0_0_8px_rgba(34,211,238,0.6)]' 
                : 'text-slate-500'
            }`}>
              Target Acquisition
            </label>
            <button 
              onClick={() => onTrackingChange?.(!isTracking)}
              className={`flex items-center space-x-1 px-2 py-0.5 rounded border transition-all ${isTracking ? 'bg-cyan-500/10 border-cyan-500 text-cyan-400' : 'bg-slate-900 border-slate-800 text-slate-600 hover:text-slate-400'}`}
            >
              <div className={`w-1.5 h-1.5 rounded-full ${isTracking ? 'bg-cyan-500 animate-pulse' : 'bg-slate-700'}`}></div>
              <span className="text-[8px] font-bold uppercase tracking-tighter">Live GPS</span>
            </button>
          </div>

          <div className="relative">
            <input
              type="text"
              placeholder={isOpen ? "ENTER SATELLITE NAME OR SLOT..." : sat.name}
              className={`w-full bg-slate-950 border ${isOpen ? 'border-cyan-500 shadow-[0_0_10px_rgba(34,211,238,0.2)]' : 'border-slate-800'} rounded-lg p-2.5 pl-9 text-xs text-white outline-none transition-all mono placeholder:text-slate-600`}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setIsOpen(true);
              }}
              onFocus={() => setIsOpen(true)}
            />
            <div className="absolute left-3 top-1/2 -translate-y-1/2">
              <svg className={`w-4 h-4 ${isOpen ? 'text-cyan-400' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
          </div>

          {isOpen && (
            <div className="absolute mt-2 w-full glass bg-slate-950/95 border border-cyan-500/30 rounded-xl shadow-2xl overflow-hidden max-h-[300px] flex flex-col z-[100]">
              <div className="bg-cyan-500/5 px-4 py-2 border-b border-slate-800/50">
                <span className="text-[8px] font-bold text-cyan-400 uppercase tracking-widest">Results Found: {filteredSatellites.length}</span>
              </div>
              <div className="overflow-y-auto scrollbar-hide py-1">
                {filteredSatellites.length > 0 ? (
                  filteredSatellites.map((s) => (
                    <button
                      key={s.id}
                      onClick={() => handleSelect(s)}
                      className={`w-full text-left px-4 py-3 hover:bg-cyan-500/10 transition-colors flex items-center justify-between group border-b border-slate-900/50 last:border-none ${s.id === sat.id ? 'bg-cyan-500/5' : ''}`}
                    >
                      <div className="flex flex-col">
                        <span className={`text-[11px] font-bold tracking-wide ${s.id === sat.id ? 'text-cyan-400' : 'text-slate-300 group-hover:text-cyan-200'}`}>{s.name}</span>
                        <span className="text-[9px] text-slate-500 mono group-hover:text-slate-400">{s.operator || 'UNKNOWN OPERATOR'}</span>
                      </div>
                      <div className="flex flex-col items-end">
                        <span className="text-[10px] text-cyan-500 font-mono font-bold tracking-tighter">{s.orbitalSlot}</span>
                      </div>
                    </button>
                  ))
                ) : (
                  <div className="px-4 py-8 text-center">
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">No matching assets found</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        <div className="grid grid-cols-2 gap-3 mt-4">
           <div className="group">
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-1 tracking-widest group-hover:text-cyan-500 transition-colors">Deployment Lat</label>
              <div className="relative">
                <input 
