            <div className={`w-1.5 h-1.5 rounded-full ${isTracking ? 'bg-cyan-500 shadow-[0_0_5px_rgba(34,211,238,0.5)] opacity-60 animate-pulse' : 'bg-slate-800'}`}></div>
            <div className={`w-1.5 h-1.5 rounded-full ${isTracking ? 'bg-cyan-500 shadow-[0_0_5px_rgba(34,211,238,0.5)] opacity-30 animate-pulse delay-75' : 'bg-slate-800'}`}></div>
