                          ? `bg-opacity-20 ${defconColors[lvl].split(' ').slice(0,2).join(' ')} bg-current` 
                          : 'bg-slate-900 border-slate-800 text-slate-600'
                      }`}
                    >
                      {lvl}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex items-center space-x-6 z-20">
              <div className="text-right">
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Global Uplink</p>
                <p className={`text-xs font-bold mono ${defcon === 1 || isJamming ? 'text-red-500' : 'text-green-400'}`}>
                  {isJamming ? 'ACTIVE_EW_INTERFERENCE' : (defcon === 1 ? 'CRITICAL_JAMMING_DETECTED' : 'ENCRYPTED // LINK ACTIVE')}
                </p>
              </div>
              <div className="flex -space-x-2">
                <button 
                  onClick={() => setIsTracking(!isTracking)}
                  className={`w-9 h-9 rounded-full border-2 bg-slate-900 flex items-center justify-center transition-all ${isTracking ? 'border-cyan-500 shadow-[0_0_10px_rgba(34,211,238,0.5)]' : 'border-slate-800 opacity-50'}`}
                  title={isTracking ? "GPS Tracking Active" : "Enable GPS Tracking"}
                >
                  <span className={`text-[9px] font-bold ${isTracking ? 'text-cyan-400 animate-pulse' : 'text-slate-500'}`}>GPS</span>
                </button>
                <div className={`w-9 h-9 rounded-full border-2 border-slate-800 bg-slate-900 flex items-center justify-center ${defcon === 1 || isJamming ? 'border-red-500 animate-pulse' : ''}`}>
                  <span className={`text-[9px] font-bold ${isJamming ? 'text-red-500' : 'text-cyan-500'}`}>EW</span>
                </div>
              </div>
            </div>
          </div>

          {/* PROMINENT DEFCON DISPLAY */}
          <div className={`glass p-6 rounded-2xl border-2 transition-all duration-500 flex flex-col md:flex-row items-center justify-between overflow-hidden relative ${isJamming ? 'text-red-500 border-red-500/50 shadow-red-500/20' : defconColors[defcon]}`}>
            {(defcon === 1 || isJamming) && <div className="absolute inset-0 bg-red-600/5 animate-pulse pointer-events-none"></div>}
            <div className="flex items-center space-x-8 z-10">
                <div className="flex flex-col items-center justify-center">
                  <span className="text-[10px] font-black uppercase tracking-[0.5em] opacity-60 mb-1">System State</span>
                  <div className="text-6xl font-black mono leading-none tracking-tighter">
                    {isJamming ? 'EW_ACT' : 'DEFCON'} <span className="underline decoration-4 underline-offset-8">{isJamming ? '!!!' : defcon}</span>
                  </div>
                </div>
                <div className="h-16 w-px bg-current opacity-20 hidden md:block"></div>
                <div className="flex flex-col">
                  <span className="text-[11px] font-bold uppercase tracking-[0.3em] opacity-70 mb-1">Authorization Protocol</span>
                  <div className="text-xl md:text-2xl font-bold tracking-tight uppercase">
                    {isJamming ? 'ELECTRONIC WARFARE IN PROGRESS' : defconLabels[defcon]}
                  </div>
                  <div className="flex items-center mt-2 space-x-4">
                    <div className="flex items-center space-x-1">
                      <div className={`w-2 h-2 rounded-full bg-current ${defcon <= 2 || isJamming ? 'animate-ping' : ''}`}></div>
                      <span className="text-[10px] font-bold mono uppercase opacity-80">Link_{isJamming ? 'JAMMING_LOCAL' : (defcon === 1 ? 'SECURED_HARDENED' : 'ENCRYPTED')}</span>
                    </div>
                    <div className="text-[10px] font-bold mono uppercase opacity-50">NODE_ID: 0x{((defcon * 7234) % 65535).toString(16).toUpperCase()}</div>
                  </div>
                </div>
            </div>
            <div className="mt-6 md:mt-0 flex space-x-2 z-10">
                {Array.from({length: 5}).map((_, i) => (
                  <div 
                    key={i} 
                    className={`h-12 w-3 rounded-sm transition-all duration-300 ${5-i <= (isJamming ? 1 : defcon) ? 'bg-current opacity-20' : 'bg-current shadow-[0_0_15px_rgba(var(--current-rgb),0.5)]'}`}
                  />
                ))}
            </div>
          </div>

          <div className="min-h-[70vh]">
            {view === 'tactical' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="lg:col-span-4 space-y-6">
                  <TacticalHUD 
                    loc={userLoc} 
                    sat={selectedSat} 
                    onLocChange={setUserLoc} 
                    onSatChange={setSelectedSat}
                    isTracking={isTracking}
                    onTrackingChange={setIsTracking}
                    isJamming={isJamming}
                    setIsJamming={setIsJamming}
                    jammingPower={jammingPower}
                    setJammingPower={setJammingPower}
                    weather={weather}
                    setWeather={setWeather}
                  />
                  <TacticalMap 
                    userLoc={userLoc} 
                    satellite={selectedSat} 
                    isTracking={isTracking}
                    onLocChange={setUserLoc}
                    onTrackingChange={setIsTracking}
                  />
                  {lookAngles && <LookAngleCard angles={lookAngles} satellite={selectedSat} />}
                  <SignalVisualizer 
                    quality={lookAngles?.elevation && lookAngles.elevation > 0 ? (defcon === 1 ? 42 : 88) : 0} 
                    isJamming={isJamming}
                    jammingPower={jammingPower}
                    rainFade={currentRainFade}
                  />
                </div>
                <div className="lg:col-span-8">
                  <AITechnician 
                    context={{ 
                      lat: userLoc.lat, 
                      lng: userLoc.lng, 
                      satName: selectedSat.name,
                      defcon: defcon 
                    }} 
                  />
                </div>
              </div>
            )}

            {view === 'intelligence' && (
              <div className="animate-in zoom-in-95 duration-500">
                <SecurityTools 
                  userLoc={userLoc} 
                  selectedSatName={selectedSat.name}
                  isJamming={isJamming}
                  setIsJamming={setIsJamming}
                  jammingPower={jammingPower}
                  setJammingPower={setJammingPower}
                  signalQuality={lookAngles?.elevation && lookAngles.elevation > 0 ? 88 : 0}
                />
              </div>
            )}

            {view === 'calculations' && lookAngles && (
              <div className="animate-in fade-in duration-500">
                <LinkBudgetCalculator distance={lookAngles.distance} externalRainFade={currentRainFade} />
              </div>
            )}

            {view === 'news' && (
              <div className="animate-in slide-in-from-right-4 duration-500">
                <RSSReader />
              </div>
            )}
          </div>
        </div>
      </Layout>
    </div>
  );
};

export default App;

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Coordinates, Satellite, SatelliteStatus, WeatherCondition } from '../types.ts';
import { COMMON_SATELLITES } from '../constants.ts';

interface Props {
  loc: Coordinates;
  sat: Satellite;
  onLocChange: (loc: Coordinates) => void;
  onSatChange: (sat: Satellite) => void;
  isTracking?: boolean;
  onTrackingChange?: (val: boolean) => void;
  // EW State
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  // Weather State
  weather: WeatherCondition;
  setWeather: (val: WeatherCondition) => void;
}

const StatusBadge: React.FC<{ status?: SatelliteStatus }> = ({ status }) => {
  const config = {
    active: { color: 'bg-green-500', label: 'ONLINE', pulse: true },
    offline: { color: 'bg-red-500', label: 'OFFLINE', pulse: false },
    maintenance: { color: 'bg-amber-500', label: 'MAINT', pulse: true },
    decommissioned: { color: 'bg-slate-600', label: 'EOL', pulse: false },
  }[status || 'active'];

  return (
    <div className="flex items-center space-x-1.5">
      <div className={`w-1.5 h-1.5 rounded-full ${config.color} ${config.pulse ? 'animate-pulse' : ''}`}></div>
      <span className={`text-[8px] font-bold tracking-tighter ${config.color.replace('bg-', 'text-')}`}>
        {config.label}
      </span>
    </div>
  );
};

export const TacticalHUD: React.FC<Props> = ({ 
  loc, sat, onLocChange, onSatChange, isTracking, onTrackingChange,
  isJamming, setIsJamming, jammingPower, setJammingPower,
  weather, setWeather
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [animateLabel, setAnimateLabel] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const filteredSatellites = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return COMMON_SATELLITES;
    return COMMON_SATELLITES.filter(
      s => s.name.toLowerCase().includes(query) || 
           s.orbitalSlot.toLowerCase().includes(query)
    );
  }, [searchQuery]);

  useEffect(() => {
    setAnimateLabel(true);
    const timer = setTimeout(() => setAnimateLabel(false), 600);
    return () => clearTimeout(timer);
  }, [sat.id]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (s: Satellite) => {
    onSatChange(s);
    setSearchQuery('');
    setIsOpen(false);
  };

  const weatherIcons = {
    CLEAR: '☀️',
    OVERCAST: '☁️',
    LIGHT_RAIN: '🌧️',
    HEAVY_STORM: '⛈️'
  };

  return (
    <div className="glass rounded-2xl p-6 border-slate-800 relative z-50">
      <div className="space-y-4">
        <div className="relative" ref={dropdownRef}>
          <div className="flex items-center justify-between mb-1">
            <label className={`block text-[9px] font-bold uppercase tracking-widest transition-all duration-300 transform ${
              animateLabel 
                ? 'text-cyan-400 scale-105 drop-shadow-[0_0_8px_rgba(34,211,238,0.6)]' 
                : 'text-slate-500'
            }`}>
              Target Acquisition
            </label>
            <button 
              onClick={() => onTrackingChange?.(!isTracking)}
              className={`flex items-center space-x-1 px-2 py-0.5 rounded border transition-all ${isTracking ? 'bg-cyan-500/10 border-cyan-500 text-cyan-400' : 'bg-slate-900 border-slate-800 text-slate-600 hover:text-slate-400'}`}
            >
              <div className={`w-1.5 h-1.5 rounded-full ${isTracking ? 'bg-cyan-500 animate-pulse' : 'bg-slate-700'}`}></div>
              <span className="text-[8px] font-bold uppercase tracking-tighter">Live GPS</span>
            </button>
          </div>

          <div className="relative">
            <input
              type="text"
              placeholder={isOpen ? "ENTER SATELLITE NAME OR SLOT..." : sat.name}
              className={`w-full bg-slate-950 border ${isOpen ? 'border-cyan-500 shadow-[0_0_10px_rgba(34,211,238,0.2)]' : 'border-slate-800'} rounded-lg p-2.5 pl-9 text-xs text-white outline-none transition-all mono placeholder:text-slate-600`}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setIsOpen(true);
              }}
              onFocus={() => setIsOpen(true)}
            />
            <div className="absolute left-3 top-1/2 -translate-y-1/2">
              <svg className={`w-4 h-4 ${isOpen ? 'text-cyan-400' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center">
               {!isOpen && <StatusBadge status={sat.status} />}
            </div>
          </div>

          {isOpen && (
            <div className="absolute mt-2 w-full glass bg-slate-950/95 border border-cyan-500/30 rounded-xl shadow-2xl overflow-hidden max-h-[300px] flex flex-col z-[100]">
              <div className="bg-cyan-500/5 px-4 py-2 border-b border-slate-800/50">
                <span className="text-[8px] font-bold text-cyan-400 uppercase tracking-widest">Results Found: {filteredSatellites.length}</span>
              </div>
              <div className="overflow-y-auto scrollbar-hide py-1">
                {filteredSatellites.length > 0 ? (
                  filteredSatellites.map((s) => (
                    <button
                      key={s.id}
                      onClick={() => handleSelect(s)}
                      className={`w-full text-left px-4 py-3 hover:bg-cyan-500/10 transition-colors flex items-center justify-between group border-b border-slate-900/50 last:border-none ${s.id === sat.id ? 'bg-cyan-500/5' : ''}`}
                    >
                      <div className="flex flex-col">
                        <div className="flex items-center space-x-2">
                           <span className={`text-[11px] font-bold tracking-wide ${s.id === sat.id ? 'text-cyan-400' : 'text-slate-300 group-hover:text-cyan-200'}`}>{s.name}</span>
                           <StatusBadge status={s.status} />
                        </div>
                        <span className="text-[9px] text-slate-500 mono group-hover:text-slate-400">{s.operator || 'UNKNOWN OPERATOR'}</span>
                      </div>
                      <div className="flex flex-col items-end">
                        <span className="text-[10px] text-cyan-500 font-mono font-bold tracking-tighter">{s.orbitalSlot}</span>
                      </div>
                    </button>
                  ))
                ) : (
                  <div className="px-4 py-8 text-center">
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">No matching assets found</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Asset Identity Block */}
        <div className="bg-slate-950/50 rounded-xl border border-slate-800/50 p-3 flex items-center justify-between animate-in fade-in slide-in-from-top-1 duration-300">
          <div className="flex flex-col">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Operator Authority</span>
            <span className="text-[10px] font-bold text-slate-200 mono truncate max-w-[120px]">
              {sat.operator || 'UNSPECIFIED'}
            </span>
          </div>
          <div className="h-8 w-px bg-slate-800/50 mx-2"></div>
          <div className="flex flex-col items-center px-2">
             <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Link State</span>
             <StatusBadge status={sat.status} />
          </div>
          <div className="h-8 w-px bg-slate-800/50 mx-2"></div>
          <div className="flex flex-col items-end text-right">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Orbital Slot</span>
            <div className="flex items-center space-x-2">
              <span className="text-[10px] font-bold text-cyan-400 mono">{sat.orbitalSlot}</span>
              <div className="w-1.5 h-1.5 bg-cyan-500/50 rounded-full animate-pulse"></div>
            </div>
          </div>
        </div>

        {/* Atmospheric Dynamics Block */}
        <div className="bg-slate-950/60 rounded-xl border border-slate-800 p-3 space-y-3 animate-in fade-in slide-in-from-top-1 duration-500">
          <div className="flex items-center justify-between">
             <span className="text-[8px] font-black text-cyan-500/80 uppercase tracking-[0.2em]">Atmospheric_Dynamics</span>
             <div className="flex items-center space-x-1">
                <span className="text-[7px] text-slate-600 mono uppercase tracking-tighter">SIM: Ka-BAND_RAIN_FADE</span>
             </div>
          </div>
          <div className="grid grid-cols-4 gap-1">
            {(['CLEAR', 'OVERCAST', 'LIGHT_RAIN', 'HEAVY_STORM'] as WeatherCondition[]).map((cond) => (
              <button 
                key={cond}
                onClick={() => setWeather(cond)}
                className={`flex flex-col items-center justify-center p-2 rounded-lg border transition-all ${
                  weather === cond 
                    ? 'bg-cyan-500/10 border-cyan-500 text-cyan-400 shadow-[0_0_10px_rgba(34,211,238,0.2)]' 
                    : 'bg-slate-900/50 border-slate-800 text-slate-600 hover:border-slate-700'
                }`}
              >
                <span className="text-sm mb-1">{weatherIcons[cond]}</span>
                <span className="text-[6px] font-bold uppercase tracking-tighter">{cond.replace('_', ' ')}</span>
              </button>
            ))}
          </div>
          <div className="flex justify-between items-center text-[8px] font-mono border-t border-slate-800/50 pt-2">
             <div className="flex flex-col">
               <span className="text-slate-500 uppercase">Attenuation</span>
               <span className={`${weather === 'HEAVY_STORM' ? 'text-red-500 animate-pulse' : 'text-cyan-400'}`}>
                 {weather === 'CLEAR' ? '0.5' : weather === 'OVERCAST' ? '1.8' : weather === 'LIGHT_RAIN' ? '4.5' : '12.0'} dB
               </span>
             </div>
             <div className="flex flex-col text-right">
               <span className="text-slate-500 uppercase">Humidity</span>
               <span className="text-slate-300">{weather === 'CLEAR' ? '12%' : weather === 'OVERCAST' ? '45%' : '88%'}</span>
             </div>
          </div>
        </div>

        {/* Electronic Warfare Override */}
        <div className={`rounded-xl border p-3 space-y-3 transition-all duration-300 ${isJamming ? 'bg-red-950/20 border-red-500/40 shadow-[0_0_15px_rgba(239,68,68,0.1)]' : 'bg-slate-950/40 border-slate-800'}`}>
          <div className="flex items-center justify-between">
            <div className="flex flex-col">
              <span className={`text-[8px] font-black uppercase tracking-[0.2em] ${isJamming ? 'text-red-500' : 'text-slate-500'}`}>EW_Signal_Override</span>
              <span className="text-[7px] text-slate-600 mono">MODE: RF_CONTINUOUS_WAVE</span>
            </div>
            <button 
              onClick={() => setIsJamming(!isJamming)}
              className={`px-3 py-1 rounded-md text-[9px] font-bold uppercase transition-all ${isJamming ? 'bg-red-600 text-white shadow-lg animate-pulse' : 'bg-slate-800 text-slate-500 hover:text-slate-300'}`}
            >
              {isJamming ? 'Engaged' : 'Standby'}
            </button>
          </div>

          <div className="space-y-2">
            <div className="flex items-center justify-between text-[8px] font-bold mono">
              <span className={isJamming ? 'text-red-400' : 'text-slate-600'}>INTENSITY: {jammingPower}%</span>
              <span className={isJamming ? 'text-red-400' : 'text-slate-600'}>SNR_LOSS: -{(jammingPower / 5).toFixed(1)} dB</span>
            </div>
            <input 
              type="range" 
              min="0" max="100" 
              value={jammingPower} 
              onChange={(e) => setJammingPower(parseInt(e.target.value))}
              className={`w-full h-1 rounded-lg appearance-none cursor-pointer transition-all ${isJamming ? 'bg-red-900/50 accent-red-500' : 'bg-slate-800 accent-slate-600'}`}
            />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3 mt-4">
           <div className="group">
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-1 tracking-widest group-hover:text-cyan-500 transition-colors">Deployment Lat</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  disabled={isTracking}
                  className={`w-full bg-slate-950 p-2.5 text-xs rounded-lg border text-cyan-400 outline-none mono transition-all ${isTracking ? 'border-cyan-500/30 opacity-50' : 'border-slate-800 focus:border-cyan-500/50'}`} 
                  value={loc.lat} 
                  onChange={e => onLocChange({...loc, lat: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-700 font-bold">N/S</span>
              </div>
           </div>
           <div className="group">
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-1 tracking-widest group-hover:text-cyan-500 transition-colors">Deployment Lng</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  disabled={isTracking}
                  className={`w-full bg-slate-950 p-2.5 text-xs rounded-lg border text-cyan-400 outline-none mono transition-all ${isTracking ? 'border-cyan-500/30 opacity-50' : 'border-slate-800 focus:border-cyan-500/50'}`} 
                  value={loc.lng} 
                  onChange={e => onLocChange({...loc, lng: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-700 font-bold">E/W</span>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useEffect } from 'react';
import { LinkBudgetParams, LinkBudgetResults } from '../types.ts';
import { calculateLinkBudget } from '../utils/geoUtils.ts';

interface Props {
  distance: number;
  externalRainFade?: number;
}

export const LinkBudgetCalculator: React.FC<Props> = ({ distance, externalRainFade }) => {
  const [params, setParams] = useState<LinkBudgetParams>({
    uplinkFreq: 14.25, downlinkFreq: 11.75, txPower: 5, antSize: 1.2, efficiency: 65, lnbNoiseTemp: 75, rainFade: externalRainFade || 2.5
  });
  const [results, setResults] = useState<LinkBudgetResults | null>(null);

  useEffect(() => {
    const activeRainFade = externalRainFade !== undefined ? externalRainFade : params.rainFade;
    setResults(calculateLinkBudget({...params, rainFade: activeRainFade}, distance));
  }, [params, distance, externalRainFade]);

  return (
    <div className="glass rounded-2xl border-slate-700 overflow-hidden flex flex-col md:flex-row">
      <div className="p-6 bg-slate-800 md:w-64 border-r border-slate-700 space-y-3">
        <h3 className="text-white font-bold text-xs uppercase tracking-widest mb-4">RF Config</h3>
        <div>
          <label className="block text-[9px] font-bold text-slate-500 uppercase">TX Power (dBW)</label>
          <input type="number" value={params.txPower} onChange={e => setParams({...params, txPower: parseFloat(e.target.value)})} className="w-full bg-slate-900 border border-slate-700 rounded p-1.5 text-xs text-cyan-400" />
        </div>
        <div>
          <label className="block text-[9px] font-bold text-slate-500 uppercase">Dish Size (m)</label>
          <input type="number" value={params.antSize} onChange={e => setParams({...params, antSize: parseFloat(e.target.value)})} className="w-full bg-slate-900 border border-slate-700 rounded p-1.5 text-xs text-cyan-400" />
        </div>
        {externalRainFade === undefined && (
          <div>
            <label className="block text-[9px] font-bold text-slate-500 uppercase">Rain Fade (dB)</label>
            <input type="number" value={params.rainFade} onChange={e => setParams({...params, rainFade: parseFloat(e.target.value)})} className="w-full bg-slate-900 border border-slate-700 rounded p-1.5 text-xs text-cyan-400" />
          </div>
        )}
      </div>
      <div className="flex-grow p-6 flex flex-col space-y-6">
        <div className="flex items-center justify-between">
           <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Link Performance Metrics</span>
           {externalRainFade !== undefined && (
             <span className="text-[8px] font-bold text-cyan-500 bg-cyan-500/10 px-2 py-0.5 rounded border border-cyan-500/20">LIVE_ATMOSPHERIC_SYNC</span>
           )}
        </div>
        <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">
          <div className="bg-slate-950/40 p-4 rounded-xl border border-slate-800">
