import * as React from 'react';
import { useEffect, useRef } from 'react';

interface Props {
  quality: number; 
  isJamming?: boolean;
  jammingPower?: number;
  rainFade?: number;
}

export const SignalVisualizer: React.FC<Props> = ({ quality, isJamming = false, jammingPower = 0, rainFade = 0 }) => {
  const spectrumRef = useRef<HTMLCanvasElement>(null);
  const constellationRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const specCtx = spectrumRef.current?.getContext('2d');
    const constCtx = constellationRef.current?.getContext('2d');
    if (!specCtx || !constCtx) return;

    let frame = 0;
    const animate = () => {
      frame++;

      // Clear
      specCtx.clearRect(0, 0, 400, 150);

      specCtx.save();
      if (isJamming && jammingPower > 80 && Math.random() > 0.9) {
        specCtx.translate((Math.random() - 0.5) * 4, (Math.random() - 0.5) * 4);
      }

      // Base Noise Floor
      specCtx.strokeStyle = 'rgba(51, 65, 85, 0.4)';
      specCtx.lineWidth = 1;
      specCtx.beginPath();
      for (let i = 0; i < 400; i++) {
        // Rain fade increases base noise floor jitter
        const rainJitter = (rainFade / 4);
        const y = 135 + (Math.random() * (4 + rainJitter));
        if (i === 0) specCtx.moveTo(i, y); else specCtx.lineTo(i, y);
      }
      specCtx.stroke();

      // Jamming Noise Floor
      if (isJamming) {
        specCtx.strokeStyle = `rgba(239, 68, 68, ${0.4 + (jammingPower / 200)})`;
        specCtx.lineWidth = 1;
        specCtx.beginPath();
        for (let i = 0; i < 400; i++) {
          const jammingLevel = (jammingPower / 100) * 80;
          const y = 135 - (Math.random() * jammingLevel);
          if (i === 0) specCtx.moveTo(i, y); else specCtx.lineTo(i, y);
        }
        specCtx.stroke();
      }

      // Main Signal
      specCtx.strokeStyle = isJamming ? '#ef4444' : (rainFade > 5 ? '#fbbf24' : '#22d3ee');
      specCtx.lineWidth = 2;
      specCtx.beginPath();
      for (let i = 0; i < 400; i++) {
        const distToCenter = Math.abs(200 - i);
        // Effective quality calculation including Rain Fade
        const effectiveQuality = Math.max(0, (isJamming ? quality - (jammingPower * 1.5) : quality) - (rainFade * 4));

        let signal = distToCenter < 60 ? Math.pow(60 - distToCenter, 1.4) * (effectiveQuality / 100) : 0;

        if (isJamming && distToCenter < 20) {
           signal += (Math.random() - 0.5) * (jammingPower / 10);
        }

        const y = 135 - (signal + Math.random() * 2);
        if (i === 0) specCtx.moveTo(i, y); else specCtx.lineTo(i, y);
      }
      specCtx.stroke();

      // Anomaly Visuals
      if ((quality > 0 && (quality < 90 || rainFade > 5) && frame % 200 < 50) || isJamming) {
        specCtx.strokeStyle = isJamming ? '#ef4444' : '#fbbf24';
        specCtx.lineWidth = 1;
        specCtx.beginPath();
        const anomalyX = isJamming ? 200 + (Math.sin(frame/5) * (jammingPower * 2)) : 280;
        specCtx.moveTo(anomalyX, 150); specCtx.lineTo(anomalyX, 20);
        specCtx.stroke();

        specCtx.fillStyle = isJamming ? '#ef4444' : '#fbbf24';
        specCtx.font = 'bold 8px JetBrains Mono';
        const label = isJamming ? `JAM_LVL_${jammingPower}%` : rainFade > 5 ? "RAIN_ATTENUATION" : "ANOMALY";
        specCtx.fillText(label, anomalyX + 5, 30 + (isJamming ? Math.random()*2 : 0));
      }

      specCtx.restore();

      // Constellation
      constCtx.clearRect(0, 0, 200, 200);
      constCtx.fillStyle = isJamming || (quality - (rainFade * 3)) < 30 ? '#ef4444' : (rainFade > 5 ? '#fbbf24' : '#22d3ee');
      const spread = isJamming ? (jammingPower / 2) : Math.max(1, (100 - (quality - (rainFade * 3))) / 4);
      for(let i=0; i<40; i++) {
        const quadrants = [[50, 50], [150, 50], [50, 150], [150, 150]];
        quadrants.forEach(([qx, qy]) => {
          constCtx.fillRect(qx + (Math.random()-0.5)*spread, qy + (Math.random()-0.5)*spread, 1.5, 1.5);
        });
      }

      requestAnimationFrame(animate);
    };

    const handle = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(handle);
  }, [quality, isJamming, jammingPower, rainFade]);

  return (
    <div className={`glass p-4 rounded-2xl border-slate-800 transition-all ${isJamming ? 'border-red-500/30 bg-red-950/5 tactical-glow' : ''}`}>
      <div className="flex items-center justify-between mb-2">
        <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">Spectrum Engine</p>
        <div className="flex space-x-2">
           {rainFade > 1 && <span className="text-[8px] font-bold text-amber-500">RAIN_FADE: {rainFade}dB</span>}
           {isJamming && <span className="text-[8px] font-bold text-red-500 animate-pulse">EW_OVERRIDE_ACTIVE</span>}
        </div>
      </div>
      <canvas ref={spectrumRef} width="400" height="150" className={`w-full h-32 bg-slate-950 rounded-xl mb-4 border border-slate-900 shadow-inner ${isJamming && jammingPower > 90 ? 'animate-pulse' : ''}`} />
      <div className="grid grid-cols-2 gap-4">
         <div className="relative">
            <canvas ref={constellationRef} width="200" height="200" className="w-full h-24 bg-slate-950 rounded-xl border border-slate-900" />
            <div className="absolute inset-0 flex items-center justify-center opacity-10 pointer-events-none">
              <div className="w-full h-px bg-slate-500"></div>
              <div className="h-full w-px bg-slate-500 absolute"></div>
            </div>
         </div>
         <div className={`bg-slate-900 p-2 rounded-xl flex flex-col items-center justify-center border ${isJamming ? 'border-red-900/50' : 'border-slate-800'}`}>
            <span className="text-[8px] font-bold text-slate-500 uppercase mb-1">Effective Margin</span>
            <span className={`text-xl font-bold mono ${isJamming || rainFade > 8 ? 'text-red-500' : (rainFade > 3 ? 'text-amber-500' : 'text-cyan-400')}`}>
              {Math.max(0, (quality/10) - (isJamming ? jammingPower/10 : 0) - (rainFade/2)).toFixed(1)} dB
            </span>
            <span className="text-[7px] text-slate-600 mono mt-1">LOCK_{isJamming || rainFade > 8 ? 'CRITICAL' : (quality > 50 ? 'STABLE' : 'WEAK')}</span>
         </div>
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Coordinates, Satellite, SatelliteStatus, WeatherCondition } from '../types.ts';
import { COMMON_SATELLITES } from '../constants.ts';

interface Props {
  loc: Coordinates;
  sat: Satellite;
  onLocChange: (loc: Coordinates) => void;
  onSatChange: (sat: Satellite) => void;
  isTracking?: boolean;
  onTrackingChange?: (val: boolean) => void;
  // EW State
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  // Weather State
  weather: WeatherCondition;
  setWeather: (val: WeatherCondition) => void;
}

const StatusBadge: React.FC<{ status?: SatelliteStatus }> = ({ status }) => {
  const config = {
    active: { color: 'bg-green-500', label: 'ONLINE', pulse: true },
    offline: { color: 'bg-red-500', label: 'OFFLINE', pulse: false },
    maintenance: { color: 'bg-amber-500', label: 'MAINT', pulse: true },
    decommissioned: { color: 'bg-slate-600', label: 'EOL', pulse: false },
  }[status || 'active'];

  return (
    <div className="flex items-center space-x-1.5">
      <div className={`w-1.5 h-1.5 rounded-full ${config.color} ${config.pulse ? 'animate-pulse' : ''}`}></div>
      <span className={`text-[8px] font-bold tracking-tighter ${config.color.replace('bg-', 'text-')}`}>
        {config.label}
      </span>
    </div>
  );
};

export const TacticalHUD: React.FC<Props> = ({ 
  loc, sat, onLocChange, onSatChange, isTracking, onTrackingChange,
  isJamming, setIsJamming, jammingPower, setJammingPower,
  weather, setWeather
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [animateLabel, setAnimateLabel] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const filteredSatellites = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return COMMON_SATELLITES;
    return COMMON_SATELLITES.filter(
      s => s.name.toLowerCase().includes(query) || 
           s.orbitalSlot.toLowerCase().includes(query)
    );
  }, [searchQuery]);

  useEffect(() => {
    setAnimateLabel(true);
    const timer = setTimeout(() => setAnimateLabel(false), 600);
    return () => clearTimeout(timer);
  }, [sat.id]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (s: Satellite) => {
    onSatChange(s);
    setSearchQuery('');
    setIsOpen(false);
  };

