import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { SignalVisualizer } from './SignalVisualizer.tsx';

interface Props {
  userLoc: { lat: number, lng: number };
  selectedSatName: string;
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  signalQuality: number;
  onBack?: () => void;
}

interface HardeningOption {
  id: string;
  label: string;
  description: string;
  enabled: boolean;
}

export const SecurityTools: React.FC<Props> = ({ 
  userLoc, 
  selectedSatName,
  isJamming,
  setIsJamming,
  jammingPower,
  setJammingPower,
  signalQuality,
  onBack
}) => {
  const [activeTab, setActiveTab] = useState<string>('overview');
  const [outputs, setOutputs] = useState<Record<string, string>>({});
  const [intelLoading, setIntelLoading] = useState(false);

  // Attack States (Local)
  const [bruteForceLog, setBruteForceLog] = useState<string[]>([]);
  const [isBruteForcing, setIsBruteForcing] = useState(false);
  const [spoofFrame, setSpoofFrame] = useState('');

  // New Attack States
  const [mitmTraffic, setMitmTraffic] = useState<string[]>([]);
  const [isMitmActive, setIsMitmActive] = useState(false);
  const [bgpLog, setBgpLog] = useState<string[]>([]);
  const [isBgpActive, setIsBgpActive] = useState(false);
  const [capturedPackets, setCapturedPackets] = useState<{id: string, data: string}[]>([]);

  // Hardening States - Expanded per technical requirements
  const [hardeningOptions, setHardeningOptions] = useState<HardeningOption[]>([
    { id: 'telnet', label: 'Disable Telnet', description: 'Terminate unencrypted legacy remote access port 23.', enabled: false },
    { id: 'ssh', label: 'Enable SSH v2', description: 'Enforce encrypted administrative access via RSA/ED25519 keys.', enabled: false },
    { id: 'encryption', label: 'Stronger Encryption', description: 'Upgrade air interface to AES-256 and enforce FIPS 140-2.', enabled: false },
    { id: 'firmware', label: 'Firmware Integrity', description: 'Enable secure boot and periodic cryptographic hash validation.', enabled: false },
    { id: 'ports', label: 'Disable Unused Ports', description: 'Seal non-essential logical ports (1-1024) and audit open services.', enabled: false },
    { id: 'rate-limiting', label: 'Implement Rate Limiting', description: 'Prevent DoS/DDoS by throttling excessive packet request rates on the management plane.', enabled: false },
    { id: 'firmware-mandatory', label: 'Mandatory Firmware Updates', description: 'Enforce automatic signed updates to patch zero-day vulnerabilities across the modem fleet.', enabled: false },
    { id: 'segmentation', label: 'Network Segmentation', description: 'Isolate management, telemetry, and user traffic into cryptographically distinct VLANs.', enabled: false },
  ]);

  const terminalRef = useRef<HTMLDivElement>(null);
  const mitmRef = useRef<HTMLDivElement>(null);
  const bgpRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (terminalRef.current) terminalRef.current.scrollTop = terminalRef.current.scrollHeight;
  }, [bruteForceLog]);

  useEffect(() => {
    if (mitmRef.current) mitmRef.current.scrollTop = mitmRef.current.scrollHeight;
  }, [mitmTraffic]);

  useEffect(() => {
    if (bgpRef.current) bgpRef.current.scrollTop = bgpRef.current.scrollHeight;
  }, [bgpLog]);

  // MITM Simulation
  useEffect(() => {
    let interval: number;
    if (isMitmActive) {
      const trafficSeeds = [
        "GET /api/v1/config HTTP/1.1 (Target: 10.0.4.1)",
        "DNS QUERY: update.satcom.id (From: 192.168.1.55)",
        "POST /auth/login (Payload: user=admin&pass=********)",
        "TCP SYN (From: 8.8.8.8 -> Target: 10.0.4.1)",
        "UDP STATUS_REPORT (From: Remote_Modem_99)",
      ];
      interval = window.setInterval(() => {
        setMitmTraffic(prev => [...prev.slice(-15), `[INTERCEPT] ${trafficSeeds[Math.floor(Math.random() * trafficSeeds.length)]}`]);
      }, 1500);
    }
    return () => clearInterval(interval);
  }, [isMitmActive]);

  const runBgpSimulation = () => {
    setIsBgpActive(true);
    setBgpLog(["[BGP] Initializing Routing Table Scan...", "[BGP] Current AS Path: 64496 -> 64511 -> 65510"]);
    setTimeout(() => {
      setBgpLog(prev => [...prev, "[!] ALERT: Unauthorized ASN 42200 announcing prefix 10.0.0.0/8", "[BGP] Injecting Malicious Route Leak..."]);
    }, 2000);
    setTimeout(() => {
      setBgpLog(prev => [...prev, "[SUCCESS] Traffic redirected to localized sinkhole (Node_Zero)."]);
    }, 4500);
  };

  const capturePacket = () => {
    const id = `PKT_${Math.floor(Math.random() * 9999).toString(16).toUpperCase()}`;
    const data = `CMD_MODEM_REBOOT_AUTH_${Math.random().toString(36).substring(7)}`;
    setCapturedPackets(prev => [{id, data}, ...prev.slice(0, 4)]);
  };

  const fetchThreatIntel = async (hardware: string) => {
    if (!hardware) return;
    setIntelLoading(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const systemInstruction = "You are a senior satellite security researcher. Provide technical briefs on hardware vulnerabilities, CVEs, and hardening steps.";
      const prompt = `Provide a professional technical security brief for VSAT hardware: ${hardware}. Search for latest CVEs, default credentials, and hardening guides.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction,
          tools: [{ googleSearch: {} }] 
        }
      });

      let content = response.text || "No intel found.";
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const links = chunks.map((c: any) => c.web ? `- [${c.web.title}](${c.web.uri})` : '').filter(Boolean).join('\n');
        if (links) content += "\n\n[INTEL_SOURCES]:\n" + links;
      }
      setOutputs(prev => ({ ...prev, intel: content }));
    } catch (e) {
      setOutputs(prev => ({ ...prev, intel: 'Error querying database.' }));
    } finally {
      setIntelLoading(false);
    }
  };

  const runBruteForce = () => {
    if (isBruteForcing) return;
    setIsBruteForcing(true);
    setBruteForceLog(["[INIT] Target: 192.168.100.1 (Modem Portal)", "[SCAN] Port 80, 443, 22 detected..."]);

    const commonPass = ["admin", "password", "iDirect123", "root", "123456", "sysadmin", "HughesNet!"];
    let i = 0;
    const interval = window.setInterval(() => {
      if (i >= commonPass.length) {
