import * as React from 'react';
import { useState, useEffect } from 'react';

interface RSSItem {
  title: string;
  link: string;
  source: string;
}

const FALLBACK_INTEL: RSSItem[] = [
  { title: "ALERT: Solar storm activity affecting Ku-band performance in Northern Europe.", link: "#", source: "LOCAL_INTEL" },
  { title: "INTEL: New firmware vulnerabilities discovered in legacy HughesNet modems.", link: "#", source: "SECURITY_DESK" },
  { title: "UPDATE: Eutelsat 10B enters regular commercial service at 10°E.", link: "#", source: "ORBITAL_OPS" },
  { title: "NOTICE: Global GPS constellation undergoing scheduled maintenance cycle.", link: "#", source: "NAV_SYSTEMS" },
  { title: "RESEARCH: Advances in Ka-band rain fade mitigation techniques.", link: "#", source: "RF_LABS" }
];

export const RSSReader: React.FC = () => {
  const [items, setItems] = useState<RSSItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [useFallback, setUseFallback] = useState(false);

  useEffect(() => {
    const fetchFeed = async () => {
      setLoading(true);
      try {
        // Attempt fetch through bridge
        const response = await fetch(`https://api.allorigins.win/get?url=${encodeURIComponent('https://spacenews.com/feed/')}`);
        if (!response.ok) throw new Error('Network response error');

        const data = await response.json();
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(data.contents, "text/xml");
        const channelItems = xmlDoc.querySelectorAll("item");

        if (channelItems.length === 0) throw new Error('Empty feed');

        setItems(Array.from(channelItems).slice(0, 8).map(node => ({
          title: node.querySelector("title")?.textContent || 'Untitled Intelligence',
          link: node.querySelector("link")?.textContent || '#',
          source: 'SPACENEWS_LIVE'
        })));
        setUseFallback(false);
      } catch (err) { 
        console.warn("RSS_UPLINK_FAILURE: Defaulting to local intelligence cache.", err);
        setItems(FALLBACK_INTEL);
        setUseFallback(true);
      } finally { 
        setLoading(false); 
      }
    };
    fetchFeed();
  }, []);

  return (
    <div className="glass p-6 rounded-2xl border-slate-800">
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-xl font-bold text-white uppercase tracking-widest flex items-center">
          <span className="w-3 h-3 bg-cyan-500 rounded-full mr-3 animate-pulse"></span>
          Industry Intel Feed
        </h2>
        {useFallback && (
          <span className="text-[8px] font-bold text-amber-500 border border-amber-500/20 px-2 py-0.5 rounded uppercase tracking-tighter">Offline Cache Active</span>
        )}
      </div>

      <div className="space-y-3">
        {loading ? (
          <div className="py-12 flex flex-col items-center justify-center space-y-3">
            <div className="w-8 h-8 border-2 border-cyan-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">Synchronizing Uplink...</p>
          </div>
        ) : (
          items.map((item, i) => (
            <a 
              key={i} 
              href={item.link} 
              target="_blank" 
              rel="noopener noreferrer"
              className="group block p-4 rounded-xl border border-slate-800 bg-slate-950/30 hover:border-cyan-500/50 hover:bg-cyan-500/5 transition-all"
            >
              <div className="flex justify-between items-start mb-1">
                <span className="text-[8px] font-bold text-cyan-500 mono uppercase tracking-widest">{item.source}</span>
                <svg className="w-3 h-3 text-slate-600 group-hover:text-cyan-400 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                </svg>
              </div>
              <p className="text-[12px] font-medium text-slate-300 leading-snug group-hover:text-white transition-colors">
                {item.title}
              </p>
            </a>
          ))
        )}
      </div>

      {!loading && (
        <div className="mt-6 pt-6 border-t border-slate-800/50 flex justify-center">
          <p className="text-[9px] text-slate-600 font-bold uppercase tracking-[0.3em]">Monitoring active for new intelligence</p>
        </div>
      )}
    </div>
  );
};

import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
// Import getTroubleshootingAdvice to use for intel queries
import { getTroubleshootingAdvice } from '../services/geminiService.ts';

interface Props {
  userLoc: { lat: number, lng: number };
  selectedSatName: string;
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  signalQuality: number;
  onBack?: () => void;
}

interface HardeningOption {
  id: string;
  label: string;
  description: string;
  enabled: boolean;
}

export const SecurityTools: React.FC<Props> = ({ 
  userLoc, 
  selectedSatName,
  isJamming,
  setIsJamming,
  jammingPower,
  setJammingPower,
  signalQuality,
  onBack
}) => {
  const [activeTab, setActiveTab] = useState<string>('overview');
  const [outputs, setOutputs] = useState<Record<string, string>>({});
  const [intelLoading, setIntelLoading] = useState(false);

  // Attack States
  const [bruteForceLog, setBruteForceLog] = useState<string[]>([]);
  const [isBruteForcing, setIsBruteForcing] = useState(false);
  const [spoofFrame, setSpoofFrame] = useState('');
  const [targetIp, setTargetIp] = useState('192.168.1.100');
  const [ipAttackLog, setIpAttackLog] = useState<string[]>([]);
  const [isIpAttacking, setIsIpAttacking] = useState(false);

  // Detection States
  const [detectionLogs, setDetectionLogs] = useState<{id: string, type: string, severity: 'LOW' | 'MED' | 'HIGH', msg: string}[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  // Hardening States
  const [hardeningOptions, setHardeningOptions] = useState<HardeningOption[]>([
    { id: 'telnet', label: 'Disable Telnet', description: 'Terminate unencrypted legacy remote access port 23.', enabled: false },
    { id: 'ssh', label: 'Enable SSH v2', description: 'Enforce encrypted administrative access via RSA/ED25519 keys.', enabled: false },
    { id: 'encryption', label: 'Stronger Encryption', description: 'Upgrade air interface to AES-256 and enforce FIPS 140-2.', enabled: false },
    { id: 'firmware', label: 'Firmware Integrity', description: 'Enable secure boot and cryptographic hash validation.', enabled: false },
    { id: 'ports', label: 'Disable Unused Ports', description: 'Seal non-essential logical ports and audit open services.', enabled: false },
    { id: 'rate-limiting', label: 'Implement Rate Limiting', description: 'Prevent DoS/DDoS by throttling excessive packet requests.', enabled: false },
    { id: 'firmware-mandatory', label: 'Mandatory Firmware Updates', description: 'Enforce automatic signed updates to patch zero-day vulnerabilities.', enabled: false },
    { id: 'segmentation', label: 'Network Segmentation', description: 'Isolate management and user traffic into distinct VLANs.', enabled: false },
  ]);

  const terminalRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (terminalRef.current) terminalRef.current.scrollTop = terminalRef.current.scrollHeight;
  }, [bruteForceLog, ipAttackLog]);

  // Added fetchThreatIntel to handle tactical intelligence queries via Gemini
  const fetchThreatIntel = async (query: string) => {
    if (!query || intelLoading) return;
    setIntelLoading(true);
    try {
      const advice = await getTroubleshootingAdvice(`Strategic assessment and threat intelligence for: ${query}`, {
        lat: userLoc.lat,
        lng: userLoc.lng,
        satName: selectedSatName
      });
      setOutputs(prev => ({ ...prev, intel: advice || "NO_DATA_RETURNED" }));
    } catch (error) {
      console.error("STIA_INTEL_UPLINK_ERROR", error);
      setOutputs(prev => ({ ...prev, intel: "SYSTEM_FAILURE: INTELLIGENCE_UPLINK_TIMEOUT. CHECK SECURE LINK." }));
    } finally {
      setIntelLoading(false);
    }
  };

  const runIpAttack = () => {
    if (!targetIp || isIpAttacking) return;
    setIsIpAttacking(true);
    setIpAttackLog([`[INIT] Targeting IP: ${targetIp}`, "[SCAN] Probing for open vectors..."]);

    const steps = [
      `[PROBE] TCP SYN flood initiated against ${targetIp}:443`,
      "[INFO] Remote firewall detected (CheckPoint v8.2)",
      "[EXPLOIT] Injecting buffer overflow payload to port 8080...",
      "[SUCCESS] Payload delivered. Attempting shell callback...",
      "[!] ALERT: Intrusion detection triggered at target.",
      "[CLEANUP] Wiping temporary logs and terminating session."
    ];

    let i = 0;
    const interval = window.setInterval(() => {
      if (i >= steps.length) {
        setIpAttackLog(prev => [...prev, "[EXIT] Operation Complete."]);
        setIsIpAttacking(false);
        clearInterval(interval);
        return;
      }
      setIpAttackLog(prev => [...prev, steps[i]]);
      i++;
    }, 1200);
  };

  const runThreatScan = () => {
    setIsScanning(true);
    setDetectionLogs([]);
    setTimeout(() => {
      setDetectionLogs([
        { id: 'DT-01', type: 'RF_ANOMALY', severity: 'LOW', msg: 'Abnormal noise floor deviation at 14.2GHz' },
        { id: 'DT-02', type: 'AUTH_FAILURE', severity: 'MED', msg: 'Multiple failed SSH attempts from 10.0.0.42' },
        { id: 'DT-03', type: 'ENCRYPTION', severity: 'HIGH', msg: 'Clear-text traffic detected on management plane' }
      ]);
      setIsScanning(false);
    }, 2000);
  };

  const toggleHardening = (id: string) => {
    setHardeningOptions(prev => prev.map(opt => 
      opt.id === id ? { ...opt, enabled: !opt.enabled } : opt
    ));
  };

  const complianceScore = Math.round((hardeningOptions.filter(o => o.enabled).length / hardeningOptions.length) * 100);

