                      </div>
                    )}
                  </div>
                  {attackOutcome && (
                    <div className="bg-red-950/20 border border-red-500/30 p-2 rounded-lg text-center animate-bounce">
                      <span className="text-[10px] font-bold text-red-500 uppercase tracking-[0.3em]">
                        {attackOutcome}
                      </span>
                    </div>
                  )}
                </div>
              </div>

              <div className="glass p-6 rounded-2xl border-slate-800 border-l-4 border-l-red-500/50">
                <div className="flex items-center justify-between mb-4">
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Jamming Control</h4>
                  <div className={`px-2 py-0.5 rounded text-[8px] font-bold ${isJamming ? 'bg-red-500 text-white' : 'bg-slate-800 text-slate-500'}`}>
                    {isJamming ? 'TRANSMITTING' : 'IDLE'}
                  </div>
                </div>
                <div className="space-y-2">
                  <div className="flex justify-between text-[9px] font-bold mono text-slate-600">
                    <span>Power Intensity</span>
                    <span>{jammingPower}%</span>
                  </div>
                  <input 
                    type="range" min="0" max="100" value={jammingPower} 
                    onChange={(e) => setJammingPower(parseInt(e.target.value))}
                    className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-red-500"
                  />
                </div>
                <button 
                  onClick={() => setIsJamming(!isJamming)}
                  className={`w-full mt-4 py-3 rounded-xl font-bold text-xs uppercase tracking-widest transition-all ${isJamming ? 'bg-red-600 text-white shadow-[0_0_20px_rgba(239,68,68,0.3)]' : 'bg-slate-800 text-red-500 border border-red-500/20 hover:bg-red-950/10'}`}
                >
                  {isJamming ? 'Halt Transmission' : 'Engage EW Jammer'}
                </button>
              </div>
            </div>

            <div className="space-y-6">
              <div className="glass p-6 rounded-2xl border-slate-800 border-l-4 border-l-cyan-500/50">
                <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Protocol Injection</h4>
                <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 mono text-[10px] text-cyan-400 break-all mb-4 h-32 flex items-center justify-center text-center">
                  {spoofFrame || "NO_DATA_STAGED_FOR_UPLINK"}
                </div>
                <button 
                  onClick={() => setSpoofFrame(`DVB_S2X_ACM_FRAME_${Math.random().toString(16).slice(2, 12).toUpperCase()}`)}
                  className="w-full py-3 bg-slate-800 text-cyan-400 font-bold text-[10px] uppercase tracking-widest rounded-xl border border-cyan-500/20 hover:bg-cyan-950/20 transition-all"
                >
                  Forge Command Packet
                </button>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'detection' && (
          <div className="animate-in fade-in duration-500">
            <div className="glass p-6 rounded-2xl border-slate-800">
              <div className="flex items-center justify-between mb-6">
                <div>
                  <h3 className="text-white font-bold uppercase text-sm tracking-widest">Link Monitoring Service</h3>
                  <p className="text-xs text-slate-500">Anomaly detection for the active satellite segment.</p>
                </div>
                <button 
                  onClick={runThreatScan}
                  disabled={isScanning}
                  className="bg-cyan-600 hover:bg-cyan-500 disabled:opacity-30 text-slate-950 font-bold px-6 py-2 rounded-lg text-[10px] uppercase tracking-widest shadow-lg"
                >
                  {isScanning ? 'Synchronizing Sensors...' : 'Start Global Scan'}
                </button>
              </div>

              {isScanning && (
                <div className="w-full h-1 bg-slate-900 rounded-full mb-6 overflow-hidden">
                  <div className="h-full bg-cyan-500 animate-pulse w-full origin-left scale-x-50"></div>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 text-center">
                  <span className="text-[8px] font-bold text-slate-500 uppercase block mb-1">Active Vectors</span>
                  <span className={`text-xl font-bold mono ${detectionLogs.length > 0 ? 'text-red-500' : 'text-green-500'}`}>{detectionLogs.length}</span>
                </div>
                <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 text-center">
                  <span className="text-[8px] font-bold text-slate-500 uppercase block mb-1">Signal Health</span>
                  <span className="text-xl font-bold mono text-cyan-400">92%</span>
                </div>
                <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 text-center">
                  <span className="text-[8px] font-bold text-slate-500 uppercase block mb-1">Uplink Lock</span>
                  <span className="text-xl font-bold mono text-green-500">STABLE</span>
                </div>
              </div>

              <div className="space-y-3">
                {detectionLogs.length === 0 ? (
                  <div className="text-center py-16 border border-dashed border-slate-800 rounded-2xl">
                    <div className="text-slate-700 italic text-[10px] uppercase tracking-widest">
                      {isScanning ? "Probing RF Spectrum..." : "No active threats detected in current segment."}
                    </div>
                  </div>
                ) : (
                  detectionLogs.map((log) => (
                    <div key={log.id} className="bg-slate-950 p-4 rounded-xl border border-slate-800/50 hover:border-slate-700 transition-all">
                      <div className="flex items-center justify-between mb-2">
                        <div className="flex items-center space-x-3">
                          <span className={`text-[8px] font-bold px-2 py-0.5 rounded uppercase ${
                            log.severity === 'HIGH' ? 'bg-red-500 text-white' : 
                            log.severity === 'MED' ? 'bg-amber-500 text-black' : 'bg-blue-500 text-white'
                          }`}>
                            {log.severity}_SEVERITY
                          </span>
                          <span className="text-[10px] font-bold text-white uppercase">{log.type}</span>
                        </div>
                        <span className="text-[8px] text-slate-700 mono">{log.id}</span>
                      </div>
                      <p className="text-[10px] text-slate-400 mono mb-3">{log.msg}</p>
                      <div className="bg-slate-900 p-2 rounded border border-slate-800">
                        <span className="text-[8px] font-bold text-cyan-500 uppercase block mb-1">Field_Mitigation:</span>
                        <p className="text-[9px] text-slate-500 italic">{log.mitigation}</p>
                      </div>
                    </div>
                  ))
