              <div className="glass p-6 rounded-2xl border-slate-800">
                <div className="flex items-center justify-between mb-6">
                  <h3 className="text-white font-bold uppercase text-sm tracking-widest">Modem Security baseline</h3>
                  <div className="text-right">
                    <span className="text-[8px] font-bold text-slate-500 uppercase">Compliance Score</span>
                    <div className="text-2xl font-black text-green-500 mono">{complianceScore}%</div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {hardeningOptions.map((opt) => (
                    <div 
                      key={opt.id} 
                      onClick={() => toggleHardening(opt.id)}
                      className={`group flex items-center p-4 rounded-xl border cursor-pointer transition-all ${
                        opt.enabled ? 'bg-green-500/5 border-green-500/30 shadow-[0_0_15px_rgba(34,197,94,0.05)]' : 'bg-slate-950/40 border-slate-800 hover:border-slate-700'
                      }`}
                    >
                      <div className={`w-5 h-5 rounded border flex items-center justify-center shrink-0 ${
                        opt.enabled ? 'bg-green-500 border-green-500' : 'border-slate-700'
                      }`}>
                        {opt.enabled && <svg className="w-3.5 h-3.5 text-slate-950" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={4}><path d="M5 13l4 4L19 7" /></svg>}
                      </div>
                      <div className="ml-4">
                        <div className={`text-[10px] font-bold uppercase ${opt.enabled ? 'text-green-400' : 'text-slate-300'}`}>{opt.label}</div>
                        <p className="text-[9px] text-slate-500 mt-0.5">{opt.description}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="lg:col-span-4 glass p-6 rounded-2xl border-slate-800 h-full flex flex-col items-center justify-center text-center">
              <div className="text-4xl font-black text-white mono mb-2">{complianceScore}%</div>
              <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Defense Readiness</div>
              <div className="w-full h-1.5 bg-slate-900 rounded-full mt-6 overflow-hidden">
                <div className="h-full bg-green-500 transition-all duration-1000" style={{width: `${complianceScore}%`}}></div>
              </div>
              <p className="text-[9px] text-slate-600 mono mt-6 italic px-4">
                "Ground segment hardening is mandatory for mission resilience."
