          </div>
        )}

        {activeTab === 'intel' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-2xl border-slate-800">
              <input 
                id="hw-search" 
                placeholder="Enter Asset Model (e.g. iDirect Evolution)..." 
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-white mono mb-4 focus:border-cyan-500 transition-all outline-none" 
              />
              <button 
                onClick={() => fetchThreatIntel((document.getElementById('hw-search') as HTMLInputElement).value)} 
