                    className={`w-full h-1 rounded-lg appearance-none cursor-pointer transition-all ${isJamming ? 'bg-red-900/50 accent-red-500' : 'bg-slate-800 accent-slate-600'}`}
                  />
                </div>
                <button 
                  onClick={() => setIsJamming(!isJamming)}
                  className={`w-full mt-4 py-3 rounded-xl font-bold text-xs uppercase tracking-widest transition-all ${isJamming ? 'bg-red-600 text-white shadow-[0_0_20px_rgba(239,68,68,0.3)]' : 'bg-slate-800 text-red-500 border border-red-500/20 hover:bg-red-950/10'}`}
                >
                  {isJamming ? 'Halt Transmission' : 'Engage EW Jammer'}
