              </div>
            </div>

            <div className="space-y-6">
              <div className="glass p-6 rounded-2xl border-slate-800 border-l-4 border-l-cyan-500/50">
                <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Protocol Injection</h4>
                <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 mono text-[10px] text-cyan-400 break-all mb-4 h-32 flex items-center justify-center text-center">
                  {spoofFrame || "NO_DATA_STAGED_FOR_UPLINK"}
                </div>
                <button 
                  onClick={() => setSpoofFrame(`DVB_S2X_ACM_FRAME_${Math.random().toString(16).slice(2, 12).toUpperCase()}`)}
                  className="w-full py-3 bg-slate-800 text-cyan-400 font-bold text-[10px] uppercase tracking-widest rounded-xl border border-cyan-500/20 hover:bg-cyan-950/20 transition-all"
                >
                  Forge Command Packet
                </button>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'detection' && (
          <div className="animate-in fade-in duration-500">
            <div className="glass p-6 rounded-2xl border-slate-800">
              <div className="flex items-center justify-between mb-6">
                <div>
                  <h3 className="text-white font-bold uppercase text-sm tracking-widest">Link Monitoring Service</h3>
                  <p className="text-xs text-slate-500">Anomaly detection for the active satellite segment.</p>
                </div>
                <button 
                  onClick={runThreatScan}
                  disabled={isScanning}
                  className="bg-cyan-600 hover:bg-cyan-500 disabled:opacity-30 text-slate-950 font-bold px-6 py-2 rounded-lg text-[10px] uppercase tracking-widest shadow-lg"
                >
                  {isScanning ? 'Synchronizing Sensors...' : 'Start Global Scan'}
                </button>
              </div>

              {isScanning && (
                <div className="w-full h-1 bg-slate-900 rounded-full mb-6 overflow-hidden">
                  <div className="h-full bg-cyan-500 animate-pulse w-full origin-left scale-x-50"></div>
