                        <span className="text-[8px] text-slate-700 mono">{log.id}</span>
                      </div>
                      <p className="text-[10px] text-slate-400 mono mb-3">{log.msg}</p>
                      <div className="bg-slate-900 p-2 rounded border border-slate-800">
                        <span className="text-[8px] font-bold text-cyan-500 uppercase block mb-1">Field_Mitigation:</span>
                        <p className="text-[9px] text-slate-500 italic">{log.mitigation}</p>
