                <svg className="w-full h-full transform -rotate-90">
                  <circle
                    cx="80"
                    cy="80"
                    r="70"
                    stroke="currentColor"
                    strokeWidth="8"
                    fill="transparent"
                    className="text-slate-900"
                  />
                  <circle
                    cx="80"
                    cy="80"
                    r="70"
                    stroke="currentColor"
                    strokeWidth="8"
                    fill="transparent"
                    strokeDasharray={440}
                    strokeDashoffset={440 - (440 * complianceScore) / 100}
                    className={`transition-all duration-1000 ease-out ${gradeInfo.color.replace('text-', 'stroke-')}`}
                    strokeLinecap="round"
                  />
                </svg>
                <div className="absolute flex flex-col items-center justify-center">
                  <div className={`text-4xl font-black mono transition-colors duration-500 ${gradeInfo.color}`}>{complianceScore}%</div>
                  <div className={`text-xs font-bold uppercase tracking-[0.2em] mt-1 opacity-60 ${gradeInfo.color}`}>Grade: {gradeInfo.grade}</div>
                </div>
                {complianceScore === 100 && (
                   <div className="absolute inset-0 rounded-full bg-green-500/5 animate-pulse"></div>
                )}
              </div>

              <div className="space-y-2 z-10">
                <div className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.3em]">Compliance Rating</div>
                <div className={`text-[11px] font-bold mono uppercase px-4 py-1.5 rounded-full border bg-slate-950/80 ${gradeInfo.color.replace('text-', 'border-').replace('text-', 'text-')}`}>
                  {complianceScore === 100 ? "FULLY_HARDENED" : complianceScore > 75 ? "SECURE_OPTIMAL" : complianceScore > 40 ? "DEFICIENT" : "CRITICAL_VULNERABILITY"}
                </div>
              </div>

              <p className="text-[9px] text-slate-600 mono mt-8 italic px-4 leading-relaxed opacity-60">
                "Ground segment security baseline is evaluated in real-time. Enforce all hardening protocols for mission continuity."
              </p>

              {/* Decorative Scanlines behind gauge */}
              <div className="absolute inset-0 pointer-events-none opacity-5 bg-[linear-gradient(transparent_0%,rgba(34,211,238,0.2)_50%,transparent_100%)] bg-[length:100%_4px]"></div>
