        {activeTab === 'intel' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-2xl border-slate-800">
              <input 
                id="hw-search" 
                placeholder="Enter Asset Model (e.g. iDirect Evolution)..." 
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-white mono mb-4 focus:border-cyan-500 transition-all outline-none" 
              />
              <button 
                onClick={() => fetchThreatIntel((document.getElementById('hw-search') as HTMLInputElement).value)} 
                disabled={intelLoading}
                className="w-full py-3 bg-cyan-600 text-slate-950 font-bold text-[10px] uppercase tracking-widest rounded-xl disabled:opacity-50 shadow-lg"
              >
                {intelLoading ? 'QUERING_STRATEGIC_DATABASE...' : 'Query Threat Database'}
              </button>
            </div>
            {outputs.intel && (
              <div className="animate-in fade-in slide-in-from-top-2 duration-700">
                <div className="flex items-center space-x-2 mb-2 px-1">
                  <div className="w-1.5 h-1.5 bg-cyan-500 rounded-full animate-pulse"></div>
                  <span className="text-[10px] font-bold text-cyan-500 uppercase tracking-widest">Briefing_Report</span>
                </div>
                <pre className="bg-slate-950 p-6 rounded-2xl border border-slate-800 text-cyan-400 text-[11px] font-mono whitespace-pre-wrap leading-relaxed max-h-[500px] overflow-auto shadow-inner">
                  {outputs.intel}
                </pre>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Coordinates, Satellite, SatelliteStatus, WeatherCondition } from '../types.ts';
import { COMMON_SATELLITES } from '../constants.ts';

interface Props {
  loc: Coordinates;
  sat: Satellite;
  onLocChange: (loc: Coordinates) => void;
  onSatChange: (sat: Satellite) => void;
  isTracking?: boolean;
  onTrackingChange?: (val: boolean) => void;
  // EW State
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  // Weather State
  weather: WeatherCondition;
  setWeather: (val: WeatherCondition) => void;
}

interface TacticalEvent {
  id: string;
  timestamp: string;
  satName: string;
  satId: string;
  status: SatelliteStatus;
  detail: string;
}

const EVENT_LOG_STORAGE_KEY = 'satexpert_event_logs';

const StatusBadge: React.FC<{ status?: SatelliteStatus }> = ({ status }) => {
  const config = {
    active: { color: 'bg-green-500', label: 'ONLINE', pulse: true },
    offline: { color: 'bg-red-500', label: 'OFFLINE', pulse: false },
    maintenance: { color: 'bg-amber-500', label: 'MAINT', pulse: true },
    decommissioned: { color: 'bg-slate-600', label: 'EOL', pulse: false },
  }[status || 'active'];

  return (
    <div className="flex items-center space-x-1.5">
      <div className={`w-1.5 h-1.5 rounded-full ${config.color} ${config.pulse ? 'animate-pulse' : ''}`}></div>
      <span className={`text-[8px] font-bold tracking-tighter ${config.color.replace('bg-', 'text-')}`}>
        {config.label}
      </span>
    </div>
  );
};

export const TacticalHUD: React.FC<Props> = ({ 
  loc, sat, onLocChange, onSatChange, isTracking, onTrackingChange,
  isJamming, setIsJamming, jammingPower, setJammingPower,
  weather, setWeather
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [showEventLog, setShowEventLog] = useState(false);
  const [animateLabel, setAnimateLabel] = useState(false);
  const [eventLogs, setEventLogs] = useState<TacticalEvent[]>([]);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const prevSatRef = useRef<{id: string, status?: SatelliteStatus} | null>(null);

  // Load event logs
  useEffect(() => {
    const saved = localStorage.getItem(EVENT_LOG_STORAGE_KEY);
    if (saved) {
      try {
        setEventLogs(JSON.parse(saved));
      } catch (e) {
        console.error("EVENT_LOG_LOAD_ERROR", e);
      }
    }
  }, []);

  // Save event logs
  useEffect(() => {
    localStorage.setItem(EVENT_LOG_STORAGE_KEY, JSON.stringify(eventLogs));
  }, [eventLogs]);

  // Track Satellite Status Changes & Acquisitions
  useEffect(() => {
    setAnimateLabel(true);
    const timer = setTimeout(() => setAnimateLabel(false), 600);

    const isSameSat = prevSatRef.current?.id === sat.id;
    const isStatusChanged = prevSatRef.current?.status !== sat.status;

    if (!isSameSat || isStatusChanged) {
      const newEvent: TacticalEvent = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: new Date().toLocaleString(),
        satName: sat.name,
        satId: sat.id,
        status: sat.status || 'active',
        detail: !isSameSat 
          ? `ASSET_ACQUISITION: Targeted ${sat.name} (${sat.orbitalSlot})`
          : `STATUS_RECOVERY: Asset ${sat.name} transitioned to ${sat.status?.toUpperCase()}`
      };
      setEventLogs(prev => [newEvent, ...prev].slice(0, 50)); // Keep last 50
    }

    prevSatRef.current = { id: sat.id, status: sat.status };
    return () => clearTimeout(timer);
  }, [sat.id, sat.status]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (s: Satellite) => {
    onSatChange(s);
    setSearchQuery('');
    setIsOpen(false);
  };

  const clearLogs = () => {
    setEventLogs([]);
    setShowEventLog(false);
  };

  const handleExportData = () => {
    const timestamp = new Date().toISOString();
    const content = `
[TACTICAL ASSET BRIEFING]
-------------------------
TIMESTAMP: ${timestamp}
ASSET_ID: ${sat.id}
ASSET_NAME: ${sat.name}
OPERATOR: ${sat.operator || 'UNKNOWN'}
ORBITAL_SLOT: ${sat.orbitalSlot}
LONGITUDE: ${sat.longitude}°
STATUS: ${sat.status || 'UNKNOWN'}

[ORBITAL_TELEMETRY]
APOGEE: ${sat.apogee ? sat.apogee.toLocaleString() : 'N/A'} KM
PERIGEE: ${sat.perigee ? sat.perigee.toLocaleString() : 'N/A'} KM
INCLINATION: ${sat.inclination ? sat.inclination.toFixed(4) : 'N/A'}°
VELOCITY: ${sat.velocity ? sat.velocity.toFixed(4) : 'N/A'} KM/S

[DEPLOYMENT_CONTEXT]
USER_LAT: ${loc.lat.toFixed(6)}
USER_LNG: ${loc.lng.toFixed(6)}
WEATHER_SIM: ${weather}

[SECURITY_POSTURE]
EW_INTERFERENCE: ${isJamming ? 'ACTIVE' : 'STANDBY'}
JAM_POWER: ${jammingPower}%
-------------------------
EOF // ENCRYPTED_BRIEF
`;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `SAT_BRIEF_${sat.id}_${Date.now()}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const weatherIcons = {
    CLEAR: '☀️',
    OVERCAST: '☁️',
    LIGHT_RAIN: '🌧️',
    HEAVY_STORM: '⛈️'
  };

  return (
    <div className="glass rounded-2xl p-6 border-slate-800 relative z-50">
      <div className="space-y-4">
        <div className="relative" ref={dropdownRef}>
          <div className="flex items-center justify-between mb-1">
            <label className={`block text-[9px] font-bold uppercase tracking-widest transition-all duration-300 transform ${
              animateLabel 
                ? 'text-cyan-400 scale-105 drop-shadow-[0_0_8px_rgba(34,211,238,0.6)]' 
                : 'text-slate-500'
            }`}>
              Target Acquisition
            </label>
            <div className="flex items-center space-x-2">
              <button 
                onClick={() => setShowEventLog(true)}
                className="flex items-center space-x-1 px-2 py-0.5 rounded border border-slate-800 bg-slate-900 text-[8px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/30 transition-all uppercase tracking-tighter"
              >
                <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                </svg>
                <span>Logs</span>
              </button>
              <button 
                onClick={handleExportData}
                className="flex items-center space-x-1 px-2 py-0.5 rounded border border-slate-800 bg-slate-900 text-[8px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/30 transition-all uppercase tracking-tighter"
                title="Export Asset Brief"
              >
                <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
                <span>Export</span>
              </button>
            </div>
          </div>

          <div className="relative">
            <input
              type="text"
              placeholder={isOpen ? "ENTER SATELLITE NAME OR SLOT..." : sat.name}
              className={`w-full bg-slate-950 border ${isOpen ? 'border-cyan-500 shadow-[0_0_10px_rgba(34,211,238,0.2)]' : 'border-slate-800'} rounded-lg p-2.5 pl-9 text-xs text-white outline-none transition-all mono placeholder:text-slate-600`}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setIsOpen(true);
              }}
              onFocus={() => setIsOpen(true)}
            />
            <div className="absolute left-3 top-1/2 -translate-y-1/2">
              <svg className={`w-4 h-4 ${isOpen ? 'text-cyan-400' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center">
               {!isOpen && <StatusBadge status={sat.status} />}
            </div>
          </div>

          {isOpen && (
            <div className="absolute mt-2 w-full glass bg-slate-950/95 border border-cyan-500/30 rounded-xl shadow-2xl overflow-hidden max-h-[300px] flex flex-col z-[100]">
              <div className="bg-cyan-500/5 px-4 py-2 border-b border-slate-800/50">
                <span className="text-[8px] font-bold text-cyan-400 uppercase tracking-widest">Results Found: {filteredSatellites.length}</span>
              </div>
              <div className="overflow-y-auto scrollbar-hide py-1">
                {filteredSatellites.length > 0 ? (
                  filteredSatellites.map((s) => (
                    <button
                      key={s.id}
                      onClick={() => handleSelect(s)}
                      className={`w-full text-left px-4 py-3 hover:bg-cyan-500/10 transition-colors flex items-center justify-between group border-b border-slate-900/50 last:border-none ${s.id === sat.id ? 'bg-cyan-500/5' : ''}`}
                    >
                      <div className="flex flex-col">
                        <div className="flex items-center space-x-2">
                           <span className={`text-[11px] font-bold tracking-wide ${s.id === sat.id ? 'text-cyan-400' : 'text-slate-300 group-hover:text-cyan-200'}`}>{s.name}</span>
                           <StatusBadge status={s.status} />
                        </div>
                        <span className="text-[9px] text-slate-500 mono group-hover:text-slate-400">{s.operator || 'UNKNOWN OPERATOR'}</span>
                      </div>
                      <div className="flex flex-col items-end">
                        <span className="text-[10px] text-cyan-500 font-mono font-bold tracking-tighter">{s.orbitalSlot}</span>
                      </div>
                    </button>
                  ))
                ) : (
                  <div className="px-4 py-8 text-center">
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">No matching assets found</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Asset Identity Block */}
        <div className="bg-slate-950/50 rounded-xl border border-slate-800/50 p-3 flex items-center justify-between animate-in fade-in slide-in-from-top-1 duration-300">
          <div className="flex flex-col">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Operator Authority</span>
            <span className="text-[10px] font-bold text-slate-200 mono truncate max-w-[120px]">
              {sat.operator || 'UNSPECIFIED'}
            </span>
          </div>
          <div className="h-8 w-px bg-slate-800/50 mx-2"></div>
          <div className="flex flex-col items-center px-2">
             <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Link State</span>
             <StatusBadge status={sat.status} />
          </div>
          <div className="h-8 w-px bg-slate-800/50 mx-2"></div>
          <div className="flex flex-col items-end text-right">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Orbital Slot</span>
            <div className="flex items-center space-x-2">
              <span className="text-[10px] font-bold text-cyan-400 mono">{sat.orbitalSlot}</span>
              <div className="w-1.5 h-1.5 bg-cyan-500/50 rounded-full animate-pulse"></div>
            </div>
          </div>
        </div>

        {/* Atmospheric Dynamics Block */}
        <div className="bg-slate-950/60 rounded-xl border border-slate-800 p-3 space-y-3 animate-in fade-in slide-in-from-top-1 duration-500">
          <div className="flex items-center justify-between">
             <span className="text-[8px] font-black text-cyan-500/80 uppercase tracking-[0.2em]">Atmospheric_Dynamics</span>
             <div className="flex items-center space-x-1">
                <span className="text-[7px] text-slate-600 mono uppercase tracking-tighter">SIM: Ka-BAND_RAIN_FADE</span>
             </div>
          </div>
          <div className="grid grid-cols-4 gap-1">
            {(['CLEAR', 'OVERCAST', 'LIGHT_RAIN', 'HEAVY_STORM'] as WeatherCondition[]).map((cond) => (
              <button 
                key={cond}
                onClick={() => setWeather(cond)}
                className={`flex flex-col items-center justify-center p-2 rounded-lg border transition-all ${
                  weather === cond 
                    ? 'bg-cyan-500/10 border-cyan-500 text-cyan-400 shadow-[0_0_10px_rgba(34,211,238,0.2)]' 
                    : 'bg-slate-900/50 border-slate-800 text-slate-600 hover:border-slate-700'
                }`}
              >
                <span className="text-sm mb-1">{weatherIcons[cond]}</span>
                <span className="text-[6px] font-bold uppercase tracking-tighter">{cond.replace('_', ' ')}</span>
              </button>
            ))}
          </div>
          <div className="flex justify-between items-center text-[8px] font-mono border-t border-slate-800/50 pt-2">
             <div className="flex flex-col">
               <span className="text-slate-500 uppercase">Attenuation</span>
               <span className={`${weather === 'HEAVY_STORM' ? 'text-red-500 animate-pulse' : 'text-cyan-400'}`}>
                 {weather === 'CLEAR' ? '0.5' : weather === 'OVERCAST' ? '1.8' : weather === 'LIGHT_RAIN' ? '4.5' : '12.0'} dB
               </span>
             </div>
             <div className="flex flex-col text-right">
               <span className="text-slate-500 uppercase">Humidity</span>
               <span className="text-slate-300">{weather === 'CLEAR' ? '12%' : weather === 'OVERCAST' ? '45%' : '88%'}</span>
             </div>
          </div>
        </div>

        {/* Electronic Warfare Override */}
        <div className={`rounded-xl border p-3 space-y-3 transition-all duration-300 ${isJamming ? 'bg-red-950/20 border-red-500/40 shadow-[0_0_15px_rgba(239,68,68,0.1)]' : 'bg-slate-950/40 border-slate-800'}`}>
          <div className="flex items-center justify-between">
            <div className="flex flex-col">
              <span className={`text-[8px] font-black uppercase tracking-[0.2em] ${isJamming ? 'text-red-500' : 'text-slate-500'}`}>EW_Signal_Override</span>
              <span className="text-[7px] text-slate-600 mono">MODE: RF_CONTINUOUS_WAVE</span>
            </div>
            <button 
              onClick={() => setIsJamming(!isJamming)}
              className={`px-3 py-1 rounded-md text-[9px] font-bold uppercase transition-all ${isJamming ? 'bg-red-600 text-white shadow-lg animate-pulse' : 'bg-slate-800 text-slate-500 hover:text-slate-300'}`}
            >
              {isJamming ? 'Engaged' : 'Standby'}
            </button>
          </div>

          <div className="space-y-2">
            <div className="flex items-center justify-between text-[8px] font-bold mono">
              <span className={isJamming ? 'text-red-400' : 'text-slate-600'}>INTENSITY: {jammingPower}%</span>
              <span className={isJamming ? 'text-red-400' : 'text-slate-600'}>SNR_LOSS: -{(jammingPower / 5).toFixed(1)} dB</span>
            </div>
            <input 
              type="range" 
              min="0" max="100" 
              value={jammingPower} 
              onChange={(e) => setJammingPower(parseInt(e.target.value))}
              className={`w-full h-1 rounded-lg appearance-none cursor-pointer transition-all ${isJamming ? 'bg-red-900/50 accent-red-500' : 'bg-slate-800 accent-slate-600'}`}
            />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3 mt-4">
           <div className="group">
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-1 tracking-widest group-hover:text-cyan-500 transition-colors">Deployment Lat</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  disabled={isTracking}
                  className={`w-full bg-slate-950 p-2.5 text-xs rounded-lg border text-cyan-400 outline-none mono transition-all ${isTracking ? 'border-cyan-500/30 opacity-50' : 'border-slate-800 focus:border-cyan-500/50'}`} 
                  value={loc.lat} 
                  onChange={e => onLocChange({...loc, lat: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-700 font-bold">N/S</span>
              </div>
           </div>
           <div className="group">
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-1 tracking-widest group-hover:text-cyan-500 transition-colors">Deployment Lng</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  disabled={isTracking}
                  className={`w-full bg-slate-950 p-2.5 text-xs rounded-lg border text-cyan-400 outline-none mono transition-all ${isTracking ? 'border-cyan-500/30 opacity-50' : 'border-slate-800 focus:border-cyan-500/50'}`} 
                  value={loc.lng} 
                  onChange={e => onLocChange({...loc, lng: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-700 font-bold">E/W</span>
              </div>
           </div>
        </div>
      </div>

      {/* Event Log Modal */}
      {showEventLog && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="glass w-full max-w-lg rounded-3xl border border-slate-700 shadow-2xl flex flex-col max-h-[80vh] overflow-hidden">
            <div className="p-6 border-b border-slate-800 flex items-center justify-between bg-slate-900/50">
               <div>
                  <h3 className="text-sm font-bold text-white uppercase tracking-widest flex items-center">
                    <span className="w-2 h-2 bg-cyan-500 rounded-full mr-2 animate-pulse"></span>
                    Asset Intelligence Logs
                  </h3>
                  <p className="text-[9px] text-slate-500 uppercase font-bold tracking-tighter mt-1">Tactical Audit Trail // STIA_MONITOR</p>
               </div>
               <button 
                onClick={() => setShowEventLog(false)}
                className="text-slate-500 hover:text-white transition-colors"
               >
                 <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
               </button>
            </div>

            <div className="flex-grow overflow-y-auto p-4 space-y-3 bg-slate-950/30">
              {eventLogs.length > 0 ? (
                eventLogs.map((log) => (
                  <div key={log.id} className="p-3 bg-slate-900/60 rounded-xl border border-slate-800/80 flex items-start space-x-3 group hover:border-cyan-500/20 transition-all">
                    <div className="pt-1">
                       <StatusBadge status={log.status} />
                    </div>
                    <div className="flex-grow">
                       <div className="flex items-center justify-between mb-1">
                          <span className="text-[10px] font-bold text-cyan-400 mono">{log.satName}</span>
                          <span className="text-[8px] text-slate-600 mono font-bold">{log.timestamp}</span>
                       </div>
                       <p className="text-[11px] text-slate-400 leading-tight mono">{log.detail}</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center py-20 text-center">
                   <svg className="w-12 h-12 text-slate-800 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                     <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                   </svg>
                   <p className="text-[10px] font-bold text-slate-700 uppercase tracking-widest">No Intelligence Logs Recorded</p>
                </div>
              )}
            </div>

            <div className="p-4 border-t border-slate-800 bg-slate-900/50 flex justify-end space-x-3">
               <button 
                onClick={clearLogs}
                className="px-4 py-2 rounded-lg text-[9px] font-bold uppercase tracking-widest text-slate-500 hover:text-red-400 transition-colors"
               >
                 Clear Audit Trail
               </button>
               <button 
                onClick={() => setShowEventLog(false)}
                className="px-6 py-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded-lg text-[9px] font-bold uppercase tracking-widest text-slate-200 transition-all"
               >
                 Acknowledge
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Coordinates, Satellite, SatelliteStatus, WeatherCondition } from '../types.ts';
import { COMMON_SATELLITES } from '../constants.ts';

interface Props {
  loc: Coordinates;
  sat: Satellite;
  onLocChange: (loc: Coordinates) => void;
  onSatChange: (sat: Satellite) => void;
  isTracking?: boolean;
  onTrackingChange?: (val: boolean) => void;
  // EW State
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  // Weather State
  weather: WeatherCondition;
  setWeather: (val: WeatherCondition) => void;
}

interface TacticalEvent {
  id: string;
  timestamp: string;
  satName: string;
  satId: string;
  status: SatelliteStatus;
  detail: string;
}

const EVENT_LOG_STORAGE_KEY = 'satexpert_event_logs';

const StatusBadge: React.FC<{ status?: SatelliteStatus }> = ({ status }) => {
  const config = {
    active: { color: 'bg-green-500', label: 'ONLINE', pulse: true },
    offline: { color: 'bg-red-500', label: 'OFFLINE', pulse: false },
    maintenance: { color: 'bg-amber-500', label: 'MAINT', pulse: true },
    decommissioned: { color: 'bg-slate-600', label: 'EOL', pulse: false },
  }[status || 'active'];

  return (
    <div className="flex items-center space-x-1.5">
      <div className={`w-1.5 h-1.5 rounded-full ${config.color} ${config.pulse ? 'animate-pulse' : ''}`}></div>
      <span className={`text-[8px] font-bold tracking-tighter ${config.color.replace('bg-', 'text-')}`}>
        {config.label}
      </span>
    </div>
  );
};

export const TacticalHUD: React.FC<Props> = ({ 
  loc, sat, onLocChange, onSatChange, isTracking, onTrackingChange,
  isJamming, setIsJamming, jammingPower, setJammingPower,
  weather, setWeather
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [showEventLog, setShowEventLog] = useState(false);
  const [animateLabel, setAnimateLabel] = useState(false);
  const [eventLogs, setEventLogs] = useState<TacticalEvent[]>([]);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const prevSatRef = useRef<{id: string, status?: SatelliteStatus} | null>(null);

  // Added filteredSatellites variable using useMemo to filter COMMON_SATELLITES based on search query and slot
  const filteredSatellites = useMemo(() => {
    return COMMON_SATELLITES.filter(s => 
      s.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      s.orbitalSlot.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [searchQuery]);

  // Load event logs
  useEffect(() => {
    const saved = localStorage.getItem(EVENT_LOG_STORAGE_KEY);
    if (saved) {
      try {
        setEventLogs(JSON.parse(saved));
      } catch (e) {
        console.error("EVENT_LOG_LOAD_ERROR", e);
      }
    }
  }, []);

  // Save event logs
  useEffect(() => {
    localStorage.setItem(EVENT_LOG_STORAGE_KEY, JSON.stringify(eventLogs));
  }, [eventLogs]);

  // Track Satellite Status Changes & Acquisitions
  useEffect(() => {
    setAnimateLabel(true);
    const timer = setTimeout(() => setAnimateLabel(false), 600);

    const isSameSat = prevSatRef.current?.id === sat.id;
    const isStatusChanged = prevSatRef.current?.status !== sat.status;

    if (!isSameSat || isStatusChanged) {
      const newEvent: TacticalEvent = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: new Date().toLocaleString(),
        satName: sat.name,
        satId: sat.id,
        status: sat.status || 'active',
        detail: !isSameSat 
          ? `ASSET_ACQUISITION: Targeted ${sat.name} (${sat.orbitalSlot})`
          : `STATUS_RECOVERY: Asset ${sat.name} transitioned to ${sat.status?.toUpperCase()}`
      };
      setEventLogs(prev => [newEvent, ...prev].slice(0, 50)); // Keep last 50
    }

    prevSatRef.current = { id: sat.id, status: sat.status };
    return () => clearTimeout(timer);
  }, [sat.id, sat.status]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (s: Satellite) => {
    onSatChange(s);
    setSearchQuery('');
    setIsOpen(false);
  };

  const clearLogs = () => {
    setEventLogs([]);
    setShowEventLog(false);
  };

  const handleExportData = () => {
    const timestamp = new Date().toISOString();
    const content = `
[TACTICAL ASSET BRIEFING]
-------------------------
TIMESTAMP: ${timestamp}
ASSET_ID: ${sat.id}
ASSET_NAME: ${sat.name}
OPERATOR: ${sat.operator || 'UNKNOWN'}
ORBITAL_SLOT: ${sat.orbitalSlot}
LONGITUDE: ${sat.longitude}°
STATUS: ${sat.status || 'UNKNOWN'}

[ORBITAL_TELEMETRY]
APOGEE: ${sat.apogee ? sat.apogee.toLocaleString() : 'N/A'} KM
PERIGEE: ${sat.perigee ? sat.perigee.toLocaleString() : 'N/A'} KM
INCLINATION: ${sat.inclination ? sat.inclination.toFixed(4) : 'N/A'}°
VELOCITY: ${sat.velocity ? sat.velocity.toFixed(4) : 'N/A'} KM/S

[DEPLOYMENT_CONTEXT]
USER_LAT: ${loc.lat.toFixed(6)}
USER_LNG: ${loc.lng.toFixed(6)}
WEATHER_SIM: ${weather}

[SECURITY_POSTURE]
EW_INTERFERENCE: ${isJamming ? 'ACTIVE' : 'STANDBY'}
JAM_POWER: ${jammingPower}%
-------------------------
EOF // ENCRYPTED_BRIEF
`;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `SAT_BRIEF_${sat.id}_${Date.now()}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const weatherIcons = {
    CLEAR: '☀️',
    OVERCAST: '☁️',
    LIGHT_RAIN: '🌧️',
    HEAVY_STORM: '⛈️'
  };

  return (
    <div className="glass rounded-2xl p-6 border-slate-800 relative z-50">
      <div className="space-y-4">
        <div className="relative" ref={dropdownRef}>
          <div className="flex items-center justify-between mb-1">
            <label className={`block text-[9px] font-bold uppercase tracking-widest transition-all duration-300 transform ${
              animateLabel 
                ? 'text-cyan-400 scale-105 drop-shadow-[0_0_8px_rgba(34,211,238,0.6)]' 
                : 'text-slate-500'
            }`}>
              Target Acquisition
            </label>
            <div className="flex items-center space-x-2">
              <button 
                onClick={() => setShowEventLog(true)}
                className="flex items-center space-x-1 px-2 py-0.5 rounded border border-slate-800 bg-slate-900 text-[8px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/30 transition-all uppercase tracking-tighter"
              >
                <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                </svg>
                <span>Logs</span>
              </button>
              <button 
                onClick={handleExportData}
                className="flex items-center space-x-1 px-2 py-0.5 rounded border border-slate-800 bg-slate-900 text-[8px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/30 transition-all uppercase tracking-tighter"
                title="Export Asset Brief"
              >
                <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
                <span>Export</span>
              </button>
            </div>
          </div>

          <div className="relative">
            <input
              type="text"
              placeholder={isOpen ? "ENTER SATELLITE NAME OR SLOT..." : sat.name}
              className={`w-full bg-slate-950 border ${isOpen ? 'border-cyan-500 shadow-[0_0_10px_rgba(34,211,238,0.2)]' : 'border-slate-800'} rounded-lg p-2.5 pl-9 text-xs text-white outline-none transition-all mono placeholder:text-slate-600`}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setIsOpen(true);
              }}
              onFocus={() => setIsOpen(true)}
            />
            <div className="absolute left-3 top-1/2 -translate-y-1/2">
              <svg className={`w-4 h-4 ${isOpen ? 'text-cyan-400' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center">
               {!isOpen && <StatusBadge status={sat.status} />}
            </div>
          </div>

          {isOpen && (
            <div className="absolute mt-2 w-full glass bg-slate-950/95 border border-cyan-500/30 rounded-xl shadow-2xl overflow-hidden max-h-[300px] flex flex-col z-[100]">
              <div className="bg-cyan-500/5 px-4 py-2 border-b border-slate-800/50">
                <span className="text-[8px] font-bold text-cyan-400 uppercase tracking-widest">Results Found: {filteredSatellites.length}</span>
              </div>
              <div className="overflow-y-auto scrollbar-hide py-1">
                {filteredSatellites.length > 0 ? (
                  filteredSatellites.map((s) => (
                    <button
                      key={s.id}
                      onClick={() => handleSelect(s)}
                      className={`w-full text-left px-4 py-3 hover:bg-cyan-500/10 transition-colors flex items-center justify-between group border-b border-slate-900/50 last:border-none ${s.id === sat.id ? 'bg-cyan-500/5' : ''}`}
                    >
                      <div className="flex flex-col">
                        <div className="flex items-center space-x-2">
                           <span className={`text-[11px] font-bold tracking-wide ${s.id === sat.id ? 'text-cyan-400' : 'text-slate-300 group-hover:text-cyan-200'}`}>{s.name}</span>
                           <StatusBadge status={s.status} />
                        </div>
                        <span className="text-[9px] text-slate-500 mono group-hover:text-slate-400">{s.operator || 'UNKNOWN OPERATOR'}</span>
                      </div>
                      <div className="flex flex-col items-end">
                        <span className="text-[10px] text-cyan-500 font-mono font-bold tracking-tighter">{s.orbitalSlot}</span>
                      </div>
                    </button>
                  ))
                ) : (
                  <div className="px-4 py-8 text-center">
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">No matching assets found</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Asset Identity Block */}
        <div className="bg-slate-950/50 rounded-xl border border-slate-800/50 p-3 flex items-center justify-between animate-in fade-in slide-in-from-top-1 duration-300">
          <div className="flex flex-col">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Operator Authority</span>
            <span className="text-[10px] font-bold text-slate-200 mono truncate max-w-[120px]">
              {sat.operator || 'UNSPECIFIED'}
            </span>
          </div>
          <div className="h-8 w-px bg-slate-800/50 mx-2"></div>
          <div className="flex flex-col items-center px-2">
             <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Link State</span>
             <StatusBadge status={sat.status} />
          </div>
          <div className="h-8 w-px bg-slate-800/50 mx-2"></div>
          <div className="flex flex-col items-end text-right">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Orbital Slot</span>
            <div className="flex items-center space-x-2">
              <span className="text-[10px] font-bold text-cyan-400 mono">{sat.orbitalSlot}</span>
              <div className="w-1.5 h-1.5 bg-cyan-500/50 rounded-full animate-pulse"></div>
            </div>
          </div>
        </div>

        {/* Atmospheric Dynamics Block */}
        <div className="bg-slate-950/60 rounded-xl border border-slate-800 p-3 space-y-3 animate-in fade-in slide-in-from-top-1 duration-500">
          <div className="flex items-center justify-between">
             <span className="text-[8px] font-black text-cyan-500/80 uppercase tracking-[0.2em]">Atmospheric_Dynamics</span>
             <div className="flex items-center space-x-1">
                <span className="text-[7px] text-slate-600 mono uppercase tracking-tighter">SIM: Ka-BAND_RAIN_FADE</span>
             </div>
          </div>
          <div className="grid grid-cols-4 gap-1">
            {(['CLEAR', 'OVERCAST', 'LIGHT_RAIN', 'HEAVY_STORM'] as WeatherCondition[]).map((cond) => (
              <button 
                key={cond}
                onClick={() => setWeather(cond)}
                className={`flex flex-col items-center justify-center p-2 rounded-lg border transition-all ${
                  weather === cond 
                    ? 'bg-cyan-500/10 border-cyan-500 text-cyan-400 shadow-[0_0_10px_rgba(34,211,238,0.2)]' 
                    : 'bg-slate-900/50 border-slate-800 text-slate-600 hover:border-slate-700'
                }`}
              >
                <span className="text-sm mb-1">{weatherIcons[cond]}</span>
                <span className="text-[6px] font-bold uppercase tracking-tighter">{cond.replace('_', ' ')}</span>
              </button>
            ))}
          </div>
          <div className="flex justify-between items-center text-[8px] font-mono border-t border-slate-800/50 pt-2">
             <div className="flex flex-col">
               <span className="text-slate-500 uppercase">Attenuation</span>
               <span className={`${weather === 'HEAVY_STORM' ? 'text-red-500 animate-pulse' : 'text-cyan-400'}`}>
                 {weather === 'CLEAR' ? '0.5' : weather === 'OVERCAST' ? '1.8' : weather === 'LIGHT_RAIN' ? '4.5' : '12.0'} dB
               </span>
             </div>
             <div className="flex flex-col text-right">
               <span className="text-slate-500 uppercase">Humidity</span>
               <span className="text-slate-300">{weather === 'CLEAR' ? '12%' : weather === 'OVERCAST' ? '45%' : '88%'}</span>
             </div>
          </div>
        </div>

        {/* Electronic Warfare Override */}
        <div className={`rounded-xl border p-3 space-y-3 transition-all duration-300 ${isJamming ? 'bg-red-950/20 border-red-500/40 shadow-[0_0_15px_rgba(239,68,68,0.1)]' : 'bg-slate-950/40 border-slate-800'}`}>
          <div className="flex items-center justify-between">
            <div className="flex flex-col">
              <span className={`text-[8px] font-black uppercase tracking-[0.2em] ${isJamming ? 'text-red-500' : 'text-slate-500'}`}>EW_Signal_Override</span>
              <span className="text-[7px] text-slate-600 mono">MODE: RF_CONTINUOUS_WAVE</span>
            </div>
            <button 
              onClick={() => setIsJamming(!isJamming)}
              className={`px-3 py-1 rounded-md text-[9px] font-bold uppercase transition-all ${isJamming ? 'bg-red-600 text-white shadow-lg animate-pulse' : 'bg-slate-800 text-slate-500 hover:text-slate-300'}`}
            >
              {isJamming ? 'Engaged' : 'Standby'}
            </button>
          </div>

          <div className="space-y-2">
            <div className="flex items-center justify-between text-[8px] font-bold mono">
              <span className={isJamming ? 'text-red-400' : 'text-slate-600'}>INTENSITY: {jammingPower}%</span>
              <span className={isJamming ? 'text-red-400' : 'text-slate-600'}>SNR_LOSS: -{(jammingPower / 5).toFixed(1)} dB</span>
            </div>
            <input 
              type="range" 
              min="0" max="100" 
              value={jammingPower} 
              onChange={(e) => setJammingPower(parseInt(e.target.value))}
              className={`w-full h-1 rounded-lg appearance-none cursor-pointer transition-all ${isJamming ? 'bg-red-900/50 accent-red-500' : 'bg-slate-800 accent-slate-600'}`}
            />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3 mt-4">
           <div className="group">
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-1 tracking-widest group-hover:text-cyan-500 transition-colors">Deployment Lat</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  disabled={isTracking}
                  className={`w-full bg-slate-950 p-2.5 text-xs rounded-lg border text-cyan-400 outline-none mono transition-all ${isTracking ? 'border-cyan-500/30 opacity-50' : 'border-slate-800 focus:border-cyan-500/50'}`} 
                  value={loc.lat} 
                  onChange={e => onLocChange({...loc, lat: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-700 font-bold">N/S</span>
              </div>
           </div>
           <div className="group">
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-1 tracking-widest group-hover:text-cyan-500 transition-colors">Deployment Lng</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  disabled={isTracking}
                  className={`w-full bg-slate-950 p-2.5 text-xs rounded-lg border text-cyan-400 outline-none mono transition-all ${isTracking ? 'border-cyan-500/30 opacity-50' : 'border-slate-800 focus:border-cyan-500/50'}`} 
                  value={loc.lng} 
                  onChange={e => onLocChange({...loc, lng: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-700 font-bold">E/W</span>
              </div>
           </div>
        </div>
      </div>

      {/* Event Log Modal */}
      {showEventLog && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="glass w-full max-w-lg rounded-3xl border border-slate-700 shadow-2xl flex flex-col max-h-[80vh] overflow-hidden">
            <div className="p-6 border-b border-slate-800 flex items-center justify-between bg-slate-900/50">
               <div>
                  <h3 className="text-sm font-bold text-white uppercase tracking-widest flex items-center">
                    <span className="w-2 h-2 bg-cyan-500 rounded-full mr-2 animate-pulse"></span>
                    Asset Intelligence Logs
                  </h3>
                  <p className="text-[9px] text-slate-500 uppercase font-bold tracking-tighter mt-1">Tactical Audit Trail // STIA_MONITOR</p>
               </div>
               <button 
                onClick={() => setShowEventLog(false)}
                className="text-slate-500 hover:text-white transition-colors"
               >
                 <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
               </button>
            </div>

            <div className="flex-grow overflow-y-auto p-4 space-y-3 bg-slate-950/30">
              {eventLogs.length > 0 ? (
                eventLogs.map((log) => (
                  <div key={log.id} className="p-3 bg-slate-900/60 rounded-xl border border-slate-800/80 flex items-start space-x-3 group hover:border-cyan-500/20 transition-all">
                    <div className="pt-1">
                       <StatusBadge status={log.status} />
                    </div>
                    <div className="flex-grow">
