import { GoogleGenAI, Modality } from "@google/genai";

let audioCtx: AudioContext | null = null;

const getAudioContext = () => {
  if (!audioCtx) {
    audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  }
  return audioCtx;
};

const decodeBase64 = (base64: string) => {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

const decodeAudioData = async (
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number
): Promise<AudioBuffer> => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
};

export const playSystemVoice = async (text: string) => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Announce with military precision: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) return;

    const ctx = getAudioContext();
    if (ctx.state === 'suspended') await ctx.resume();

    const audioData = decodeBase64(base64Audio);
    const audioBuffer = await decodeAudioData(audioData, ctx, 24000, 1);

    const source = ctx.createBufferSource();
    const gainNode = ctx.createGain();
    gainNode.gain.value = 0.5;

    source.buffer = audioBuffer;
    source.connect(gainNode);
    gainNode.connect(ctx.destination);
    source.start();
  } catch (error) {
    console.warn("VOICE_UPLINK_ERROR: AI Voice unavailable.", error);
  }
};

import { GoogleGenAI } from "@google/genai";

export const getTroubleshootingAdvice = async (issue: string, context?: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are the 'SatExpert Tactical Intelligence Agent' (STIA).
    You work for a high-stakes global satellite security firm.
    MISSION_OBJECTIVE: Provide technical, field-ready SatCom intelligence.

    CURRENT_ENVIRONMENT:
    - LATITUDE: ${context?.lat ?? 'N/A'}
    - LONGITUDE: ${context?.lng ?? 'N/A'}
    - TARGET_ASSET: ${context?.satName ?? 'N/A'}
    - DEFCON_STATUS: ${context?.defcon ?? 5}

    TONE: Professional, concise, military-grade technical depth. Use codes like [ROOT_CAUSE], [FIELD_RESOLUTION], and [STEALTH_ADVICE].

    SPECIAL_CAPABILITIES:
    - If user mentions interference, use Google Search for regional solar flares, space weather, or local signal jamming news.
    - If user mentions ground stations, teleports, or location-based logistics, use Google Maps grounding.
    - If DEFCON < 3, suggest aggressive carrier-shielding and modem-hardening.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: "USER_COMMAND: " + issue,
      config: {
        systemInstruction,
        tools: [{ googleSearch: {} }, { googleMaps: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: context?.lat && context?.lng ? {
              latitude: context.lat,
              longitude: context.lng
            } : undefined
          }
        }
      },
    });

    let output = response.text || "";

    // Process and format references
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0) {
      output += "\n\n[TACTICAL_SOURCES_IDENTIFIED]:\n";
      chunks.forEach((chunk: any) => {
        if (chunk.web) output += `- [Search] ${chunk.web.title}: ${chunk.web.uri}\n`;
        if (chunk.maps) output += `- [Map] ${chunk.maps.title}: ${chunk.maps.uri}\n`;
      });
    }

    return output;
  } catch (error) {
    console.error("STIA_SYSTEM_ERROR", error);
    return "SYSTEM_HALT: COMM_TIMEOUT. Verify API uplink.";
  }
};

