                        <option value="EXPLOIT">EXPLOIT_PAYLOAD</option>
                        <option value="DOS">DENIAL_OF_SERVICE</option>
                      </select>
                    </div>
                  </div>
                  <button onClick={runIpAttack} disabled={isIpAttacking} className="w-full bg-red-600 hover:bg-red-500 disabled:opacity-30 text-white text-[10px] font-bold py-3 rounded-xl uppercase tracking-widest shadow-lg shadow-red-500/10">
                    {isIpAttacking ? 'MISSION_IN_PROGRESS...' : 'COMMENCE_STRIKE'}
                  </button>
                  <div ref={terminalRef} className="bg-slate-950 p-4 rounded-xl h-[240px] overflow-y-auto font-mono text-[9px] border border-slate-900 shadow-inner">
                    {ipAttackLog.length === 0 ? <div className="h-full flex flex-col items-center justify-center text-slate-700 italic">WAITING FOR MISSION PARAMETERS...</div> : (
                      <div className="space-y-1">
                        {ipAttackLog.map((log, i) => (
                          <div key={i} className="flex space-x-2"><span className="text-slate-600 shrink-0">[{log.time}]</span><span className={getLogColor(log.type)}>{log.msg}</span></div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
            <div className="space-y-6">
              <div className="glass p-6 rounded-2xl border-slate-800 border-l-4 border-l-red-500/50">
                <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Jamming Control</h4>
                <div className="space-y-2">
                  <div className="flex justify-between text-[9px] font-bold mono text-slate-600"><span>Power Intensity</span><span>{jammingPower}%</span></div>
                  <input type="range" min="0" max="100" value={jammingPower} onChange={(e) => setJammingPower(parseInt(e.target.value))} className={`w-full h-1 rounded-lg appearance-none cursor-pointer transition-all ${isJamming ? 'bg-red-900/50 accent-red-500' : 'bg-slate-800 accent-slate-600'}`} />
                </div>
                <button onClick={() => setIsJamming(!isJamming)} className={`w-full mt-4 py-3 rounded-xl font-bold text-xs uppercase transition-all ${isJamming ? 'bg-red-600 text-white shadow-[0_0_20px_rgba(239,68,68,0.3)]' : 'bg-slate-800 text-red-500 border border-red-500/20 hover:bg-red-950/10'}`}>
                  {isJamming ? 'Halt Transmission' : 'Engage EW Jammer'}
                </button>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'detection' && (
          <div className="glass p-6 rounded-2xl border-slate-800">
            <div className="flex items-center justify-between mb-6">
              <div><h3 className="text-white font-bold uppercase text-sm tracking-widest">Link Monitoring Service</h3></div>
              <button onClick={runThreatScan} disabled={isScanning} className="bg-cyan-600 hover:bg-cyan-500 disabled:opacity-30 text-slate-950 font-bold px-6 py-2 rounded-lg text-[10px] uppercase tracking-widest shadow-lg">
                {isScanning ? 'Synchronizing Sensors...' : 'Start Global Scan'}
              </button>
            </div>
            <div className="space-y-3">
              {detectionLogs.map((log) => (
                <div key={log.id} className="bg-slate-950 p-4 rounded-xl border border-slate-800/50">
                  <div className="flex items-center justify-between mb-2">
                    <span className={`text-[8px] font-bold px-2 py-0.5 rounded uppercase ${log.severity === 'HIGH' ? 'bg-red-500 text-white' : log.severity === 'MED' ? 'bg-amber-500 text-black' : 'bg-blue-500 text-white'}`}>{log.severity}_SEVERITY</span>
                    <span className="text-[10px] font-bold text-white uppercase">{log.type}</span>
                  </div>
                  <p className="text-[10px] text-slate-400 mono">{log.msg}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'hardening' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-8 space-y-4">
              <div className="glass p-6 rounded-2xl border-slate-800">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {hardeningOptions.map((opt) => (
                    <div key={opt.id} onClick={() => toggleHardening(opt.id)} className={`group flex items-center p-4 rounded-xl border cursor-pointer transition-all duration-300 ${opt.enabled ? 'bg-green-500/10 border-green-500/40 shadow-[0_0_20px_rgba(34,197,94,0.1)]' : 'bg-slate-950/40 border-slate-800 hover:border-slate-700'}`}>
                      <div className={`w-5 h-5 rounded border flex items-center justify-center shrink-0 transition-all ${opt.enabled ? 'bg-green-500 border-green-500 scale-110' : 'border-slate-700'}`}>
                        {opt.enabled && <svg className="w-3.5 h-3.5 text-slate-950" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={4}><path d="M5 13l4 4L19 7" /></svg>}
                      </div>
                      <div className="ml-4">
                        <div className={`text-[10px] font-bold uppercase tracking-wide ${opt.enabled ? 'text-green-400' : 'text-slate-300'}`}>{opt.label}</div>
                        <p className="text-[9px] text-slate-500 mt-0.5 leading-tight">{opt.description}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
            <div className="lg:col-span-4 glass p-8 rounded-2xl border-slate-800 h-full flex flex-col items-center justify-center text-center relative overflow-hidden">
              <div className="relative w-40 h-40 flex items-center justify-center mb-6">
                <svg className="w-full h-full transform -rotate-90">
                  <circle cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-900" />
                  <circle cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={440} strokeDashoffset={440 - (440 * complianceScore) / 100} className={`transition-all duration-1000 ease-out ${gradeInfo.color.replace('text-', 'stroke-')}`} strokeLinecap="round" />
                </svg>
                <div className="absolute flex flex-col items-center justify-center">
                  <div className={`text-4xl font-black mono transition-colors duration-500 ${gradeInfo.color}`}>{complianceScore}%</div>
                  <div className={`text-xs font-bold uppercase tracking-[0.2em] mt-1 opacity-60 ${gradeInfo.color}`}>Grade: {gradeInfo.grade}</div>
                </div>
              </div>
              <div className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.3em]">Compliance Rating</div>
            </div>
          </div>
        )}

        {activeTab === 'intel' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-2xl border-slate-800">
              <input id="hw-search" placeholder="Enter Asset Model or Location Query..." className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-white mono mb-4 outline-none" />
              <button onClick={() => fetchThreatIntel((document.getElementById('hw-search') as HTMLInputElement).value)} disabled={intelLoading} className="w-full py-3 bg-cyan-600 text-slate-950 font-bold text-[10px] uppercase tracking-widest rounded-xl shadow-lg">
                {intelLoading ? 'QUERING_STRATEGIC_DATABASE...' : 'Query Threat Database'}
              </button>
            </div>
            {outputs.intel && (
              <div className="animate-in fade-in slide-in-from-top-2 duration-700">
                <pre className="bg-slate-950 p-6 rounded-2xl border border-slate-800 text-cyan-400 text-[11px] font-mono whitespace-pre-wrap leading-relaxed max-h-[500px] overflow-auto shadow-inner">
                  {outputs.intel}
                </pre>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { getTroubleshootingAdvice } from '../services/geminiService.ts';

interface Props {
  userLoc: { lat: number, lng: number };
  selectedSatName: string;
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  signalQuality: number;
  onBack?: () => void;
}

interface HardeningOption {
  id: string;
  label: string;
  description: string;
  enabled: boolean;
}

interface IPLogEntry {
  time: string;
  msg: string;
  type: 'INFO' | 'WARN' | 'SUCCESS' | 'FAIL';
}

type AttackVector = 'SCAN' | 'EXPLOIT' | 'DOS';

const HARDENING_STORAGE_KEY = 'satexpert_hardening_state';

export const SecurityTools: React.FC<Props> = ({ 
  userLoc, 
  selectedSatName,
  isJamming,
  setIsJamming,
  jammingPower,
  setJammingPower,
  signalQuality,
  onBack
}) => {
  const [activeTab, setActiveTab] = useState<string>('overview');
  const [outputs, setOutputs] = useState<Record<string, string>>({});
  const [intelLoading, setIntelLoading] = useState(false);

  // Codes States
  const [authCodes, setAuthCodes] = useState({ 
    uplink: 'ST-A7X', 
    downlink: 'BK-92Z', 
    telemetry: 'XP-11Q', 
    expire: 30 
  });
  const [revealed, setRevealed] = useState<Record<string, boolean>>({ uplink: false, downlink: false, telemetry: false });
  const [keyRotation, setKeyRotation] = useState(1);

  // Attack States
  const [spoofFrame, setSpoofFrame] = useState('');
  const [targetIp, setTargetIp] = useState('192.168.1.100');
  const [ipAttackLog, setIpAttackLog] = useState<IPLogEntry[]>([]);
  const [isIpAttacking, setIsIpAttacking] = useState(false);
  const [attackVector, setAttackVector] = useState<AttackVector>('SCAN');
  const [attackOutcome, setAttackOutcome] = useState<string | null>(null);

  // Detection States
  const [detectionLogs, setDetectionLogs] = useState<{id: string, type: string, severity: 'LOW' | 'MED' | 'HIGH', msg: string, mitigation: string}[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  // Hardening States
  const [hardeningOptions, setHardeningOptions] = useState<HardeningOption[]>([
    { id: 'telnet', label: 'Disable Telnet', description: 'Terminate unencrypted legacy remote access port 23.', enabled: false },
    { id: 'ssh', label: 'Enable SSH v2', description: 'Enforce encrypted administrative access via RSA/ED25519 keys.', enabled: false },
    { id: 'encryption', label: 'Stronger Encryption', description: 'Upgrade air interface to AES-256 and enforce FIPS 140-2.', enabled: false },
    { id: 'firmware', label: 'Firmware Integrity', description: 'Enable secure boot and cryptographic hash validation.', enabled: false },
    { id: 'ports', label: 'Disable Unused Ports', description: 'Seal non-essential logical ports and audit open services.', enabled: false },
    { id: 'rate-limiting', label: 'Implement Rate Limiting', description: 'Prevent DoS/DDoS by throttling excessive packet requests.', enabled: false },
    { id: 'firmware-mandatory', label: 'Mandatory Firmware Updates', description: 'Enforce automatic signed updates to patch zero-day vulnerabilities.', enabled: false },
    { id: 'segmentation', label: 'Network Segmentation', description: 'Isolate management and user traffic into distinct VLANs.', enabled: false },
  ]);

  const terminalRef = useRef<HTMLDivElement>(null);
  const isFirstRender = useRef(true);

  // Load hardening state
  useEffect(() => {
    const saved = localStorage.getItem(HARDENING_STORAGE_KEY);
    if (saved) {
      try {
        setHardeningOptions(JSON.parse(saved));
      } catch (e) { console.error("HARDENING_LOAD_ERR", e); }
    }
  }, []);

  // Save hardening state
  useEffect(() => {
    if (isFirstRender.current) return;
    localStorage.setItem(HARDENING_STORAGE_KEY, JSON.stringify(hardeningOptions));
  }, [hardeningOptions]);

  const generateNewCodes = () => {
    setKeyRotation(r => r + 1);
    setAuthCodes({
      uplink: Math.random().toString(36).substr(2, 6).toUpperCase(),
      downlink: Math.random().toString(36).substr(2, 6).toUpperCase(),
      telemetry: Math.random().toString(36).substr(2, 6).toUpperCase(),
      expire: 30
    });
    // Re-mask on rotate
    setRevealed({ uplink: false, downlink: false, telemetry: false });
  };

  // Auth Code Rotation Logic
  useEffect(() => {
    const interval = setInterval(() => {
      setAuthCodes(prev => {
        if (prev.expire <= 1) {
          generateNewCodes();
          return { ...prev, expire: 30 }; // This is redundant but helps with React state batching safety
        }
        return { ...prev, expire: prev.expire - 1 };
      });
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (terminalRef.current) terminalRef.current.scrollTop = terminalRef.current.scrollHeight;
  }, [ipAttackLog]);

  const addIpLog = (msg: string, type: IPLogEntry['type'] = 'INFO') => {
    const time = new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
    setIpAttackLog(prev => [...prev, { time, msg, type }]);
  };

  useEffect(() => {
    if (isFirstRender.current) return;
    const status = isJamming ? 'ENGAGED' : 'STANDBY';
    addIpLog(`EW_SIGNAL_STATUS_CHANGE: ${status}`, 'WARN');
  }, [isJamming]);

  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    addIpLog(`EW_INTENSITY_ADJUSTED: ${jammingPower}%`, 'INFO');
  }, [jammingPower]);

  const runIpAttack = () => {
    if (!targetIp || isIpAttacking) return;
    setIsIpAttacking(true);
    setAttackOutcome(null);
    setIpAttackLog([]);
    addIpLog(`STRIKE_PROTOCOL_INITIALIZED: VECTOR[${attackVector}] TARGET[${targetIp}]`, 'INFO');
    let sequence: { msg: string, type: IPLogEntry['type'] }[] = [];
    if (attackVector === 'SCAN') {
      sequence = [{ msg: "STARTING_RECONNAISSANCE: PROBING_TCP_STACK...", type: 'INFO' }, { msg: "PORT_DETECTED: 22 [SSH] - STATE_OPEN", type: 'SUCCESS' }, { msg: "PORT_DETECTED: 80 [HTTP] - STATE_FILTERED", type: 'WARN' }, { msg: "SCAN_COMPLETE: TARGET_SURFACE_MAPPED", type: 'SUCCESS' }];
    } else if (attackVector === 'EXPLOIT') {
      sequence = [{ msg: "STAGING_EXPLOIT: RCE_CVE_2024_SATELLITE_LINK", type: 'WARN' }, { msg: "CALCULATING_OFFSET: MEMORY_ALIGNMENT_0xDEADBEEF", type: 'INFO' }, { msg: "SENDING_PAYLOAD: MALICIOUS_HEADER_PULSE...", type: 'INFO' }, { msg: "INITIATING_SHELL: REVERSE_LINK_ESTABLISHED", type: 'SUCCESS' }];
    } else if (attackVector === 'DOS') {
      sequence = [{ msg: "COMMENCING_FLOOD: UDP_PACKET_STORM_INITIATED", type: 'WARN' }, { msg: "BANDWIDTH_CONSUMPTION: 450Mbps_AND_RISING", type: 'INFO' }, { msg: "TARGET_STATE: CONNECTION_TIMEOUT_DETECTION", type: 'FAIL' }, { msg: "OUTCOME: SERVICE_UNAVAILABLE_SUCCESS", type: 'SUCCESS' }];
    }
    let i = 0;
    const interval = window.setInterval(() => {
      if (i >= sequence.length) {
        setAttackOutcome(attackVector === 'SCAN' ? "SCAN_SUCCESSFUL" : attackVector === 'EXPLOIT' ? "TARGET_BREACHED" : "DENIAL_CONFIRMED");
        setIsIpAttacking(false);
        clearInterval(interval);
        return;
      }
      addIpLog(sequence[i].msg, sequence[i].type);
      i++;
    }, 800);
  };

  const fetchThreatIntel = async (query: string) => {
    if (!query || intelLoading) return;
    setIntelLoading(true);
    try {
      const advice = await getTroubleshootingAdvice(query, { lat: userLoc.lat, lng: userLoc.lng, satName: selectedSatName });
      setOutputs(prev => ({ ...prev, intel: advice || "NO_DATA_RETURNED" }));
    } catch (error) {
      setOutputs(prev => ({ ...prev, intel: "SYSTEM_FAILURE: INTELLIGENCE_UPLINK_TIMEOUT." }));
    } finally {
      setIntelLoading(false);
    }
  };

  const runThreatScan = () => {
    setIsScanning(true);
    setDetectionLogs([]);
    setTimeout(() => {
      setDetectionLogs([{ id: 'DT-01', type: 'RF_ANOMALY', severity: 'LOW', msg: 'Abnormal noise floor deviation at 14.2GHz', mitigation: 'Check hardware grounding.' }, { id: 'DT-02', type: 'AUTH_FAILURE', severity: 'MED', msg: 'Multiple failed SSH attempts from 10.0.0.42', mitigation: 'Enable Fail2Ban.' }, { id: 'DT-03', type: 'ENCRYPTION', severity: 'HIGH', msg: 'Clear-text traffic detected', mitigation: 'Enforce HTTPS/SSH immediately.' }]);
      setIsScanning(false);
    }, 2000);
  };

  const toggleHardening = (id: string) => {
    setHardeningOptions(prev => prev.map(opt => opt.id === id ? { ...opt, enabled: !opt.enabled } : opt));
  };

  const complianceScore = Math.round((hardeningOptions.filter(o => o.enabled).length / hardeningOptions.length) * 100);
  const getComplianceGrade = (score: number) => {
    if (score >= 95) return { grade: 'A+', color: 'text-green-400' };
    if (score >= 85) return { grade: 'A', color: 'text-green-500' };
    if (score >= 70) return { grade: 'B', color: 'text-cyan-400' };
    if (score >= 50) return { grade: 'C', color: 'text-amber-400' };
    if (score >= 25) return { grade: 'D', color: 'text-orange-500' };
    return { grade: 'F', color: 'text-red-500' };
  };
  const gradeInfo = getComplianceGrade(complianceScore);

  const getLogColor = (type: IPLogEntry['type']) => {
    switch(type) {
      case 'SUCCESS': return 'text-green-400';
      case 'FAIL': return 'text-red-500';
      case 'WARN': return 'text-amber-400';
      default: return 'text-slate-400';
    }
  };

  const toggleReveal = (key: string) => {
    setRevealed(prev => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex items-center justify-between mb-2">
        <h2 className="text-2xl font-bold flex items-center text-white uppercase tracking-tight">
          <span className="mr-3">🛡️</span> Security <span className="text-cyan-400 ml-2">Intelligence</span>
        </h2>
        {onBack && (
          <button onClick={onBack} className="flex items-center space-x-2 bg-slate-800 hover:bg-slate-700 text-[10px] font-bold text-slate-300 px-4 py-2 rounded-xl border border-slate-700 transition-all uppercase tracking-widest">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            <span>Mission Command</span>
          </button>
        )}
      </header>

      <div className="flex flex-wrap gap-2 border-b border-slate-800 pb-px">
        {['overview', 'attack', 'codes', 'intel', 'detection', 'hardening'].map((id) => (
          <button key={id} onClick={() => setActiveTab(id)} className={`px-4 py-2 text-[10px] font-bold uppercase tracking-widest transition-all border-b-2 ${activeTab === id ? 'border-cyan-500 text-cyan-400 bg-cyan-500/5' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
            {id}
          </button>
        ))}
      </div>

      <div className="py-4">
        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="glass p-6 rounded-2xl border-slate-800 hover:border-red-500/50 transition-all cursor-pointer group" onClick={() => setActiveTab('attack')}>
              <div className="w-10 h-10 bg-red-950/20 rounded-lg flex items-center justify-center border border-red-500/30 mb-4">
                <svg className="w-6 h-6 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              </div>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Offensive Ops</h3>
              <p className="text-xs text-slate-400">Jamming, IP Exploits, and Signal Hijacking.</p>
            </div>
            <div className="glass p-6 rounded-2xl border-slate-800 hover:border-cyan-500 transition-all cursor-pointer group" onClick={() => setActiveTab('detection')}>
              <div className="w-10 h-10 bg-cyan-950/20 rounded-lg flex items-center justify-center border border-cyan-500/30 mb-4">
                <svg className="w-6 h-6 text-cyan-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
              </div>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Signal Detection</h3>
              <p className="text-xs text-slate-400">Real-time monitoring for unauthorized uplinks.</p>
            </div>
            <div className="glass p-6 rounded-2xl border-slate-800 hover:border-amber-500/50 transition-all cursor-pointer group" onClick={() => setActiveTab('hardening')}>
              <div className="w-10 h-10 bg-amber-950/20 rounded-lg flex items-center justify-center border border-amber-500/30 mb-4">
                <svg className="w-6 h-6 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
              </div>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Hardening</h3>
              <p className="text-xs text-slate-400">Enforce FIPS compliance and port security.</p>
            </div>
          </div>
        )}

        {activeTab === 'codes' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in slide-in-from-bottom-2">
            <div className="glass p-8 rounded-3xl border-slate-800 flex flex-col justify-between relative overflow-hidden">
               {/* Background Sync Pulse */}
               <div className="absolute top-0 right-0 p-4">
                 <div className="flex items-center space-x-2">
                    <span className="text-[8px] font-bold text-slate-600 uppercase tracking-widest">Uplink_Sync</span>
                    <div className="w-2 h-2 rounded-full bg-cyan-500 animate-ping"></div>
                 </div>
               </div>

               <div>
                  <h3 className="text-white font-bold uppercase text-sm tracking-widest mb-1">Rolling One-Time-Pad</h3>
                  <p className="text-[10px] text-slate-500 uppercase mono mb-8">Protocol: AES-256-OTP // ASSET_SECURE_LINK</p>

                  <div className="space-y-6">
                    {(['uplink', 'downlink', 'telemetry'] as const).map((key) => (
                      <div key={key} className="flex justify-between items-center border-b border-slate-900 pb-4 group">
                         <div className="flex flex-col">
                           <span className="text-[9px] font-bold text-slate-600 uppercase mb-1">{key.replace('_', ' ')} Command</span>
                           <button 
                             onClick={() => toggleReveal(key)}
                             className="text-[8px] font-bold text-cyan-500 hover:text-cyan-300 uppercase tracking-tighter text-left"
                           >
                             {revealed[key] ? '[MASK_TOKEN]' : '[REVEAL_TOKEN]'}
                           </button>
                         </div>
                         <span className={`text-2xl font-black mono tracking-widest transition-all duration-300 ${
                           revealed[key] 
                            ? (key === 'uplink' ? 'text-cyan-400' : key === 'downlink' ? 'text-amber-400' : 'text-slate-200')
                            : 'text-slate-800 blur-sm select-none'
                         }`}>
                           {revealed[key] ? authCodes[key] : 'XXXXXX'}
                         </span>
                      </div>
                    ))}
                  </div>
               </div>

               <div className="mt-8">
                  <div className="flex justify-between text-[8px] font-bold mono text-slate-600 mb-2">
                    <span>KEY_EXPIRATION_TIMER</span>
                    <span className={authCodes.expire < 10 ? 'text-red-500 animate-pulse' : ''}>{authCodes.expire}S</span>
