                       <span className="text-green-500">+0.002ms</span>
                    </div>
                    <div className="flex justify-between text-[9px] mono border-b border-slate-900 pb-2">
                       <span className="text-slate-500">Entropy Source</span>
                       <span className="text-cyan-500">TRNG_ST-9</span>
                    </div>
                    <div className="flex justify-between text-[9px] mono border-b border-slate-900 pb-2">
                       <span className="text-slate-500">Sync Status</span>
                       <span className="text-green-500 font-bold">LOCKED</span>
                    </div>
                  </div>

                  <div className="mt-6 space-y-2">
                    <span className="text-[8px] font-bold text-slate-700 uppercase tracking-widest">Recent Audit Log</span>
                    <div className="space-y-1 max-h-24 overflow-y-auto pr-2 scrollbar-hide">
                      {[...Array(5)].map((_, i) => (
                        <div key={i} className="flex justify-between text-[8px] mono text-slate-700">
                           <span>ROTATION_ENTRY_{keyRotation - i}</span>
                           <span>[OK]</span>
                        </div>
                      ))}
