import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { Layout } from './components/Layout.tsx';
import { LookAngleCard } from './components/LookAngleCard.tsx';
import { AITechnician } from './components/AITechnician.tsx';
import { SecurityTools } from './components/SecurityTools.tsx';
import { LinkBudgetCalculator } from './components/LinkBudgetCalculator.tsx';
import { SignalVisualizer } from './components/SignalVisualizer.tsx';
import { TacticalHUD } from './components/TacticalHUD.tsx';
import { TacticalMap } from './components/TacticalMap.tsx';
import { RSSReader } from './components/RSSReader.tsx';
import { Coordinates, Satellite, LookAngles, WeatherCondition } from './types.ts';
import { COMMON_SATELLITES } from './constants.ts';
import { calculateLookAngles } from './utils/geoUtils.ts';
import { playSystemVoice } from './services/audioService.ts';

type MainView = 'tactical' | 'intelligence' | 'calculations' | 'news';

const STORAGE_KEY = 'satexpert_tactical_v5';

export const App: React.FC = () => {
  const [userLoc, setUserLoc] = useState<Coordinates>({ lat: 51.5074, lng: -0.1278 });
  const [selectedSat, setSelectedSat] = useState<Satellite>(COMMON_SATELLITES[0]);
  const [lookAngles, setLookAngles] = useState<LookAngles | null>(null);
  const [view, setView] = useState<MainView>('tactical');
  const [defcon, setDefcon] = useState<number>(5);
  const [isTracking, setIsTracking] = useState<boolean>(false);
  const [weather, setWeather] = useState<WeatherCondition>('CLEAR');
  const prevDefconRef = useRef(5);
  const isFirstMount = useRef(true);

  // Shared Jamming State
  const [isJamming, setIsJamming] = useState<boolean>(false);
  const [jammingPower, setJammingPower] = useState<number>(50);

  // Rain Fade Calculation based on weather condition
  const getRainFade = (cond: WeatherCondition) => {
    switch(cond) {
      case 'CLEAR': return 0.5;
      case 'OVERCAST': return 1.8;
      case 'LIGHT_RAIN': return 4.5;
      case 'HEAVY_STORM': return 12.0;
      default: return 0.5;
    }
  };

  const currentRainFade = getRainFade(weather);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.loc) setUserLoc(parsed.loc);
      if (parsed.satId) {
        const sat = COMMON_SATELLITES.find(s => s.id === parsed.satId);
        if (sat) setSelectedSat(sat);
      }
      if (parsed.defcon) {
        setDefcon(parsed.defcon);
        prevDefconRef.current = parsed.defcon;
      }
      if (parsed.isTracking) setIsTracking(parsed.isTracking);
    }
    isFirstMount.current = false;
  }, []);

  useEffect(() => {
    const angles = calculateLookAngles(userLoc, selectedSat.longitude);
    setLookAngles(angles);
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ 
      loc: userLoc, 
      satId: selectedSat.id, 
      defcon,
      isTracking 
    }));
  }, [userLoc, selectedSat, defcon, isTracking]);

  // System Voice Feedback
  useEffect(() => {
    if (isFirstMount.current) return;
    if (defcon !== prevDefconRef.current) {
      playSystemVoice(`Defcon ${defcon} protocol active.`);
      prevDefconRef.current = defcon;
    }
  }, [defcon]);

  useEffect(() => {
    if (isFirstMount.current) return;
    if (isJamming) {
      playSystemVoice("Electronic Warfare engaged. Carrier suppression active.");
    } else {
      playSystemVoice("Electronic Warfare standby.");
    }
  }, [isJamming]);

  useEffect(() => {
    if (isFirstMount.current) return;
    playSystemVoice(`Target acquired: ${selectedSat.name}. Slot ${selectedSat.orbitalSlot}.`);
  }, [selectedSat.id]);

  // Geolocation Effect
  useEffect(() => {
    let watchId: number | null = null;

    if (isTracking && navigator.geolocation) {
      watchId = navigator.geolocation.watchPosition(
        (position) => {
          setUserLoc({
            lat: position.coords.latitude,
            lng: position.coords.longitude
          });
        },
        (error) => {
          console.error("GPS_ERROR:", error.message);
          setIsTracking(false);
        },
        { enableHighAccuracy: true }
      );
    }

    return () => {
      if (watchId !== null) navigator.geolocation.clearWatch(watchId);
