};

export default App;

import * as React from 'react';
import { useState, useRef, useEffect } from 'react';
import { getTroubleshootingAdvice } from '../services/geminiService.ts';
import { TroubleshootingLog } from '../types.ts';

interface Props {
  context: any;
}

export const AITechnician: React.FC<Props> = ({ context }) => {
  const [messages, setMessages] = useState<TroubleshootingLog[]>([
    { 
      role: 'assistant', 
      content: `[SYSTEM_READY] STIA-Agent Active.\nMONITORING: Field Site Alpha\nDEFCON: ${context.defcon || 5}\nCOORDINATES: ${context.lat?.toFixed(3)}, ${context.lng?.toFixed(3)}\nWEATHER: ${context.weather || 'CLEAR'}\nEW_STATUS: ${context.isJamming ? 'ENGAGED' : 'STANDBY'}\nState your technical query or operational objective.`, 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: TroubleshootingLog = { role: 'user', content: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    const advice = await getTroubleshootingAdvice(input, context);
    const assistantMessage: TroubleshootingLog = { role: 'assistant', content: advice || 'COMM_FAILURE: Satellite link timed out.', timestamp: new Date() };

    setMessages(prev => [...prev, assistantMessage]);
    setIsLoading(false);
  };

  return (
    <div className="glass rounded-2xl border-slate-800 flex flex-col h-[700px] overflow-hidden relative shadow-2xl bg-slate-950/40">
      <div className="p-4 border-b border-slate-800 bg-slate-900/60 flex justify-between items-center z-20">
        <div className="flex items-center">
          <div className="w-8 h-8 bg-cyan-900/40 rounded-lg flex items-center justify-center border border-cyan-500/30 mr-3">
             <svg className="w-5 h-5 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
          </div>
          <div>
            <h3 className="text-[10px] font-bold tracking-[0.3em] text-cyan-400 uppercase">STIA Intelligence Orchestrator</h3>
            <div className="flex items-center space-x-2 mt-0.5">
               <span className="text-[8px] text-slate-500 font-bold uppercase tracking-widest">Link: Stable</span>
               <div className="w-1.5 h-1.5 bg-green-500 rounded-full status-pulse"></div>
            </div>
          </div>
        </div>
      </div>

      <div ref={scrollRef} className="flex-grow overflow-y-auto p-6 space-y-6 scrollbar-hide">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-2xl border ${
              m.role === 'user' 
                ? 'bg-cyan-950/30 text-cyan-100 rounded-br-none border-cyan-500/20 shadow-lg' 
                : 'bg-slate-900/90 text-slate-300 rounded-bl-none border-slate-800 shadow-xl'
            }`}>
              <div className="text-[13px] whitespace-pre-wrap leading-relaxed font-medium mono">{m.content}</div>
              <div className="text-[8px] mt-4 opacity-40 font-mono tracking-widest uppercase flex items-center">
                <span className="mr-2">PKT_ID:</span> {m.timestamp.getTime().toString(16).slice(-8)} | {m.timestamp.toLocaleTimeString()}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-slate-900/50 p-4 rounded-2xl rounded-bl-none border border-slate-800 flex items-center space-x-2">
               <span className="w-1.5 h-1.5 bg-cyan-500 rounded-full animate-bounce"></span>
               <span className="w-1.5 h-1.5 bg-cyan-500 rounded-full animate-bounce delay-75"></span>
               <span className="w-1.5 h-1.5 bg-cyan-500 rounded-full animate-bounce delay-150"></span>
               <span className="text-[9px] text-cyan-500 font-bold tracking-widest ml-2 uppercase">Decrypting Uplink...</span>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-slate-900/60 border-t border-slate-800 z-20">
        <div className="flex space-x-3 bg-slate-950 p-2 rounded-xl border border-slate-800/80 shadow-inner">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="ENTER COMMAND >"
            className="flex-grow bg-transparent border-none px-4 py-2 text-xs text-white focus:outline-none mono placeholder:text-slate-700"
          />
          <button
            onClick={handleSend}
            disabled={isLoading}
            className="bg-cyan-600 hover:bg-cyan-500 disabled:opacity-30 text-slate-950 font-bold rounded-lg px-6 py-2 transition-all shadow-[0_0_15px_rgba(34,211,238,0.2)]"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

export const getTroubleshootingAdvice = async (issue: string, context?: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are the 'SatExpert Tactical Intelligence Agent' (STIA).
    You work for a high-stakes global satellite security firm.
    MISSION_OBJECTIVE: Provide technical, field-ready SatCom intelligence.

    CURRENT_ENVIRONMENT:
    - LATITUDE: ${context?.lat ?? 'N/A'}
    - LONGITUDE: ${context?.lng ?? 'N/A'}
    - TARGET_ASSET: ${context?.satName ?? 'N/A'}
    - DEFCON_STATUS: ${context?.defcon ?? 5}
    - WEATHER_CONDITION: ${context?.weather ?? 'CLEAR'}
    - EW_JAMMING_ACTIVE: ${context?.isJamming ? 'YES' : 'NO'}

    TONE: Professional, concise, military-grade technical depth. Use codes like [ROOT_CAUSE], [FIELD_RESOLUTION], and [STEALTH_ADVICE].

    SPECIAL_CAPABILITIES:
    - If WEATHER_CONDITION is not CLEAR, prioritize explaining 'Rain Fade' attenuation and suggested G/T adjustments.
    - If EW_JAMMING_ACTIVE is YES, focus on signal suppression mitigation, carrier identification, and spread-spectrum techniques.
    - If user mentions interference, use Google Search for regional solar flares, space weather, or local signal jamming news.
    - If user mentions ground stations, teleports, or location-based logistics, use Google Maps grounding.
    - If DEFCON < 3, suggest aggressive carrier-shielding and modem-hardening.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: "USER_COMMAND: " + issue,
      config: {
        systemInstruction,
        tools: [{ googleSearch: {} }, { googleMaps: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: context?.lat && context?.lng ? {
              latitude: context.lat,
              longitude: context.lng
            } : undefined
          }
        }
      },
    });

    let output = response.text || "";

    // Process and format references
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0) {
      output += "\n\n[TACTICAL_SOURCES_IDENTIFIED]:\n";
      chunks.forEach((chunk: any) => {
        if (chunk.web) output += `- [Search] ${chunk.web.title}: ${chunk.web.uri}\n`;
        if (chunk.maps) output += `- [Map] ${chunk.maps.title}: ${chunk.maps.uri}\n`;
      });
    }

    return output;
  } catch (error) {
    console.error("STIA_SYSTEM_ERROR", error);
    return "SYSTEM_HALT: COMM_TIMEOUT. Verify API uplink.";
  }
};

import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { Layout } from './components/Layout.tsx';
import { LookAngleCard } from './components/LookAngleCard.tsx';
import { AITechnician } from './components/AITechnician.tsx';
import { SecurityTools } from './components/SecurityTools.tsx';
import { LinkBudgetCalculator } from './components/LinkBudgetCalculator.tsx';
import { SignalVisualizer } from './components/SignalVisualizer.tsx';
import { TacticalHUD } from './components/TacticalHUD.tsx';
import { TacticalMap } from './components/TacticalMap.tsx';
import { RSSReader } from './components/RSSReader.tsx';
import { Coordinates, Satellite, LookAngles, WeatherCondition } from './types.ts';
import { COMMON_SATELLITES } from './constants.ts';
import { calculateLookAngles } from './utils/geoUtils.ts';
import { playSystemVoice } from './services/audioService.ts';

type MainView = 'tactical' | 'intelligence' | 'calculations' | 'news';

const STORAGE_KEY = 'satexpert_tactical_v5';

export const App: React.FC = () => {
  const [userLoc, setUserLoc] = useState<Coordinates>({ lat: 51.5074, lng: -0.1278 });
  const [selectedSat, setSelectedSat] = useState<Satellite>(COMMON_SATELLITES[0]);
  const [lookAngles, setLookAngles] = useState<LookAngles | null>(null);
  const [view, setView] = useState<MainView>('tactical');
  const [defcon, setDefcon] = useState<number>(5);
  const [isTracking, setIsTracking] = useState<boolean>(false);
  const [weather, setWeather] = useState<WeatherCondition>('CLEAR');
  const prevDefconRef = useRef(5);
  const isFirstMount = useRef(true);

  const [isJamming, setIsJamming] = useState<boolean>(false);
  const [jammingPower, setJammingPower] = useState<number>(50);

  const getRainFade = (cond: WeatherCondition) => {
    switch(cond) {
      case 'CLEAR': return 0.5;
      case 'OVERCAST': return 1.8;
      case 'LIGHT_RAIN': return 4.5;
      case 'HEAVY_STORM': return 12.0;
      default: return 0.5;
    }
  };

  const currentRainFade = getRainFade(weather);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.loc) setUserLoc(parsed.loc);
      if (parsed.satId) {
        const sat = COMMON_SATELLITES.find(s => s.id === parsed.satId);
        if (sat) setSelectedSat(sat);
      }
      if (parsed.defcon) {
        setDefcon(parsed.defcon);
        prevDefconRef.current = parsed.defcon;
      }
      if (parsed.isTracking) setIsTracking(parsed.isTracking);
    }
    isFirstMount.current = false;
  }, []);

  useEffect(() => {
    const angles = calculateLookAngles(userLoc, selectedSat.longitude);
    setLookAngles(angles);
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ 
      loc: userLoc, 
      satId: selectedSat.id, 
      defcon,
      isTracking 
    }));
  }, [userLoc, selectedSat, defcon, isTracking]);

  useEffect(() => {
    if (isFirstMount.current) return;
    if (defcon !== prevDefconRef.current) {
      playSystemVoice(`Defcon ${defcon} protocol active.`);
      prevDefconRef.current = defcon;
    }
  }, [defcon]);

  useEffect(() => {
    if (isFirstMount.current) return;
    if (isJamming) {
      playSystemVoice("Electronic Warfare engaged. Carrier suppression active.");
    } else {
      playSystemVoice("Electronic Warfare standby.");
    }
  }, [isJamming]);

  useEffect(() => {
    if (isFirstMount.current) return;
    playSystemVoice(`Target acquired: ${selectedSat.name}. Slot ${selectedSat.orbitalSlot}.`);
  }, [selectedSat.id]);

  useEffect(() => {
    let watchId: number | null = null;
    if (isTracking && navigator.geolocation) {
      watchId = navigator.geolocation.watchPosition(
        (position) => {
          setUserLoc({
            lat: position.coords.latitude,
            lng: position.coords.longitude
          });
        },
        (error) => {
          console.error("GPS_ERROR:", error.message);
          setIsTracking(false);
        },
        { enableHighAccuracy: true }
      );
    }
    return () => {
      if (watchId !== null) navigator.geolocation.clearWatch(watchId);
    };
  }, [isTracking]);

  const defconColors: Record<number, string> = {
    5: 'text-blue-400 border-blue-500/30 shadow-blue-500/5',
    4: 'text-green-400 border-green-500/30 shadow-green-500/5',
    3: 'text-yellow-400 border-yellow-500/30 shadow-yellow-500/5',
    2: 'text-orange-400 border-orange-500/30 shadow-orange-500/5',
    1: 'text-red-500 border-red-500/50 shadow-red-500/20'
  };

  const defconLabels: Record<number, string> = {
    5: 'FADE OUT // NORMAL READINESS',
    4: 'DOUBLE TAKE // INCREASED INTELLIGENCE',
    3: 'ROUND HOUSE // FORCE MOBILIZATION',
    2: 'FAST PACE // MAXIMUM READINESS',
    1: 'COCKED PISTOL // COMBAT IMMINENT'
  };

  const isDistorted = isJamming || defcon === 1;

  return (
    <div className={`crt-screen min-h-screen ${isDistorted ? 'crt-distorted' : ''}`}>
      <Layout>
        <div className={`flex flex-col space-y-6 max-w-7xl mx-auto pb-12 transition-all duration-1000 ${defcon === 1 ? 'brightness-[1.1]' : ''}`}>

          <div className={`flex flex-col md:flex-row items-center justify-between gap-4 glass p-4 rounded-2xl border-slate-800 shadow-2xl relative overflow-hidden ${defcon === 1 || isJamming ? 'defcon-alert' : ''}`}>
            <div className="flex items-center space-x-6 z-20">
              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-cyan-500 uppercase tracking-[0.2em] mb-1">Mission Module</span>
                <div className="flex space-x-1 bg-slate-950/50 p-1 rounded-lg border border-slate-800">
                  {(['tactical', 'intelligence', 'calculations', 'news'] as MainView[]).map((v) => (
                    <button
                      key={v}
                      onClick={() => setView(v)}
                      className={`px-4 py-1.5 rounded text-[9px] font-bold uppercase tracking-widest transition-all ${
                        view === v 
                          ? 'bg-cyan-500 text-slate-950 shadow-lg' 
                          : 'text-slate-500 hover:text-cyan-400'
                      }`}
                    >
                      {v}
                    </button>
                  ))}
                </div>
              </div>
              <div className="h-10 w-px bg-slate-800 hidden md:block"></div>
              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Threat Protocol</span>
                <div className="flex space-x-2">
