            <div className="flex items-center space-x-6 z-20">
              <div className="text-right">
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Global Uplink</p>
                <p className={`text-xs font-bold mono ${defcon === 1 || isJamming ? 'text-red-500' : 'text-green-400'}`}>
                  {isJamming ? 'ACTIVE_EW_INTERFERENCE' : (defcon === 1 ? 'CRITICAL_JAMMING_DETECTED' : 'ENCRYPTED // LINK ACTIVE')}
                </p>
              </div>
              <div className="flex -space-x-2">
                <button 
                  onClick={() => setIsTracking(!isTracking)}
                  className={`w-9 h-9 rounded-full border-2 bg-slate-900 flex items-center justify-center transition-all ${isTracking ? 'border-cyan-500 shadow-[0_0_10px_rgba(34,211,238,0.5)]' : 'border-slate-800 opacity-50'}`}
                  title={isTracking ? "GPS Tracking Active" : "Enable GPS Tracking"}
                >
                  <span className={`text-[9px] font-bold ${isTracking ? 'text-cyan-400 animate-pulse' : 'text-slate-500'}`}>GPS</span>
                </button>
                <div className={`w-9 h-9 rounded-full border-2 border-slate-800 bg-slate-900 flex items-center justify-center ${defcon === 1 || isJamming ? 'border-red-500 animate-pulse' : ''}`}>
                  <span className={`text-[9px] font-bold ${isJamming ? 'text-red-500' : 'text-cyan-500'}`}>EW</span>
                </div>
              </div>
            </div>
          </div>

          <div className={`glass p-6 rounded-2xl border-2 transition-all duration-500 flex flex-col md:flex-row items-center justify-between overflow-hidden relative ${isJamming ? 'text-red-500 border-red-500/50 shadow-red-500/20' : defconColors[defcon]}`}>
            {(defcon === 1 || isJamming) && <div className="absolute inset-0 bg-red-600/5 animate-pulse pointer-events-none"></div>}
            <div className="flex items-center space-x-8 z-10">
                <div className="flex flex-col items-center justify-center">
                  <span className="text-[10px] font-black uppercase tracking-[0.5em] opacity-60 mb-1">System State</span>
                  <div className="text-6xl font-black mono leading-none tracking-tighter">
                    {isJamming ? 'EW_ACT' : 'DEFCON'} <span className="underline decoration-4 underline-offset-8">{isJamming ? '!!!' : defcon}</span>
                  </div>
                </div>
                <div className="h-16 w-px bg-current opacity-20 hidden md:block"></div>
                <div className="flex flex-col">
                  <span className="text-[11px] font-bold uppercase tracking-[0.3em] opacity-70 mb-1">Authorization Protocol</span>
                  <div className="text-xl md:text-2xl font-bold tracking-tight uppercase">
                    {isJamming ? 'ELECTRONIC WARFARE IN PROGRESS' : defconLabels[defcon]}
                  </div>
                  <div className="flex items-center mt-2 space-x-4">
                    <div className="flex items-center space-x-1">
                      <div className={`w-2 h-2 rounded-full bg-current ${defcon <= 2 || isJamming ? 'animate-ping' : ''}`}></div>
                      <span className="text-[10px] font-bold mono uppercase opacity-80">Link_{isJamming ? 'JAMMING_LOCAL' : (defcon === 1 ? 'SECURED_HARDENED' : 'ENCRYPTED')}</span>
                    </div>
                    <div className="text-[10px] font-bold mono uppercase opacity-50">NODE_ID: 0x{((defcon * 7234) % 65535).toString(16).toUpperCase()}</div>
                  </div>
                </div>
            </div>
            <div className="mt-6 md:mt-0 flex space-x-2 z-10">
                {Array.from({length: 5}).map((_, i) => (
                  <div 
                    key={i} 
                    className={`h-12 w-3 rounded-sm transition-all duration-300 ${5-i <= (isJamming ? 1 : defcon) ? 'bg-current opacity-20' : 'bg-current shadow-[0_0_15px_rgba(34,211,238,0.5)]'}`}
                  />
                ))}
            </div>
          </div>

          <div className="min-h-[70vh]">
            {view === 'tactical' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="lg:col-span-4 space-y-6">
                  <TacticalHUD 
                    loc={userLoc} 
                    sat={selectedSat} 
                    onLocChange={setUserLoc} 
                    onSatChange={setSelectedSat}
                    isTracking={isTracking}
                    onTrackingChange={setIsTracking}
                    isJamming={isJamming}
                    setIsJamming={setIsJamming}
                    jammingPower={jammingPower}
                    setJammingPower={setJammingPower}
                    weather={weather}
                    setWeather={setWeather}
                  />
                  <TacticalMap 
                    userLoc={userLoc} 
                    satellite={selectedSat} 
                    isTracking={isTracking}
                    onLocChange={setUserLoc}
                    onTrackingChange={setIsTracking}
                  />
                  {lookAngles && <LookAngleCard angles={lookAngles} satellite={selectedSat} />}
                  <SignalVisualizer 
                    quality={lookAngles?.elevation && lookAngles.elevation > 0 ? (defcon === 1 ? 42 : 88) : 0} 
                    isJamming={isJamming}
                    jammingPower={jammingPower}
                    rainFade={currentRainFade}
                  />
                </div>
                <div className="lg:col-span-8">
                  <AITechnician 
                    context={{ 
                      lat: userLoc.lat, 
                      lng: userLoc.lng, 
                      satName: selectedSat.name,
                      defcon: defcon,
                      weather: weather,
                      isJamming: isJamming
                    }} 
                  />
                </div>
              </div>
            )}

            {view === 'intelligence' && (
              <div className="animate-in zoom-in-95 duration-500">
                <SecurityTools 
                  userLoc={userLoc} 
                  selectedSatName={selectedSat.name}
                  isJamming={isJamming}
                  setIsJamming={setIsJamming}
                  jammingPower={jammingPower}
                  setJammingPower={setJammingPower}
                  signalQuality={lookAngles?.elevation && lookAngles.elevation > 0 ? 88 : 0}
                  onBack={() => setView('tactical')}
                />
              </div>
            )}

            {view === 'calculations' && lookAngles && (
              <div className="animate-in fade-in duration-500">
                <LinkBudgetCalculator distance={lookAngles.distance} externalRainFade={currentRainFade} />
              </div>
            )}

            {view === 'news' && (
              <div className="animate-in slide-in-from-right-4 duration-500">
                <RSSReader />
              </div>
            )}
          </div>
        </div>
      </Layout>
    </div>
  );
};

export default App;

import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { getTroubleshootingAdvice } from '../services/geminiService.ts';
import { playSystemVoice } from '../services/audioService.ts';

interface Props {
  userLoc: { lat: number, lng: number };
  selectedSatName: string;
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  signalQuality: number;
  onBack?: () => void;
}

interface HardeningOption {
  id: string;
  label: string;
  description: string;
  enabled: boolean;
}

interface IPLogEntry {
  time: string;
  msg: string;
  type: 'INFO' | 'WARN' | 'SUCCESS' | 'FAIL';
}

type AttackVector = 'SCAN' | 'EXPLOIT' | 'DOS';

const HARDENING_STORAGE_KEY = 'satexpert_hardening_state';

export const SecurityTools: React.FC<Props> = ({ 
  userLoc, 
  selectedSatName,
  isJamming,
  setIsJamming,
  jammingPower,
  setJammingPower,
  signalQuality,
  onBack
}) => {
  const [activeTab, setActiveTab] = useState<string>('overview');
  const [outputs, setOutputs] = useState<Record<string, string>>({});
  const [intelLoading, setIntelLoading] = useState(false);

  const [authCodes, setAuthCodes] = useState({ 
    uplink: 'ST-A7X', 
    downlink: 'BK-92Z', 
    telemetry: 'XP-11Q', 
    expire: 30 
  });
  const [revealed, setRevealed] = useState<Record<string, boolean>>({ uplink: false, downlink: false, telemetry: false });
  const [keyRotationCount, setKeyRotationCount] = useState(1);
  const [isSyncing, setIsSyncing] = useState(false);

  const [targetIp, setTargetIp] = useState('192.168.1.100');
  const [ipAttackLog, setIpAttackLog] = useState<IPLogEntry[]>([]);
  const [isIpAttacking, setIsIpAttacking] = useState(false);
  const [attackVector, setAttackVector] = useState<AttackVector>('SCAN');

  const [detectionLogs, setDetectionLogs] = useState<{id: string, type: string, severity: 'LOW' | 'MED' | 'HIGH', msg: string, mitigation: string}[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  const [hardeningOptions, setHardeningOptions] = useState<HardeningOption[]>([
    { id: 'telnet', label: 'Disable Telnet', description: 'Terminate unencrypted legacy remote access port 23.', enabled: false },
    { id: 'ssh', label: 'Enable SSH v2', description: 'Enforce encrypted administrative access via RSA/ED25519 keys.', enabled: false },
    { id: 'encryption', label: 'Stronger Encryption', description: 'Upgrade air interface to AES-256 and enforce FIPS 140-2.', enabled: false },
    { id: 'firmware', label: 'Firmware Integrity', description: 'Enable secure boot and cryptographic hash validation.', enabled: false },
    { id: 'ports', label: 'Disable Unused Ports', description: 'Seal non-essential logical ports and audit open services.', enabled: false },
    { id: 'rate-limiting', label: 'Implement Rate Limiting', description: 'Prevent DoS/DDoS by throttling excessive packet requests.', enabled: false },
    { id: 'firmware-mandatory', label: 'Mandatory Firmware Updates', description: 'Enforce automatic signed updates to patch zero-day vulnerabilities.', enabled: false },
    { id: 'segmentation', label: 'Network Segmentation', description: 'Isolate management and user traffic into distinct VLANs.', enabled: false },
  ]);

  const terminalRef = useRef<HTMLDivElement>(null);
  const isFirstRender = useRef(true);

  useEffect(() => {
    const saved = localStorage.getItem(HARDENING_STORAGE_KEY);
    if (saved) {
      try {
        setHardeningOptions(JSON.parse(saved));
      } catch (e) { console.error("HARDENING_LOAD_ERR", e); }
    }
  }, []);

  useEffect(() => {
    if (isFirstRender.current) return;
    localStorage.setItem(HARDENING_STORAGE_KEY, JSON.stringify(hardeningOptions));
  }, [hardeningOptions]);

  const generateNewCodes = (silent = false) => {
    setKeyRotationCount(r => r + 1);
    setAuthCodes({
      uplink: Math.random().toString(36).substr(2, 6).toUpperCase(),
      downlink: Math.random().toString(36).substr(2, 6).toUpperCase(),
      telemetry: Math.random().toString(36).substr(2, 6).toUpperCase(),
      expire: 30
    });
    setRevealed({ uplink: false, downlink: false, telemetry: false });
    if (!silent) {
      playSystemVoice("Cryptographic keys rotated. Authentication synchronized.");
    }
  };

  useEffect(() => {
    const interval = setInterval(() => {
      setAuthCodes(prev => {
        if (prev.expire <= 1) {
          generateNewCodes(true);
          return { ...prev, expire: 30 };
        }
        return { ...prev, expire: prev.expire - 1 };
      });
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const addIpLog = (msg: string, type: IPLogEntry['type'] = 'INFO') => {
    const time = new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
    setIpAttackLog(prev => [...prev, { time, msg, type }]);
  };

  const runIpAttack = () => {
    if (!targetIp || isIpAttacking) return;
    setIsIpAttacking(true);
    setIpAttackLog([]);
    addIpLog(`STRIKE_PROTOCOL_INITIALIZED: VECTOR[${attackVector}] TARGET[${targetIp}]`, 'INFO');
    let sequence: { msg: string, type: IPLogEntry['type'] }[] = [];
    if (attackVector === 'SCAN') {
      sequence = [{ msg: "STARTING_RECONNAISSANCE: PROBING_TCP_STACK...", type: 'INFO' }, { msg: "PORT_DETECTED: 22 [SSH] - STATE_OPEN", type: 'SUCCESS' }, { msg: "PORT_DETECTED: 80 [HTTP] - STATE_FILTERED", type: 'WARN' }, { msg: "SCAN_COMPLETE: TARGET_SURFACE_MAPPED", type: 'SUCCESS' }];
    } else if (attackVector === 'EXPLOIT') {
      sequence = [{ msg: "STAGING_EXPLOIT: RCE_CVE_2024_SATELLITE_LINK", type: 'WARN' }, { msg: "CALCULATING_OFFSET: MEMORY_ALIGNMENT_0xDEADBEEF", type: 'INFO' }, { msg: "SENDING_PAYLOAD: MALICIOUS_HEADER_PULSE...", type: 'INFO' }, { msg: "INITIATING_SHELL: REVERSE_LINK_ESTABLISHED", type: 'SUCCESS' }];
    } else if (attackVector === 'DOS') {
      sequence = [{ msg: "COMMENCING_FLOOD: UDP_PACKET_STORM_INITIATED", type: 'WARN' }, { msg: "BANDWIDTH_CONSUMPTION: 450Mbps_AND_RISING", type: 'INFO' }, { msg: "TARGET_STATE: CONNECTION_TIMEOUT_DETECTION", type: 'FAIL' }, { msg: "OUTCOME: SERVICE_UNAVAILABLE_SUCCESS", type: 'SUCCESS' }];
    }
    let i = 0;
    const interval = window.setInterval(() => {
      if (i >= sequence.length) {
        setIsIpAttacking(false);
        clearInterval(interval);
        return;
      }
      addIpLog(sequence[i].msg, sequence[i].type);
      i++;
    }, 800);
  };

  const fetchThreatIntel = async (query: string) => {
    if (!query || intelLoading) return;
    setIntelLoading(true);
    try {
      const advice = await getTroubleshootingAdvice(query, { lat: userLoc.lat, lng: userLoc.lng, satName: selectedSatName });
      setOutputs(prev => ({ ...prev, intel: advice || "NO_DATA_RETURNED" }));
    } catch (error) {
      setOutputs(prev => ({ ...prev, intel: "SYSTEM_FAILURE: INTELLIGENCE_UPLINK_TIMEOUT." }));
    } finally {
      setIntelLoading(false);
    }
  };

  const runThreatScan = () => {
    setIsScanning(true);
    setDetectionLogs([]);
    setTimeout(() => {
      setDetectionLogs([{ id: 'DT-01', type: 'RF_ANOMALY', severity: 'LOW', msg: 'Abnormal noise floor deviation at 14.2GHz', mitigation: 'Check hardware grounding.' }, { id: 'DT-02', type: 'AUTH_FAILURE', severity: 'MED', msg: 'Multiple failed SSH attempts from 10.0.0.42', mitigation: 'Enable Fail2Ban.' }, { id: 'DT-03', type: 'ENCRYPTION', severity: 'HIGH', msg: 'Clear-text traffic detected', mitigation: 'Enforce HTTPS/SSH immediately.' }]);
      setIsScanning(false);
    }, 2000);
  };

  const toggleHardening = (id: string) => {
    setHardeningOptions(prev => prev.map(opt => opt.id === id ? { ...opt, enabled: !opt.enabled } : opt));
  };

  const complianceScore = Math.round((hardeningOptions.filter(o => o.enabled).length / hardeningOptions.length) * 100);
  const getComplianceGrade = (score: number) => {
    if (score >= 95) return { grade: 'A+', color: 'text-green-400' };
    if (score >= 85) return { grade: 'A', color: 'text-green-500' };
    if (score >= 70) return { grade: 'B', color: 'text-cyan-400' };
    if (score >= 50) return { grade: 'C', color: 'text-amber-400' };
    if (score >= 25) return { grade: 'D', color: 'text-orange-500' };
    return { grade: 'F', color: 'text-red-500' };
  };
  const gradeInfo = getComplianceGrade(complianceScore);

  const getLogColor = (type: IPLogEntry['type']) => {
    switch(type) {
      case 'SUCCESS': return 'text-green-400';
      case 'FAIL': return 'text-red-500';
      case 'WARN': return 'text-amber-400';
      default: return 'text-slate-400';
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex items-center justify-between mb-2">
        <h2 className="text-2xl font-bold flex items-center text-white uppercase tracking-tight">
          <span className="mr-3">🛡️</span> Security <span className="text-cyan-400 ml-2">Intelligence</span>
        </h2>
        {onBack && (
          <button onClick={onBack} className="flex items-center space-x-2 bg-slate-800 hover:bg-slate-700 text-[10px] font-bold text-slate-300 px-4 py-2 rounded-xl border border-slate-700 transition-all uppercase tracking-widest">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            <span>Mission Command</span>
          </button>
        )}
      </header>

      <div className="flex flex-wrap gap-2 border-b border-slate-800 pb-px">
        {['overview', 'attack', 'codes', 'intel', 'detection', 'hardening'].map((id) => (
          <button key={id} onClick={() => setActiveTab(id)} className={`px-4 py-2 text-[10px] font-bold uppercase tracking-widest transition-all border-b-2 ${activeTab === id ? 'border-cyan-500 text-cyan-400 bg-cyan-500/5' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
            {id}
          </button>
        ))}
      </div>

      <div className="py-4">
        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="glass p-6 rounded-2xl border-slate-800 hover:border-red-500/50 transition-all cursor-pointer" onClick={() => setActiveTab('attack')}>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Offensive Ops</h3>
              <p className="text-xs text-slate-400">Jamming, IP Exploits, and Signal Hijacking.</p>
            </div>
            <div className="glass p-6 rounded-2xl border-slate-800 hover:border-cyan-500 transition-all cursor-pointer" onClick={() => setActiveTab('detection')}>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Signal Detection</h3>
              <p className="text-xs text-slate-400">Real-time monitoring for unauthorized uplinks.</p>
            </div>
            <div className="glass p-6 rounded-2xl border-slate-800 hover:border-amber-500/50 transition-all cursor-pointer" onClick={() => setActiveTab('hardening')}>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Hardening</h3>
              <p className="text-xs text-slate-400">Enforce FIPS compliance and port security.</p>
            </div>
          </div>
        )}

        {activeTab === 'codes' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 glass p-8 rounded-3xl border-slate-800 flex flex-col justify-between">
              <h3 className="text-white font-bold uppercase text-sm tracking-widest mb-10">Tactical Authenticator</h3>
              <div className="grid grid-cols-1 gap-8">
                {(['uplink', 'downlink', 'telemetry'] as const).map((key) => (
                  <div key={key} className="flex justify-between items-center border-b border-slate-900 pb-5">
                    <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">{key} Signal</span>
                    <span className={`text-3xl font-black mono tracking-[0.2em] ${revealed[key] ? 'text-cyan-400' : 'text-slate-800 blur-md'}`}>
                      {revealed[key] ? authCodes[key] : 'XXXXXX'}
                    </span>
                    <button onClick={() => setRevealed(prev => ({...prev, [key]: !prev[key]}))} className="text-[8px] text-cyan-500 uppercase">{revealed[key] ? '[MASK]' : '[REVEAL]'}</button>
                  </div>
                ))}
              </div>
              <div className="mt-12 bg-slate-950 p-6 rounded-2xl">
                <span className="text-[9px] font-bold text-cyan-400 uppercase">{authCodes.expire}S REMAINING</span>
                <div className="w-full h-1.5 bg-slate-900 rounded-full mt-2">
                  <div className="h-full bg-cyan-600" style={{ width: `${(authCodes.expire / 30) * 100}%` }}></div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'attack' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="glass p-6 rounded-2xl border-slate-800 border-l-4 border-l-red-500/50">
              <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Strike & EW Terminal</h4>
              <div className="space-y-4">
                <input type="text" value={targetIp} onChange={(e) => setTargetIp(e.target.value)} placeholder="IP_ADDR..." className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-xs text-white mono" />
                <select value={attackVector} onChange={(e) => setAttackVector(e.target.value as AttackVector)} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-xs text-white mono">
                  <option value="SCAN">PORT_SCAN</option>
                  <option value="EXPLOIT">EXPLOIT_PAYLOAD</option>
                  <option value="DOS">DENIAL_OF_SERVICE</option>
                </select>
                <button onClick={runIpAttack} disabled={isIpAttacking} className="w-full bg-red-600 hover:bg-red-500 text-white text-[10px] font-bold py-3 rounded-xl uppercase">
                  {isIpAttacking ? 'MISSION_IN_PROGRESS...' : 'COMMENCE_STRIKE'}
                </button>
                <div ref={terminalRef} className="bg-slate-950 p-4 rounded-xl h-[200px] overflow-y-auto font-mono text-[9px]">
                  {ipAttackLog.map((log, i) => (
                    <div key={i} className="flex space-x-2"><span className="text-slate-600 shrink-0">[{log.time}]</span><span className={getLogColor(log.type)}>{log.msg}</span></div>
                  ))}
                </div>
              </div>
            </div>
            <div className="glass p-6 rounded-2xl border-slate-800 border-l-4 border-l-red-500/50">
              <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Jamming Control</h4>
              <input type="range" min="0" max="100" value={jammingPower} onChange={(e) => setJammingPower(parseInt(e.target.value))} className="w-full h-1 bg-slate-800 accent-red-500" />
              <button onClick={() => setIsJamming(!isJamming)} className={`w-full mt-4 py-3 rounded-xl font-bold text-xs uppercase ${isJamming ? 'bg-red-600 text-white' : 'bg-slate-800 text-red-500'}`}>
                {isJamming ? 'Halt Transmission' : 'Engage EW Jammer'}
              </button>
            </div>
          </div>
        )}

        {activeTab === 'intel' && (
          <div className="space-y-6">
            <div className="glass p-6 rounded-2xl border-slate-800">
              <input id="hw-search" placeholder="Enter Asset Model..." className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-white mono mb-4" />
              <button onClick={() => fetchThreatIntel((document.getElementById('hw-search') as HTMLInputElement).value)} disabled={intelLoading} className="w-full py-3 bg-cyan-600 text-slate-950 font-bold text-[10px] uppercase rounded-xl">
                {intelLoading ? 'QUERING...' : 'Query Threat Database'}
              </button>
            </div>
            {outputs.intel && (
              <pre className="bg-slate-950 p-6 rounded-2xl border border-slate-800 text-cyan-400 text-[11px] font-mono whitespace-pre-wrap">
                {outputs.intel}
              </pre>
            )}
          </div>
        )}

        {activeTab === 'hardening' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-3">
              {hardeningOptions.map((opt) => (
                <div key={opt.id} onClick={() => toggleHardening(opt.id)} className={`p-4 rounded-xl border cursor-pointer ${opt.enabled ? 'bg-green-500/10 border-green-500/40' : 'bg-slate-950 border-slate-800'}`}>
                  <div className="text-[10px] font-bold uppercase tracking-wide text-white">{opt.label}</div>
                  <p className="text-[9px] text-slate-500 mt-0.5">{opt.description}</p>
                </div>
              ))}
            </div>
            <div className="lg:col-span-4 glass p-8 rounded-2xl border-slate-800 flex flex-col items-center justify-center text-center">
              <div className={`text-4xl font-black mono ${gradeInfo.color}`}>{complianceScore}%</div>
              <div className={`text-xs font-bold uppercase mt-1 opacity-60 ${gradeInfo.color}`}>Grade: {gradeInfo.grade}</div>
            </div>
          </div>
        )}

        {activeTab === 'detection' && (
          <div className="glass p-6 rounded-2xl border-slate-800">
            <button onClick={runThreatScan} disabled={isScanning} className="bg-cyan-600 hover:bg-cyan-500 text-slate-950 font-bold px-6 py-2 rounded-lg text-[10px] uppercase">
              {isScanning ? 'Scanning...' : 'Start Global Scan'}
            </button>
            <div className="mt-6 space-y-3">
              {detectionLogs.map((log) => (
                <div key={log.id} className="bg-slate-950 p-4 rounded-xl border border-slate-800">
                  <span className={`text-[8px] font-bold px-2 py-0.5 rounded uppercase ${log.severity === 'HIGH' ? 'bg-red-500 text-white' : 'bg-blue-500 text-white'}`}>{log.severity}</span>
                  <p className="text-[10px] text-slate-400 mono mt-1">{log.msg}</p>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { getTroubleshootingAdvice } from '../services/geminiService.ts';
import { playSystemVoice } from '../services/audioService.ts';

interface Props {
  userLoc: { lat: number, lng: number };
  selectedSatName: string;
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  signalQuality: number;
  onBack?: () => void;
}

interface HardeningOption {
  id: string;
  label: string;
  description: string;
  enabled: boolean;
}

interface IPLogEntry {
  time: string;
  msg: string;
  type: 'INFO' | 'WARN' | 'SUCCESS' | 'FAIL';
}

type AttackVector = 'SCAN' | 'EXPLOIT' | 'DOS';

const HARDENING_STORAGE_KEY = 'satexpert_hardening_state';

export const SecurityTools: React.FC<Props> = ({ 
  userLoc, 
  selectedSatName,
  isJamming,
  setIsJamming,
  jammingPower,
  setJammingPower,
  signalQuality,
  onBack
}) => {
  const [activeTab, setActiveTab] = useState<string>('overview');
  const [outputs, setOutputs] = useState<Record<string, string>>({});
  const [intelLoading, setIntelLoading] = useState(false);

  // Codes States
  const [authCodes, setAuthCodes] = useState({ 
    uplink: 'ST-A7X', 
    downlink: 'BK-92Z', 
    telemetry: 'XP-11Q', 
    expire: 30 
  });
  const [revealed, setRevealed] = useState<Record<string, boolean>>({ uplink: false, downlink: false, telemetry: false });
  const [keyRotationCount, setKeyRotationCount] = useState(1);
  const [isSyncing, setIsSyncing] = useState(false);

  // Attack States
  const [targetIp, setTargetIp] = useState('192.168.1.100');
  const [ipAttackLog, setIpAttackLog] = useState<IPLogEntry[]>([]);
  const [isIpAttacking, setIsIpAttacking] = useState(false);
  const [attackVector, setAttackVector] = useState<AttackVector>('SCAN');

  // Detection States
  const [detectionLogs, setDetectionLogs] = useState<{id: string, type: string, severity: 'LOW' | 'MED' | 'HIGH', msg: string, mitigation: string}[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  // Hardening States
  const [hardeningOptions, setHardeningOptions] = useState<HardeningOption[]>([
    { id: 'telnet', label: 'Disable Telnet', description: 'Terminate unencrypted legacy remote access port 23.', enabled: false },
    { id: 'ssh', label: 'Enable SSH v2', description: 'Enforce encrypted administrative access via RSA/ED25519 keys.', enabled: false },
    { id: 'encryption', label: 'Stronger Encryption', description: 'Upgrade air interface to AES-256 and enforce FIPS 140-2.', enabled: false },
    { id: 'firmware', label: 'Firmware Integrity', description: 'Enable secure boot and cryptographic hash validation.', enabled: false },
    { id: 'ports', label: 'Disable Unused Ports', description: 'Seal non-essential logical ports and audit open services.', enabled: false },
    { id: 'rate-limiting', label: 'Implement Rate Limiting', description: 'Prevent DoS/DDoS by throttling excessive packet requests.', enabled: false },
    { id: 'firmware-mandatory', label: 'Mandatory Firmware Updates', description: 'Enforce automatic signed updates to patch zero-day vulnerabilities.', enabled: false },
    { id: 'segmentation', label: 'Network Segmentation', description: 'Isolate management and user traffic into distinct VLANs.', enabled: false },
  ]);

  const terminalRef = useRef<HTMLDivElement>(null);
  const isFirstRender = useRef(true);

  // Load hardening state
  useEffect(() => {
    const saved = localStorage.getItem(HARDENING_STORAGE_KEY);
    if (saved) {
      try {
        setHardeningOptions(JSON.parse(saved));
      } catch (e) { console.error("HARDENING_LOAD_ERR", e); }
    }
  }, []);

  // Save hardening state
  useEffect(() => {
    if (isFirstRender.current) return;
    localStorage.setItem(HARDENING_STORAGE_KEY, JSON.stringify(hardeningOptions));
  }, [hardeningOptions]);

  const generateNewCodes = (silent = false) => {
    setKeyRotationCount(r => r + 1);
    setAuthCodes({
      uplink: Math.random().toString(36).substr(2, 6).toUpperCase(),
      downlink: Math.random().toString(36).substr(2, 6).toUpperCase(),
      telemetry: Math.random().toString(36).substr(2, 6).toUpperCase(),
      expire: 30
    });
    setRevealed({ uplink: false, downlink: false, telemetry: false });
    if (!silent) {
      playSystemVoice("Cryptographic keys rotated. Authentication synchronized.");
    }
  };

  // Auth Code Rotation Logic
  useEffect(() => {
    const interval = setInterval(() => {
      setAuthCodes(prev => {
        if (prev.expire <= 1) {
          generateNewCodes(true);
          return { ...prev, expire: 30 };
        }
        return { ...prev, expire: prev.expire - 1 };
      });
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (terminalRef.current) terminalRef.current.scrollTop = terminalRef.current.scrollHeight;
  }, [ipAttackLog]);

  const addIpLog = (msg: string, type: IPLogEntry['type'] = 'INFO') => {
    const time = new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
    setIpAttackLog(prev => [...prev, { time, msg, type }]);
  };

  const runIpAttack = () => {
    if (!targetIp || isIpAttacking) return;
    setIsIpAttacking(true);
    setIpAttackLog([]);
    addIpLog(`STRIKE_PROTOCOL_INITIALIZED: VECTOR[${attackVector}] TARGET[${targetIp}]`, 'INFO');
    let sequence: { msg: string, type: IPLogEntry['type'] }[] = [];
    if (attackVector === 'SCAN') {
      sequence = [{ msg: "STARTING_RECONNAISSANCE: PROBING_TCP_STACK...", type: 'INFO' }, { msg: "PORT_DETECTED: 22 [SSH] - STATE_OPEN", type: 'SUCCESS' }, { msg: "PORT_DETECTED: 80 [HTTP] - STATE_FILTERED", type: 'WARN' }, { msg: "SCAN_COMPLETE: TARGET_SURFACE_MAPPED", type: 'SUCCESS' }];
    } else if (attackVector === 'EXPLOIT') {
      sequence = [{ msg: "STAGING_EXPLOIT: RCE_CVE_2024_SATELLITE_LINK", type: 'WARN' }, { msg: "CALCULATING_OFFSET: MEMORY_ALIGNMENT_0xDEADBEEF", type: 'INFO' }, { msg: "SENDING_PAYLOAD: MALICIOUS_HEADER_PULSE...", type: 'INFO' }, { msg: "INITIATING_SHELL: REVERSE_LINK_ESTABLISHED", type: 'SUCCESS' }];
    } else if (attackVector === 'DOS') {
      sequence = [{ msg: "COMMENCING_FLOOD: UDP_PACKET_STORM_INITIATED", type: 'WARN' }, { msg: "BANDWIDTH_CONSUMPTION: 450Mbps_AND_RISING", type: 'INFO' }, { msg: "TARGET_STATE: CONNECTION_TIMEOUT_DETECTION", type: 'FAIL' }, { msg: "OUTCOME: SERVICE_UNAVAILABLE_SUCCESS", type: 'SUCCESS' }];
    }
    let i = 0;
    const interval = window.setInterval(() => {
      if (i >= sequence.length) {
        setIsIpAttacking(false);
        clearInterval(interval);
        return;
      }
      addIpLog(sequence[i].msg, sequence[i].type);
      i++;
    }, 800);
  };

  const fetchThreatIntel = async (query: string) => {
    if (!query || intelLoading) return;
    setIntelLoading(true);
    try {
      const advice = await getTroubleshootingAdvice(query, { lat: userLoc.lat, lng: userLoc.lng, satName: selectedSatName });
      setOutputs(prev => ({ ...prev, intel: advice || "NO_DATA_RETURNED" }));
    } catch (error) {
      setOutputs(prev => ({ ...prev, intel: "SYSTEM_FAILURE: INTELLIGENCE_UPLINK_TIMEOUT." }));
    } finally {
      setIntelLoading(false);
    }
  };

  const runThreatScan = () => {
    setIsScanning(true);
    setDetectionLogs([]);
    setTimeout(() => {
      setDetectionLogs([{ id: 'DT-01', type: 'RF_ANOMALY', severity: 'LOW', msg: 'Abnormal noise floor deviation at 14.2GHz', mitigation: 'Check hardware grounding.' }, { id: 'DT-02', type: 'AUTH_FAILURE', severity: 'MED', msg: 'Multiple failed SSH attempts from 10.0.0.42', mitigation: 'Enable Fail2Ban.' }, { id: 'DT-03', type: 'ENCRYPTION', severity: 'HIGH', msg: 'Clear-text traffic detected', mitigation: 'Enforce HTTPS/SSH immediately.' }]);
      setIsScanning(false);
    }, 2000);
  };

  const toggleHardening = (id: string) => {
    setHardeningOptions(prev => prev.map(opt => opt.id === id ? { ...opt, enabled: !opt.enabled } : opt));
  };

  const complianceScore = Math.round((hardeningOptions.filter(o => o.enabled).length / hardeningOptions.length) * 100);
  const getComplianceGrade = (score: number) => {
    if (score >= 95) return { grade: 'A+', color: 'text-green-400' };
    if (score >= 85) return { grade: 'A', color: 'text-green-500' };
    if (score >= 70) return { grade: 'B', color: 'text-cyan-400' };
    if (score >= 50) return { grade: 'C', color: 'text-amber-400' };
    if (score >= 25) return { grade: 'D', color: 'text-orange-500' };
    return { grade: 'F', color: 'text-red-500' };
  };
  const gradeInfo = getComplianceGrade(complianceScore);

  const getLogColor = (type: IPLogEntry['type']) => {
    switch(type) {
      case 'SUCCESS': return 'text-green-400';
      case 'FAIL': return 'text-red-500';
      case 'WARN': return 'text-amber-400';
      default: return 'text-slate-400';
    }
  };

  const toggleReveal = (key: string) => {
    setRevealed(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleManualResync = () => {
    setIsSyncing(true);
    setTimeout(() => {
      generateNewCodes();
      setIsSyncing(false);
    }, 1500);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex items-center justify-between mb-2">
        <h2 className="text-2xl font-bold flex items-center text-white uppercase tracking-tight">
          <span className="mr-3">🛡️</span> Security <span className="text-cyan-400 ml-2">Intelligence</span>
        </h2>
        {onBack && (
          <button onClick={onBack} className="flex items-center space-x-2 bg-slate-800 hover:bg-slate-700 text-[10px] font-bold text-slate-300 px-4 py-2 rounded-xl border border-slate-700 transition-all uppercase tracking-widest">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            <span>Mission Command</span>
          </button>
        )}
      </header>

      <div className="flex flex-wrap gap-2 border-b border-slate-800 pb-px">
        {['overview', 'attack', 'codes', 'intel', 'detection', 'hardening'].map((id) => (
          <button key={id} onClick={() => setActiveTab(id)} className={`px-4 py-2 text-[10px] font-bold uppercase tracking-widest transition-all border-b-2 ${activeTab === id ? 'border-cyan-500 text-cyan-400 bg-cyan-500/5' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
            {id}
          </button>
        ))}
      </div>

      <div className="py-4">
        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="glass p-6 rounded-2xl border-slate-800 hover:border-red-500/50 transition-all cursor-pointer group" onClick={() => setActiveTab('attack')}>
              <div className="w-10 h-10 bg-red-950/20 rounded-lg flex items-center justify-center border border-red-500/30 mb-4">
                <svg className="w-6 h-6 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              </div>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Offensive Ops</h3>
              <p className="text-xs text-slate-400">Jamming, IP Exploits, and Signal Hijacking.</p>
            </div>
            <div className="glass p-6 rounded-2xl border-slate-800 hover:border-cyan-500 transition-all cursor-pointer group" onClick={() => setActiveTab('detection')}>
              <div className="w-10 h-10 bg-cyan-950/20 rounded-lg flex items-center justify-center border border-cyan-500/30 mb-4">
                <svg className="w-6 h-6 text-cyan-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
              </div>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Signal Detection</h3>
              <p className="text-xs text-slate-400">Real-time monitoring for unauthorized uplinks.</p>
            </div>
            <div className="glass p-6 rounded-2xl border-slate-800 hover:border-amber-500/50 transition-all cursor-pointer group" onClick={() => setActiveTab('hardening')}>
              <div className="w-10 h-10 bg-amber-950/20 rounded-lg flex items-center justify-center border border-amber-500/30 mb-4">
                <svg className="w-6 h-6 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
              </div>
              <h3 className="text-white font-bold mb-2 uppercase text-sm tracking-widest">Hardening</h3>
              <p className="text-xs text-slate-400">Enforce FIPS compliance and port security.</p>
            </div>
          </div>
        )}

        {activeTab === 'codes' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-2">
            <div className="lg:col-span-2 glass p-8 rounded-3xl border-slate-800 flex flex-col justify-between relative overflow-hidden">
               <div className="absolute top-0 right-0 p-6 flex flex-col items-end">
                 <div className="flex items-center space-x-2">
                    <span className="text-[8px] font-bold text-slate-600 uppercase tracking-widest">Orbital_Sync_Phase</span>
                    <div className={`w-2 h-2 rounded-full ${authCodes.expire < 5 ? 'bg-red-500 animate-ping' : 'bg-cyan-500 animate-pulse'}`}></div>
                 </div>
                 <span className="text-[7px] mono text-slate-700 mt-1">PKT_DRIFT: +0.003ms</span>
               </div>

               <div>
                  <h3 className="text-white font-bold uppercase text-sm tracking-widest mb-1 flex items-center">
                    <svg className="w-4 h-4 mr-2 text-cyan-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
                    Tactical Authenticator
                  </h3>
                  <p className="text-[10px] text-slate-500 uppercase mono mb-10">Protocol: DVB-S2X_OTP_UPLINK // LAYER_2_AUTH</p>

                  <div className="grid grid-cols-1 gap-8">
                    {(['uplink', 'downlink', 'telemetry'] as const).map((key) => (
                      <div key={key} className="flex justify-between items-center border-b border-slate-900 pb-5 group hover:border-slate-800 transition-colors">
                         <div className="flex flex-col">
                           <span className="text-[9px] font-black text-slate-600 uppercase mb-1 tracking-widest">{key} Signal</span>
                           <button 
                             onClick={() => toggleReveal(key)}
                             className={`text-[8px] font-bold uppercase tracking-tighter text-left transition-colors ${revealed[key] ? 'text-slate-600' : 'text-cyan-500 hover:text-cyan-300'}`}
                           >
                             {revealed[key] ? '[MASK_DATA]' : '[DECRYPT_TOKEN]'}
                           </button>
                         </div>
                         <div className="flex flex-col items-end">
                           <span className={`text-3xl font-black mono tracking-[0.2em] transition-all duration-300 ${
                             revealed[key] 
                              ? (key === 'uplink' ? 'text-cyan-400 drop-shadow-[0_0_10px_rgba(34,211,238,0.4)]' : key === 'downlink' ? 'text-amber-400' : 'text-slate-200')
                              : 'text-slate-800 blur-md select-none opacity-30'
                           }`}>
                             {revealed[key] ? authCodes[key] : 'XXXXXX'}
                           </span>
                           {revealed[key] && <span className="text-[7px] text-slate-700 mono mt-1">HASH_VERIFIED_SHA256</span>}
                         </div>
                      </div>
                    ))}
                  </div>
               </div>

               <div className="mt-12 bg-slate-950/80 p-6 rounded-2xl border border-slate-900">
                  <div className="flex justify-between text-[9px] font-bold mono text-slate-500 mb-3 uppercase tracking-widest">
                    <span>Key_Expiration_Countdown</span>
                    <span className={authCodes.expire < 10 ? 'text-red-500 animate-pulse' : 'text-cyan-400'}>{authCodes.expire}S</span>
                  </div>
                  <div className="w-full h-1.5 bg-slate-900 rounded-full overflow-hidden shadow-inner">
                    <div className={`h-full transition-all duration-1000 ${authCodes.expire < 10 ? 'bg-red-600' : 'bg-cyan-600'}`} style={{ width: `${(authCodes.expire / 30) * 100}%` }}></div>
                  </div>
                  <div className="grid grid-cols-2 gap-3 mt-6">
                    <button 
                      onClick={handleManualResync}
                      disabled={isSyncing}
                      className={`py-3 rounded-xl text-[9px] font-bold uppercase tracking-[0.2em] transition-all flex items-center justify-center space-x-2 ${isSyncing ? 'bg-slate-800 text-slate-600' : 'bg-slate-900 hover:bg-slate-800 text-cyan-500 border border-cyan-500/20'}`}
                    >
                      <span>{isSyncing ? 'RESYNCING...' : 'Manual Sync'}</span>
                    </button>
                    <button 
                      onClick={() => generateNewCodes()}
                      className="py-3 bg-red-950/20 hover:bg-red-950/40 border border-red-500/20 rounded-xl text-[9px] font-bold text-red-500 uppercase tracking-[0.2em] transition-all"
                    >
                      Cycle Keys
                    </button>
                  </div>
               </div>
            </div>

            <div className="lg:col-span-1 space-y-6 flex flex-col">
               <div className="glass p-6 rounded-3xl border-slate-800 bg-slate-950/40 flex-grow">
                  <div className="flex items-center justify-between mb-6">
                    <h4 className="text-[10px] font-bold text-cyan-500 uppercase tracking-widest">Rotation Telemetry</h4>
                    <span className="text-[8px] font-bold text-slate-700 px-2 py-0.5 border border-slate-800 rounded mono">CYCLE_{keyRotationCount}</span>
                  </div>

                  <div className="space-y-4">
                    <div className="flex items-center space-x-3 bg-slate-950 p-3 rounded-xl border border-slate-900">
                       <div className="flex flex-col">
                          <span className="text-[8px] font-bold text-slate-500 uppercase">Signal Strength</span>
                          <span className="text-[10px] font-bold text-white mono">-72.4 dBm</span>
                       </div>
                    </div>
                    <div className="space-y-3 px-1">
                      <div className="flex justify-between text-[9px] mono border-b border-slate-900 pb-2">
                         <span className="text-slate-600">Entropy Source</span>
                         <span className="text-cyan-500 uppercase">Quantum_TRNG</span>
                      </div>
                      <div className="flex justify-between text-[9px] mono border-b border-slate-900 pb-2">
                         <span className="text-slate-600">Sync Status</span>
                         <span className="text-green-500 font-bold uppercase">Locked</span>
                      </div>
                    </div>
                  </div>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'attack' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-in slide-in-from-bottom-2">
            <div className="glass p-6 rounded-2xl border-slate-800 border-l-4 border-l-red-500/50">
              <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Strike & EW Terminal</h4>
              <div className="space-y-4">
                <input type="text" value={targetIp} onChange={(e) => setTargetIp(e.target.value)} placeholder="IP_ADDR..." className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-xs text-white mono outline-none focus:border-red-500 transition-colors" />
                <select value={attackVector} onChange={(e) => setAttackVector(e.target.value as AttackVector)} className="w-full bg-slate-950 border border-slate-800 rounded-lg p-2 text-xs text-white mono outline-none focus:border-red-500 cursor-pointer">
                  <option value="SCAN">PORT_SCAN</option>
                  <option value="EXPLOIT">EXPLOIT_PAYLOAD</option>
                  <option value="DOS">DENIAL_OF_SERVICE</option>
                </select>
                <button onClick={runIpAttack} disabled={isIpAttacking} className="w-full bg-red-600 hover:bg-red-500 disabled:opacity-30 text-white text-[10px] font-bold py-3 rounded-xl uppercase tracking-widest shadow-lg shadow-red-500/10">
                  {isIpAttacking ? 'MISSION_IN_PROGRESS...' : 'COMMENCE_STRIKE'}
                </button>
                <div ref={terminalRef} className="bg-slate-950 p-4 rounded-xl h-[240px] overflow-y-auto font-mono text-[9px] border border-slate-900">
                  {ipAttackLog.map((log, i) => (
                    <div key={i} className="flex space-x-2"><span className="text-slate-600 shrink-0">[{log.time}]</span><span className={getLogColor(log.type)}>{log.msg}</span></div>
                  ))}
                </div>
              </div>
            </div>
            <div className="glass p-6 rounded-2xl border-slate-800 border-l-4 border-l-red-500/50">
              <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Jamming Control</h4>
              <div className="space-y-2">
                <div className="flex justify-between text-[9px] font-bold mono text-slate-600"><span>Power Intensity</span><span>{jammingPower}%</span></div>
                <input type="range" min="0" max="100" value={jammingPower} onChange={(e) => setJammingPower(parseInt(e.target.value))} className={`w-full h-1 rounded-lg appearance-none cursor-pointer transition-all ${isJamming ? 'bg-red-900/50 accent-red-500' : 'bg-slate-800 accent-slate-600'}`} />
              </div>
              <button onClick={() => setIsJamming(!isJamming)} className={`w-full mt-4 py-3 rounded-xl font-bold text-xs uppercase transition-all ${isJamming ? 'bg-red-600 text-white shadow-[0_0_20px_rgba(239,68,68,0.3)]' : 'bg-slate-800 text-red-500 border border-red-500/20 hover:bg-red-950/10'}`}>
