                {intelLoading ? 'QUERING_STRATEGIC_DATABASE...' : 'Query Threat Database'}
              </button>
            </div>
            {outputs.intel && (
              <div className="animate-in fade-in slide-in-from-top-2 duration-700">
                <pre className="bg-slate-950 p-6 rounded-2xl border border-slate-800 text-cyan-400 text-[11px] font-mono whitespace-pre-wrap leading-relaxed max-h-[500px] overflow-auto shadow-inner">
                  {outputs.intel}
                </pre>
              </div>
            )}
          </div>
        )}

        {activeTab === 'hardening' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-8 space-y-4">
              <div className="glass p-6 rounded-2xl border-slate-800">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {hardeningOptions.map((opt) => (
                    <div key={opt.id} onClick={() => toggleHardening(opt.id)} className={`group flex items-center p-4 rounded-xl border cursor-pointer transition-all duration-300 ${opt.enabled ? 'bg-green-500/10 border-green-500/40 shadow-[0_0_20px_rgba(34,197,94,0.1)]' : 'bg-slate-950 border-slate-800 hover:border-slate-700'}`}>
                      <div className="ml-4">
                        <div className={`text-[10px] font-bold uppercase tracking-wide ${opt.enabled ? 'text-green-400' : 'text-slate-300'}`}>{opt.label}</div>
                        <p className="text-[9px] text-slate-500 mt-0.5 leading-tight">{opt.description}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
            <div className="lg:col-span-4 glass p-8 rounded-2xl border-slate-800 flex flex-col items-center justify-center text-center">
              <div className={`text-4xl font-black mono transition-colors duration-500 ${gradeInfo.color}`}>{complianceScore}%</div>
              <div className={`text-xs font-bold uppercase mt-1 opacity-60 ${gradeInfo.color}`}>Grade: {gradeInfo.grade}</div>
            </div>
          </div>
        )}

        {activeTab === 'detection' && (
          <div className="glass p-6 rounded-2xl border-slate-800">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-white font-bold uppercase text-sm tracking-widest">Link Monitoring Service</h3>
              <button onClick={runThreatScan} disabled={isScanning} className="bg-cyan-600 hover:bg-cyan-500 disabled:opacity-30 text-slate-950 font-bold px-6 py-2 rounded-lg text-[10px] uppercase tracking-widest shadow-lg">
                {isScanning ? 'Scanning...' : 'Start Global Scan'}
              </button>
            </div>
            <div className="space-y-3">
              {detectionLogs.map((log) => (
                <div key={log.id} className="bg-slate-950 p-4 rounded-xl border border-slate-800">
                  <div className="flex items-center justify-between mb-2">
                    <span className={`text-[8px] font-bold px-2 py-0.5 rounded uppercase ${log.severity === 'HIGH' ? 'bg-red-500 text-white' : 'bg-blue-500 text-white'}`}>{log.severity}</span>
                  </div>
                  <p className="text-[10px] text-slate-400 mono">{log.msg}</p>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

