    setIsScanning(true);
    setDetectionLogs([]);
    setTimeout(() => {
      setDetectionLogs([{ id: 'DT-01', type: 'RF_ANOMALY', severity: 'LOW', msg: 'Abnormal noise floor deviation at 14.2GHz', mitigation: 'Check hardware grounding.' }, { id: 'DT-02', type: 'AUTH_FAILURE', severity: 'MED', msg: 'Multiple failed SSH attempts from 10.0.0.42', mitigation: 'Enable Fail2Ban.' }, { id: 'DT-03', type: 'ENCRYPTION', severity: 'HIGH', msg: 'Clear-text traffic detected', mitigation: 'En

