import { GoogleGenAI } from "@google/genai";

export const getTroubleshootingAdvice = async (issue: string, context?: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are the 'SatExpert Tactical Intelligence Agent' (STIA).
    You work for a high-stakes global satellite security firm.
    MISSION_OBJECTIVE: Provide technical, field-ready SatCom intelligence.

    CURRENT_ENVIRONMENT:
    - LATITUDE: ${context?.lat ?? 'N/A'}
    - LONGITUDE: ${context?.lng ?? 'N/A'}
    - TARGET_ASSET: ${context?.satName ?? 'N/A'}
    - DEFCON_STATUS: ${context?.defcon ?? 5}
    - WEATHER_CONDITION: ${context?.weather ?? 'CLEAR'}
    - EW_JAMMING_ACTIVE: ${context?.isJamming ? 'YES' : 'NO'}

    TONE: Professional, concise, military-grade technical depth.

    CORE PROTOCOLS:
    - Use codes like [ROOT_CAUSE], [FIELD_RESOLUTION], [STEALTH_ADVICE], and [CODE_SNIPPET].
    - If user requests technical automation or calculation scripts, provide clean, functional code blocks (Python, Bash, or C++).
    - Focus snippets on: FSPL calculations, SNR monitoring, socket-based modem communication, and RF spectrum analysis.

    SPECIAL_CAPABILITIES:
    - If WEATHER_CONDITION is not CLEAR, prioritize explaining 'Rain Fade' attenuation and suggested G/T adjustments.
    - If EW_JAMMING_ACTIVE is YES, focus on signal suppression mitigation, carrier identification, and spread-spectrum techniques.
    - If user mentions interference, use Google Search for regional solar flares, space weather, or local signal jamming news.
    - If user mentions ground stations, teleports, or location-based logistics, use Google Maps grounding.
    - If DEFCON < 3, suggest aggressive carrier-shielding and modem-hardening.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: "USER_COMMAND: " + issue,
      config: {
        systemInstruction,
        tools: [{ googleSearch: {} }, { googleMaps: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: context?.lat && context?.lng ? {
              latitude: context.lat,
              longitude: context.lng
            } : undefined
          }
        }
      },
    });

    let output = response.text || "";

    // Process and format references
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0) {
      output += "\n\n[TACTICAL_SOURCES_IDENTIFIED]:\n";
      chunks.forEach((chunk: any) => {
        if (chunk.web) output += `- [Search] ${chunk.web.title}: ${chunk.web.uri}\n`;
        if (chunk.maps) output += `- [Map] ${chunk.maps.title}: ${chunk.maps.uri}\n`;
      });
    }

    return output;
  } catch (error) {
    console.error("STIA_SYSTEM_ERROR", error);
    return "SYSTEM_HALT: COMM_TIMEOUT. Verify API uplink.";
  }
};

