import { GoogleGenAI, Type, FunctionDeclaration, Content } from "@google/genai";

// Mock Data Function for VSAT Terminal Sensors
const getMockSensorData = (context: any) => {
  const isJamming = context?.isJamming || false;
  const weather = context?.weather || 'CLEAR';
  const defcon = context?.defcon || 5;

  let snr = 16.0;
  let rxPower = -42.0;
  let packetLoss = 0.00;
  let bucTemp = 45.0;

  // Weather effects on signal
  if (weather === 'OVERCAST') { snr -= 2.0; rxPower -= 1.5; }
  else if (weather === 'LIGHT_RAIN') { snr -= 5.0; rxPower -= 3.5; packetLoss += 0.8; }
  else if (weather === 'HEAVY_STORM') { snr -= 14.0; rxPower -= 12.0; packetLoss += 12.5; }

  // Jamming effects
  if (isJamming) {
    snr -= 18.0; 
    packetLoss += 45.0;
    rxPower += 8.0; // Noise floor increase typically raises measured power while degrading SNR
    bucTemp += 5.0;
  }

  // High alert state often means harder driving of the BUC
  if (defcon <= 2) bucTemp += 8.0;

  // Add random jitter for realism
  snr += (Math.random() - 0.5);
  bucTemp += (Math.random() - 0.5) * 2;

  return {
    timestamp: new Date().toISOString(),
    telemetry: {
        snr_margin_db: Math.max(0, snr).toFixed(2),
        rx_power_dbm: rxPower.toFixed(1),
        buc_temperature_c: bucTemp.toFixed(1),
        lnb_voltage_v: "18.1",
        packet_loss_percent: packetLoss.toFixed(2),
        round_trip_latency_ms: (550 + Math.random() * 50).toFixed(0),
        modem_lock_status: snr > 4 ? "LOCKED" : "UNLOCKED"
    },
    system_status: snr > 10 ? "NOMINAL" : (snr > 4 ? "DEGRADED" : "CRITICAL_FAILURE")
  };
};

// Tool Definition
const terminalSensorTool: FunctionDeclaration = {
  name: "read_terminal_sensors",
  description: "Reads live sensor telemetry from the local VSAT terminal hardware. Returns SNR, power levels, temperature, and packet stats.",
  parameters: {
    type: Type.OBJECT,
    properties: {},
  },
};

export const getTroubleshootingAdvice = async (issue: string, context?: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelId = 'gemini-2.5-flash';

  const systemInstruction = `
    You are the 'SatExpert Tactical Intelligence Agent' (STIA).
    You work for a high-stakes global satellite security firm.
    MISSION_OBJECTIVE: Provide technical, field-ready SatCom intelligence.

    CURRENT_ENVIRONMENT:
    - LATITUDE: ${context?.lat ?? 'N/A'}
    - LONGITUDE: ${context?.lng ?? 'N/A'}
    - TARGET_ASSET: ${context?.satName ?? 'N/A'}
    - DEFCON_STATUS: ${context?.defcon ?? 5}
    - WEATHER_CONDITION: ${context?.weather ?? 'CLEAR'}
    - EW_JAMMING_ACTIVE: ${context?.isJamming ? 'YES' : 'NO'}

    CAPABILITIES:
    - You can read terminal sensors using the tool 'read_terminal_sensors'. USE THIS if the user asks for "diagnostics", "sensor data", "telemetry", "health check", or "status".

    TONE: Professional, concise, military-grade technical depth.

    CORE PROTOCOLS:
    - Use codes like [ROOT_CAUSE], [FIELD_RESOLUTION], [STEALTH_ADVICE], and [CODE_SNIPPET].
    - If user requests technical automation or calculation scripts, provide clean, functional code blocks (Python, Bash, or C++).
    - Focus snippets on: FSPL calculations, SNR monitoring, socket-based modem communication, and RF spectrum analysis.

    SPECIAL_CAPABILITIES:
    - If WEATHER_CONDITION is not CLEAR, prioritize explaining 'Rain Fade' attenuation and suggested G/T adjustments.
    - If EW_JAMMING_ACTIVE is YES, focus on signal suppression mitigation, carrier identification, and spread-spectrum techniques.
    - If user mentions interference, use Google Search for regional solar flares, space weather, or local signal jamming news.
    - If user mentions ground stations, teleports, or location-based logistics, use Google Maps grounding.
    - If DEFCON < 3, suggest aggressive carrier-shielding and modem-hardening.
  `;

  try {
    const tools = [
        { googleSearch: {} }, 
        { googleMaps: {} }, 
        { functionDeclarations: [terminalSensorTool] }
    ];

    const messages: Content[] = [
        { role: 'user', parts: [{ text: "USER_COMMAND: " + issue }] }
    ];

    // Initial Request
    let response = await ai.models.generateContent({
      model: modelId,
      contents: messages,
      config: {
        systemInstruction,
        tools,
        toolConfig: {
          retrievalConfig: {
            latLng: context?.lat && context?.lng ? {
              latitude: context.lat,
              longitude: context.lng
            } : undefined
          }
        }
      },
    });

    // Handle Tool Calls
    const functionCalls = response.functionCalls;
    if (functionCalls && functionCalls.length > 0) {
        const call = functionCalls[0];
        if (call.name === 'read_terminal_sensors') {
            const data = getMockSensorData(context);

            // Add the model's request to history
            // We use non-null assertion because if functionCalls exists, candidates[0] exists.
            messages.push(response.candidates![0].content);

            // Add the tool response
            messages.push({
                role: 'tool',
                parts: [{
                    functionResponse: {
                        name: 'read_terminal_sensors',
                        response: { result: data }
                    }
                }]
            });

            // Follow up with tool data
            response = await ai.models.generateContent({
                model: modelId,
                contents: messages,
                config: { systemInstruction, tools }
            });
        }
    }

    let output = response.text || "";

    // Process and format references from grounding
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0) {
      output += "\n\n[TACTICAL_SOURCES_IDENTIFIED]:\n";
      chunks.forEach((chunk: any) => {
        if (chunk.web) output += `- [Search] ${chunk.web.title}: ${chunk.web.uri}\n`;
        if (chunk.maps) output += `- [Map] ${chunk.maps.title}: ${chunk.maps.uri}\n`;
      });
    }

    return output;
  } catch (error) {
    console.error("STIA_SYSTEM_ERROR", error);
    return "SYSTEM_HALT: COMM_TIMEOUT. Verify API uplink.";
  }
};

