import { GoogleGenAI, Type, FunctionDeclaration, Content } from "@google/genai";

// Tool Definition
const terminalSensorTool: FunctionDeclaration = {
  name: "read_terminal_sensors",
  description: "Reads live sensor telemetry from the local VSAT terminal hardware. Returns SNR, power levels, temperature, and packet stats.",
  parameters: {
    type: Type.OBJECT,
    properties: {},
  },
};

export const getTroubleshootingAdvice = async (issue: string, context?: any, telemetry?: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelId = 'gemini-3-flash-preview';

  const systemInstruction = `
    You are the 'SatExpert Tactical Intelligence Agent' (STIA).
    MISSION: Provide technical SatCom intelligence.

    ENVIRONMENT:
    - LAT: ${context?.lat ?? 'N/A'}, LNG: ${context?.lng ?? 'N/A'}
    - TARGET: ${context?.satName ?? 'N/A'}
    - DEFCON: ${context?.defcon ?? 5}
    - WEATHER: ${context?.weather ?? 'CLEAR'}
    - EW_JAMMING: ${context?.isJamming ? 'YES' : 'NO'}

    REAL-TIME TELEMETRY (IF TOOL CALLED):
    - When 'read_terminal_sensors' is called, you will receive the actual hardware state. 
    - Base your diagnostic strictly on these numbers.

    TONE: Professional, concise, military-grade.
  `;

  try {
    const tools = [
        { googleSearch: {} }, 
        { googleMaps: {} }, 
        { functionDeclarations: [terminalSensorTool] }
    ];

    const messages: Content[] = [
        { role: 'user', parts: [{ text: "USER_COMMAND: " + issue }] }
    ];

    let response = await ai.models.generateContent({
      model: modelId,
      contents: messages,
      config: {
        systemInstruction,
        tools,
        toolConfig: {
          retrievalConfig: {
            latLng: context?.lat && context?.lng ? {
              latitude: context.lat,
              longitude: context.lng
            } : undefined
          }
        }
      },
    });

    const functionCalls = response.functionCalls;
    if (functionCalls && functionCalls.length > 0) {
        const call = functionCalls[0];
        if (call.name === 'read_terminal_sensors') {
            // Use telemetry passed from the UI source of truth
            messages.push(response.candidates![0].content);
            messages.push({
                role: 'tool',
                parts: [{
                    functionResponse: {
                        name: 'read_terminal_sensors',
                        response: { result: telemetry }
                    }
                }]
            });

            response = await ai.models.generateContent({
                model: modelId,
                contents: messages,
                config: { systemInstruction, tools }
            });
        }
    }

    let output = response.text || "";
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0) {
      output += "\n\n[TACTICAL_SOURCES_IDENTIFIED]:\n";
      chunks.forEach((chunk: any) => {
        if (chunk.web) output += `- [Search] ${chunk.web.title}: ${chunk.web.uri}\n`;
        if (chunk.maps) output += `- [Map] ${chunk.maps.title}: ${chunk.maps.uri}\n`;
      });
    }

    return output;
  } catch (error) {
    console.error("STIA_SYSTEM_ERROR", error);
    return "SYSTEM_HALT: COMM_TIMEOUT. Verify API uplink.";
  }
};

import * as React from 'react';
import { useState, useEffect, useRef, useMemo } from 'react';
import { Layout } from './components/Layout.tsx';
import { LookAngleCard } from './components/LookAngleCard.tsx';
import { AITechnician } from './components/AITechnician.tsx';
import { SecurityTools } from './components/SecurityTools.tsx';
import { LinkBudgetCalculator } from './components/LinkBudgetCalculator.tsx';
import { SignalVisualizer } from './components/SignalVisualizer.tsx';
import { TacticalHUD } from './components/TacticalHUD.tsx';
import { TacticalMap } from './components/TacticalMap.tsx';
import { RSSReader } from './components/RSSReader.tsx';
import { TelemetryPulse } from './components/TelemetryPulse.tsx';
import { Coordinates, Satellite, LookAngles, WeatherCondition } from './types.ts';
import { COMMON_SATELLITES } from './constants.ts';
import { calculateLookAngles } from './utils/geoUtils.ts';
import { playSystemVoice } from './services/audioService.ts';

type MainView = 'tactical' | 'intelligence' | 'calculations' | 'news';

const STORAGE_KEY = 'satexpert_tactical_v5';

export const App: React.FC = () => {
  const [userLoc, setUserLoc] = useState<Coordinates>({ lat: 51.5074, lng: -0.1278 });
  const [selectedSat, setSelectedSat] = useState<Satellite>(COMMON_SATELLITES[0]);
  const [lookAngles, setLookAngles] = useState<LookAngles | null>(null);
  const [view, setView] = useState<MainView>('tactical');
  const [defcon, setDefcon] = useState<number>(5);
  const [isTracking, setIsTracking] = useState<boolean>(false);
  const [weather, setWeather] = useState<WeatherCondition>('CLEAR');
  const [isJamming, setIsJamming] = useState<boolean>(false);
  const [jammingPower, setJammingPower] = useState<number>(50);

  const prevDefconRef = useRef(5);
  const isFirstMount = useRef(true);

  // Source of Truth Telemetry logic
  const telemetry = useMemo(() => {
    let snr = 16.0;
    let rxPower = -42.0;
    let packetLoss = 0.00;
    let bucTemp = 45.0;

    if (weather === 'OVERCAST') { snr -= 2.0; rxPower -= 1.5; }
    else if (weather === 'LIGHT_RAIN') { snr -= 5.0; rxPower -= 3.5; packetLoss += 0.8; }
    else if (weather === 'HEAVY_STORM') { snr -= 14.0; rxPower -= 12.0; packetLoss += 12.5; }

    if (isJamming) {
      snr -= (jammingPower / 5); 
      packetLoss += (jammingPower / 2);
      rxPower += (jammingPower / 10);
      bucTemp += (jammingPower / 15);
    }

    if (defcon <= 2) bucTemp += 8.0;

    return {
      snr: Math.max(0, snr + (Math.random() - 0.5)).toFixed(2),
      rxPower: (rxPower + (Math.random() - 0.5)).toFixed(1),
      bucTemp: (bucTemp + (Math.random() - 0.5)).toFixed(1),
      packetLoss: Math.min(100, packetLoss + (Math.random() * 0.2)).toFixed(2),
      status: snr > 10 ? "NOMINAL" : (snr > 4 ? "DEGRADED" : "CRITICAL")
    };
  }, [weather, isJamming, jammingPower, defcon]);

  const currentRainFade = useMemo(() => {
    switch(weather) {
      case 'CLEAR': return 0.5;
      case 'OVERCAST': return 1.8;
      case 'LIGHT_RAIN': return 4.5;
      case 'HEAVY_STORM': return 12.0;
      default: return 0.5;
    }
  }, [weather]);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.loc) setUserLoc(parsed.loc);
      if (parsed.satId) {
        const sat = COMMON_SATELLITES.find(s => s.id === parsed.satId);
        if (sat) setSelectedSat(sat);
      }
      setDefcon(parsed.defcon || 5);
    }
    isFirstMount.current = false;
  }, []);

  useEffect(() => {
    const angles = calculateLookAngles(userLoc, selectedSat.longitude);
    setLookAngles(angles);
  }, [userLoc, selectedSat]);

  const isDistorted = isJamming || defcon === 1;

  return (
    <div className={`crt-screen min-h-screen ${isDistorted ? 'crt-distorted' : ''}`}>
      <Layout>
        <div className="flex flex-col space-y-6 max-w-7xl mx-auto pb-12 transition-all duration-1000">

          {/* Defcon & Status Bar */}
          <div className={`flex flex-col md:flex-row items-center justify-between gap-4 glass p-4 rounded-2xl border-slate-800 shadow-2xl relative overflow-hidden ${defcon === 1 || isJamming ? 'defcon-alert' : ''}`}>
             <div className="flex items-center space-x-6 z-20">
              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-cyan-500 uppercase tracking-[0.2em] mb-1">Mission Module</span>
                <div className="flex space-x-1 bg-slate-950/50 p-1 rounded-lg border border-slate-800">
                  {(['tactical', 'intelligence', 'calculations', 'news'] as MainView[]).map((v) => (
                    <button
                      key={v}
                      onClick={() => setView(v)}
                      className={`px-4 py-1.5 rounded text-[9px] font-bold uppercase tracking-widest transition-all ${
                        view === v 
                          ? 'bg-cyan-500 text-slate-950 shadow-lg' 
                          : 'text-slate-500 hover:text-cyan-400'
                      }`}
                    >
                      {v}
                    </button>
                  ))}
                </div>
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Threat Protocol</span>
                <div className="flex space-x-2">
                  {[5, 4, 3, 2, 1].map(lvl => (
                    <button 
                      key={lvl}
                      onClick={() => setDefcon(lvl)}
                      className={`w-7 h-7 rounded flex items-center justify-center text-[10px] font-bold transition-all border ${
                        defcon === lvl ? 'bg-cyan-500/20 text-cyan-400 border-cyan-500/40' : 'bg-slate-900 border-slate-800 text-slate-600'
                      }`}
                    >
                      {lvl}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex items-center space-x-6 z-20">
               <TelemetryPulse telemetry={telemetry} />
            </div>
          </div>

          <div className="min-h-[70vh]">
            {view === 'tactical' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="lg:col-span-4 space-y-6">
                  <TacticalHUD 
                    loc={userLoc} 
                    sat={selectedSat} 
                    onLocChange={setUserLoc} 
                    onSatChange={setSelectedSat}
                    isTracking={isTracking}
                    onTrackingChange={setIsTracking}
                    isJamming={isJamming}
                    setIsJamming={setIsJamming}
                    jammingPower={jammingPower}
                    setJammingPower={setJammingPower}
                    weather={weather}
                    setWeather={setWeather}
                  />
                  <TacticalMap userLoc={userLoc} satellite={selectedSat} isTracking={isTracking} onLocChange={setUserLoc} />
                  {lookAngles && <LookAngleCard angles={lookAngles} satellite={selectedSat} />}
                  <SignalVisualizer 
                    quality={lookAngles?.elevation && lookAngles.elevation > 0 ? 85 : 0} 
                    isJamming={isJamming}
                    jammingPower={jammingPower}
                    rainFade={currentRainFade}
                  />
                </div>
                <div className="lg:col-span-8">
                  <AITechnician 
                    context={{ 
                      lat: userLoc.lat, 
                      lng: userLoc.lng, 
                      satName: selectedSat.name,
                      defcon,
                      weather,
                      isJamming
                    }}
                    telemetry={telemetry}
                  />
                </div>
              </div>
            )}

            {view === 'intelligence' && (
              <SecurityTools 
                userLoc={userLoc} 
                selectedSatName={selectedSat.name}
                isJamming={isJamming}
                setIsJamming={setIsJamming}
                jammingPower={jammingPower}
                setJammingPower={setJammingPower}
                signalQuality={88}
                onBack={() => setView('tactical')}
              />
            )}

            {view === 'calculations' && lookAngles && (
              <LinkBudgetCalculator distance={lookAngles.distance} externalRainFade={currentRainFade} />
            )}

            {view === 'news' && <RSSReader />}
          </div>
        </div>
      </Layout>
    </div>
  );
};

