              <div ref={terminalRef} className="bg-slate-950 p-4 rounded-2xl border border-slate-900 h-full min-h-[300px] overflow-y-auto font-mono text-[9px] shadow-inner">
                <div className="text-[8px] font-bold text-slate-700 uppercase mb-2 border-b border-slate-900 pb-1">EW_AUDIT_TRAIL</div>
