                  <p className="text-[10px] text-slate-500 uppercase mono mb-10">Protocol: DVB-S2X_OTP_UPLINK // LAYER_2_AUTH</p>

                  <div className="grid grid-cols-1 gap-8">
                    {(['uplink', 'downlink', 'telemetry'] as const).map((key) => (
                      <div key={key} className="flex justify-between items-center border-b border-slate-900 pb-5 group hover:border-slate-800 transition-colors">
