            type,
            severity,
            message,
        };
        setEventLog(prev => [newEvent, ...prev].slice(0, 100));
    };

    const handleQkdSync = () => {
        if (qkdStatus === 'SYNCING') return;
        setQkdStatus('SYNCING');
        addLog('QKD', 'NOMINAL', 'Photon stream initiated for key exchange.');
        playSystemVoice('Initiating quantum key exchange.');

        setTimeout(() => {
            const outcome = Math.random();
            if (outcome < 0.7) {
                setQkdStatus('SYNCHRONIZED');
                addLog('QKD', 'NOMINAL', 'Key synchronization successful. Entanglement verified.');
