                setQkdStatus('EAVESDROP_DETECTED');
                addLog('QKD', 'CRITICAL', 'ALERT: Photon state collapse indicates measurement attempt! Eavesdropper detected!');
                playSystemVoice('Critical alert. Eavesdropping detected on quantum channel.');
            }
