    return (
        <div className={`grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4 duration-700 ${isCritical ? 'defcon-alert' : ''}`}>
            {/* LEFT COLUMN */}
            <div className="lg:col-span-1 space-y-6">
                <div className={`glass p-6 rounded-2xl border ${isCritical ? 'border-red-500/50' : 'border-slate-800'}`}>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-white mb-4">Quantum Core Status</h3>
                    <div className="flex flex-col items-center justify-center space-y-4">
                        <div className={`text-center font-bold mono text-lg uppercase transition-colors ${statusConfig[qkdStatus].color} ${statusConfig[qkdStatus].pulse ? 'animate-pulse' : ''}`}>
                           {statusConfig[qkdStatus].label}
                        </div>
                        <p className="text-[9px] text-slate-500 text-center mono max-w-xs">
                           System monitors photon polarization to ensure cryptographic integrity. Any measurement attempt collapses the waveform, instantly revealing tampering.
                        </p>
                    </div>
                </div>

                <div className="glass p-6 rounded-2xl border border-slate-800">
                    <h3 className="text-sm font-bold uppercase tracking-widest text-white mb-4">Quantum Key Distribution</h3>
                    <button 
                        onClick={handleQkdSync} 
                        disabled={qkdStatus === 'SYNCING'}
                        className="w-full bg-cyan-600 hover:bg-cyan-500 disabled:opacity-30 text-slate-950 font-bold py-3 rounded-xl uppercase tracking-widest text-xs shadow-lg shadow-cyan-500/10 transition-all"
                    >
                        {qkdStatus === 'SYNCING' ? 'Transmitting Photons...' : 'Initiate QKD Sync'}
                    </button>
                </div>
            </div>

            {/* MIDDLE COLUMN */}
            <div className="lg:col-span-1 space-y-6">
                <div className="glass p-6 rounded-2xl border border-slate-800">
                    <h3 className="text-sm font-bold uppercase tracking-widest text-white mb-4">Defensive Protocols</h3>
                    <div className="space-y-4">
