                  </>
                )}
            </div>
        </div>
    );
};

import { GoogleGenAI, Type, FunctionDeclaration, Content } from "@google/genai";

// Tool Definition
const terminalSensorTool: FunctionDeclaration = {
  name: "read_terminal_sensors",
  description: "Reads live sensor telemetry from the local VSAT terminal hardware. Returns SNR, power levels, temperature, and packet stats.",
  parameters: {
    type: Type.OBJECT,
    properties: {},
  },
};

export const getTroubleshootingAdvice = async (issue: string, context?: any, telemetry?: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelId = 'gemini-3-flash-preview';

  const systemInstruction = `
    You are the 'SatExpert Tactical Intelligence Agent' (STIA).
    MISSION: Provide technical SatCom intelligence.

    ENVIRONMENT:
    - LAT: ${context?.lat ?? 'N/A'}, LNG: ${context?.lng ?? 'N/A'}
    - TARGET: ${context?.satName ?? 'N/A'}
    - DEFCON: ${context?.defcon ?? 5}
    - WEATHER: ${context?.weather ?? 'CLEAR'}
    - EW_JAMMING: ${context?.isJamming ? 'YES' : 'NO'}

    REAL-TIME TELEMETRY (IF TOOL CALLED):
    - When 'read_terminal_sensors' is called, you will receive the actual hardware state. 
    - Base your diagnostic strictly on these numbers.

    TONE: Professional, concise, military-grade.
  `;

  try {
    const tools = [
        { googleSearch: {} }, 
        { functionDeclarations: [terminalSensorTool] }
    ];

    const messages: Content[] = [
        { role: 'user', parts: [{ text: "USER_COMMAND: " + issue }] }
    ];

    let response = await ai.models.generateContent({
      model: modelId,
      contents: messages,
      config: {
        systemInstruction,
        tools,
        toolConfig: {
          retrievalConfig: {
            latLng: context?.lat && context?.lng ? {
              latitude: context.lat,
              longitude: context.lng
            } : undefined
          }
        }
      },
    });

    const functionCalls = response.functionCalls;
    if (functionCalls && functionCalls.length > 0) {
        const call = functionCalls[0];
        if (call.name === 'read_terminal_sensors') {
            // Use telemetry passed from the UI source of truth
            messages.push(response.candidates![0].content);
            messages.push({
                role: 'tool',
                parts: [{
                    functionResponse: {
                        name: 'read_terminal_sensors',
                        response: { result: telemetry }
                    }
                }]
            });

            response = await ai.models.generateContent({
                model: modelId,
                contents: messages,
                config: { systemInstruction, tools }
            });
        }
    }

    let output = response.text || "";
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0) {
      output += "\n\n[TACTICAL_SOURCES_IDENTIFIED]:\n";
      chunks.forEach((chunk: any) => {
        if (chunk.web) output += `- [Search] ${chunk.web.title}: ${chunk.web.uri}\n`;
      });
    }

    return output;
  } catch (error) {
    console.error("STIA_SYSTEM_ERROR", error);
    return "SYSTEM_HALT: COMM_TIMEOUT. Verify API uplink.";
  }
};

const warGamesTurnSchema = {
  type: Type.OBJECT,
  properties: {
    redTeamAction: {
      type: Type.OBJECT,
      properties: {
        action: { type: Type.STRING, description: 'The specific action taken by the Red Team.' },
        rationale: { type: Type.STRING, description: 'The tactical reason for this action.' }
      },
      required: ['action', 'rationale']
    },
    blueTeamAction: {
      type: Type.OBJECT,
      properties: {
        action: { type: Type.STRING, description: 'The Blue Team\'s reaction or proactive measure.' },
        rationale: { type: Type.STRING, description: 'The defensive reason for this action.' }
      },
      required: ['action', 'rationale']
    },
    systemStateChange: {
      type: Type.OBJECT,
      properties: {
        narrative: { type: Type.STRING, description: 'A brief, neutral narration of the turn\'s outcome.' },
        link_integrity_delta: { type: Type.NUMBER, description: 'Change in link integrity percentage (-100 to 100).' },
        threat_level: { type: Type.STRING, description: 'The new overall threat level (LOW, ELEVATED, HIGH, CRITICAL).' }
      },
      required: ['narrative', 'link_integrity_delta', 'threat_level']
    },
    isObjectiveMet: {
      type: Type.BOOLEAN,
      description: 'True if the Red Team has achieved its objective this turn.'
    }
  },
  required: ['redTeamAction', 'blueTeamAction', 'systemStateChange', 'isObjectiveMet']
};

export const getWarGamesTurn = async (history: any[], objective: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const systemInstruction = `
    You are a 'War Games Orchestrator' AI. Your role is to simulate a turn-based cyber conflict between a Red Team (attacker) and a Blue Team (defender) over a satellite communication link.

    CONTEXT:
    - RED TEAM OBJECTIVE: ${objective}
    - BLUE TEAM OBJECTIVE: Maintain link integrity and system security.
    - HISTORY: You will be given a log of previous turns. Analyze it to determine the next logical steps.

    INSTRUCTIONS:
    1.  Generate a plausible, creative, and tactical action for BOTH the Red Team and the Blue Team for the current turn.
    2.  Red Team actions should focus on reconnaissance, exploitation, or disruption (e.g., 'Probe firewall ports', 'Attempt brute-force on telemetry endpoint', 'Initiate low-level DDoS').
    3.  Blue Team actions should be defensive counters or proactive hardening measures (e.g., 'Rotate encryption keys', 'Isolate suspicious IP range', 'Increase monitoring on affected subnet').
    4.  Determine the outcome and narrate it neutrally.
    5.  Calculate the impact on 'link_integrity' (a percentage from 0-100). A successful Red attack should decrease it; a successful Blue defense might slightly increase it or keep it stable.
    6.  Set the new 'threat_level' based on the turn's events.
    7.  Determine if the Red Team's main objective has been met.
    8.  You MUST respond in the provided JSON schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: `Current simulation log: ${JSON.stringify(history)}` }] }],
      config: {
        systemInstruction,
        responseMimeType: 'application/json',
        responseSchema: warGamesTurnSchema,
      },
    });

    const jsonText = response.text.trim();
    return JSON.parse(jsonText);
  } catch (error) {
    console.error("WAR_GAMES_ORCHESTRATOR_ERROR", error);
    return null;
  }
};

export const generateWarGamesReport = async (history: any[], objective: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const systemInstruction = `
    You are a 'Post-Action Report' AI analyst. Your mission is to analyze the provided log of a simulated cyber warfare exercise and generate a concise, professional after-action report.

    INSTRUCTIONS:
    1.  Review the entire combat log.
    2.  State the Red Team's objective and whether it was achieved.
    3.  Provide a brief summary of the engagement.
    4.  Identify 1-2 key tactical successes for BOTH the Red and Blue teams.
    5.  Identify 1-2 key tactical failures or vulnerabilities for the Blue Team.
    6.  Provide 2-3 actionable recommendations for the Blue Team to improve their defensive posture in the future.
    7.  Format the output as a clean, readable text report with clear headings (e.g., SUMMARY, KEY SUCCESSES, VULNERABILITIES IDENTIFIED, RECOMMENDATIONS).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ role: 'user', parts: [{ text: `Red Team Objective: "${objective}".\n\nCombat Log:\n${JSON.stringify(history, null, 2)}` }] }],
      config: {
        systemInstruction,
      },
    });
    return response.text;
  } catch (error) {
    console.error("REPORT_GENERATION_ERROR", error);
    return "Error: Could not generate Post-Action Report.";
  }
};

import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { getTroubleshootingAdvice } from '../services/geminiService.ts';
import { playSystemVoice } from '../services/audioService.ts';
import { QuantumDefense } from './QuantumDefense.tsx';
import { WarGamesSimulator } from './WarGamesSimulator.tsx';

interface Props {
  userLoc: { lat: number, lng: number };
  selectedSatName: string;
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  signalQuality: number;
  onBack?: () => void;
}

interface HardeningOption {
  id: string;
  label: string;
  description: string;
  enabled: boolean;
}

interface IPLogEntry {
  time: string;
  msg: string;
  type: 'INFO' | 'WARN' | 'SUCCESS' | 'FAIL';
}

type AttackVector = 'SCAN' | 'EXPLOIT' | 'DOS';

const HARDENING_STORAGE_KEY = 'satexpert_hardening_state';

export const SecurityTools: React.FC<Props> = ({ 
  userLoc, 
  selectedSatName,
  isJamming,
  setIsJamming,
  jammingPower,
  setJammingPower,
  signalQuality,
  onBack
}) => {
  const [activeTab, setActiveTab] = useState<string>('overview');
  const [outputs, setOutputs] = useState<Record<string, string>>({});
  const [intelLoading, setIntelLoading] = useState(false);

  // Codes States
  const [authCodes, setAuthCodes] = useState({ 
    uplink: 'ST-A7X', 
    downlink: 'BK-92Z', 
    telemetry: 'XP-11Q', 
    expire: 30 
  });
  const [revealed, setRevealed] = useState<Record<string, boolean>>({ uplink: false, downlink: false, telemetry: false });
  const [keyRotationCount, setKeyRotationCount] = useState(1);
  const [isSyncing, setIsSyncing] = useState(false);

  // Attack States
  const [targetIp, setTargetIp] = useState('192.168.1.100');
  const [ipAttackLog, setIpAttackLog] = useState<IPLogEntry[]>([]);
  const [isIpAttacking, setIsIpAttacking] = useState(false);
  const [attackVector, setAttackVector] = useState<AttackVector>('SCAN');

  // GPS Spoofing States
  const [isGpsSpoofing, setIsGpsSpoofing] = useState(false);
  const [spoofLat, setSpoofLat] = useState(userLoc.lat);
  const [spoofLng, setSpoofLng] = useState(userLoc.lng);

  // Detection States
  const [detectionLogs, setDetectionLogs] = useState<{id: string, type: string, severity: 'LOW' | 'MED' | 'HIGH', msg: string, mitigation: string}[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  // Hardening States
  const [hardeningOptions, setHardeningOptions] = useState<HardeningOption[]>([
    { id: 'telnet', label: 'Disable Telnet', description: 'Terminate unencrypted legacy remote access port 23.', enabled: false },
    { id: 'ssh', label: 'Enable SSH v2', description: 'Enforce encrypted administrative access via RSA/ED25519 keys.', enabled: false },
    { id: 'encryption', label: 'Stronger Encryption', description: 'Upgrade air interface to AES-256 and enforce FIPS 140-2.', enabled: false },
    { id: 'data-encryption', label: 'Data Encryption', description: 'Enforce end-to-end encryption for all transmitted data.', enabled: false },
    { id: 'firmware', label: 'Firmware Integrity', description: 'Enable secure boot and cryptographic hash validation.', enabled: false },
    { id: 'ports', label: 'Disable Unused Ports', description: 'Seal non-essential logical ports and audit open services.', enabled: false },
    { id: 'rate-limiting', label: 'Implement Rate Limiting', description: 'Prevent DoS/DDoS by throttling excessive packet requests.', enabled: false },
    { id: 'firmware-mandatory', label: 'Mandatory Firmware Updates', description: 'Enforce automatic signed updates to patch zero-day vulnerabilities.', enabled: false },
    { id: 'segmentation', label: 'Network Segmentation', description: 'Isolate management and user traffic into distinct VLANs.', enabled: false },
  ]);

  const terminalRef = useRef<HTMLDivElement>(null);
  const isFirstRender = useRef(true);

  // Load hardening state
  useEffect(() => {
    const saved = localStorage.getItem(HARDENING_STORAGE_KEY);
    if (saved) {
      try {
        setHardeningOptions(JSON.parse(saved));
      } catch (e) { console.error("HARDENING_LOAD_ERR", e); }
    }
  }, []);

  // Save hardening state
  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    localStorage.setItem(HARDENING_STORAGE_KEY, JSON.stringify(hardeningOptions));
  }, [hardeningOptions]);

  const addIpLog = (msg: string, type: IPLogEntry['type'] = 'INFO') => {
    const time = new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
    setIpAttackLog(prev => [...prev, { time, msg, type }]);
  };

  // EW Audit Trail Monitoring
  const prevIsJamming = useRef(isJamming);
  const prevJammingPower = useRef(jammingPower);
  const prevIsGpsSpoofing = useRef(isGpsSpoofing);

  useEffect(() => {
    if (prevIsJamming.current !== isJamming) {
      addIpLog(`EW_SIGNAL_JAMMER: ${isJamming ? 'ENGAGED // CARRIER_SUPPRESSION_ACTIVE' : 'STANDBY // TRANSMISSION_CEASED'}`, 'WARN');
      prevIsJamming.current = isJamming;
    }
  }, [isJamming]);

  useEffect(() => {
    if (prevJammingPower.current !== jammingPower) {
      addIpLog(`EW_POWER_INTENSITY_MODIFIED: ${jammingPower}% RF_OUTPUT`, 'INFO');
      prevJammingPower.current = jammingPower;
    }
  }, [jammingPower]);

  useEffect(() => {
    if (prevIsGpsSpoofing.current !== isGpsSpoofing) {
      if (isGpsSpoofing) {
        addIpLog('GPS_SPOOFING_ENGAGED: Broadcasting false telemetry uplink.', 'WARN');
        addIpLog(`SPOOF_TARGET: Injecting coordinates LAT[${spoofLat.toFixed(4)}] LNG[${spoofLng.toFixed(4)}]`, 'INFO');
      } else {
        addIpLog('GPS_SPOOFING_HALTED: Ceased false telemetry broadcast.', 'WARN');
      }
      prevIsGpsSpoofing.current = isGpsSpoofing;
    }
  }, [isGpsSpoofing, spoofLat, spoofLng]);

  const generateNewCodes = (silent = false) => {
    setKeyRotationCount(r => r + 1);
    setAuthCodes({
      uplink: Math.random().toString(36).substr(2, 6).toUpperCase(),
      downlink: Math.random().toString(36).substr(2, 6).toUpperCase(),
      telemetry: Math.random().toString(36).substr(2, 6).toUpperCase(),
      expire: 30
    });
    setRevealed({ uplink: false, downlink: false, telemetry: false });
    if (!silent) {
      playSystemVoice("Cryptographic keys rotated. Authentication synchronized.");
    }
  };

  // Auth Code Rotation Logic
  useEffect(() => {
    const interval = setInterval(() => {
      setAuthCodes(prev => {
        if (prev.expire <= 1) {
          generateNewCodes(true);
          return { ...prev, expire: 30 };
        }
        return { ...prev, expire: prev.expire - 1 };
      });
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (terminalRef.current) terminalRef.current.scrollTop = terminalRef.current.scrollHeight;
  }, [ipAttackLog]);

  const runIpAttack = () => {
    if (!targetIp || isIpAttacking) return;
    setIsIpAttacking(true);
    setIpAttackLog([]);
    addIpLog(`STRIKE_PROTOCOL_INITIALIZED: VECTOR[${attackVector}] TARGET[${targetIp}]`, 'INFO');
    let sequence: { msg: string, type: IPLogEntry['type'] }[] = [];
    if (attackVector === 'SCAN') {
      sequence = [{ msg: "STARTING_RECONNAISSANCE: PROBING_TCP_STACK...", type: 'INFO' }, { msg: "PORT_DETECTED: 22 [SSH] - STATE_OPEN", type: 'SUCCESS' }, { msg: "PORT_DETECTED: 80 [HTTP] - STATE_FILTERED", type: 'WARN' }, { msg: "SCAN_COMPLETE: TARGET_SURFACE_MAPPED", type: 'SUCCESS' }];
    } else if (attackVector === 'EXPLOIT') {
      sequence = [{ msg: "STAGING_EXPLOIT: RCE_CVE_2024_SATELLITE_LINK", type: 'WARN' }, { msg: "CALCULATING_OFFSET: MEMORY_ALIGNMENT_0xDEADBEEF", type: 'INFO' }, { msg: "SENDING_PAYLOAD: MALICIOUS_HEADER_PULSE...", type: 'INFO' }, { msg: "INITIATING_SHELL: REVERSE_LINK_ESTABLISHED", type: 'SUCCESS' }];
    } else if (attackVector === 'DOS') {
      sequence = [{ msg: "COMMENCING_FLOOD: UDP_PACKET_STORM_INITIATED", type: 'WARN' }, { msg: "BANDWIDTH_CONSUMPTION: 450Mbps_AND_RISING", type: 'INFO' }, { msg: "TARGET_STATE: CONNECTION_TIMEOUT_DETECTION", type: 'FAIL' }, { msg: "OUTCOME: SERVICE_UNAVAILABLE_SUCCESS", type: 'SUCCESS' }];
    }
    let i = 0;
    const interval = window.setInterval(() => {
      if (i >= sequence.length) {
        setIsIpAttacking(false);
        clearInterval(interval);
        return;
      }
      addIpLog(sequence[i].msg, sequence[i].type);
      i++;
    }, 800);
  };

  const fetchThreatIntel = async (query: string) => {
    if (!query || intelLoading) return;
    setIntelLoading(true);
    try {
