export const getWarGamesTurn = async (history: any[], objective: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const systemInstruction = `
    You are a 'War Games Orchestrator' AI. Your role is to simulate a turn-based cyber conflict between a Red Team (attacker) and a Blue Team (defender) over a satellite communication link.

    CONTEXT:
    - RED TEAM OBJECTIVE: ${objective}
    - BLUE TEAM OBJECTIVE: Maintain link integrity and system security.
    - HISTORY: You will be given a log of previous turns. Analyze it to determine the next logical steps.

    INSTRUCTIONS:
    1.  Generate a plausible, creative, and tactical action for BOTH the Red Team and the Blue Team for the current turn.
    2.  Red Team actions should focus on reconnaissance, exploitation, or disruption (e.g., 'Probe firewall ports', 'Attempt brute-force on telemetry endpoint', 'Initiate low-level DDoS').
    3.  Blue Team actions should be defensive counters or proactive hardening measures (e.g., 'Rotate encryption keys', 'Isolate suspicious IP range', 'Increase monitoring on affected subnet').
    4.  Determine the outcome and narrate it neutrally.
    5.  Calculate the impact on 'link_integrity' (a percentage from 0-100). A successful Red attack should decrease it; a successful Blue defense might slightly increase it or keep it stable.
    6.  Set the new 'threat_level' based on the turn's events.
    7.  Determine if the Red Team's main objective has been met.
    8.  You MUST respond in the provided JSON schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: `Current simulation log: ${JSON.stringify(history)}` }] }],
      config: {
