          </div>
          <div className="flex space-x-1">
             <div className="px-2 py-0.5 rounded border border-cyan-500/20 bg-cyan-500/5 text-[7px] text-cyan-500 font-black uppercase tracking-widest">SNIPPET_ENGINE_V3</div>
          </div>
