import * as React from 'react';
import { useEffect, useRef } from 'react';

interface Props {
  quality: number; 
  isJamming?: boolean;
  jammingPower?: number;
  rainFade?: number;
  isStealthMode: boolean; // New prop
}

export const SignalVisualizer: React.FC<Props> = ({ quality, isJamming = false, jammingPower = 0, rainFade = 0, isStealthMode }) => {
  const spectrumRef = useRef<HTMLCanvasElement>(null);
  const constellationRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const specCtx = spectrumRef.current?.getContext('2d');
    const constCtx = constellationRef.current?.getContext('2d');
    if (!specCtx || !constCtx) return;

    let frame = 0;
    const animate = () => {
      frame++;

      // Clear
      specCtx.clearRect(0, 0, 400, 150);

      specCtx.save();
      if (isJamming && jammingPower > 80 && Math.random() > 0.9 && !isStealthMode) { // Stealth mode negates visual distortion
        specCtx.translate((Math.random() - 0.5) * 4, (Math.random() - 0.5) * 4);
      }

      // Base Noise Floor
      specCtx.strokeStyle = 'rgba(51, 65, 85, 0.4)';
      specCtx.lineWidth = 1;
      specCtx.beginPath();
      for (let i = 0; i < 400; i++) {
        // Rain fade increases base noise floor jitter, negated by stealth mode
        const rainJitter = isStealthMode ? 0 : (rainFade / 4);
        const y = 135 + (Math.random() * (isStealthMode ? 1 : (4 + rainJitter))); // Smaller noise in stealth mode
        if (i === 0) specCtx.moveTo(i, y); else specCtx.lineTo(i, y);
      }
      specCtx.stroke();

      // Jamming Noise Floor
      if (isJamming && !isStealthMode) { // Jamming visuals negated by stealth mode
        specCtx.strokeStyle = `rgba(239, 68, 68, ${0.4 + (jammingPower / 200)})`;
        specCtx.lineWidth = 1;
        specCtx.beginPath();
        for (let i = 0; i < 400; i++) {
          const jammingLevel = (jammingPower / 100) * 80;
          const y = 135 - (Math.random() * jammingLevel);
          if (i === 0) specCtx.moveTo(i, y); else specCtx.lineTo(i, y);
        }
        specCtx.stroke();
      }

      // Main Signal
      specCtx.strokeStyle = isStealthMode ? '#a855f7' : (isJamming ? '#ef4444' : (rainFade > 5 ? '#fbbf24' : '#22d3ee')); // Stealth mode has unique color
      specCtx.lineWidth = isStealthMode ? 3 : 2; // Thicker signal in stealth mode
      specCtx.beginPath();
      for (let i = 0; i < 400; i++) {
        const distToCenter = Math.abs(200 - i);
        // Effective quality calculation including Rain Fade and Jamming, negated by stealth mode
        const effectiveQuality = isStealthMode ? 100 : Math.max(0, (isJamming ? quality - (jammingPower * 1.5) : quality) - (rainFade * 4));

        let signal = distToCenter < 60 ? Math.pow(60 - distToCenter, 1.4) * (effectiveQuality / 100) : 0;

        if (isJamming && distToCenter < 20 && !isStealthMode) { // Jamming visual artifacts negated by stealth mode
           signal += (Math.random() - 0.5) * (jammingPower / 10);
        }

        const y = 135 - (signal + (isStealthMode ? Math.random() * 0.5 : Math.random() * 2)); // Less random noise in stealth mode
        if (i === 0) specCtx.moveTo(i, y); else specCtx.lineTo(i, y);
      }
      specCtx.stroke();

      // Anomaly Visuals
      if (((quality > 0 && (quality < 90 || rainFade > 5) && frame % 200 < 50) || isJamming) && !isStealthMode) { // Anomalies negated by stealth mode
        specCtx.strokeStyle = isJamming ? '#ef4444' : '#fbbf24';
        specCtx.lineWidth = 1;
        specCtx.beginPath();
        const anomalyX = isJamming ? 200 + (Math.sin(frame/5) * (jammingPower * 2)) : 280;
        specCtx.moveTo(anomalyX, 150); specCtx.lineTo(anomalyX, 20);
        specCtx.stroke();

        specCtx.fillStyle = isJamming ? '#ef4444' : '#fbbf24';
        specCtx.font = 'bold 8px JetBrains Mono';
        const label = isJamming ? `JAM_LVL_${jammingPower}%` : rainFade > 5 ? "RAIN_ATTENUATION" : "ANOMALY";
        specCtx.fillText(label, anomalyX + 5, 30 + (isJamming ? Math.random()*2 : 0));
      } else if (isStealthMode && frame % 300 < 10) { // Subtle stealth operational pulse
        specCtx.fillStyle = 'rgba(168, 85, 247, 0.2)';
        specCtx.fillRect(0, 0, 400, 150);
      }

      specCtx.restore();

      // Constellation
      constCtx.clearRect(0, 0, 200, 200);
      constCtx.fillStyle = isStealthMode ? '#a855f7' : (isJamming || (quality - (rainFade * 3)) < 30 ? '#ef4444' : (rainFade > 5 ? '#fbbf24' : '#22d3ee'));
      const spread = isStealthMode ? 1 : (isJamming ? (jammingPower / 2) : Math.max(1, (100 - (quality - (rainFade * 3))) / 4));
      for(let i=0; i< (isStealthMode ? 8 : 40); i++) { // Fewer points, tighter cluster in stealth
        const quadrants = [[50, 50], [150, 50], [50, 150], [150, 150]];
        quadrants.forEach(([qx, qy]) => {
          constCtx.fillRect(qx + (Math.random()-0.5)*spread, qy + (Math.random()-0.5)*spread, 1.5, 1.5);
        });
      }

      requestAnimationFrame(animate);
    };

    const handle = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(handle);
  }, [quality, isJamming, jammingPower, rainFade, isStealthMode]); // Add isStealthMode to dependencies

  return (
    <div className={`glass p-4 rounded-2xl border-slate-800 transition-all ${isJamming && !isStealthMode ? 'border-red-500/30 bg-red-950/5 tactical-glow' : ''} ${isStealthMode ? 'border-purple-500/30 bg-purple-950/5' : ''}`}>
      <div className="flex items-center justify-between mb-2">
        <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">Spectrum Engine</p>
        <div className="flex space-x-2">
           {isStealthMode && <span className="text-[8px] font-bold text-purple-400 animate-pulse">STEALTH_PROTO_ACTIVE</span>}
           {rainFade > 1 && !isStealthMode && <span className="text-[8px] font-bold text-amber-500">RAIN_FADE: {rainFade}dB</span>}
           {isJamming && !isStealthMode && <span className="text-[8px] font-bold text-red-500 animate-pulse">EW_OVERRIDE_ACTIVE</span>}
        </div>
      </div>
      <canvas ref={spectrumRef} width="400" height="150" className={`w-full h-32 bg-slate-950 rounded-xl mb-4 border border-slate-900 shadow-inner ${isJamming && jammingPower > 90 && !isStealthMode ? 'animate-pulse' : ''} ${isStealthMode ? 'border-purple-900 shadow-purple-500/10' : ''}`} />
      <div className="grid grid-cols-2 gap-4">
         <div className="relative">
            <canvas ref={constellationRef} width="200" height="200" className="w-full h-24 bg-slate-950 rounded-xl border border-slate-900" />
            <div className="absolute inset-0 flex items-center justify-center opacity-10 pointer-events-none">
              <div className="w-full h-px bg-slate-500"></div>
              <div className="h-full w-px bg-slate-500 absolute"></div>
            </div>
         </div>
         <div className={`bg-slate-900 p-2 rounded-xl flex flex-col items-center justify-center border ${isStealthMode ? 'border-purple-900/50' : (isJamming ? 'border-red-900/50' : 'border-slate-800')}`}>
            <span className="text-[8px] font-bold text-slate-500 uppercase mb-1">Effective Margin</span>
            <span className={`text-xl font-bold mono ${isStealthMode ? 'text-purple-400' : (isJamming || rainFade > 8 ? 'text-red-500' : (rainFade > 3 ? 'text-amber-500' : 'text-cyan-400'))}`}>
              {isStealthMode ? '20.0' : Math.max(0, (quality/10) - (isJamming ? jammingPower/10 : 0) - (rainFade/2)).toFixed(1)} dB
            </span>
            <span className="text-[7px] text-slate-600 mono mt-1">LOCK_{isStealthMode ? 'STEALTH_ACTIVE' : (isJamming || rainFade > 8 ? 'CRITICAL' : (quality > 50 ? 'STABLE' : 'WEAK'))}</span>
         </div>
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useEffect } from 'react';
import { LinkBudgetParams, LinkBudgetResults } from '../types.ts';
import { calculateLinkBudget } from '../utils/geoUtils.ts';

interface Props {
  distance: number;
  externalRainFade?: number;
  isStealthMode: boolean; // New prop
}

export const LinkBudgetCalculator: React.FC<Props> = ({ distance, externalRainFade, isStealthMode }) => {
  const [params, setParams] = useState<LinkBudgetParams>({
    uplinkFreq: 14.25, downlinkFreq: 11.75, txPower: 5, antSize: 1.2, efficiency: 65, lnbNoiseTemp: 75, rainFade: externalRainFade || 2.5
  });
  const [results, setResults] = useState<LinkBudgetResults | null>(null);

  useEffect(() => {
    const activeRainFade = isStealthMode ? 0.0 : (externalRainFade !== undefined ? externalRainFade : params.rainFade);
    setResults(calculateLinkBudget({...params, rainFade: activeRainFade}, distance));
  }, [params, distance, externalRainFade, isStealthMode]); // Add isStealthMode to dependencies

  return (
    <div className="glass rounded-2xl border-slate-700 overflow-hidden flex flex-col md:flex-row">
      <div className="p-6 bg-slate-800 md:w-64 border-r border-slate-700 space-y-3">
        <h3 className="text-white font-bold text-xs uppercase tracking-widest mb-4">RF Config</h3>
        <div>
          <label className="block text-[9px] font-bold text-slate-500 uppercase">TX Power (dBW)</label>
          <input type="number" value={params.txPower} onChange={e => setParams({...params, txPower: parseFloat(e.target.value)})} className="w-full bg-slate-900 border border-slate-700 rounded p-1.5 text-xs text-cyan-400" />
        </div>
        <div>
          <label className="block text-[9px] font-bold text-slate-500 uppercase">Dish Size (m)</label>
          <input type="number" value={params.antSize} onChange={e => setParams({...params, antSize: parseFloat(e.target.value)})} className="w-full bg-slate-900 border border-slate-700 rounded p-1.5 text-xs text-cyan-400" />
        </div>
        {externalRainFade === undefined && (
          <div>
            <label className="block text-[9px] font-bold text-slate-500 uppercase">Rain Fade (dB)</label>
            <input 
              type="number" 
              value={isStealthMode ? 0.0 : params.rainFade} 
              onChange={e => setParams({...params, rainFade: parseFloat(e.target.value)})} 
              disabled={isStealthMode} // Disable input when stealth mode is active
              className={`w-full bg-slate-900 border border-slate-700 rounded p-1.5 text-xs text-cyan-400 ${isStealthMode ? 'opacity-50' : ''}`} 
            />
             {isStealthMode && <span className="block text-[7px] text-purple-400 mt-1">STEALTH_OVERRIDE: 0.0dB</span>}
          </div>
        )}
      </div>
      <div className="flex-grow p-6 flex flex-col space-y-6">
        <div className="flex items-center justify-between">
           <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Link Performance Metrics</span>
           {isStealthMode && (
             <span className="text-[8px] font-bold text-purple-500 bg-purple-500/10 px-2 py-0.5 rounded border border-purple-500/20">STEALTH_PROTO_ACTIVE</span>
           )}
           {externalRainFade !== undefined && !isStealthMode && (
             <span className="text-[8px] font-bold text-cyan-500 bg-cyan-500/10 px-2 py-0.5 rounded border border-cyan-500/20">LIVE_ATMOSPHERIC_SYNC</span>
           )}
        </div>
        <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">
          <div className="bg-slate-950/40 p-4 rounded-xl border border-slate-800">
             <p className="text-[9px] font-bold text-slate-500 uppercase">Eb/No (Margin)</p>
             <p className={`text-2xl font-bold mono ${results && results.ebNo < 5 && !isStealthMode ? 'text-red-500' : 'text-cyan-400'} ${isStealthMode ? 'text-purple-400' : ''}`}>
               {results?.ebNo.toFixed(2)} dB
             </p>
          </div>
          <div className="bg-slate-950/40 p-4 rounded-xl border border-slate-800">
             <p className="text-[9px] font-bold text-slate-500 uppercase">BER Estimate</p>
             <p className="text-2xl font-bold mono text-white">{results?.ber}</p>
          </div>
          <div className="bg-slate-950/40 p-4 rounded-xl border border-slate-800">
             <p className="text-[9px] font-bold text-slate-500 uppercase">FSPL Loss</p>
             <p className="text-2xl font-bold mono text-slate-400">{results?.fspl.toFixed(1)} dB</p>
          </div>
        </div>
        <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-800/50">
           <div className="flex items-center justify-between mb-2">
              <span className="text-[8px] font-bold text-slate-500 uppercase">Dynamic Link Summary</span>
              <span className="text-[7px] text-slate-700 mono">Ka-BAND_PROF_V4</span>
           </div>
           <p className="text-[11px] text-slate-400 leading-relaxed italic">
             Based on a distance of {distance.toLocaleString()}km, the carrier EIRP is estimated at {(params.txPower + (results?.antGain || 0)).toFixed(1)} dBW. 
             {isStealthMode ? " STEALTH_PROTOCOL_ACTIVE: All link parameters nominal and masked for external detection." : (results && results.ebNo < 6 ? " CAUTION: Link is approaching rain fade threshold. Modulation fallback recommended." : " Link stability is optimal for current environmental profile.")}
           </p>
        </div>
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Coordinates, Satellite, SatelliteStatus, WeatherCondition } from '../types.ts';
import { fetchSatelliteStatusUpdates } from '../services/satelliteService.ts';

interface Props {
  loc: Coordinates;
  sat: Satellite;
  satellites: Satellite[];
  onLocChange: (loc: Coordinates) => void;
  onSatChange: (sat: Satellite) => void;
  onSatellitesUpdate: (sats: Satellite[]) => void;
  isTracking?: boolean;
  onTrackingChange?: (val: boolean) => void;
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  weather: WeatherCondition;
  setWeather: (val: WeatherCondition) => void;
  isStealthMode: boolean; // New prop
}

interface TacticalEvent {
  id: string;
  timestamp: string;
  satName: string;
  satId: string;
  status: SatelliteStatus;
  detail: string;
}

const EVENT_LOG_STORAGE_KEY = 'satexpert_event_logs';

const StatusBadge: React.FC<{ status?: SatelliteStatus }> = ({ status }) => {
  const config = {
    active: { color: 'bg-green-500', label: 'ONLINE', pulse: true },
    offline: { color: 'bg-red-500', label: 'OFFLINE', pulse: false },
    maintenance: { color: 'bg-amber-500', label: 'MAINT', pulse: true },
    decommissioned: { color: 'bg-slate-600', label: 'EOL', pulse: false },
  }[status || 'active'];

  return (
    <div className="flex items-center space-x-1.5">
      <div className={`w-1.5 h-1.5 rounded-full ${config.color} ${config.pulse ? 'animate-pulse' : ''}`}></div>
      <span className={`text-[8px] font-bold tracking-tighter ${config.color.replace('bg-', 'text-')}`}>
        {config.label}
      </span>
    </div>
  );
};

export const TacticalHUD: React.FC<Props> = ({ 
  loc, sat, satellites, onLocChange, onSatChange, onSatellitesUpdate, isTracking, onTrackingChange,
  isJamming, setIsJamming, jammingPower, setJammingPower,
  weather, setWeather, isStealthMode
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [showEventLog, setShowEventLog] = useState(false);
  const [animateLabel, setAnimateLabel] = useState(false);
  const [eventLogs, setEventLogs] = useState<TacticalEvent[]>([]);
  const [hasNewLogs, setHasNewLogs] = useState(false);
  const [isAcknowledging, setIsAcknowledging] = useState(false);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const prevSatRef = useRef<{id: string, status?: SatelliteStatus} | null>(null);

  const filteredSatellites = useMemo(() => {
    return satellites.filter(s => 
      s.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      s.orbitalSlot.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [searchQuery, satellites]);

  // Load event logs
  useEffect(() => {
    const saved = localStorage.getItem(EVENT_LOG_STORAGE_KEY);
    if (saved) {
      try {
        setEventLogs(JSON.parse(saved));
      } catch (e) {
        console.error("EVENT_LOG_LOAD_ERROR", e);
      }
    }
  }, []);

  // Save event logs
  useEffect(() => {
    localStorage.setItem(EVENT_LOG_STORAGE_KEY, JSON.stringify(eventLogs));
  }, [eventLogs]);

  // Poll for satellite status updates
  useEffect(() => {
    const pollInterval = setInterval(async () => {
      const updatedSatellites = await fetchSatelliteStatusUpdates();
      onSatellitesUpdate(updatedSatellites);
    }, 15000); // Poll every 15 seconds

    return () => clearInterval(pollInterval);
  }, [onSatellitesUpdate]);

  // Track Satellite Status Changes & Acquisitions
  useEffect(() => {
    setAnimateLabel(true);
    const timer = setTimeout(() => setAnimateLabel(false), 600);

    if (prevSatRef.current === null) {
      prevSatRef.current = { id: sat.id, status: sat.status };
      return;
    }

    const isSameSat = prevSatRef.current?.id === sat.id;
    const isStatusChanged = prevSatRef.current?.status !== sat.status;

    if (!isSameSat || (isSameSat && isStatusChanged)) {
      const newEvent: TacticalEvent = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: new Date().toLocaleString(),
        satName: sat.name,
        satId: sat.id,
        status: sat.status || 'active',
        detail: !isSameSat 
          ? `ASSET_ACQUISITION: Targeted ${sat.name} (${sat.orbitalSlot})`
          : `STATUS_CHANGE: Asset ${sat.name} transitioned to ${sat.status?.toUpperCase()}`
      };
      setEventLogs(prev => [newEvent, ...prev].slice(0, 50)); // Keep last 50
      if (!showEventLog) {
        setHasNewLogs(true);
      }
    }

    prevSatRef.current = { id: sat.id, status: sat.status };
    return () => clearTimeout(timer);
  }, [sat.id, sat.status, showEventLog]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (s: Satellite) => {
    onSatChange(s);
    setSearchQuery('');
    setIsOpen(false);
  };

  const clearLogs = () => {
    setEventLogs([]);
    setHasNewLogs(false);
    setShowEventLog(false);
  };

  const handleAcknowledge = () => {
    if (isAcknowledging) return;
    setIsAcknowledging(true);
    setTimeout(() => {
      setShowEventLog(false);
      setIsAcknowledging(false);
    }, 1000);
  };

  const handleExportBrief = () => {
    const timestamp = new Date().toISOString();
    const content = `
[TACTICAL ASSET BRIEFING]
-------------------------
TIMESTAMP: ${timestamp}
ASSET_ID: ${sat.id}
ASSET_NAME: ${sat.name}
OPERATOR: ${sat.operator || 'UNKNOWN'}
ORBITAL_SLOT: ${sat.orbitalSlot}
LONGITUDE: ${sat.longitude}°
STATUS: ${sat.status || 'UNKNOWN'}

[ORBITAL_TELEMETRY]
APOGEE: ${sat.apogee ? sat.apogee.toLocaleString() : 'N/A'} KM
PERIGEE: ${sat.perigee ? sat.perigee.toLocaleString() : 'N/A'} KM
INCLINATION: ${sat.inclination ? sat.inclination.toFixed(4) : 'N/A'}°
VELOCITY: ${sat.velocity ? sat.velocity.toFixed(4) : 'N/A'} KM/S

[DEPLOYMENT_CONTEXT]
USER_LAT: ${loc.lat.toFixed(6)}
USER_LNG: ${loc.lng.toFixed(6)}
WEATHER_SIM: ${weather}

[SECURITY_POSTURE]
EW_INTERFERENCE: ${isJamming ? 'ACTIVE' : 'STANDBY'}
JAM_POWER: ${jammingPower}%
STEALTH_PROTOCOL: ${isStealthMode ? 'ACTIVE' : 'INACTIVE'}
-------------------------
EOF // ENCRYPTED_BRIEF
`;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `SAT_BRIEF_${sat.id}_${Date.now()}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleExportJsonData = () => {
    const timestamp = new Date().toISOString();
    const assetLogs = eventLogs
      .filter(log => log.satId === sat.id)
      .map(({ id, ...rest }) => ({
        ...rest,
        stealth_mode_at_log: isStealthMode, // Add stealth mode status to log export
      }));

    const dataToExport = {
      export_generated_utc: timestamp,
      asset_id: sat.id,
      asset_name: sat.name,
      current_status: sat.status || 'UNKNOWN',
      stealth_mode_active: isStealthMode, // Add current stealth mode status
      asset_details: {
        operator: sat.operator || 'UNKNOWN',
        orbital_slot: sat.orbitalSlot,
        longitude_deg: sat.longitude,
        orbital_parameters: {
          apogee_km: sat.apogee,
          perigee_km: sat.perigee,
          inclination_deg: sat.inclination,
          velocity_kms: sat.velocity,
        },
      },
      telemetry_log: assetLogs,
    };

    const jsonString = JSON.stringify(dataToExport, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    const filename = `SATELLITE_DATA_${sat.id}_${timestamp.replace(/[:.]/g, '-')}.json`;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const weatherIcons = {
    CLEAR: '☀️',
    OVERCAST: '☁️',
    LIGHT_RAIN: '🌧️',
    HEAVY_STORM: '⛈️'
  };

  const openLogModal = () => {
    setShowEventLog(true);
    setHasNewLogs(false);
  };

  return (
    <div className="glass rounded-2xl p-6 border-slate-800 relative z-50">
      <div className="space-y-4">
        <div className="relative" ref={dropdownRef}>
          <div className="flex items-center justify-between mb-1">
            <label className={`block text-[9px] font-bold uppercase tracking-widest transition-all duration-300 transform ${
              animateLabel 
                ? 'text-cyan-400 scale-105 drop-shadow-[0_0_8px_rgba(34,211,238,0.6)]' 
                : 'text-slate-500'
            }`}>
              Target Acquisition
            </label>
            <div className="flex items-center space-x-2">
              {isStealthMode && (
                <div className="flex items-center space-x-2 bg-purple-500/10 border border-purple-500/30 px-3 py-1 rounded-lg shadow-lg shadow-purple-500/10 animate-pulse-light">
                  <div className="w-1.5 h-1.5 bg-purple-500 rounded-full"></div>
                  <span className="text-[9px] font-bold text-purple-400 uppercase tracking-tighter">STEALTH ACTIVE</span>
                </div>
              )}
              <button 
                onClick={openLogModal}
                className="relative flex items-center space-x-2 px-3 py-1 rounded-lg border border-cyan-500/30 bg-slate-900 text-[9px] font-bold text-cyan-400 hover:bg-cyan-500/10 transition-all uppercase tracking-tighter shadow-md shadow-cyan-500/5"
              >
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                </svg>
                <span>Event Log</span>
                {hasNewLogs && <div className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-slate-800 animate-pulse"></div>}
              </button>
              <button 
                onClick={handleExportJsonData}
                className="flex items-center space-x-1 px-2 py-0.5 rounded border border-slate-800 bg-slate-900 text-[8px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/30 transition-all uppercase tracking-tighter"
                title="Export Raw Satellite Data (JSON)"
              >
                <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4" />
                </svg>
                <span>Data</span>
              </button>
              <button 
                onClick={handleExportBrief}
                className="flex items-center space-x-1 px-2 py-0.5 rounded border border-slate-800 bg-slate-900 text-[8px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/30 transition-all uppercase tracking-tighter"
                title="Export Asset Brief"
              >
                <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
                <span>Export</span>
              </button>
            </div>
          </div>

          <div className="relative">
            <input
              type="text"
              placeholder={isOpen ? "ENTER SATELLITE NAME OR SLOT..." : sat.name}
              className={`w-full bg-slate-950 border ${isOpen ? 'border-cyan-500 shadow-[0_0_10px_rgba(34,211,238,0.2)]' : 'border-slate-800'} rounded-lg p-2.5 pl-9 text-xs text-white outline-none transition-all mono placeholder:text-slate-600`}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setIsOpen(true);
              }}
              onFocus={() => setIsOpen(true)}
            />
            <div className="absolute left-3 top-1/2 -translate-y-1/2">
              <svg className={`w-4 h-4 ${isOpen ? 'text-cyan-400' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center">
               {!isOpen && <StatusBadge status={sat.status} />}
            </div>
          </div>

          {isOpen && (
            <div className="absolute mt-2 w-full glass bg-slate-950/95 border border-cyan-500/30 rounded-xl shadow-2xl overflow-hidden max-h-[300px] flex flex-col z-[100]">
              <div className="bg-cyan-500/5 px-4 py-2 border-b border-slate-800/50">
                <span className="text-[8px] font-bold text-cyan-400 uppercase tracking-widest">Results Found: {filteredSatellites.length}</span>
              </div>
              <div className="overflow-y-auto scrollbar-hide py-1">
                {filteredSatellites.length > 0 ? (
                  filteredSatellites.map((s) => (
                    <button
                      key={s.id}
                      onClick={() => handleSelect(s)}
                      className={`w-full text-left px-4 py-3 hover:bg-cyan-500/10 transition-colors flex items-center justify-between group border-b border-slate-900/50 last:border-none ${s.id === sat.id ? 'bg-cyan-500/5' : ''}`}
                    >
                      <div className="flex flex-col">
                        <div className="flex items-center space-x-2">
                           <span className={`text-[11px] font-bold tracking-wide ${s.id === sat.id ? 'text-cyan-400' : 'text-slate-300 group-hover:text-cyan-200'}`}>{s.name}</span>
                           <StatusBadge status={s.status} />
                        </div>
                        <span className="text-[9px] text-slate-500 mono group-hover:text-slate-400">{s.operator || 'UNSPECIFIED'}</span>
                      </div>
                      <div className="flex flex-col items-end">
                        <span className="text-[10px] text-cyan-500 font-mono font-bold tracking-tighter">{s.orbitalSlot}</span>
                      </div>
                    </button>
                  ))
                ) : (
                  <div className="px-4 py-8 text-center">
                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">No matching assets found</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Asset Identity Block */}
        <div className="bg-slate-950/50 rounded-xl border border-slate-800/50 p-3 flex items-center justify-between animate-in fade-in slide-in-from-top-1 duration-300">
          <div className="flex flex-col">
