import * as React from 'react';
import { useState, useRef, useEffect } from 'react';
import { analyzeInterceptedSignal, generateDecryptedMessage } from '../services/geminiService.ts';

type ScanState = 'IDLE' | 'SCANNING' | 'INTERCEPTED' | 'ANALYZING' | 'ANALYZED' | 'DECRYPTING' | 'DECRYPTED';
const MODULATION_TYPES = ['QPSK', '8PSK', '16-QAM', 'BPSK', 'FHSS', 'OFDM'];

const getRandomFloat = (min: number, max: number, decimals: number) => {
  const str = (Math.random() * (max - min) + min).toFixed(decimals);
  return parseFloat(str);
};

export const SignalInterceptor: React.FC<{ isJamming: boolean; jammingPower: number; isStealthMode: boolean; }> = ({ isJamming, jammingPower, isStealthMode }) => {
    const [scanState, setScanState] = useState<ScanState>('IDLE');
    const [signalParams, setSignalParams] = useState<any>(null);
    const [analysis, setAnalysis] = useState<any>(null);
    const [decryptedMessage, setDecryptedMessage] = useState('');
    const [displayedMessage, setDisplayedMessage] = useState('');
    const visualizerRef = useRef<HTMLCanvasElement>(null);

    const resetState = () => {
        setScanState('IDLE');
        setSignalParams(null);
        setAnalysis(null);
        setDecryptedMessage('');
        setDisplayedMessage('');
    };

    const handleScan = () => {
        resetState();
        setScanState('SCANNING');
        setTimeout(() => {
            if (isStealthMode) { // If stealth mode is active, report no signals
                setSignalParams(null);
                setScanState('INTERCEPTED'); // Still change state to indicate scan completed
                setAnalysis({ probableOrigin: "NO_SIGNALS", suspectedPurpose: "NO_DETECTION", threatLevel: "NOMINAL", encryptionType: "N/A", suggestedKeyFragment: "N/A"});
            } else {
                setSignalParams({
                    frequency: getRandomFloat(10.5, 14.8, 3), // GHz
                    bandwidth: getRandomFloat(2, 72, 0), // MHz
                    modulation: MODULATION_TYPES[Math.floor(Math.random() * MODULATION_TYPES.length)],
                    snr: getRandomFloat(5, 25, 1),
                });
                setScanState('INTERCEPTED');
            }
        }, 4000); // 4 seconds scan simulation
    };

    const handleAnalyze = async () => {
        if (!signalParams && !isStealthMode) return;
        setScanState('ANALYZING');
        const analysisResult = await analyzeInterceptedSignal(signalParams);
        if (analysisResult) {
            setAnalysis(analysisResult);
            setScanState('ANALYZED');
        } else {
            // Handle error case
            setAnalysis({ error: "STIA analysis uplink failed." });
            setScanState('ANALYZED');
        }
    };

    const handleDecrypt = async () => {
        if(!analysis || analysis.error || isStealthMode) return; // Cannot decrypt if stealth mode is active (no signals)
        setScanState('DECRYPTING');
        const message = await generateDecryptedMessage(analysis);
        setDecryptedMessage(message || "// DECRYPTION FAILED //");
        setScanState('DECRYPTED');
    };

    useEffect(() => {
        let interval: number;
        if(scanState === 'DECRYPTED' && decryptedMessage) {
            let i = 0;
            const randomChars = 'AZERTYUIOPQSDFGHJKLMWXCVBN0123456789#@&?!$';
            interval = window.setInterval(() => {
                if (i >= decryptedMessage.length) {
                    clearInterval(interval);
                    return;
                }
                let newText = '';
                for(let j=0; j < decryptedMessage.length; j++) {
                    if (j <= i) {
                        newText += decryptedMessage[j];
                    } else {
                        newText += randomChars[Math.floor(Math.random() * randomChars.length)];
                    }
                }
                setDisplayedMessage(newText);
                i++;
            }, 50);
        }
        return () => clearInterval(interval);
    }, [scanState, decryptedMessage]);

    useEffect(() => {
        const canvas = visualizerRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let animationFrameId: number;
        let t = 0;

        const render = () => {
            t++;
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = '#0f172a';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            if (scanState === 'SCANNING' || scanState === 'IDLE' || isStealthMode) { // Show clean scan in stealth mode
                if (!isStealthMode) {
                    const scanX = (t * 4) % canvas.width;
                    ctx.fillStyle = 'rgba(34, 211, 238, 0.2)';
                    ctx.fillRect(scanX, 0, 3, canvas.height);
                }

                for (let i = 0; i < 50; i++) {
                    const x = Math.random() * canvas.width;
                    const y = canvas.height * 0.8 + Math.random() * (canvas.height * 0.2);
                    const width = Math.random() * 2;
                    ctx.fillStyle = isStealthMode ? `rgba(168, 85, 247, ${Math.random() * 0.1})` : `rgba(51, 65, 85, ${Math.random() * 0.5})`; // Subtle stealth noise
                    ctx.fillRect(x, y, width, 1);
                }
            }

            if (['INTERCEPTED', 'ANALYZING', 'ANALYZED', 'DECRYPTING', 'DECRYPTED'].includes(scanState) && !isStealthMode) { // Only show signal if not in stealth mode
                ctx.strokeStyle = '#22d3ee';
                ctx.lineWidth = 1.5;
                ctx.beginPath();
                const vcenter = canvas.height / 2;
                const amplitude = canvas.height * 0.3;
                const noise = isJamming ? (jammingPower / 10) : 1;

                for (let x = 0; x < canvas.width; x++) {
                    const angle = (x / 50) + (t / 20);
                    const y = vcenter + Math.sin(angle) * Math.cos(angle * 0.5) * amplitude + (Math.random() - 0.5) * noise;
                    if(x === 0) ctx.moveTo(x,y);
                    else ctx.lineTo(x,y);
                }
                ctx.stroke();
            } else if (isStealthMode && (scanState === 'INTERCEPTED' || scanState === 'ANALYZED')) { // Visual for "no signal" in stealth
                 ctx.font = 'bold 16px JetBrains Mono';
                 ctx.fillStyle = '#a855f7';
                 ctx.textAlign = 'center';
                 ctx.fillText('NO_ANOMALY_DETECTED', canvas.width / 2, canvas.height / 2);
            }

            animationFrameId = requestAnimationFrame(render);
        };
        render();

        return () => {
            cancelAnimationFrame(animationFrameId);
        };
    }, [scanState, isJamming, jammingPower, isStealthMode]);

    const getThreatColor = (level?: string) => {
        if (!level) return 'text-slate-500';
        switch(level.toUpperCase()) {
            case 'NOMINAL': return 'text-cyan-400';
            case 'GUARDED': return 'text-amber-400';
            case 'ELEVATED': return 'text-orange-500';
            case 'SEVERE': return 'text-red-500';
            default: return 'text-slate-500';
        }
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in duration-500">
            {/* Left Panel */}
            <div className="lg:col-span-3 space-y-6">
                <div className="glass p-6 rounded-2xl border-slate-800">
                    <h3 className="text-sm font-bold uppercase tracking-widest text-white mb-4">SIGINT Controls</h3>
                    <button onClick={handleScan} disabled={scanState !== 'IDLE'} className="w-full bg-cyan-600 hover:bg-cyan-500 disabled:opacity-30 text-slate-950 font-bold py-3 rounded-xl uppercase tracking-widest text-xs">
                       {scanState === 'SCANNING' ? 'SCANNING...' : 'SCAN FOR ANOMALOUS SIGNALS'}
                    </button>
                    {scanState !== 'IDLE' && scanState !== 'SCANNING' && (
                         <button onClick={resetState} className="w-full mt-3 bg-red-900/40 hover:bg-red-900/60 border border-red-500/30 text-red-400 font-bold py-2 rounded-xl uppercase tracking-widest text-xs">
                             Reset Scanner
                         </button>
                    )}
                </div>
                 {signalParams && !isStealthMode && ( /* Hide parameters if stealth mode is active */
                    <div className="glass p-6 rounded-2xl border-slate-800 animate-in fade-in">
                        <h3 className="text-sm font-bold uppercase tracking-widest text-white mb-4">Intercept Parameters</h3>
                        <div className="space-y-3 text-xs mono">
                            <div className="flex justify-between border-b border-slate-800 pb-2"><span className="text-slate-500">FREQ:</span> <span className="text-cyan-400">{signalParams.frequency} GHz</span></div>
                            <div className="flex justify-between border-b border-slate-800 pb-2"><span className="text-slate-500">BW:</span> <span className="text-cyan-400">{signalParams.bandwidth} MHz</span></div>
                            <div className="flex justify-between border-b border-slate-800 pb-2"><span className="text-slate-500">MOD:</span> <span className="text-cyan-400">{signalParams.modulation}</span></div>
                            <div className="flex justify-between"><span className="text-slate-500">SNR:</span> <span className="text-cyan-400">{signalParams.snr} dB</span></div>
                        </div>
                    </div>
                 )}
                 {isStealthMode && (
                    <div className="glass p-6 rounded-2xl border-purple-500/50 animate-in fade-in">
                        <h3 className="text-sm font-bold uppercase tracking-widest text-purple-400 mb-4">Stealth Protocol Status</h3>
                        <p className="text-xs mono text-slate-400">All external signal emissions suppressed. No anomalous activity detected.</p>
                    </div>
                 )}
            </div>

            {/* Center Panel */}
            <div className="lg:col-span-6 flex flex-col space-y-6">
                <div className="glass p-4 rounded-2xl border-slate-800 flex-grow flex flex-col">
                   <h3 className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-3 px-2">Live Spectrum Analysis</h3>
                   <div className="bg-slate-950 rounded-lg border border-slate-900 shadow-inner flex-grow">
                       <canvas ref={visualizerRef} className="w-full h-full min-h-[200px]" width="600" height="200"></canvas>
                   </div>
                </div>
                <div className="glass p-6 rounded-2xl border-slate-800">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-4">STIA Analysis & Decryption</h3>
                    <div className="grid grid-cols-2 gap-4">
                        <button onClick={handleAnalyze} disabled={(!signalParams && !isStealthMode) || scanState !== 'INTERCEPTED'} className="w-full bg-slate-800 hover:bg-slate-700 disabled:opacity-30 border border-slate-700 text-slate-200 font-bold py-3 rounded-xl uppercase tracking-widest text-xs">
                           {scanState === 'ANALYZING' ? 'ANALYZING...' : 'ANALYZE WITH STIA'}
                        </button>
                        <button onClick={handleDecrypt} disabled={!analysis || analysis.error || scanState !== 'ANALYZED' || isStealthMode} className="w-full bg-slate-800 hover:bg-slate-700 disabled:opacity-30 border border-slate-700 text-slate-200 font-bold py-3 rounded-xl uppercase tracking-widest text-xs">
                           {isStealthMode ? 'PROTOCOL ACTIVE' : (scanState === 'DECRYPTING' ? 'DECRYPTING...' : 'DECRYPT SIGNAL')}
                        </button>
                    </div>
                </div>
            </div>

            {/* Right Panel */}
            <div className="lg:col-span-3 glass p-4 rounded-2xl border-slate-800 flex flex-col">
                <h3 className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-3 px-2">Intelligence Log</h3>
                <div className="flex-grow overflow-y-auto scrollbar-hide bg-slate-950/50 rounded-lg p-4 space-y-4">
                    {!analysis && <p className="text-xs text-slate-600 mono animate-pulse">Awaiting analysis...</p>}
                    {analysis && analysis.error && <p className="text-xs text-red-500 mono">{analysis.error}</p>}
                    {analysis && !analysis.error && !isStealthMode && ( /* Hide analysis if stealth mode is active and no signal was found */
                        <div className="text-xs mono space-y-3 animate-in fade-in">
                            <div><span className="text-slate-500 font-bold">ORIGIN:</span> <span className="text-slate-200">{analysis.probableOrigin}</span></div>
                            <div><span className="text-slate-500 font-bold">PURPOSE:</span> <span className="text-slate-200">{analysis.suspectedPurpose}</span></div>
                            <div><span className="text-slate-500 font-bold">ENCRYPTION:</span> <span className="text-slate-200">{analysis.encryptionType}</span></div>
                            <div><span className="text-slate-500 font-bold">THREAT LVL:</span> <span className={`font-bold ${getThreatColor(analysis.threatLevel)}`}>{analysis.threatLevel}</span></div>
                            <div><span className="text-slate-500 font-bold">KEY FRAGMENT:</span> <span className="text-amber-400">{analysis.suggestedKeyFragment}</span></div>
                        </div>
                    )}
                     {isStealthMode && (
                        <div className="text-xs mono space-y-3 animate-in fade-in">
                            <p className="text-purple-400">STEALTH_PROTOCOL_ACTIVE: No incoming transmissions detected. Operational security maintained.</p>
                        </div>
                    )}

                    {(scanState === 'DECRYPTING' || scanState === 'DECRYPTED') && !isStealthMode && ( /* Hide decryption if stealth mode is active */
                        <div className="pt-4 border-t border-slate-800">
                             <h4 className="text-[10px] font-bold uppercase tracking-widest text-cyan-400 mb-2">Decrypted Transmission:</h4>
                             <p className="text-sm text-cyan-200 mono bg-cyan-500/5 p-3 rounded-md min-h-[80px]">
                                {displayedMessage}
                                {scanState === 'DECRYPTING' && <span className="animate-pulse">_</span>}
                             </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import * as React from 'react';
import { useState, useEffect, useRef, useMemo } from 'react';
import { Layout } from './components/Layout.tsx';
import { LookAngleCard } from './components/LookAngleCard.tsx';
import { AITechnician } from './components/AITechnician.tsx';
import { SecurityTools } from './components/SecurityTools.tsx';
import { LinkBudgetCalculator } from './components/LinkBudgetCalculator.tsx';
import { SignalVisualizer } from './components/SignalVisualizer.tsx';
import { TacticalHUD } from './components/TacticalHUD.tsx';
import { TacticalMap } from './components/TacticalMap.tsx';
import { RSSReader } from './components/RSSReader.tsx';
import { TelemetryPulse } from './components/TelemetryPulse.tsx';
import { SignalInterceptor } from './components/SignalInterceptor.tsx';
import { Coordinates, Satellite, LookAngles, WeatherCondition } from './types.ts';
import { COMMON_SATELLITES } from './constants.ts';
import { calculateLookAngles } from './utils/geoUtils.ts';
import { playSystemVoice } from './services/audioService.ts';

type MainView = 'tactical' | 'intelligence' | 'interception' | 'calculations' | 'news';

const STORAGE_KEY = 'satexpert_tactical_v5';
const STEALTH_STORAGE_KEY = 'satexpert_stealth_mode';

export const App: React.FC = () => {
  const [satellites, setSatellites] = useState<Satellite[]>(COMMON_SATELLITES);
  const [userLoc, setUserLoc] = useState<Coordinates>({ lat: 51.5074, lng: -0.1278 });
  const [selectedSat, setSelectedSat] = useState<Satellite>(satellites[0]);
  const [lookAngles, setLookAngles] = useState<LookAngles | null>(null);
  const [view, setView] = useState<MainView>('tactical');
  const [defcon, setDefcon] = useState<number>(5);
  const [isTracking, setIsTracking] = useState<boolean>(false);
  const [weather, setWeather] = useState<WeatherCondition>('CLEAR');
  const [isJamming, setIsJamming] = useState<boolean>(false);
  const [jammingPower, setJammingPower] = useState<number>(50);
  const [isStealthMode, setIsStealthMode] = useState<boolean>(false);

  const isFirstMount = useRef(true);

  // Source of Truth Telemetry logic
  const telemetry = useMemo(() => {
    let snr = 16.0;
    let rxPower = -42.0;
    let packetLoss = 0.00;
    let bucTemp = 45.0;

    if (weather === 'OVERCAST') { snr -= 2.0; rxPower -= 1.5; }
    else if (weather === 'LIGHT_RAIN') { snr -= 5.0; rxPower -= 3.5; packetLoss += 0.8; }
    else if (weather === 'HEAVY_STORM') { snr -= 14.0; rxPower -= 12.0; packetLoss += 12.5; }

    if (isJamming) {
      snr -= (jammingPower / 5); 
      packetLoss += (jammingPower / 2);
      rxPower += (jammingPower / 10);
      bucTemp += (jammingPower / 15);
    }

    if (defcon <= 2) bucTemp += 8.0;

    if (isStealthMode) {
      snr = 20.0;
      rxPower = -30.0;
      packetLoss = 0.00;
      bucTemp = 35.0;
    }

    return {
      snr: Math.max(0, snr + (Math.random() - 0.5)).toFixed(2),
      rxPower: (rxPower + (Math.random() - 0.5)).toFixed(1),
      bucTemp: (bucTemp + (Math.random() - 0.5)).toFixed(1),
      packetLoss: Math.min(100, packetLoss + (Math.random() * 0.2)).toFixed(2),
      status: snr > 10 ? "NOMINAL" : (snr > 4 ? "DEGRADED" : "CRITICAL")
    };
  }, [weather, isJamming, jammingPower, defcon, isStealthMode]);

  const currentRainFade = useMemo(() => {
    if (isStealthMode) return 0.0;
    switch(weather) {
      case 'CLEAR': return 0.5;
      case 'OVERCAST': return 1.8;
      case 'LIGHT_RAIN': return 4.5;
      case 'HEAVY_STORM': return 12.0;
      default: return 0.5;
    }
  }, [weather, isStealthMode]);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.loc) setUserLoc(parsed.loc);
      if (parsed.satId) {
        const sat = satellites.find(s => s.id === parsed.satId);
        if (sat) setSelectedSat(sat);
      }
      setDefcon(parsed.defcon || 5);
    }
    const savedStealth = localStorage.getItem(STEALTH_STORAGE_KEY);
    if (savedStealth !== null) {
      setIsStealthMode(JSON.parse(savedStealth));
    }
    isFirstMount.current = false;
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      loc: userLoc,
      satId: selectedSat.id,
      defcon
    }));
  }, [userLoc, selectedSat, defcon]);

  useEffect(() => {
    if (!isFirstMount.current) {
      localStorage.setItem(STEALTH_STORAGE_KEY, JSON.stringify(isStealthMode));
    }
  }, [isStealthMode]);

  useEffect(() => {
    const angles = calculateLookAngles(userLoc, selectedSat.longitude);
    setLookAngles(angles);
  }, [userLoc, selectedSat]);

  useEffect(() => {
    const updatedSelectedSat = satellites.find(s => s.id === selectedSat.id);
    if (updatedSelectedSat && JSON.stringify(updatedSelectedSat) !== JSON.stringify(selectedSat)) {
      setSelectedSat(updatedSelectedSat);
    }
  }, [satellites, selectedSat.id]);

  const isDistorted = isStealthMode ? false : (isJamming || defcon === 1);

  useEffect(() => {
    if (isStealthMode) {
      document.body.classList.add('stealth-active');
    } else {
      document.body.classList.remove('stealth-active');
    }
  }, [isStealthMode]);

  const handleSatellitesUpdate = (updatedSatellites: Satellite[]) => {
    setSatellites(updatedSatellites);
  };

  return (
    <div className={`crt-screen min-h-screen ${isDistorted ? 'crt-distorted' : ''}`}>
      <Layout isStealthMode={isStealthMode}>
        <div className="flex flex-col space-y-6 max-w-7xl mx-auto pb-12 transition-all duration-1000">

          {/* Header Controls Area */}
          <div className={`flex flex-col lg:flex-row items-stretch justify-between gap-4 glass p-4 rounded-2xl border-slate-800 shadow-2xl relative overflow-hidden ${defcon === 1 || isJamming ? 'defcon-alert' : ''}`}>
             <div className="flex flex-col md:flex-row items-center gap-6 z-20">
              <div className="flex flex-col min-w-[280px]">
                <span className="text-[10px] font-bold text-cyan-500 uppercase tracking-[0.2em] mb-2 px-1">Mission Control System</span>
                <div className="flex flex-wrap gap-1 bg-slate-950/80 p-1 rounded-xl border border-slate-800/50">
                  {(['tactical', 'intelligence', 'interception', 'calculations', 'news'] as MainView[]).map((v) => (
                    <button
                      key={v}
                      onClick={() => setView(v)}
                      className={`px-3 py-2 rounded-lg text-[10px] font-bold uppercase tracking-widest transition-all duration-200 ${
                        view === v 
                          ? 'bg-cyan-500 text-slate-950 shadow-[0_0_15px_rgba(34,211,238,0.3)] scale-105' 
                          : 'text-slate-400 hover:text-cyan-400 hover:bg-white/5'
                      }`}
                    >
                      {v}
                    </button>
                  ))}
                </div>
              </div>

              <div className="h-12 w-px bg-slate-800 hidden md:block"></div>

              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-2 px-1">Alert Protocol</span>
                <div className="flex space-x-1.5 bg-slate-950/40 p-1 rounded-xl border border-slate-800/30">
                  {[5, 4, 3, 2, 1].map(lvl => (
                    <button 
                      key={lvl}
                      onClick={() => setDefcon(lvl)}
                      className={`w-9 h-9 rounded-lg flex items-center justify-center text-xs font-bold transition-all border ${
                        defcon === lvl 
                          ? (lvl <= 2 ? 'bg-red-500 text-white border-red-400 shadow-[0_0_12px_rgba(239,68,68,0.4)]' : 'bg-cyan-500/20 text-cyan-400 border-cyan-500/40') 
                          : 'bg-slate-900 border-slate-800 text-slate-600 hover:border-slate-600'
                      }`}
                    >
                      {lvl}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex items-center justify-center lg:justify-end flex-grow z-20 mt-4 lg:mt-0">
               <TelemetryPulse telemetry={telemetry} isStealthMode={isStealthMode} />
            </div>
          </div>

          <div className="min-h-[70vh]">
            {view === 'tactical' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="lg:col-span-5 xl:col-span-4 space-y-6">
                  <TacticalHUD 
                    loc={userLoc} 
                    sat={selectedSat}
                    satellites={satellites}
                    onLocChange={setUserLoc} 
                    onSatChange={setSelectedSat}
                    onSatellitesUpdate={handleSatellitesUpdate}
                    isTracking={isTracking}
                    onTrackingChange={setIsTracking}
                    isJamming={isJamming}
                    setIsJamming={setIsJamming}
                    jammingPower={jammingPower}
                    setJammingPower={setJammingPower}
                    weather={weather}
                    setWeather={setWeather}
                    isStealthMode={isStealthMode}
                  />
                  <TacticalMap userLoc={userLoc} satellite={selectedSat} isTracking={isTracking} onLocChange={setUserLoc} />
                  {lookAngles && <LookAngleCard angles={lookAngles} satellite={selectedSat} />}
                  <SignalVisualizer 
                    quality={lookAngles?.elevation && lookAngles.elevation > 0 ? 85 : 0} 
                    isJamming={isJamming}
                    jammingPower={jammingPower}
                    rainFade={currentRainFade}
                    isStealthMode={isStealthMode}
                  />
                </div>
                <div className="lg:col-span-7 xl:col-span-8">
                  <AITechnician 
                    context={{ 
                      lat: userLoc.lat, 
                      lng: userLoc.lng, 
                      satName: selectedSat.name,
                      defcon,
                      weather,
                      isJamming
                    }}
                    telemetry={telemetry}
                    isStealthMode={isStealthMode}
                  />
                </div>
              </div>
            )}

            {view === 'intelligence' && (
              <SecurityTools 
                userLoc={userLoc} 
                selectedSatName={selectedSat.name}
                isJamming={isJamming}
                setIsJamming={setIsJamming}
                jammingPower={jammingPower}
                setJammingPower={setJammingPower}
                signalQuality={88}
                onBack={() => setView('tactical')}
                isStealthMode={isStealthMode}
                setIsStealthMode={setIsStealthMode}
              />
            )}

            {view === 'interception' && (
              <SignalInterceptor 
                isJamming={isJamming} 
                jammingPower={jammingPower} 
                isStealthMode={isStealthMode}
              />
            )}

            {view === 'calculations' && lookAngles && (
              <div className="max-w-4xl mx-auto">
                <LinkBudgetCalculator 
                  distance={lookAngles.distance} 
                  externalRainFade={currentRainFade} 
                  isStealthMode={isStealthMode}
                />
              </div>
            )}

            {view === 'news' && (
              <div className="max-w-4xl mx-auto">
                <RSSReader />
              </div>
            )}
          </div>
        </div>
      </Layout>
    </div>
  );
};

export default App;

import * as React from 'react';
import { useState, useRef, useEffect } from 'react';
import { getTroubleshootingAdvice } from '../services/geminiService.ts';
import { TroubleshootingLog } from '../types.ts';

interface Props {
  context: any;
  telemetry: any;
  isStealthMode: boolean;
}

const SNIPPET_COMMANDS = [
  { id: 'fspl', label: 'FSPL Calc (Python)', prompt: 'Generate a Python script to calculate Free Space Path Loss (FSPL) given distance and frequency.' },
  { id: 'snr', label: 'SNR Monitor (Python)', prompt: 'Create a Python script that uses sockets to monitor SNR levels from a standard SatCom modem IP.' },
  { id: 'diag', label: 'Diagnostics (Live)', prompt: 'Initiate a full terminal diagnostic check. Read the live sensors to check SNR, packet loss, and hardware temperatures.' },
  { id: 'mitigate', label: 'Interference Mitigation', prompt: 'Based on current sensor data, provide a step-by-step mitigation plan for the detected signal degradation.' }
];

export const AITechnician: React.FC<Props> = ({ context, telemetry, isStealthMode }) => {
  const [messages, setMessages] = useState<TroubleshootingLog[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const initialGreeting = { 
      role: 'assistant', 
      content: `[SYSTEM_READY] STIA-Agent Active.\n${isStealthMode ? 'PROTOCOL: STEALTH_MODE_ACTIVE\n' : ''}MONITORING: Field Site Alpha\nDEFCON: ${context.defcon || 5}\nCOORDINATES: ${context.lat?.toFixed(3)}, ${context.lng?.toFixed(3)}\nWEATHER: ${context.weather || 'CLEAR'}\nEW_STATUS: ${context.isJamming ? 'ENGAGED' : 'STANDBY'}\nState your technical query or select a [TACTICAL_SNIPPET] below.`, 
      timestamp: new Date() 
    };
    setMessages([initialGreeting]);
  }, [isStealthMode, context.defcon, context.lat, context.lng, context.weather, context.isJamming]);


  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = async (customPrompt?: string) => {
    const textToSend = customPrompt || input;
    if (!textToSend.trim() || isLoading) return;

    const userMessage: TroubleshootingLog = { role: 'user', content: textToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    const advice = await getTroubleshootingAdvice(textToSend, { ...context, isStealthMode }, telemetry);
    const assistantMessage: TroubleshootingLog = { role: 'assistant', content: advice || 'COMM_FAILURE: Satellite link timed out.', timestamp: new Date() };

    setMessages(prev => [...prev, assistantMessage]);
    setIsLoading(false);
  };

  return (
    <div className="glass rounded-2xl border-slate-800 flex flex-col h-[760px] lg:h-full lg:min-h-[850px] overflow-hidden relative shadow-2xl bg-slate-950/40">
      <div className="p-4 border-b border-slate-800 bg-slate-900/60 flex flex-col z-20">
        <div className="flex justify-between items-center mb-4">
          <div className="flex items-center">
            <div className="w-10 h-10 bg-cyan-900/40 rounded-xl flex items-center justify-center border border-cyan-500/30 mr-3 status-pulse">
               <svg className="w-6 h-6 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
            </div>
            <div>
              <h3 className="text-[11px] font-bold tracking-[0.2em] text-white uppercase">STIA Intelligence Orchestrator</h3>
              <div className="flex items-center space-x-2 mt-0.5">
                 <span className="text-[8px] text-slate-500 font-bold uppercase tracking-widest">Core Status:</span>
                 <span className="text-[9px] text-green-500 font-black uppercase">Online</span>
              </div>
            </div>
          </div>
          <div className="flex items-center space-x-2">
             <div className="px-2 py-1 rounded border border-cyan-500/20 bg-cyan-500/5 text-[8px] text-cyan-500 font-black uppercase tracking-widest">STIA_PRO_V3</div>
          </div>
        </div>

        <div className="flex items-center space-x-2 overflow-x-auto pb-1 scrollbar-hide">
          <span className="text-[7px] text-slate-500 font-black uppercase tracking-widest shrink-0 border-r border-slate-800 pr-2">Tactical Snippets</span>
          {SNIPPET_COMMANDS.map(cmd => (
            <button
              key={cmd.id}
              onClick={() => handleSend(cmd.prompt)}
              disabled={isLoading}
              className="shrink-0 px-3 py-1.5 bg-slate-950 border border-slate-800/80 rounded-lg text-[9px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/40 transition-all uppercase tracking-tighter"
            >
              {cmd.label}
            </button>
          ))}
        </div>
      </div>

      <div ref={scrollRef} className="flex-grow overflow-y-auto p-6 space-y-6 scrollbar-hide bg-slate-950/20">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in duration-300`}>
            <div className={`max-w-[85%] p-5 rounded-2xl border ${
              m.role === 'user' 
                ? 'bg-cyan-950/20 text-cyan-50 rounded-br-none border-cyan-500/30 shadow-lg' 
                : 'bg-slate-900/80 text-slate-100 rounded-bl-none border-slate-700 shadow-xl'
            }`}>
              <div className="text-[14px] whitespace-pre-wrap leading-relaxed font-medium mono selection:bg-cyan-500/40">{m.content}</div>
              <div className="text-[9px] mt-4 opacity-30 font-mono tracking-widest uppercase flex items-center justify-between">
                <span>PKT_ID: {m.timestamp.getTime().toString(16).slice(-8)}</span>
                <span>{m.timestamp.toLocaleTimeString()}</span>
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-slate-900/50 p-4 rounded-2xl rounded-bl-none border border-slate-800 flex items-center space-x-3">
               <div className="flex space-x-1">
                 <span className="w-2 h-2 bg-cyan-500 rounded-full animate-bounce"></span>
                 <span className="w-2 h-2 bg-cyan-500 rounded-full animate-bounce delay-75"></span>
                 <span className="w-2 h-2 bg-cyan-500 rounded-full animate-bounce delay-150"></span>
               </div>
               <span className="text-[10px] text-cyan-500 font-bold tracking-widest uppercase">Consulting Satellite Data...</span>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-slate-900/40 border-t border-slate-800 z-20 backdrop-blur-md">
        <div className="flex space-x-3 bg-slate-950 p-2 rounded-xl border border-slate-800/80 shadow-inner group">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="ENTER TACTICAL COMMAND OR QUERY >"
            className="flex-grow bg-transparent border-none px-4 py-2.5 text-xs text-white focus:outline-none mono placeholder:text-slate-700"
          />
          <button
            onClick={() => handleSend()}
            disabled={isLoading}
            className="bg-cyan-600 hover:bg-cyan-500 disabled:opacity-30 text-slate-950 font-black rounded-lg px-6 py-2 transition-all shadow-[0_0_15px_rgba(34,211,238,0.2)] active:scale-95"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Coordinates, Satellite, SatelliteStatus, WeatherCondition } from '../types.ts';
import { fetchSatelliteStatusUpdates } from '../services/satelliteService.ts';

interface Props {
  loc: Coordinates;
  sat: Satellite;
  satellites: Satellite[];
  onLocChange: (loc: Coordinates) => void;
  onSatChange: (sat: Satellite) => void;
  onSatellitesUpdate: (sats: Satellite[]) => void;
  isTracking?: boolean;
  onTrackingChange?: (val: boolean) => void;
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  weather: WeatherCondition;
  setWeather: (val: WeatherCondition) => void;
  isStealthMode: boolean;
}

interface TacticalEvent {
  id: string;
  timestamp: string;
  satName: string;
  satId: string;
  status: SatelliteStatus;
  detail: string;
}

const EVENT_LOG_STORAGE_KEY = 'satexpert_event_logs';

const StatusBadge: React.FC<{ status?: SatelliteStatus }> = ({ status }) => {
  const config = {
    active: { color: 'bg-green-500', label: 'ONLINE', pulse: true },
    offline: { color: 'bg-red-500', label: 'OFFLINE', pulse: false },
    maintenance: { color: 'bg-amber-500', label: 'MAINT', pulse: true },
    decommissioned: { color: 'bg-slate-600', label: 'EOL', pulse: false },
  }[status || 'active'];

  return (
    <div className="flex items-center space-x-1.5">
      <div className={`w-2 h-2 rounded-full ${config.color} ${config.pulse ? 'status-pulse' : ''}`}></div>
      <span className={`text-[9px] font-bold tracking-widest ${config.color.replace('bg-', 'text-')}`}>
        {config.label}
      </span>
    </div>
  );
};

export const TacticalHUD: React.FC<Props> = ({ 
  loc, sat, satellites, onLocChange, onSatChange, onSatellitesUpdate, isTracking, onTrackingChange,
  isJamming, setIsJamming, jammingPower, setJammingPower,
  weather, setWeather, isStealthMode
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [showEventLog, setShowEventLog] = useState(false);
  const [animateLabel, setAnimateLabel] = useState(false);
  const [eventLogs, setEventLogs] = useState<TacticalEvent[]>([]);
  const [hasNewLogs, setHasNewLogs] = useState(false);
  const [isAcknowledging, setIsAcknowledging] = useState(false);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const prevSatRef = useRef<{id: string, status?: SatelliteStatus} | null>(null);

  const filteredSatellites = useMemo(() => {
    return satellites.filter(s => 
      s.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      s.orbitalSlot.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [searchQuery, satellites]);

  useEffect(() => {
    const saved = localStorage.getItem(EVENT_LOG_STORAGE_KEY);
    if (saved) {
      try {
        setEventLogs(JSON.parse(saved));
      } catch (e) { console.error("EVENT_LOG_LOAD_ERROR", e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(EVENT_LOG_STORAGE_KEY, JSON.stringify(eventLogs));
  }, [eventLogs]);

  useEffect(() => {
    const pollInterval = setInterval(async () => {
      const updatedSatellites = await fetchSatelliteStatusUpdates();
      onSatellitesUpdate(updatedSatellites);
    }, 15000);
    return () => clearInterval(pollInterval);
  }, [onSatellitesUpdate]);

  useEffect(() => {
    setAnimateLabel(true);
    const timer = setTimeout(() => setAnimateLabel(false), 600);

    if (prevSatRef.current === null) {
      prevSatRef.current = { id: sat.id, status: sat.status };
      return;
    }

    const isSameSat = prevSatRef.current?.id === sat.id;
    const isStatusChanged = prevSatRef.current?.status !== sat.status;

    if (!isSameSat || (isSameSat && isStatusChanged)) {
      const newEvent: TacticalEvent = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: new Date().toLocaleTimeString(),
        satName: sat.name,
        satId: sat.id,
        status: sat.status || 'active',
        detail: !isSameSat 
          ? `ASSET_ACQUISITION: Targeted ${sat.name} (${sat.orbitalSlot})`
          : `STATUS_CHANGE: Asset ${sat.name} transitioned to ${sat.status?.toUpperCase()}`
      };
      setEventLogs(prev => [newEvent, ...prev].slice(0, 50));
      if (!showEventLog) setHasNewLogs(true);
    }

    prevSatRef.current = { id: sat.id, status: sat.status };
    return () => clearTimeout(timer);
  }, [sat.id, sat.status, showEventLog]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (s: Satellite) => {
    onSatChange(s);
    setSearchQuery('');
    setIsOpen(false);
  };

  const clearLogs = () => {
    setEventLogs([]);
    setHasNewLogs(false);
    setShowEventLog(false);
  };

  const handleAcknowledge = () => {
    if (isAcknowledging) return;
    setIsAcknowledging(true);
    setTimeout(() => {
      setShowEventLog(false);
      setIsAcknowledging(false);
    }, 1000);
  };

  const weatherIcons = {
    CLEAR: '☀️',
    OVERCAST: '☁️',
    LIGHT_RAIN: '🌧️',
    HEAVY_STORM: '⛈️'
  };

  return (
    <div className="glass rounded-2xl p-6 border-slate-800 relative z-50 overflow-hidden">
      <div className="absolute top-0 left-0 w-1 h-full bg-cyan-500/20"></div>

      <div className="space-y-6">
        <div className="relative" ref={dropdownRef}>
          <div className="flex items-center justify-between mb-3 px-1">
            <div className="flex flex-col">
              <label className={`block text-[11px] font-bold uppercase tracking-[0.2em] transition-all duration-300 transform ${
                animateLabel 
                  ? 'text-cyan-400 scale-105' 
                  : 'text-white'
              }`}>
                Target Acquisition
              </label>
              <div className="card-header-line"></div>
            </div>
            <div className="flex items-center space-x-2">
              <button 
                onClick={() => setShowEventLog(true)}
                className="relative flex items-center space-x-1.5 px-3 py-1.5 rounded-lg border border-slate-800 bg-slate-900 text-[9px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/30 transition-all uppercase tracking-widest"
              >
                <span>Logs</span>
                {hasNewLogs && <div className="w-1.5 h-1.5 bg-red-500 rounded-full animate-pulse"></div>}
              </button>
            </div>
          </div>

          <div className="relative">
            <input
              type="text"
              placeholder={isOpen ? "ENTER SATELLITE NAME OR SLOT..." : sat.name}
              className={`w-full bg-slate-950/80 border ${isOpen ? 'border-cyan-500 shadow-[0_0_15px_rgba(34,211,238,0.2)]' : 'border-slate-800'} rounded-xl p-3 pl-10 text-xs text-white outline-none transition-all mono placeholder:text-slate-700`}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setIsOpen(true);
              }}
              onFocus={() => setIsOpen(true)}
            />
            <div className="absolute left-3.5 top-1/2 -translate-y-1/2">
              <svg className={`w-4.5 h-4.5 ${isOpen ? 'text-cyan-400' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
            <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center">
               {!isOpen && <StatusBadge status={sat.status} />}
            </div>
          </div>

          {isOpen && (
            <div className="absolute mt-2 w-full glass bg-slate-950 border border-cyan-500/40 rounded-xl shadow-2xl overflow-hidden max-h-[300px] flex flex-col z-[100]">
              <div className="bg-cyan-500/10 px-4 py-2 border-b border-slate-800">
                <span className="text-[9px] font-bold text-cyan-400 uppercase tracking-widest">Asset Registry</span>
              </div>
              <div className="overflow-y-auto py-1 scrollbar-hide">
                {filteredSatellites.map((s) => (
                  <button
                    key={s.id}
                    onClick={() => handleSelect(s)}
                    className={`w-full text-left px-4 py-3 hover:bg-white/5 transition-colors flex items-center justify-between border-b border-slate-900/50 last:border-none ${s.id === sat.id ? 'bg-cyan-500/5' : ''}`}
                  >
                    <div className="flex flex-col">
                      <span className={`text-[11px] font-bold ${s.id === sat.id ? 'text-cyan-400' : 'text-slate-200'}`}>{s.name}</span>
                      <span className="text-[9px] text-slate-500 mono">{s.operator}</span>
                    </div>
                    <span className="text-[10px] text-cyan-500 font-mono font-bold">{s.orbitalSlot}</span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Identity & Telemetry Strip */}
        <div className="grid grid-cols-2 gap-3">
          <div className="bg-slate-950/40 rounded-xl border border-slate-800 p-3 flex flex-col">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Authority</span>
            <span className="text-[10px] font-bold text-slate-200 mono truncate">{sat.operator || 'UNSPECIFIED'}</span>
          </div>
          <div className="bg-slate-950/40 rounded-xl border border-slate-800 p-3 flex flex-col items-end text-right">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Slot Index</span>
            <span className="text-[10px] font-bold text-cyan-400 mono">{sat.orbitalSlot}</span>
          </div>
        </div>

        {/* Weather Simulator Area */}
        <div className="bg-slate-950/40 rounded-xl border border-slate-800 p-4 space-y-4">
          <div className="flex items-center justify-between">
             <span className="text-[9px] font-black text-white uppercase tracking-widest">Atmospheric Environment</span>
             <span className="text-[8px] text-slate-500 font-bold uppercase mono">Ka-Band Simulation</span>
          </div>
          <div className="grid grid-cols-4 gap-2">
            {(['CLEAR', 'OVERCAST', 'LIGHT_RAIN', 'HEAVY_STORM'] as WeatherCondition[]).map((cond) => (
              <button 
                key={cond}
                onClick={() => setWeather(cond)}
                disabled={isStealthMode}
                className={`flex flex-col items-center justify-center p-2 rounded-xl border transition-all duration-200 ${
                  isStealthMode ? 'opacity-30' : ''
                } ${
                  weather === cond 
                    ? 'bg-cyan-500/20 border-cyan-500/60 text-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.1)]' 
                    : 'bg-slate-900 border-slate-800 text-slate-600 hover:border-slate-600'
                }`}
              >
                <span className="text-lg mb-1">{weatherIcons[cond]}</span>
                <span className="text-[7px] font-bold uppercase tracking-tighter text-center">{cond.replace('_', ' ')}</span>
              </button>
            ))}
          </div>
          <div className="grid grid-cols-2 gap-4 pt-2 border-t border-slate-800/50">
             <div className="flex flex-col">
               <span className="text-[8px] text-slate-500 font-bold uppercase">Estimated Loss</span>
               <span className={`text-xs font-bold mono ${weather === 'HEAVY_STORM' ? 'text-red-500' : 'text-cyan-400'}`}>
                 {isStealthMode ? '0.00' : (weather === 'CLEAR' ? '0.50' : weather === 'OVERCAST' ? '1.80' : weather === 'LIGHT_RAIN' ? '4.50' : '12.00')} dB
               </span>
             </div>
             <div className="flex flex-col items-end text-right">
               <span className="text-[8px] text-slate-500 font-bold uppercase">Humidity Index</span>
               <span className="text-xs font-bold text-slate-300 mono">{isStealthMode ? '0%' : (weather === 'CLEAR' ? '12%' : weather === 'OVERCAST' ? '45%' : '88%')}</span>
             </div>
          </div>
        </div>

        {/* EW Control Area */}
        <div className={`rounded-xl border p-4 space-y-4 transition-all duration-500 ${isStealthMode ? 'bg-purple-900/10 border-purple-500/30' : (isJamming ? 'bg-red-900/10 border-red-500/30 shadow-[0_0_20px_rgba(239,68,68,0.05)]' : 'bg-slate-950/40 border-slate-800')}`}>
          <div className="flex items-center justify-between">
            <div className="flex flex-col">
              <span className={`text-[10px] font-black uppercase tracking-widest ${isStealthMode ? 'text-purple-400' : (isJamming ? 'text-red-500' : 'text-white')}`}>Electronic Warfare</span>
              <span className="text-[8px] text-slate-500 font-bold uppercase mono">Mode: Continuous Wave</span>
            </div>
            <button 
              onClick={() => setIsJamming(!isJamming)}
              disabled={isStealthMode}
              className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all duration-300 ${
                isStealthMode ? 'bg-slate-800 text-slate-500' : (isJamming ? 'bg-red-600 text-white shadow-lg animate-pulse' : 'bg-slate-800 text-slate-400 hover:text-white')
              }`}
            >
              {isStealthMode ? 'Stealth' : (isJamming ? 'Engaged' : 'Standby')}
            </button>
          </div>

          <div className="space-y-3">
            <div className="flex items-center justify-between text-[9px] font-bold mono">
              <span className={isStealthMode ? 'text-purple-400' : 'text-slate-500'}>Intensity: {isStealthMode ? 0 : jammingPower}%</span>
              <span className={isStealthMode ? 'text-purple-400' : 'text-red-400'}>SNR Loss: {isStealthMode ? '0.0' : -(jammingPower / 5).toFixed(1)} dB</span>
            </div>
            <input 
              type="range" 
              min="0" max="100" 
              value={isStealthMode ? 0 : jammingPower} 
              onChange={(e) => setJammingPower(parseInt(e.target.value))}
              disabled={isStealthMode}
              className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer transition-all ${isStealthMode ? 'bg-purple-900 accent-purple-500' : (isJamming ? 'bg-red-900 accent-red-500' : 'bg-slate-800 accent-slate-600')}`}
            />
          </div>
        </div>

        {/* Manual Coordinates Grid */}
        <div className="grid grid-cols-2 gap-4">
           <div>
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-2 tracking-widest">Ground Station Lat</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  disabled={isTracking || isStealthMode}
                  className={`w-full bg-slate-950/60 p-3 text-xs rounded-xl border text-cyan-400 outline-none mono transition-all ${isTracking || isStealthMode ? 'border-slate-800 opacity-50' : 'border-slate-800 focus:border-cyan-500/40'}`} 
                  value={loc.lat} 
                  onChange={e => onLocChange({...loc, lat: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[9px] text-slate-700 font-bold mono">N/S</span>
              </div>
           </div>
           <div>
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-2 tracking-widest">Ground Station Lng</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  disabled={isTracking || isStealthMode}
                  className={`w-full bg-slate-950/60 p-3 text-xs rounded-xl border text-cyan-400 outline-none mono transition-all ${isTracking || isStealthMode ? 'border-slate-800 opacity-50' : 'border-slate-800 focus:border-cyan-500/40'}`} 
                  value={loc.lng} 
                  onChange={e => onLocChange({...loc, lng: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[9px] text-slate-700 font-bold mono">E/W</span>
              </div>
           </div>
        </div>
      </div>

      {/* Event Log Modal - Refined */}
      {showEventLog && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="glass w-full max-w-lg rounded-3xl border border-slate-700 shadow-2xl flex flex-col max-h-[75vh] overflow-hidden">
            <div className="p-6 border-b border-slate-800 flex items-center justify-between bg-slate-900/40">
               <div>
                  <h3 className="text-sm font-black text-white uppercase tracking-[0.2em] flex items-center">
                    <span className="w-2 h-2 bg-cyan-500 rounded-full mr-3 status-pulse"></span>
                    Asset Intelligence Logs
                  </h3>
                  <p className="text-[9px] text-slate-500 font-bold tracking-widest mt-1">Tactical Audit Log // Sector Alpha</p>
               </div>
               <button 
                onClick={() => setShowEventLog(false)}
                className="p-2 hover:bg-white/5 rounded-full transition-colors"
               >
                 <svg className="w-6 h-6 text-slate-500 hover:text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
               </button>
            </div>

            <div className="flex-grow overflow-y-auto p-4 space-y-3 bg-slate-950/20">
              {eventLogs.length > 0 ? (
                eventLogs.map((log) => (
                  <div key={log.id} className="p-4 bg-slate-900/40 rounded-xl border border-slate-800/60 flex items-start space-x-4 group hover:border-cyan-500/30 transition-all">
                    <div className="pt-1"><StatusBadge status={log.status} /></div>
                    <div className="flex-grow">
                       <div className="flex items-center justify-between mb-1.5">
                          <span className="text-[11px] font-black text-white mono">{log.satName}</span>
                          <span className="text-[8px] text-slate-600 font-bold mono">{log.timestamp}</span>
                       </div>
                       <p className="text-[12px] text-slate-400 leading-relaxed mono">{log.detail}</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center py-24 text-center">
                   <p className="text-[11px] font-bold text-slate-600 uppercase tracking-widest">No Tactical Logs On File</p>
                </div>
              )}
            </div>

            <div className="p-5 border-t border-slate-800 bg-slate-900/60 flex justify-end space-x-4">
