              </div>
            </div>
          </div>
          <div className="flex items-center space-x-2">
             <div className="px-2 py-1 rounded border border-cyan-500/20 bg-cyan-500/5 text-[8px] text-cyan-500 font-black uppercase tracking-widest">STIA_PRO_V4</div>
          </div>
        </div>

        <div className="flex items-center space-x-2 overflow-x-auto pb-1 scrollbar-hide">
          <span className="text-[7px] text-slate-500 font-black uppercase tracking-widest shrink-0 border-r border-slate-800 pr-2">Tactical Snippets</span>
          {SNIPPET_COMMANDS.map(cmd => (
            <button
              key={cmd.id}
              onClick={() => handleSend(cmd.prompt)}
              disabled={isLoading}
              className="shrink-0 px-3 py-1.5 bg-slate-950 border border-slate-800/80 rounded-lg text-[9px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/40 transition-all uppercase tracking-tighter"
            >
              {cmd.label}
            </button>
          ))}
        </div>
      </div>

      <div ref={scrollRef} className="flex-grow overflow-y-auto p-6 space-y-6 scrollbar-hide bg-slate-950/20">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in duration-300`}>
            <div className={`max-w-[90%] p-5 rounded-2xl border ${
              m.role === 'user' 
                ? 'bg-cyan-950/20 text-cyan-50 rounded-br-none border-cyan-500/30 shadow-lg' 
