              <div className="text-[9px] mt-4 opacity-30 font-mono tracking-widest uppercase flex items-center justify-between">
                <span>SEQ_ID: {i.toString().padStart(3, '0')}</span>
                <span>{m.timestamp.toLocaleTimeString()}</span>
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-slate-900/50 p-4 rounded-2xl rounded-bl-none border border-slate-800 flex items-center space-x-3">
               <div className="flex space-x-1">
                 <span className="w-2 h-2 bg-cyan-500 rounded-full animate-bounce"></span>
