  { id: 'fspl', label: 'FSPL Calc (Python)', prompt: 'Generate a professional Python script to calculate Free Space Path Loss (FSPL) given distance and frequency. Include comments.' },
  { id: 'snr', label: 'SNR Monitor (Python)', prompt: 'Create a robust Python script that uses sockets to monitor SNR levels from a standard SatCom modem IP. Handle exceptions.' },
