export const AITechnician: React.FC<Props> = ({ context, telemetry, isStealthMode }) => {
  const [messages, setMessages] = useState<TroubleshootingLog[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const initialGreeting = { 
      role: 'assistant', 
      content: `[SYSTEM_READY] STIA-Agent Active.\n${isStealthMode ? 'PROTOCOL: STEALTH_MODE_ACTIVE\n' : ''}MONITORING: Field Site Alpha\nDEFCON: ${context.defcon || 5}\nCOORDINATES: ${context.lat?.toFixed(3)}, ${context.lng?.toFixed(3)}\nWEATHER: ${context.weather || 'CLEAR'}\nEW_STATUS: ${context.isJamming ? 'ENGAGED' : 'STANDBY'}\nState your technical query or select a [TACTICAL_SNIPPET] below.`, 
      timestamp: new Date() 
    };
    setMessages([initialGreeting]);
  }, [isStealthMode, context.defcon, context.lat, context.lng, context.weather, context.isJamming]);


  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSend = async (customPrompt?: string) => {
    const textToSend = customPrompt || input;
    if (!textToSend.trim() || isLoading) return;

    const userMessage: TroubleshootingLog = { role: 'user', content: textToSend, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    const advice = await getTroubleshootingAdvice(textToSend, { ...context, isStealthMode }, telemetry);
