export const getTroubleshootingAdvice = async (issue: string, context?: any, telemetry?: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelId = 'gemini-3-flash-preview';

  const systemInstruction = `
    You are the 'SatExpert Tactical Intelligence Agent' (STIA).
    MISSION: Provide high-level technical SatCom intelligence and cyber defense maneuvers.

    ENVIRONMENT:
    - LAT: ${context?.lat ?? 'N/A'}, LNG: ${context?.lng ?? 'N/A'}
    - TARGET_ASSET: ${context?.satName ?? 'N/A'}
    - DEFCON: ${context?.defcon ?? 5}
    - EW_JAMMING: ${context?.isJamming ? 'YES' : 'NO'}
    - STEALTH_PROTOCOL: ${context?.isStealthMode ? 'ACTIVE' : 'INACTIVE'}

    CYBER_THREAT_POSTURE:
    - If user asks for defensive code, provide robust Python or Shell scripts.
    - If user asks for offensive signal analysis, be clinical and precise.
    - Always warn of potential "Lateral Movement" or "Man-in-the-Middle" (MITM) risks in VSAT backhauls.

    TONE: Clinical, authoritative, military-grade. Use tactical jargon (e.g., 'EIRP saturation', 'FEC degradation', 'Baseband injection').
  `;

  try {
    const tools = [
        { googleSearch: {} }, 
        { functionDeclarations: [terminalSensorTool] }
    ];

    const messages: Content[] = [
        { role: 'user', parts: [{ text: "STIA_COMMAND: " + issue }] }
    ];

    let response = await ai.models.generateContent({
      model: modelId,
      contents: messages,
      config: {
        systemInstruction,
        tools,
      },
    });

    const functionCalls = response.functionCalls;
    if (functionCalls && functionCalls.length > 0) {
        const call = functionCalls[0];
        if (call.name === 'read_terminal_sensors') {
            messages.push(response.candidates![0].content);
            messages.push({
                role: 'tool',
                parts: [{
                    functionResponse: {
                        name: 'read_terminal_sensors',
                        response: { result: telemetry }
                    }
                }]
            });

            response = await ai.models.generateContent({
                model: modelId,
                contents: messages,
                config: { systemInstruction, tools }
            });
        }
    }

    let output = response.text || "";
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0) {
      output += "\n\n[INTEL_SOURCES_MAPPED]:\n";
      chunks.forEach((chunk: any) => {
        if (chunk.web) output += `- [INTEL] ${chunk.web.title}: ${chunk.web.uri}\n`;
      });
    }

    return output;
  } catch (error) {
    console.error("STIA_CRITICAL_ERROR", error);
    return "SYSTEM_HALT: INTEL_UPLINK_FAILURE. CHECK_ENCRYPTION_LAYER.";
  }
};

