import * as React from 'react';
import { useState, useEffect, useRef, useMemo } from 'react';
import { Layout } from './components/Layout.tsx';
import { LookAngleCard } from './components/LookAngleCard.tsx';
import { AITechnician } from './components/AITechnician.tsx';
import { SecurityTools } from './components/SecurityTools.tsx';
import { LinkBudgetCalculator } from './components/LinkBudgetCalculator.tsx';
import { SignalVisualizer } from './components/SignalVisualizer.tsx';
import { TacticalHUD } from './components/TacticalHUD.tsx';
import { TacticalMap } from './components/TacticalMap.tsx';
import { RSSReader } from './components/RSSReader.tsx';
import { TelemetryPulse } from './components/TelemetryPulse.tsx';
import { SignalInterceptor } from './components/SignalInterceptor.tsx';
import { MediaForge } from './components/MediaForge.tsx';
import { LiveComms } from './components/LiveComms.tsx';
import { Coordinates, Satellite, LookAngles, WeatherCondition, MainView } from './types.ts';
import { COMMON_SATELLITES } from './constants.ts';
import { calculateLookAngles } from './utils/geoUtils.ts';

const STORAGE_KEY = 'satexpert_tactical_v5';
const STEALTH_STORAGE_KEY = 'satexpert_stealth_mode';

export const App: React.FC = () => {
  const [satellites, setSatellites] = useState<Satellite[]>(COMMON_SATELLITES);
  const [userLoc, setUserLoc] = useState<Coordinates>({ lat: 51.5074, lng: -0.1278 });
  const [selectedSat, setSelectedSat] = useState<Satellite>(satellites[0]);
  const [lookAngles, setLookAngles] = useState<LookAngles | null>(null);
  const [view, setView] = useState<MainView>('tactical');
  const [defcon, setDefcon] = useState<number>(5);
  const [isTracking, setIsTracking] = useState<boolean>(false);
  const [weather, setWeather] = useState<WeatherCondition>('CLEAR');
  const [isJamming, setIsJamming] = useState<boolean>(false);
  const [jammingPower, setJammingPower] = useState<number>(50);
  const [isStealthMode, setIsStealthMode] = useState<boolean>(false);

  const isFirstMount = useRef(true);

  // Source of Truth Telemetry logic
  const telemetry = useMemo(() => {
    let snr = 16.0;
    let rxPower = -42.0;
    let packetLoss = 0.00;
    let bucTemp = 45.0;

    if (weather === 'OVERCAST') { snr -= 2.0; rxPower -= 1.5; }
    else if (weather === 'LIGHT_RAIN') { snr -= 5.0; rxPower -= 3.5; packetLoss += 0.8; }
    else if (weather === 'HEAVY_STORM') { snr -= 14.0; rxPower -= 12.0; packetLoss += 12.5; }

    if (isJamming) {
      snr -= (jammingPower / 5); 
      packetLoss += (jammingPower / 2);
      rxPower += (jammingPower / 10);
      bucTemp += (jammingPower / 15);
    }

    if (defcon <= 2) bucTemp += 8.0;

    if (isStealthMode) {
      snr = 20.0; rxPower = -30.0; packetLoss = 0.00; bucTemp = 35.0;
    }

    return {
      snr: Math.max(0, snr + (Math.random() - 0.5)).toFixed(2),
      rxPower: (rxPower + (Math.random() - 0.5)).toFixed(1),
      bucTemp: (bucTemp + (Math.random() - 0.5)).toFixed(1),
      packetLoss: Math.min(100, packetLoss + (Math.random() * 0.2)).toFixed(2),
      status: snr > 10 ? "NOMINAL" : (snr > 4 ? "DEGRADED" : "CRITICAL")
    };
  }, [weather, isJamming, jammingPower, defcon, isStealthMode]);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.loc) setUserLoc(parsed.loc);
      if (parsed.satId) {
        const sat = satellites.find(s => s.id === parsed.satId);
        if (sat) setSelectedSat(sat);
      }
      setDefcon(parsed.defcon || 5);
    }
    const savedStealth = localStorage.getItem(STEALTH_STORAGE_KEY);
    if (savedStealth !== null) setIsStealthMode(JSON.parse(savedStealth));
    isFirstMount.current = false;
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ loc: userLoc, satId: selectedSat.id, defcon }));
  }, [userLoc, selectedSat, defcon]);

  useEffect(() => {
    if (!isFirstMount.current) localStorage.setItem(STEALTH_STORAGE_KEY, JSON.stringify(isStealthMode));
  }, [isStealthMode]);

  useEffect(() => {
    setLookAngles(calculateLookAngles(userLoc, selectedSat.longitude));
  }, [userLoc, selectedSat]);

  return (
    <div className={`crt-screen min-h-screen ${(!isStealthMode && (isJamming || defcon === 1)) ? 'crt-distorted' : ''}`}>
      <Layout isStealthMode={isStealthMode} setIsStealthMode={setIsStealthMode}>
        <div className="flex flex-col space-y-6 max-w-7xl mx-auto pb-12 transition-all duration-1000">

          <div className={`flex flex-col lg:flex-row items-stretch justify-between gap-4 glass p-4 rounded-2xl border-slate-800 shadow-2xl relative overflow-hidden ${defcon === 1 || isJamming ? 'defcon-alert' : ''}`}>
             <div className="flex flex-col md:flex-row items-center gap-6 z-20">
              <div className="flex flex-col min-w-[320px]">
                <span className="text-[10px] font-bold text-cyan-500 uppercase tracking-[0.2em] mb-2 px-1">Mission Control System</span>
                <div className="flex flex-wrap gap-1 bg-slate-950/80 p-1 rounded-xl border border-slate-800/50">
                  {(['tactical', 'intelligence', 'interception', 'media', 'live', 'calculations', 'news'] as MainView[]).map((v) => (
                    <button
                      key={v}
                      onClick={() => setView(v)}
                      className={`px-3 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all duration-200 ${
                        view === v 
                          ? 'bg-cyan-500 text-slate-950 shadow-[0_0_15px_rgba(34,211,238,0.3)]' 
                          : 'text-slate-400 hover:text-cyan-400 hover:bg-white/5'
                      }`}
                    >
                      {v}
                    </button>
                  ))}
                </div>
              </div>

              <div className="h-12 w-px bg-slate-800 hidden md:block"></div>

              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-2 px-1">Defcon Protocol</span>
                <div className="flex space-x-1.5 bg-slate-950/40 p-1 rounded-xl border border-slate-800/30">
                  {[5, 4, 3, 2, 1].map(lvl => (
                    <button key={lvl} onClick={() => setDefcon(lvl)} className={`w-9 h-9 rounded-lg flex items-center justify-center text-xs font-bold transition-all border ${defcon === lvl ? (lvl <= 2 ? 'bg-red-500 text-white border-red-400' : 'bg-cyan-500/20 text-cyan-400 border-cyan-500/40') : 'bg-slate-900 border-slate-800 text-slate-600'}`}>
                      {lvl}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex items-center justify-center lg:justify-end flex-grow z-20">
               <TelemetryPulse telemetry={telemetry} isStealthMode={isStealthMode} />
            </div>
          </div>

          <div className="min-h-[70vh]">
            {view === 'tactical' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in slide-in-from-bottom-4">
                <div className="lg:col-span-5 xl:col-span-4 space-y-6">
                  <TacticalHUD loc={userLoc} sat={selectedSat} satellites={satellites} onLocChange={setUserLoc} onSatChange={setSelectedSat} onSatellitesUpdate={setSatellites} isTracking={isTracking} onTrackingChange={setIsTracking} isJamming={isJamming} setIsJamming={setIsJamming} jammingPower={jammingPower} setJammingPower={setJammingPower} weather={weather} setWeather={setWeather} isStealthMode={isStealthMode} />
                  <TacticalMap userLoc={userLoc} satellite={selectedSat} isTracking={isTracking} onLocChange={setUserLoc} />
                  {lookAngles && <LookAngleCard angles={lookAngles} satellite={selectedSat} />}
                  <SignalVisualizer quality={lookAngles?.elevation && lookAngles.elevation > 0 ? 85 : 0} isJamming={isJamming} jammingPower={jammingPower} rainFade={weather === 'CLEAR' ? 0.5 : 5.0} isStealthMode={isStealthMode} />
                </div>
                <div className="lg:col-span-7 xl:col-span-8">
                  <AITechnician context={{ lat: userLoc.lat, lng: userLoc.lng, satName: selectedSat.name, defcon, weather, isJamming }} telemetry={telemetry} isStealthMode={isStealthMode} />
                </div>
              </div>
            )}

            {view === 'intelligence' && (
              <SecurityTools userLoc={userLoc} selectedSatName={selectedSat.name} isJamming={isJamming} setIsJamming={setIsJamming} jammingPower={jammingPower} setJammingPower={setJammingPower} signalQuality={88} onBack={() => setView('tactical')} isStealthMode={isStealthMode} setIsStealthMode={setIsStealthMode} />
            )}

            {view === 'interception' && (
              <SignalInterceptor isJamming={isJamming} jammingPower={jammingPower} isStealthMode={isStealthMode} />
            )}

            {view === 'media' && <MediaForge />}
            {view === 'live' && <LiveComms isStealthMode={isStealthMode} />}

            {view === 'calculations' && lookAngles && (
              <div className="max-w-4xl mx-auto">
                <LinkBudgetCalculator distance={lookAngles.distance} isStealthMode={isStealthMode} />
              </div>
            )}

            {view === 'news' && (
              <div className="max-w-4xl mx-auto">
                <RSSReader />
              </div>
            )}
          </div>
        </div>
      </Layout>
    </div>
  );
};

export default App;

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Coordinates, Satellite, SatelliteStatus, WeatherCondition } from '../types.ts';
import { fetchSatelliteStatusUpdates } from '../services/satelliteService.ts';

interface Props {
  loc: Coordinates;
  sat: Satellite;
  satellites: Satellite[];
  onLocChange: (loc: Coordinates) => void;
  onSatChange: (sat: Satellite) => void;
  onSatellitesUpdate: (sats: Satellite[]) => void;
  isTracking?: boolean;
  onTrackingChange?: (val: boolean) => void;
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  weather: WeatherCondition;
  setWeather: (val: WeatherCondition) => void;
  isStealthMode: boolean;
  telemetry: any; // Added telemetry prop for export functionality
}

interface TacticalEvent {
  id: string;
  timestamp: string;
  satName: string;
  satId: string;
  status: SatelliteStatus;
  detail: string;
}

const EVENT_LOG_STORAGE_KEY = 'satexpert_event_logs';

const StatusBadge: React.FC<{ status?: SatelliteStatus }> = ({ status }) => {
  const config = {
    active: { color: 'bg-green-500', label: 'ONLINE', pulse: true },
    offline: { color: 'bg-red-500', label: 'OFFLINE', pulse: false },
    maintenance: { color: 'bg-amber-500', label: 'MAINT', pulse: true },
    decommissioned: { color: 'bg-slate-600', label: 'EOL', pulse: false },
  }[status || 'active'];

  return (
    <div className="flex items-center space-x-1.5">
      <div className={`w-2 h-2 rounded-full ${config.color} ${config.pulse ? 'status-pulse' : ''}`}></div>
      <span className={`text-[9px] font-bold tracking-widest ${config.color.replace('bg-', 'text-')}`}>
        {config.label}
      </span>
    </div>
  );
};

export const TacticalHUD: React.FC<Props> = ({ 
  loc, sat, satellites, onLocChange, onSatChange, onSatellitesUpdate, isTracking, onTrackingChange,
  isJamming, setIsJamming, jammingPower, setJammingPower,
  weather, setWeather, isStealthMode, telemetry
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [showEventLog, setShowEventLog] = useState(false);
  const [animateLabel, setAnimateLabel] = useState(false);
  const [eventLogs, setEventLogs] = useState<TacticalEvent[]>([]);
  const [hasNewLogs, setHasNewLogs] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const prevSatRef = useRef<{id: string, status?: SatelliteStatus} | null>(null);

  const filteredSatellites = useMemo(() => {
    return satellites.filter(s => 
      s.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      s.orbitalSlot.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [searchQuery, satellites]);

  useEffect(() => {
    const saved = localStorage.getItem(EVENT_LOG_STORAGE_KEY);
    if (saved) {
      try {
        setEventLogs(JSON.parse(saved));
      } catch (e) { console.error("EVENT_LOG_LOAD_ERROR", e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(EVENT_LOG_STORAGE_KEY, JSON.stringify(eventLogs));
  }, [eventLogs]);

  useEffect(() => {
    const pollInterval = setInterval(async () => {
      const updatedSatellites = await fetchSatelliteStatusUpdates();
      onSatellitesUpdate(updatedSatellites);
    }, 15000);
    return () => clearInterval(pollInterval);
  }, [onSatellitesUpdate]);

  useEffect(() => {
    setAnimateLabel(true);
    const timer = setTimeout(() => setAnimateLabel(false), 600);

    if (prevSatRef.current === null) {
      prevSatRef.current = { id: sat.id, status: sat.status };
      return;
    }

    const isSameSat = prevSatRef.current?.id === sat.id;
    const isStatusChanged = prevSatRef.current?.status !== sat.status;

    if (!isSameSat || (isSameSat && isStatusChanged)) {
      const newEvent: TacticalEvent = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: new Date().toLocaleTimeString(),
        satName: sat.name,
        satId: sat.id,
        status: sat.status || 'active',
        detail: !isSameSat 
          ? `ASSET_ACQUISITION: Targeted ${sat.name} (${sat.orbitalSlot})`
          : `STATUS_CHANGE: Asset ${sat.name} transitioned to ${sat.status?.toUpperCase()}`
      };
      setEventLogs(prev => [newEvent, ...prev].slice(0, 50));
      if (!showEventLog) setHasNewLogs(true);
    }

    prevSatRef.current = { id: sat.id, status: sat.status };
    return () => clearTimeout(timer);
  }, [sat.id, sat.status, showEventLog]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (s: Satellite) => {
    onSatChange(s);
    setSearchQuery('');
    setIsOpen(false);
  };

  const handleExport = () => {
    setIsExporting(true);

    // Filter logs specific to the current satellite
    const relevantLogs = eventLogs.filter(log => log.satId === sat.id);

    const exportData = {
      mission_timestamp: new Date().toISOString(),
      security_context: {
        stealth_mode: isStealthMode ? "ACTIVE" : "INACTIVE",
        ew_jamming: isJamming ? `ACTIVE (${jammingPower}%)` : "INACTIVE",
        weather_condition: weather
      },
      asset_specifications: {
        id: sat.id,
        name: sat.name,
        orbital_slot: sat.orbitalSlot,
        operator: sat.operator,
        apogee: sat.apogee,
        perigee: sat.perigee,
        inclination: sat.inclination,
        velocity: sat.velocity,
        status: sat.status
      },
      live_telemetry: telemetry,
      ground_station: loc,
      event_history: relevantLogs
    };

    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `STIA_EXPORT_${sat.name.replace(/\s+/g, '_')}_${new Date().getTime()}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    setTimeout(() => setIsExporting(false), 1500);
  };

  const clearLogs = () => {
    setEventLogs([]);
    setHasNewLogs(false);
    setShowEventLog(false);
  };

  const weatherIcons = {
    CLEAR: '☀️',
    OVERCAST: '☁️',
    LIGHT_RAIN: '🌧️',
    HEAVY_STORM: '⛈️'
  };

  return (
    <div className="glass rounded-2xl p-6 border-slate-800 relative z-50 overflow-hidden">
      <div className="absolute top-0 left-0 w-1 h-full bg-cyan-500/20"></div>

      <div className="space-y-6">
        <div className="relative" ref={dropdownRef}>
          <div className="flex items-center justify-between mb-3 px-1">
            <div className="flex flex-col">
              <label className={`block text-[11px] font-bold uppercase tracking-[0.2em] transition-all duration-300 transform ${
                animateLabel 
                  ? 'text-cyan-400 scale-105' 
                  : 'text-white'
              }`}>
                Target Acquisition
              </label>
              <div className="card-header-line"></div>
            </div>
            <div className="flex items-center space-x-2">
              <button 
                onClick={handleExport}
                className={`flex items-center space-x-1.5 px-3 py-1.5 rounded-lg border border-slate-800 bg-slate-900 text-[9px] font-bold uppercase tracking-widest transition-all ${isExporting ? 'text-green-400 border-green-500/30' : 'text-slate-400 hover:text-cyan-400 hover:border-cyan-500/30'}`}
              >
                <svg className={`w-3 h-3 ${isExporting ? 'animate-bounce' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
                <span>{isExporting ? 'EXPT_OK' : 'Export'}</span>
              </button>
              <button 
                onClick={() => { setShowEventLog(true); setHasNewLogs(false); }}
                className="relative flex items-center space-x-1.5 px-3 py-1.5 rounded-lg border border-slate-800 bg-slate-900 text-[9px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/30 transition-all uppercase tracking-widest"
              >
                <span>Logs</span>
                {hasNewLogs && <div className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full animate-pulse border border-slate-900"></div>}
              </button>
            </div>
          </div>

          <div className="relative">
            <input
              type="text"
              placeholder={isOpen ? "ENTER SATELLITE NAME OR SLOT..." : sat.name}
              className={`w-full bg-slate-950/80 border ${isOpen ? 'border-cyan-500 shadow-[0_0_15px_rgba(34,211,238,0.2)]' : 'border-slate-800'} rounded-xl p-3 pl-10 text-xs text-white outline-none transition-all mono placeholder:text-slate-700`}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setIsOpen(true);
              }}
              onFocus={() => setIsOpen(true)}
            />
            <div className="absolute left-3.5 top-1/2 -translate-y-1/2">
              <svg className={`w-4.5 h-4.5 ${isOpen ? 'text-cyan-400' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
            <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center">
               {!isOpen && <StatusBadge status={sat.status} />}
            </div>
          </div>

          {isOpen && (
            <div className="absolute mt-2 w-full glass bg-slate-950 border border-cyan-500/40 rounded-xl shadow-2xl overflow-hidden max-h-[300px] flex flex-col z-[100]">
              <div className="bg-cyan-500/10 px-4 py-2 border-b border-slate-800">
                <span className="text-[9px] font-bold text-cyan-400 uppercase tracking-widest">Asset Registry</span>
              </div>
              <div className="overflow-y-auto py-1 scrollbar-hide">
                {filteredSatellites.map((s) => (
                  <button
                    key={s.id}
                    onClick={() => handleSelect(s)}
                    className={`w-full text-left px-4 py-3 hover:bg-white/5 transition-colors flex items-center justify-between border-b border-slate-900/50 last:border-none ${s.id === sat.id ? 'bg-cyan-500/5' : ''}`}
                  >
                    <div className="flex flex-col">
                      <span className={`text-[11px] font-bold ${s.id === sat.id ? 'text-cyan-400' : 'text-slate-200'}`}>{s.name}</span>
                      <span className="text-[9px] text-slate-500 mono">{s.operator}</span>
                    </div>
                    <span className="text-[10px] text-cyan-500 font-mono font-bold">{s.orbitalSlot}</span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Identity & Telemetry Strip */}
        <div className="grid grid-cols-2 gap-3">
          <div className="bg-slate-950/40 rounded-xl border border-slate-800 p-3 flex flex-col">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Authority</span>
            <span className="text-[10px] font-bold text-slate-200 mono truncate">{sat.operator || 'UNSPECIFIED'}</span>
          </div>
          <div className="bg-slate-950/40 rounded-xl border border-slate-800 p-3 flex flex-col items-end text-right">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Slot Index</span>
            <span className="text-[10px] font-bold text-cyan-400 mono">{sat.orbitalSlot}</span>
          </div>
        </div>

        {/* Weather Simulator Area */}
        <div className="bg-slate-950/40 rounded-xl border border-slate-800 p-4 space-y-4">
          <div className="flex items-center justify-between">
             <span className="text-[9px] font-black text-white uppercase tracking-widest">Atmospheric Environment</span>
             <span className="text-[8px] text-slate-500 font-bold uppercase mono">Ka-Band Simulation</span>
          </div>
          <div className="grid grid-cols-4 gap-2">
            {(['CLEAR', 'OVERCAST', 'LIGHT_RAIN', 'HEAVY_STORM'] as WeatherCondition[]).map((cond) => (
              <button 
                key={cond}
                onClick={() => setWeather(cond)}
                disabled={isStealthMode}
                className={`flex flex-col items-center justify-center p-2 rounded-xl border transition-all duration-200 ${
                  isStealthMode ? 'opacity-30' : ''
                } ${
                  weather === cond 
                    ? 'bg-cyan-500/20 border-cyan-500/60 text-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.1)]' 
                    : 'bg-slate-900 border-slate-800 text-slate-600 hover:border-slate-600'
                }`}
              >
                <span className="text-lg mb-1">{weatherIcons[cond]}</span>
                <span className="text-[7px] font-bold uppercase tracking-tighter text-center">{cond.replace('_', ' ')}</span>
              </button>
            ))}
          </div>
          <div className="grid grid-cols-2 gap-4 pt-2 border-t border-slate-800/50">
             <div className="flex flex-col">
               <span className="text-[8px] text-slate-500 font-bold uppercase">Estimated Loss</span>
               <span className={`text-xs font-bold mono ${weather === 'HEAVY_STORM' ? 'text-red-500' : 'text-cyan-400'}`}>
                 {isStealthMode ? '0.00' : (weather === 'CLEAR' ? '0.50' : weather === 'OVERCAST' ? '1.80' : weather === 'LIGHT_RAIN' ? '4.50' : '12.00')} dB
               </span>
             </div>
             <div className="flex flex-col items-end text-right">
               <span className="text-[8px] text-slate-500 font-bold uppercase">Humidity Index</span>
               <span className="text-xs font-bold text-slate-300 mono">{isStealthMode ? '0%' : (weather === 'CLEAR' ? '12%' : weather === 'OVERCAST' ? '45%' : '88%')}</span>
             </div>
          </div>
        </div>

        {/* EW Control Area */}
        <div className={`rounded-xl border p-4 space-y-4 transition-all duration-500 ${isStealthMode ? 'bg-purple-900/10 border-purple-500/30' : (isJamming ? 'bg-red-900/10 border-red-500/30 shadow-[0_0_20px_rgba(239,68,68,0.05)]' : 'bg-slate-950/40 border-slate-800')}`}>
          <div className="flex items-center justify-between">
            <div className="flex flex-col">
              <span className={`text-[10px] font-black uppercase tracking-widest ${isStealthMode ? 'text-purple-400' : (isJamming ? 'text-red-500' : 'text-white')}`}>Electronic Warfare</span>
              <span className="text-[8px] text-slate-500 font-bold uppercase mono">Mode: Continuous Wave</span>
            </div>
            <button 
              onClick={() => setIsJamming(!isJamming)}
              disabled={isStealthMode}
              className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all duration-300 ${
                isStealthMode ? 'bg-slate-800 text-slate-500' : (isJamming ? 'bg-red-600 text-white shadow-lg animate-pulse' : 'bg-slate-800 text-slate-400 hover:text-white')
              }`}
            >
              {isStealthMode ? 'Stealth' : (isJamming ? 'Engaged' : 'Standby')}
            </button>
          </div>

          <div className="space-y-3">
            <div className="flex items-center justify-between text-[9px] font-bold mono">
              <span className={isStealthMode ? 'text-purple-400' : 'text-slate-500'}>Intensity: {isStealthMode ? 0 : jammingPower}%</span>
              <span className={isStealthMode ? 'text-purple-400' : 'text-red-400'}>SNR Loss: {isStealthMode ? '0.0' : -(jammingPower / 5).toFixed(1)} dB</span>
            </div>
            <input 
              type="range" 
              min="0" max="100" 
              value={isStealthMode ? 0 : jammingPower} 
              onChange={(e) => setJammingPower(parseInt(e.target.value))}
              disabled={isStealthMode}
              className={`w-full h-1.5 rounded-lg appearance-none cursor-pointer transition-all ${isStealthMode ? 'bg-purple-900 accent-purple-500' : (isJamming ? 'bg-red-900 accent-red-500' : 'bg-slate-800 accent-slate-600')}`}
            />
          </div>
        </div>

        {/* Manual Coordinates Grid */}
        <div className="grid grid-cols-2 gap-4">
           <div>
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-2 tracking-widest">Ground Station Lat</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  disabled={isTracking || isStealthMode}
                  className={`w-full bg-slate-950/60 p-3 text-xs rounded-xl border text-cyan-400 outline-none mono transition-all ${isTracking || isStealthMode ? 'border-slate-800 opacity-50' : 'border-slate-800 focus:border-cyan-500/40'}`} 
                  value={loc.lat} 
                  onChange={e => onLocChange({...loc, lat: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[9px] text-slate-700 font-bold mono">N/S</span>
              </div>
           </div>
           <div>
              <label className="block text-[8px] font-bold text-slate-500 uppercase mb-2 tracking-widest">Ground Station Lng</label>
              <div className="relative">
                <input 
                  type="number" 
                  step="0.0001" 
                  disabled={isTracking || isStealthMode}
                  className={`w-full bg-slate-950/60 p-3 text-xs rounded-xl border text-cyan-400 outline-none mono transition-all ${isTracking || isStealthMode ? 'border-slate-800 opacity-50' : 'border-slate-800 focus:border-cyan-500/40'}`} 
                  value={loc.lng} 
                  onChange={e => onLocChange({...loc, lng: parseFloat(e.target.value)})} 
                />
                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[9px] text-slate-700 font-bold mono">E/W</span>
              </div>
           </div>
        </div>
      </div>

      {/* Event Log Modal - Refined */}
      {showEventLog && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="glass w-full max-w-lg rounded-3xl border border-slate-700 shadow-2xl flex flex-col max-h-[75vh] overflow-hidden">
            <div className="p-6 border-b border-slate-800 flex items-center justify-between bg-slate-900/40">
               <div>
                  <h3 className="text-sm font-black text-white uppercase tracking-[0.2em] flex items-center">
                    <span className="w-2 h-2 bg-cyan-500 rounded-full mr-3 status-pulse"></span>
                    Asset Intelligence Logs
                  </h3>
                  <p className="text-[9px] text-slate-500 font-bold tracking-widest mt-1">Tactical Audit Log // Sector Alpha</p>
               </div>
               <button 
                onClick={() => setShowEventLog(false)}
                className="p-2 hover:bg-white/5 rounded-full transition-colors"
               >
                 <svg className="w-6 h-6 text-slate-500 hover:text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
               </button>
            </div>

            <div className="flex-grow overflow-y-auto p-4 space-y-3 bg-slate-950/20">
              {eventLogs.length > 0 ? (
                eventLogs.map((log) => (
                  <div key={log.id} className="p-4 bg-slate-900/40 rounded-xl border border-slate-800/60 flex items-start space-x-4 group hover:border-cyan-500/30 transition-all">
                    <div className="pt-1"><StatusBadge status={log.status} /></div>
                    <div className="flex-grow">
                       <div className="flex items-center justify-between mb-1.5">
                          <span className="text-[11px] font-black text-white mono">{log.satName}</span>
                          <span className="text-[8px] text-slate-600 font-bold mono">{log.timestamp}</span>
                       </div>
                       <p className="text-[12px] text-slate-400 leading-relaxed mono">{log.detail}</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center py-24 text-center">
                   <p className="text-[11px] font-bold text-slate-600 uppercase tracking-widest">No Tactical Logs On File</p>
                </div>
              )}
            </div>

            <div className="p-5 border-t border-slate-800 bg-slate-900/60 flex justify-end space-x-4">
               <button onClick={clearLogs} className="text-[10px] font-bold uppercase tracking-widest text-slate-500 hover:text-red-500 transition-colors">Wipe History</button>
               <button onClick={() => setShowEventLog(false)} className="px-6 py-2.5 bg-cyan-600 hover:bg-cyan-500 rounded-xl text-[10px] font-black uppercase tracking-widest text-slate-950 transition-all active:scale-95 shadow-lg shadow-cyan-500/20">Acknowledge</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import * as React from 'react';
import { useState, useEffect, useRef, useMemo } from 'react';
import { Layout } from './components/Layout.tsx';
import { LookAngleCard } from './components/LookAngleCard.tsx';
import { AITechnician } from './components/AITechnician.tsx';
import { SecurityTools } from './components/SecurityTools.tsx';
import { LinkBudgetCalculator } from './components/LinkBudgetCalculator.tsx';
import { SignalVisualizer } from './components/SignalVisualizer.tsx';
import { TacticalHUD } from './components/TacticalHUD.tsx';
import { TacticalMap } from './components/TacticalMap.tsx';
import { RSSReader } from './components/RSSReader.tsx';
import { TelemetryPulse } from './components/TelemetryPulse.tsx';
import { SignalInterceptor } from './components/SignalInterceptor.tsx';
import { MediaForge } from './components/MediaForge.tsx';
import { LiveComms } from './components/LiveComms.tsx';
import { Coordinates, Satellite, LookAngles, WeatherCondition, MainView } from './types.ts';
import { COMMON_SATELLITES } from './constants.ts';
import { calculateLookAngles } from './utils/geoUtils.ts';

const STORAGE_KEY = 'satexpert_tactical_v5';
const STEALTH_STORAGE_KEY = 'satexpert_stealth_mode';

export const App: React.FC = () => {
  const [satellites, setSatellites] = useState<Satellite[]>(COMMON_SATELLITES);
  const [userLoc, setUserLoc] = useState<Coordinates>({ lat: 51.5074, lng: -0.1278 });
  const [selectedSat, setSelectedSat] = useState<Satellite>(satellites[0]);
  const [lookAngles, setLookAngles] = useState<LookAngles | null>(null);
  const [view, setView] = useState<MainView>('tactical');
  const [defcon, setDefcon] = useState<number>(5);
  const [isTracking, setIsTracking] = useState<boolean>(false);
  const [weather, setWeather] = useState<WeatherCondition>('CLEAR');
  const [isJamming, setIsJamming] = useState<boolean>(false);
  const [jammingPower, setJammingPower] = useState<number>(50);
  const [isStealthMode, setIsStealthMode] = useState<boolean>(false);

  const isFirstMount = useRef(true);

  // Source of Truth Telemetry logic
  const telemetry = useMemo(() => {
    let snr = 16.0;
    let rxPower = -42.0;
    let packetLoss = 0.00;
    let bucTemp = 45.0;

    if (weather === 'OVERCAST') { snr -= 2.0; rxPower -= 1.5; }
    else if (weather === 'LIGHT_RAIN') { snr -= 5.0; rxPower -= 3.5; packetLoss += 0.8; }
    else if (weather === 'HEAVY_STORM') { snr -= 14.0; rxPower -= 12.0; packetLoss += 12.5; }

    if (isJamming) {
      snr -= (jammingPower / 5); 
      packetLoss += (jammingPower / 2);
      rxPower += (jammingPower / 10);
      bucTemp += (jammingPower / 15);
    }

    if (defcon <= 2) bucTemp += 8.0;

    if (isStealthMode) {
      snr = 20.0; rxPower = -30.0; packetLoss = 0.00; bucTemp = 35.0;
    }

    return {
      snr: Math.max(0, snr + (Math.random() - 0.5)).toFixed(2),
      rxPower: (rxPower + (Math.random() - 0.5)).toFixed(1),
      bucTemp: (bucTemp + (Math.random() - 0.5)).toFixed(1),
      packetLoss: Math.min(100, packetLoss + (Math.random() * 0.2)).toFixed(2),
      status: snr > 10 ? "NOMINAL" : (snr > 4 ? "DEGRADED" : "CRITICAL")
    };
  }, [weather, isJamming, jammingPower, defcon, isStealthMode]);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.loc) setUserLoc(parsed.loc);
      if (parsed.satId) {
        const sat = satellites.find(s => s.id === parsed.satId);
        if (sat) setSelectedSat(sat);
      }
      setDefcon(parsed.defcon || 5);
    }
    const savedStealth = localStorage.getItem(STEALTH_STORAGE_KEY);
    if (savedStealth !== null) setIsStealthMode(JSON.parse(savedStealth));
    isFirstMount.current = false;
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ loc: userLoc, satId: selectedSat.id, defcon }));
  }, [userLoc, selectedSat, defcon]);

  useEffect(() => {
    if (!isFirstMount.current) localStorage.setItem(STEALTH_STORAGE_KEY, JSON.stringify(isStealthMode));
  }, [isStealthMode]);

  useEffect(() => {
    setLookAngles(calculateLookAngles(userLoc, selectedSat.longitude));
  }, [userLoc, selectedSat]);

  return (
    <div className={`crt-screen min-h-screen ${(!isStealthMode && (isJamming || defcon === 1)) ? 'crt-distorted' : ''}`}>
      <Layout isStealthMode={isStealthMode} setIsStealthMode={setIsStealthMode}>
        <div className="flex flex-col space-y-6 max-w-7xl mx-auto pb-12 transition-all duration-1000">

          <div className={`flex flex-col lg:flex-row items-stretch justify-between gap-4 glass p-4 rounded-2xl border-slate-800 shadow-2xl relative overflow-hidden ${defcon === 1 || isJamming ? 'defcon-alert' : ''}`}>
             <div className="flex flex-col md:flex-row items-center gap-6 z-20">
              <div className="flex flex-col min-w-[320px]">
                <span className="text-[10px] font-bold text-cyan-500 uppercase tracking-[0.2em] mb-2 px-1">Mission Control System</span>
                <div className="flex flex-wrap gap-1 bg-slate-950/80 p-1 rounded-xl border border-slate-800/50">
                  {(['tactical', 'intelligence', 'interception', 'media', 'live', 'calculations', 'news'] as MainView[]).map((v) => (
                    <button
                      key={v}
                      onClick={() => setView(v)}
                      className={`px-3 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all duration-200 ${
                        view === v 
                          ? 'bg-cyan-500 text-slate-950 shadow-[0_0_15px_rgba(34,211,238,0.3)]' 
                          : 'text-slate-400 hover:text-cyan-400 hover:bg-white/5'
                      }`}
                    >
                      {v}
                    </button>
                  ))}
                </div>
              </div>

              <div className="h-12 w-px bg-slate-800 hidden md:block"></div>

              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-2 px-1">Defcon Protocol</span>
                <div className="flex space-x-1.5 bg-slate-950/40 p-1 rounded-xl border border-slate-800/30">
                  {[5, 4, 3, 2, 1].map(lvl => (
                    <button key={lvl} onClick={() => setDefcon(lvl)} className={`w-9 h-9 rounded-lg flex items-center justify-center text-xs font-bold transition-all border ${defcon === lvl ? (lvl <= 2 ? 'bg-red-500 text-white border-red-400' : 'bg-cyan-500/20 text-cyan-400 border-cyan-500/40') : 'bg-slate-900 border-slate-800 text-slate-600'}`}>
                      {lvl}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex items-center justify-center lg:justify-end flex-grow z-20">
               <TelemetryPulse telemetry={telemetry} isStealthMode={isStealthMode} />
            </div>
          </div>

          <div className="min-h-[70vh]">
            {view === 'tactical' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in fade-in slide-in-from-bottom-4">
                <div className="lg:col-span-5 xl:col-span-4 space-y-6">
                  <TacticalHUD 
                    loc={userLoc} 
                    sat={selectedSat} 
                    satellites={satellites} 
                    onLocChange={setUserLoc} 
                    onSatChange={setSelectedSat} 
                    onSatellitesUpdate={setSatellites} 
                    isTracking={isTracking} 
                    onTrackingChange={setIsTracking} 
                    isJamming={isJamming} 
                    setIsJamming={setIsJamming} 
                    jammingPower={jammingPower} 
                    setJammingPower={setJammingPower} 
                    weather={weather} 
                    setWeather={setWeather} 
                    isStealthMode={isStealthMode}
                    telemetry={telemetry} 
                  />
                  <TacticalMap userLoc={userLoc} satellite={selectedSat} isTracking={isTracking} onLocChange={setUserLoc} />
                  {lookAngles && <LookAngleCard angles={lookAngles} satellite={selectedSat} />}
                  <SignalVisualizer quality={lookAngles?.elevation && lookAngles.elevation > 0 ? 85 : 0} isJamming={isJamming} jammingPower={jammingPower} rainFade={weather === 'CLEAR' ? 0.5 : 5.0} isStealthMode={isStealthMode} />
                </div>
                <div className="lg:col-span-7 xl:col-span-8">
                  <AITechnician context={{ lat: userLoc.lat, lng: userLoc.lng, satName: selectedSat.name, defcon, weather, isJamming }} telemetry={telemetry} isStealthMode={isStealthMode} />
                </div>
              </div>
            )}

            {view === 'intelligence' && (
              <SecurityTools userLoc={userLoc} selectedSatName={selectedSat.name} isJamming={isJamming} setIsJamming={setIsJamming} jammingPower={jammingPower} setJammingPower={setJammingPower} signalQuality={88} onBack={() => setView('tactical')} isStealthMode={isStealthMode} setIsStealthMode={setIsStealthMode} />
            )}

            {view === 'interception' && (
              <SignalInterceptor isJamming={isJamming} jammingPower={jammingPower} isStealthMode={isStealthMode} />
            )}

            {view === 'media' && <MediaForge />}
            {view === 'live' && <LiveComms isStealthMode={isStealthMode} />}

            {view === 'calculations' && lookAngles && (
              <div className="max-w-4xl mx-auto">
                <LinkBudgetCalculator distance={lookAngles.distance} isStealthMode={isStealthMode} />
              </div>
            )}

            {view === 'news' && (
              <div className="max-w-4xl mx-auto">
                <RSSReader />
              </div>
            )}
          </div>
        </div>
      </Layout>
    </div>
  );
};

export default App;

import * as React from 'react';
import { useState, useRef, useEffect } from 'react';
import { getTroubleshootingAdvice, transcribeAudio } from '../services/geminiService.ts';
import { TroubleshootingLog } from '../types.ts';

interface TelemetryData {
  snr: string;
  rxPower: string;
  bucTemp: string;
  packetLoss: string;
  status: string;
}

interface Props {
  context: any;
  telemetry: TelemetryData;
  isStealthMode: boolean;
}

interface Overrides {
  snr: string | null;
  rxPower: string | null;
  bucTemp: string | null;
  packetLoss: string | null;
}

export const AITechnician: React.FC<Props> = ({ context, telemetry, isStealthMode }) => {
  const [messages, setMessages] = useState<TroubleshootingLog[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isThinking, setIsThinking] = useState(false);
  const [useSearch, setUseSearch] = useState(true);
  const [isRecording, setIsRecording] = useState(false);
  const [attachedFiles, setAttachedFiles] = useState<{data: string, mimeType: string, url: string}[]>([]);
  const [showOverrides, setShowOverrides] = useState(false);
  const [overrides, setOverrides] = useState<Overrides>({
    snr: null,
    rxPower: null,
    bucTemp: null,
    packetLoss: null
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const audioChunksRef = useRef<Int16Array[]>([]);

  useEffect(() => {
    const initialGreeting = { 
      role: 'assistant', 
      content: `[SYSTEM_READY] STIA-Agent Active.\n${isStealthMode ? 'PROTOCOL: STEALTH_MODE_ACTIVE\n' : ''}INTELLIGENCE_POSTURE: ${isThinking ? 'MAX_THINK' : 'FAST_RESPONSE'}\nDEFCON: ${context.defcon || 5}\n\nAwaiting tactical directives. Grounding: ${useSearch ? 'LIVE_SEARCH_ACTIVE' : 'LOCAL_CACHE_ONLY'}.`, 
      timestamp: new Date() 
    };
    setMessages([initialGreeting]);
  }, [isStealthMode, context.defcon, isThinking]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    (Array.from(files) as File[]).forEach(file => {
      const reader = new FileReader();
      reader.onload = (rev) => {
        const base64 = (rev.target?.result as string).split(',')[1];
        setAttachedFiles(prev => [...prev, {
          data: base64,
          mimeType: file.type,
          url: URL.createObjectURL(file)
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContextRef.current = new AudioContext({ sampleRate: 16000 });
      const source = audioContextRef.current.createMediaStreamSource(stream);
      scriptProcessorRef.current = audioContextRef.current.createScriptProcessor(4096, 1, 1);

      audioChunksRef.current = [];
      scriptProcessorRef.current.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const pcm16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) {
          pcm16[i] = Math.max(-1, Math.min(1, inputData[i])) * 32767;
        }
        audioChunksRef.current.push(pcm16);
      };

      source.connect(scriptProcessorRef.current);
      scriptProcessorRef.current.connect(audioContextRef.current.destination);
      setIsRecording(true);
    } catch (err) {
      console.error("MIC_ERROR", err);
    }
  };

  const stopRecording = async () => {
    if (!scriptProcessorRef.current) return;
    scriptProcessorRef.current.disconnect();
    setIsRecording(false);

    const totalLength = audioChunksRef.current.reduce((acc, chunk) => acc + chunk.length, 0);
    const result = new Int16Array(totalLength);
    let offset = 0;
    audioChunksRef.current.forEach(chunk => {
      result.set(chunk, offset);
      offset += chunk.length;
    });

    const binary = String.fromCharCode(...new Uint8Array(result.buffer));
    const base64 = btoa(binary);

    setIsLoading(true);
    const transcription = await transcribeAudio(base64);
    setInput(prev => (prev ? prev + " " : "") + transcription);
    setIsLoading(false);
  };

  const handleSend = async () => {
    if (!input.trim() && attachedFiles.length === 0) return;
    if (isLoading) return;

    const userMessage: TroubleshootingLog = { 
      role: 'user', 
      content: input, 
      timestamp: new Date(),
      imageUrl: attachedFiles[0]?.url 
    };
    setMessages(prev => [...prev, userMessage]);
    const currentInput = input;
    const currentFiles = attachedFiles;

    setInput('');
    setAttachedFiles([]);
    setIsLoading(true);

    // Prepare active telemetry with overrides
    const activeTelemetry = {
      ...telemetry,
      snr: overrides.snr ?? telemetry.snr,
      rxPower: overrides.rxPower ?? telemetry.rxPower,
      bucTemp: overrides.bucTemp ?? telemetry.bucTemp,
      packetLoss: overrides.packetLoss ?? telemetry.packetLoss,
      isManualOverride: Object.values(overrides).some(v => v !== null)
    };

    const advice = await getTroubleshootingAdvice(currentInput, { ...context, isStealthMode }, activeTelemetry, {
      thinking: isThinking,
      useSearch: useSearch,
      useMaps: true,
      mediaData: currentFiles.map(f => ({ data: f.data, mimeType: f.mimeType }))
    });

    const assistantMessage: TroubleshootingLog = { 
      role: 'assistant', 
      content: advice || 'COMM_FAILURE: Satellite link timed out.', 
      timestamp: new Date(),
      isCode: advice?.includes('```') 
    };

    setMessages(prev => [...prev, assistantMessage]);
    setIsLoading(false);
  };

  const updateOverride = (key: keyof Overrides, value: string) => {
    setOverrides(prev => ({
      ...prev,
      [key]: value === '' ? null : value
    }));
  };

  const isOverrideActive = Object.values(overrides).some(v => v !== null);

  return (
    <div className="glass rounded-[2rem] border-slate-800 flex flex-col h-full overflow-hidden bg-slate-950/40 relative">
      <div className="p-6 border-b border-slate-800 bg-slate-900/60 z-20">
        <div className="flex justify-between items-center">
          <div className="flex items-center space-x-4">
             <div className="w-12 h-12 bg-cyan-500/10 rounded-2xl flex items-center justify-center border border-cyan-500/20">
                <svg className="w-6 h-6 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
             </div>
             <div>
                <h3 className="text-sm font-black text-white uppercase tracking-widest">STIA_SENTINEL_V6</h3>
                <div className="flex items-center space-x-2 mt-0.5">
                  <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">Multi-Modal Recon</span>
                  {isOverrideActive && <span className="text-[8px] px-1.5 py-0.5 bg-amber-500/10 text-amber-500 border border-amber-500/30 rounded font-black animate-pulse">OVERRIDE_ON</span>}
                </div>
             </div>
          </div>
          <div className="flex items-center space-x-2">
             <button 
                onClick={() => setShowOverrides(!showOverrides)} 
                className={`p-2 rounded-lg border transition-all ${showOverrides ? 'bg-amber-500/20 border-amber-500/50 text-amber-400' : 'bg-slate-800 border-slate-700 text-slate-500 hover:text-slate-300'}`}
                title="Manual Telemetry Injection"
              >
               <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" /></svg>
             </button>
             <button onClick={() => setIsThinking(!isThinking)} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${isThinking ? 'bg-amber-500 text-slate-950 shadow-[0_0_15px_rgba(245,158,11,0.3)]' : 'bg-slate-800 text-slate-500'}`}>Deep_Think</button>
             <button onClick={() => setUseSearch(!useSearch)} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${useSearch ? 'bg-cyan-500 text-slate-950 shadow-[0_0_15px_rgba(34,211,238,0.3)]' : 'bg-slate-800 text-slate-500'}`}>Grounding</button>
          </div>
        </div>

        {/* Manual Telemetry Override Panel */}
        {showOverrides && (
          <div className="mt-4 grid grid-cols-2 md:grid-cols-4 gap-3 p-4 bg-slate-950/80 rounded-2xl border border-amber-500/30 animate-in slide-in-from-top-2 duration-300">
            <div className="space-y-1.5">
              <label className="block text-[8px] font-black text-slate-500 uppercase tracking-widest">Injected_SNR</label>
              <input 
                type="text" 
                placeholder={telemetry.snr}
                value={overrides.snr ?? ''}
                onChange={e => updateOverride('snr', e.target.value)}
                className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-[10px] text-amber-400 mono outline-none focus:border-amber-500/50"
              />
            </div>
            <div className="space-y-1.5">
              <label className="block text-[8px] font-black text-slate-500 uppercase tracking-widest">Injected_Power</label>
              <input 
                type="text" 
                placeholder={telemetry.rxPower}
                value={overrides.rxPower ?? ''}
                onChange={e => updateOverride('rxPower', e.target.value)}
                className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-[10px] text-amber-400 mono outline-none focus:border-amber-500/50"
              />
            </div>
            <div className="space-y-1.5">
              <label className="block text-[8px] font-black text-slate-500 uppercase tracking-widest">Injected_Temp</label>
              <input 
                type="text" 
                placeholder={telemetry.bucTemp}
                value={overrides.bucTemp ?? ''}
                onChange={e => updateOverride('bucTemp', e.target.value)}
                className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-[10px] text-amber-400 mono outline-none focus:border-amber-500/50"
              />
            </div>
            <div className="space-y-1.5">
              <label className="block text-[8px] font-black text-slate-500 uppercase tracking-widest">Injected_Loss</label>
              <input 
                type="text" 
                placeholder={telemetry.packetLoss}
                value={overrides.packetLoss ?? ''}
                onChange={e => updateOverride('packetLoss', e.target.value)}
                className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-[10px] text-amber-400 mono outline-none focus:border-amber-500/50"
              />
            </div>
            <div className="col-span-full flex justify-end">
              <button 
                onClick={() => setOverrides({ snr: null, rxPower: null, bucTemp: null, packetLoss: null })}
                className="text-[8px] font-bold text-slate-500 hover:text-amber-500 uppercase tracking-widest underline underline-offset-4 decoration-slate-800"
              >
                Clear_All_Overrides
              </button>
            </div>
          </div>
        )}
      </div>

      <div ref={scrollRef} className="flex-grow overflow-y-auto p-6 space-y-6 scrollbar-hide">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-5 rounded-3xl border ${m.role === 'user' ? 'bg-cyan-950/30 border-cyan-500/30 rounded-br-none' : 'bg-slate-900 border-slate-800 rounded-bl-none'}`}>
              {m.imageUrl && <img src={m.imageUrl} className="max-w-xs rounded-xl mb-4 border border-slate-700 shadow-lg" />}
              <div className="text-[13px] text-slate-200 mono leading-relaxed whitespace-pre-wrap">{m.content}</div>
              <div className="text-[8px] text-slate-600 font-bold mt-4 uppercase tracking-widest flex justify-between">
                 <span>{m.role === 'user' ? 'USER_UPLINK' : 'AGENT_RECON'}</span>
                 <span>{m.timestamp.toLocaleTimeString([], { hour12: false })}</span>
              </div>
            </div>
          </div>
        ))}
        {isLoading && <div className="flex justify-start"><div className="bg-slate-900 p-4 rounded-2xl rounded-bl-none border border-slate-800 text-[10px] text-cyan-500 font-black uppercase tracking-widest animate-pulse">Processing_Intel_Stream...</div></div>}
      </div>

      <div className="p-6 bg-slate-900/60 border-t border-slate-800">
        {attachedFiles.length > 0 && (
          <div className="flex space-x-2 mb-4">
            {attachedFiles.map((f, i) => (
              <div key={i} className="relative group">
                <img src={f.url} className="w-12 h-12 rounded-lg border border-cyan-500/30 object-cover" />
                <button onClick={() => setAttachedFiles(prev => prev.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                  <svg className="w-2 h-2 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
          </div>
        )}
        <div className="flex space-x-3 items-center">
          <button onClick={() => fileInputRef.current?.click()} className="p-3 bg-slate-800 hover:bg-slate-700 rounded-xl border border-slate-700 text-slate-400 transition-all">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
          </button>
          <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} accept="image/*,video/*" />

          <button onMouseDown={startRecording} onMouseUp={stopRecording} className={`p-3 rounded-xl border transition-all ${isRecording ? 'bg-red-500 text-white border-red-400 animate-pulse' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
          </button>

          <input 
            value={input} 
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
            placeholder="STIA_TERMINAL_INPUT >" 
            className="flex-grow bg-slate-950/80 border border-slate-800 rounded-xl p-3.5 text-xs text-white mono outline-none focus:border-cyan-500/50" 
          />
          <button onClick={handleSend} disabled={isLoading} className="bg-cyan-600 hover:bg-cyan-500 px-6 py-3.5 rounded-xl shadow-lg shadow-cyan-600/20 active:scale-95 transition-all">
             <svg className="w-5 h-5 text-slate-950" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Coordinates, Satellite, SatelliteStatus, WeatherCondition } from '../types.ts';
import { fetchSatelliteStatusUpdates } from '../services/satelliteService.ts';

interface Props {
  loc: Coordinates;
  sat: Satellite;
  satellites: Satellite[];
  onLocChange: (loc: Coordinates) => void;
  onSatChange: (sat: Satellite) => void;
  onSatellitesUpdate: (sats: Satellite[]) => void;
  isTracking?: boolean;
  onTrackingChange?: (val: boolean) => void;
  isJamming: boolean;
  setIsJamming: (val: boolean) => void;
  jammingPower: number;
  setJammingPower: (val: number) => void;
  weather: WeatherCondition;
  setWeather: (val: WeatherCondition) => void;
  isStealthMode: boolean;
  telemetry: any;
}

interface TacticalEvent {
  id: string;
  timestamp: string;
  satName: string;
  satId: string;
  status: SatelliteStatus;
  detail: string;
}

const EVENT_LOG_STORAGE_KEY = 'satexpert_event_logs';

const StatusBadge: React.FC<{ status?: SatelliteStatus }> = ({ status }) => {
  const config = {
    active: { color: 'bg-green-500', label: 'ONLINE', pulse: true },
    offline: { color: 'bg-red-500', label: 'OFFLINE', pulse: false },
    maintenance: { color: 'bg-amber-500', label: 'MAINT', pulse: true },
    decommissioned: { color: 'bg-slate-600', label: 'EOL', pulse: false },
  }[status || 'active'];

  return (
    <div className="flex items-center space-x-1.5">
      <div className={`w-2 h-2 rounded-full ${config.color} ${config.pulse ? 'status-pulse' : ''}`}></div>
      <span className={`text-[9px] font-bold tracking-widest ${config.color.replace('bg-', 'text-')}`}>
        {config.label}
      </span>
    </div>
  );
};

export const TacticalHUD: React.FC<Props> = ({ 
  loc, sat, satellites, onLocChange, onSatChange, onSatellitesUpdate, isTracking, onTrackingChange,
  isJamming, setIsJamming, jammingPower, setJammingPower,
  weather, setWeather, isStealthMode, telemetry
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [showEventLog, setShowEventLog] = useState(false);
  const [animateLabel, setAnimateLabel] = useState(false);
  const [eventLogs, setEventLogs] = useState<TacticalEvent[]>([]);
  const [hasNewLogs, setHasNewLogs] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const prevSatRef = useRef<{id: string, status?: SatelliteStatus} | null>(null);

  const filteredSatellites = useMemo(() => {
    return satellites.filter(s => 
      s.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      s.orbitalSlot.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [searchQuery, satellites]);

  useEffect(() => {
    const saved = localStorage.getItem(EVENT_LOG_STORAGE_KEY);
    if (saved) {
      try {
        setEventLogs(JSON.parse(saved));
      } catch (e) { console.error("EVENT_LOG_LOAD_ERROR", e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(EVENT_LOG_STORAGE_KEY, JSON.stringify(eventLogs));
  }, [eventLogs]);

  useEffect(() => {
    const pollInterval = setInterval(async () => {
      const updatedSatellites = await fetchSatelliteStatusUpdates();
      onSatellitesUpdate(updatedSatellites);
    }, 15000);
    return () => clearInterval(pollInterval);
  }, [onSatellitesUpdate]);

  useEffect(() => {
    setAnimateLabel(true);
    const timer = setTimeout(() => setAnimateLabel(false), 600);

    if (prevSatRef.current === null) {
      prevSatRef.current = { id: sat.id, status: sat.status };
      return;
    }

    const isSameSat = prevSatRef.current?.id === sat.id;
    const isStatusChanged = prevSatRef.current?.status !== sat.status;

    if (!isSameSat || (isSameSat && isStatusChanged)) {
      const newEvent: TacticalEvent = {
        id: Math.random().toString(36).substr(2, 9),
        timestamp: new Date().toLocaleTimeString(),
        satName: sat.name,
        satId: sat.id,
        status: sat.status || 'active',
        detail: !isSameSat 
          ? `ASSET_ACQUISITION: Targeted ${sat.name} (${sat.orbitalSlot})`
          : `STATUS_CHANGE: Asset ${sat.name} transitioned to ${sat.status?.toUpperCase()}`
      };
      setEventLogs(prev => [newEvent, ...prev].slice(0, 50));
      if (!showEventLog) setHasNewLogs(true);
    }

    prevSatRef.current = { id: sat.id, status: sat.status };
    return () => clearTimeout(timer);
  }, [sat.id, sat.status, showEventLog]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (s: Satellite) => {
    onSatChange(s);
    setSearchQuery('');
    setIsOpen(false);
  };

  const handleExport = () => {
    setIsExporting(true);

    const relevantLogs = eventLogs.filter(log => log.satId === sat.id);

    const exportData = {
      mission_timestamp: new Date().toISOString(),
      security_context: {
        stealth_mode: isStealthMode ? "ACTIVE" : "INACTIVE",
        ew_jamming: isJamming ? `ACTIVE (${jammingPower}%)` : "INACTIVE",
        weather_condition: weather
      },
      asset_specifications: {
        id: sat.id,
        name: sat.name,
        orbital_slot: sat.orbitalSlot,
        operator: sat.operator,
        apogee: sat.apogee,
        perigee: sat.perigee,
        inclination: sat.inclination,
        velocity: sat.velocity,
        status: sat.status
      },
      live_telemetry: telemetry,
      ground_station: loc,
      event_history: relevantLogs
    };

    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `STIA_DATA_BRIEF_${sat.name.replace(/\s+/g, '_')}_${new Date().getTime()}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    setTimeout(() => setIsExporting(false), 2000);
  };

  const weatherIcons = {
    CLEAR: '☀️',
    OVERCAST: '☁️',
    LIGHT_RAIN: '🌧️',
    HEAVY_STORM: '⛈️'
  };

  return (
    <div className="glass rounded-2xl p-6 border-slate-800 relative z-50 overflow-hidden">
      <div className="absolute top-0 left-0 w-1 h-full bg-cyan-500/20"></div>

      <div className="space-y-6">
        <div className="relative" ref={dropdownRef}>
          <div className="flex items-center justify-between mb-3 px-1">
            <div className="flex flex-col">
              <label className={`block text-[11px] font-bold uppercase tracking-[0.2em] transition-all duration-300 transform ${
                animateLabel 
                  ? 'text-cyan-400 scale-105' 
                  : 'text-white'
              }`}>
                Target Acquisition
              </label>
              <div className="card-header-line"></div>
            </div>
            <div className="flex items-center space-x-2">
              <button 
                onClick={() => { setShowEventLog(true); setHasNewLogs(false); }}
                className="relative flex items-center space-x-1.5 px-3 py-1.5 rounded-lg border border-slate-800 bg-slate-900 text-[9px] font-bold text-slate-400 hover:text-cyan-400 hover:border-cyan-500/30 transition-all uppercase tracking-widest"
              >
                <span>Mission Logs</span>
                {hasNewLogs && <div className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full animate-pulse border border-slate-900"></div>}
              </button>
            </div>
          </div>

          <div className="relative">
            <input
              type="text"
              placeholder={isOpen ? "ENTER SATELLITE NAME OR SLOT..." : sat.name}
              className={`w-full bg-slate-950/80 border ${isOpen ? 'border-cyan-500 shadow-[0_0_15px_rgba(34,211,238,0.2)]' : 'border-slate-800'} rounded-xl p-3 pl-10 text-xs text-white outline-none transition-all mono placeholder:text-slate-700`}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setIsOpen(true);
              }}
              onFocus={() => setIsOpen(true)}
            />
            <div className="absolute left-3.5 top-1/2 -translate-y-1/2">
              <svg className={`w-4.5 h-4.5 ${isOpen ? 'text-cyan-400' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
            <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center">
               {!isOpen && <StatusBadge status={sat.status} />}
            </div>
          </div>

          {isOpen && (
            <div className="absolute mt-2 w-full glass bg-slate-950 border border-cyan-500/40 rounded-xl shadow-2xl overflow-hidden max-h-[300px] flex flex-col z-[100]">
              <div className="bg-cyan-500/10 px-4 py-2 border-b border-slate-800">
                <span className="text-[9px] font-bold text-cyan-400 uppercase tracking-widest">Asset Registry</span>
              </div>
              <div className="overflow-y-auto py-1 scrollbar-hide">
                {filteredSatellites.map((s) => (
                  <button
                    key={s.id}
                    onClick={() => handleSelect(s)}
                    className={`w-full text-left px-4 py-3 hover:bg-white/5 transition-colors flex items-center justify-between border-b border-slate-900/50 last:border-none ${s.id === sat.id ? 'bg-cyan-500/5' : ''}`}
                  >
                    <div className="flex flex-col">
                      <span className={`text-[11px] font-bold ${s.id === sat.id ? 'text-cyan-400' : 'text-slate-200'}`}>{s.name}</span>
                      <span className="text-[9px] text-slate-500 mono">{s.operator}</span>
                    </div>
                    <span className="text-[10px] text-cyan-500 font-mono font-bold">{s.orbitalSlot}</span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div className="bg-slate-950/40 rounded-xl border border-slate-800 p-3 flex flex-col">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Authority</span>
            <span className="text-[10px] font-bold text-slate-200 mono truncate">{sat.operator || 'UNSPECIFIED'}</span>
          </div>
          <div className="bg-slate-950/40 rounded-xl border border-slate-800 p-3 flex flex-col items-end text-right">
            <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mb-1">Slot Index</span>
            <span className="text-[10px] font-bold text-cyan-400 mono">{sat.orbitalSlot}</span>
          </div>
        </div>

        <div className="bg-slate-950/40 rounded-xl border border-slate-800 p-4 space-y-4">
          <div className="flex items-center justify-between">
             <span className="text-[9px] font-black text-white uppercase tracking-widest">Atmospheric Environment</span>
             <span className="text-[8px] text-slate-500 font-bold uppercase mono">Ka-Band Simulation</span>
          </div>
          <div className="grid grid-cols-4 gap-2">
            {(['CLEAR', 'OVERCAST', 'LIGHT_RAIN', 'HEAVY_STORM'] as WeatherCondition[]).map((cond) => (
              <button 
                key={cond}
                onClick={() => setWeather(cond)}
                disabled={isStealthMode}
                className={`flex flex-col items-center justify-center p-2 rounded-xl border transition-all duration-200 ${
                  isStealthMode ? 'opacity-30' : ''
                } ${
                  weather === cond 
                    ? 'bg-cyan-500/20 border-cyan-500/60 text-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.1)]' 
                    : 'bg-slate-900 border-slate-800 text-slate-600 hover:border-slate-600'
                }`}
              >
                <span className="text-lg mb-1">{weatherIcons[cond]}</span>
                <span className="text-[7px] font-bold uppercase tracking-tighter text-center">{cond.replace('_', ' ')}</span>
              </button>
            ))}
          </div>
        </div>

        <div className={`rounded-xl border p-4 space-y-4 transition-all duration-500 ${isStealthMode ? 'bg-purple-900/10 border-purple-500/30' : (isJamming ? 'bg-red-900/10 border-red-500/30 shadow-[0_0_20px_rgba(239,68,68,0.05)]' : 'bg-slate-950/40 border-slate-800')}`}>
          <div className="flex items-center justify-between">
            <div className="flex flex-col">
              <span className={`text-[10px] font-black uppercase tracking-widest ${isStealthMode ? 'text-purple-400' : (isJamming ? 'text-red-500' : 'text-white')}`}>Electronic Warfare</span>
              <span className="text-[8px] text-slate-500 font-bold uppercase mono">Mode: Continuous Wave</span>
            </div>
            <button 
              onClick={() => setIsJamming(!isJamming)}
              disabled={isStealthMode}
              className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all duration-300 ${
                isStealthMode ? 'bg-slate-800 text-slate-500' : (isJamming ? 'bg-red-600 text-white shadow-lg animate-pulse' : 'bg-slate-800 text-slate-400 hover:text-white')
              }`}
            >
              {isStealthMode ? 'Stealth' : (isJamming ? 'Engaged' : 'Standby')}
            </button>
          </div>
        </div>

        <div className="pt-2">
          <button 
            onClick={handleExport}
            disabled={isExporting}
            className={`w-full flex items-center justify-center space-x-3 py-4 rounded-2xl border-2 transition-all active:scale-[0.98] ${isExporting ? 'bg-green-500/20 border-green-500 text-green-400' : 'bg-cyan-600/10 border-cyan-500/50 text-cyan-400 hover:bg-cyan-500/20 hover:border-cyan-400 shadow-lg shadow-cyan-500/10'}`}
          >
            <svg className={`w-5 h-5 ${isExporting ? 'animate-bounce' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            <span className="text-[11px] font-black uppercase tracking-[0.2em]">{isExporting ? 'COMPILING_BRIEF...' : 'DOWNLOAD TACTICAL BRIEF'}</span>
          </button>
        </div>
      </div>

      {showEventLog && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="glass w-full max-w-lg rounded-3xl border border-slate-700 shadow-2xl flex flex-col max-h-[75vh] overflow-hidden">
            <div className="p-6 border-b border-slate-800 flex items-center justify-between bg-slate-900/40">
               <div>
                  <h3 className="text-sm font-black text-white uppercase tracking-[0.2em] flex items-center">
                    <span className="w-2 h-2 bg-cyan-500 rounded-full mr-3 status-pulse"></span>
                    Mission Asset History
                  </h3>
                  <p className="text-[9px] text-slate-500 font-bold tracking-widest mt-1">Tactical Audit Log // Sector Alpha</p>
               </div>
               <button 
                onClick={() => setShowEventLog(false)}
                className="p-2 hover:bg-white/5 rounded-full transition-colors"
               >
                 <svg className="w-6 h-6 text-slate-500 hover:text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
               </button>
            </div>

            <div className="flex-grow overflow-y-auto p-4 space-y-3 bg-slate-950/20">
              {eventLogs.length > 0 ? (
                eventLogs.map((log) => (
                  <div key={log.id} className="p-4 bg-slate-900/40 rounded-xl border border-slate-800/60 flex items-start space-x-4 group hover:border-cyan-500/30 transition-all">
                    <div className="pt-1"><StatusBadge status={log.status} /></div>
                    <div className="flex-grow">
                       <div className="flex items-center justify-between mb-1.5">
                          <span className="text-[11px] font-black text-white mono">{log.satName}</span>
                          <span className="text-[8px] text-slate-600 font-bold mono">{log.timestamp}</span>
                       </div>
                       <p className="text-[12px] text-slate-400 leading-relaxed mono">{log.detail}</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center py-24 text-center">
                   <p className="text-[11px] font-bold text-slate-600 uppercase tracking-widest">No Tactical Logs On File</p>
                </div>
              )}
            </div>

            <div className="p-5 border-t border-slate-800 bg-slate-900/60 flex justify-end space-x-4">
               <button onClick={() => setShowEventLog(false)} className="px-6 py-2.5 bg-cyan-600 hover:bg-cyan-500 rounded-xl text-[10px] font-black uppercase tracking-widest text-slate-950 transition-all active:scale-95 shadow-lg shadow-cyan-500/20">Acknowledge</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import * as React from 'react';
import { useState, useRef, useEffect } from 'react';
import { getTroubleshootingAdvice, transcribeAudio } from '../services/geminiService.ts';
import { TroubleshootingLog } from '../types.ts';

interface TelemetryData {
  snr: string;
  rxPower: string;
  bucTemp: string;
  packetLoss: string;
  status: string;
}

interface Props {
  context: any;
  telemetry: TelemetryData;
  isStealthMode: boolean;
}

interface Overrides {
  snr: string | null;
  rxPower: string | null;
  bucTemp: string | null;
  packetLoss: string | null;
}

export const AITechnician: React.FC<Props> = ({ context, telemetry, isStealthMode }) => {
  const [messages, setMessages] = useState<TroubleshootingLog[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isThinking, setIsThinking] = useState(false);
  const [useSearch, setUseSearch] = useState(true);
  const [isRecording, setIsRecording] = useState(false);
  const [attachedFiles, setAttachedFiles] = useState<{data: string, mimeType: string, url: string}[]>([]);
  const [showOverrides, setShowOverrides] = useState(false);
  const [overrides, setOverrides] = useState<Overrides>({
    snr: null,
    rxPower: null,
    bucTemp: null,
    packetLoss: null
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const audioChunksRef = useRef<Int16Array[]>([]);

  useEffect(() => {
    const initialGreeting = { 
      role: 'assistant', 
      content: `[SYSTEM_READY] STIA-Agent Active.\n${isStealthMode ? 'PROTOCOL: STEALTH_MODE_ACTIVE\n' : ''}INTELLIGENCE_POSTURE: ${isThinking ? 'MAX_THINK' : 'FAST_RESPONSE'}\nDEFCON: ${context.defcon || 5}\n\nAwaiting tactical directives. Grounding: ${useSearch ? 'LIVE_SEARCH_ACTIVE' : 'LOCAL_CACHE_ONLY'}.`, 
      timestamp: new Date() 
    };
    setMessages([initialGreeting]);
  }, [isStealthMode, context.defcon, isThinking]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, isLoading]);

  const handleDownloadLog = () => {
    const header = `--- STIA SESSION LOG | ${new Date().toLocaleString()} ---\n` +
      `ASSET: ${context.satName || 'Unknown'}\n` +
      `ENVIRONMENT: ${JSON.stringify({ ...context, telemetry }, null, 2)}\n` +
      `--------------------------------------------------\n\n`;

    const body = messages.map(m => `[${m.timestamp.toLocaleTimeString()}] ${m.role.toUpperCase()}: ${m.content}`).join('\n\n');

    const blob = new Blob([header + body], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `STIA_SESSION_${new Date().getTime()}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    (Array.from(files) as File[]).forEach(file => {
      const reader = new FileReader();
      reader.onload = (rev) => {
        const base64 = (rev.target?.result as string).split(',')[1];
        setAttachedFiles(prev => [...prev, {
          data: base64,
          mimeType: file.type,
          url: URL.createObjectURL(file)
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContextRef.current = new AudioContext({ sampleRate: 16000 });
      const source = audioContextRef.current.createMediaStreamSource(stream);
      scriptProcessorRef.current = audioContextRef.current.createScriptProcessor(4096, 1, 1);

      audioChunksRef.current = [];
      scriptProcessorRef.current.onaudioprocess = (e) => {
        const inputData = e.inputBuffer.getChannelData(0);
        const pcm16 = new Int16Array(inputData.length);
        for (let i = 0; i < inputData.length; i++) {
          pcm16[i] = Math.max(-1, Math.min(1, inputData[i])) * 32767;
        }
        audioChunksRef.current.push(pcm16);
      };

      source.connect(scriptProcessorRef.current);
      scriptProcessorRef.current.connect(audioContextRef.current.destination);
      setIsRecording(true);
    } catch (err) {
      console.error("MIC_ERROR", err);
    }
  };

  const stopRecording = async () => {
    if (!scriptProcessorRef.current) return;
    scriptProcessorRef.current.disconnect();
    setIsRecording(false);

    const totalLength = audioChunksRef.current.reduce((acc, chunk) => acc + chunk.length, 0);
    const result = new Int16Array(totalLength);
    let offset = 0;
    audioChunksRef.current.forEach(chunk => {
      result.set(chunk, offset);
      offset += chunk.length;
    });

    const binary = String.fromCharCode(...new Uint8Array(result.buffer));
    const base64 = btoa(binary);

    setIsLoading(true);
    const transcription = await transcribeAudio(base64);
    setInput(prev => (prev ? prev + " " : "") + transcription);
    setIsLoading(false);
  };

  const handleSend = async () => {
    if (!input.trim() && attachedFiles.length === 0) return;
    if (isLoading) return;

    const userMessage: TroubleshootingLog = { 
      role: 'user', 
      content: input, 
      timestamp: new Date(),
      imageUrl: attachedFiles[0]?.url 
    };
    setMessages(prev => [...prev, userMessage]);
    const currentInput = input;
    const currentFiles = attachedFiles;

    setInput('');
    setAttachedFiles([]);
    setIsLoading(true);

    const activeTelemetry = {
      ...telemetry,
      snr: overrides.snr ?? telemetry.snr,
      rxPower: overrides.rxPower ?? telemetry.rxPower,
      bucTemp: overrides.bucTemp ?? telemetry.bucTemp,
      packetLoss: overrides.packetLoss ?? telemetry.packetLoss,
      isManualOverride: Object.values(overrides).some(v => v !== null)
    };

    const advice = await getTroubleshootingAdvice(currentInput, { ...context, isStealthMode }, activeTelemetry, {
      thinking: isThinking,
      useSearch: useSearch,
      useMaps: true,
      mediaData: currentFiles.map(f => ({ data: f.data, mimeType: f.mimeType }))
    });

    const assistantMessage: TroubleshootingLog = { 
      role: 'assistant', 
      content: advice || 'COMM_FAILURE: Satellite link timed out.', 
      timestamp: new Date(),
      isCode: advice?.includes('```') 
    };

    setMessages(prev => [...prev, assistantMessage]);
    setIsLoading(false);
  };

  const updateOverride = (key: keyof Overrides, value: string) => {
    setOverrides(prev => ({
      ...prev,
      [key]: value === '' ? null : value
    }));
  };

  const isOverrideActive = Object.values(overrides).some(v => v !== null);

  return (
    <div className="glass rounded-[2rem] border-slate-800 flex flex-col h-full overflow-hidden bg-slate-950/40 relative">
      <div className="p-6 border-b border-slate-800 bg-slate-900/60 z-20">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div className="flex items-center space-x-4">
             <div className="w-12 h-12 bg-cyan-500/10 rounded-2xl flex items-center justify-center border border-cyan-500/20">
                <svg className="w-6 h-6 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
             </div>
             <div>
                <h3 className="text-sm font-black text-white uppercase tracking-widest">STIA_SENTINEL_V6</h3>
                <div className="flex items-center space-x-2 mt-0.5">
                  <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">Multi-Modal Recon</span>
                  {isOverrideActive && <span className="text-[8px] px-1.5 py-0.5 bg-amber-500/10 text-amber-500 border border-amber-500/30 rounded font-black animate-pulse">OVERRIDE_ON</span>}
                </div>
             </div>
          </div>
          <div className="flex items-center space-x-2 overflow-x-auto pb-1 md:pb-0 scrollbar-hide">
             <button 
                onClick={handleDownloadLog}
                className="flex items-center space-x-2 px-3 py-1.5 rounded-lg border border-slate-700 bg-slate-800 text-[9px] font-black text-white uppercase tracking-widest hover:bg-slate-700 hover:border-cyan-500/50 transition-all shadow-lg"
              >
                <svg className="w-3.5 h-3.5 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                <span>EXPORT_LOG</span>
             </button>
             <button 
                onClick={() => setShowOverrides(!showOverrides)} 
                className={`p-2 rounded-lg border transition-all ${showOverrides ? 'bg-amber-500/20 border-amber-500/50 text-amber-400' : 'bg-slate-800 border-slate-700 text-slate-500 hover:text-slate-300'}`}
                title="Manual Telemetry Injection"
              >
               <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" /></svg>
             </button>
             <button onClick={() => setIsThinking(!isThinking)} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all whitespace-nowrap ${isThinking ? 'bg-amber-500 text-slate-950 shadow-[0_0_15px_rgba(245,158,11,0.3)]' : 'bg-slate-800 text-slate-500'}`}>Deep_Think</button>
             <button onClick={() => setUseSearch(!useSearch)} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all whitespace-nowrap ${useSearch ? 'bg-cyan-500 text-slate-950 shadow-[0_0_15px_rgba(34,211,238,0.3)]' : 'bg-slate-800 text-slate-500'}`}>Grounding</button>
          </div>
        </div>

        {showOverrides && (
          <div className="mt-4 grid grid-cols-2 md:grid-cols-4 gap-3 p-4 bg-slate-950/80 rounded-2xl border border-amber-500/30 animate-in slide-in-from-top-2 duration-300">
            <div className="space-y-1.5">
              <label className="block text-[8px] font-black text-slate-500 uppercase tracking-widest">Injected_SNR</label>
              <input 
                type="text" 
                placeholder={telemetry.snr}
                value={overrides.snr ?? ''}
                onChange={e => updateOverride('snr', e.target.value)}
                className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-[10px] text-amber-400 mono outline-none focus:border-amber-500/50"
              />
            </div>
            <div className="space-y-1.5">
              <label className="block text-[8px] font-black text-slate-500 uppercase tracking-widest">Injected_Power</label>
              <input 
                type="text" 
                placeholder={telemetry.rxPower}
                value={overrides.rxPower ?? ''}
                onChange={e => updateOverride('rxPower', e.target.value)}
                className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-[10px] text-amber-400 mono outline-none focus:border-amber-500/50"
              />
            </div>
            <div className="space-y-1.5">
              <label className="block text-[8px] font-black text-slate-500 uppercase tracking-widest">Injected_Temp</label>
              <input 
                type="text" 
                placeholder={telemetry.bucTemp}
                value={overrides.bucTemp ?? ''}
                onChange={e => updateOverride('bucTemp', e.target.value)}
                className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-[10px] text-amber-400 mono outline-none focus:border-amber-500/50"
              />
            </div>
            <div className="space-y-1.5">
              <label className="block text-[8px] font-black text-slate-500 uppercase tracking-widest">Injected_Loss</label>
              <input 
                type="text" 
                placeholder={telemetry.packetLoss}
                value={overrides.packetLoss ?? ''}
                onChange={e => updateOverride('packetLoss', e.target.value)}
                className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-[10px] text-amber-400 mono outline-none focus:border-amber-500/50"
              />
            </div>
            <div className="col-span-full flex justify-end">
              <button 
                onClick={() => setOverrides({ snr: null, rxPower: null, bucTemp: null, packetLoss: null })}
                className="text-[8px] font-bold text-slate-500 hover:text-amber-500 uppercase tracking-widest underline underline-offset-4 decoration-slate-800"
              >
                Clear_All_Overrides
              </button>
            </div>
          </div>
        )}
      </div>

      <div ref={scrollRef} className="flex-grow overflow-y-auto p-6 space-y-6 scrollbar-hide">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-5 rounded-3xl border ${m.role === 'user' ? 'bg-cyan-950/30 border-cyan-500/30 rounded-br-none' : 'bg-slate-900 border-slate-800 rounded-bl-none'}`}>
              {m.imageUrl && <img src={m.imageUrl} className="max-w-xs rounded-xl mb-4 border border-slate-700 shadow-lg" />}
              <div className="text-[13px] text-slate-200 mono leading-relaxed whitespace-pre-wrap">{m.content}</div>
              <div className="text-[8px] text-slate-600 font-bold mt-4 uppercase tracking-widest flex justify-between">
                 <span>{m.role === 'user' ? 'USER_UPLINK' : 'AGENT_RECON'}</span>
                 <span>{m.timestamp.toLocaleTimeString([], { hour12: false })}</span>
              </div>
            </div>
          </div>
        ))}
        {isLoading && <div className="flex justify-start"><div className="bg-slate-900 p-4 rounded-2xl rounded-bl-none border border-slate-800 text-[10px] text-cyan-500 font-black uppercase tracking-widest animate-pulse">Processing_Intel_Stream...</div></div>}
      </div>

      <div className="p-6 bg-slate-900/60 border-t border-slate-800">
        {attachedFiles.length > 0 && (
          <div className="flex space-x-2 mb-4">
            {attachedFiles.map((f, i) => (
              <div key={i} className="relative group">
                <img src={f.url} className="w-12 h-12 rounded-lg border border-cyan-500/30 object-cover" />
                <button onClick={() => setAttachedFiles(prev => prev.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                  <svg className="w-2 h-2 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
          </div>
        )}
        <div className="flex space-x-3 items-center">
          <button onClick={() => fileInputRef.current?.click()} className="p-3 bg-slate-800 hover:bg-slate-700 rounded-xl border border-slate-700 text-slate-400 transition-all">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
          </button>
          <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} accept="image/*,video/*" />

          <button onMouseDown={startRecording} onMouseUp={stopRecording} className={`p-3 rounded-xl border transition-all ${isRecording ? 'bg-red-500 text-white border-red-400 animate-pulse' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
          </button>

          <input 
            value={input} 
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
            placeholder="STIA_TERMINAL_INPUT >" 
            className="flex-grow bg-slate-950/80 border border-slate-800 rounded-xl p-3.5 text-xs text-white mono outline-none focus:border-cyan-500/50" 
          />
          <button onClick={handleSend} disabled={isLoading} className="bg-cyan-600 hover:bg-cyan-500 px-6 py-3.5 rounded-xl shadow-lg shadow-cyan-600/20 active:scale-95 transition-all">
             <svg className="w-5 h-5 text-slate-950" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

