    const blob = new Blob([data], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `LINK_BUDGET_${new Date().getTime()}.txt`;
    link.click();
