                            <button onClick={toggleHupScrambler} disabled={isStealthMode} className={`relative w-12 h-6 rounded-full transition-all duration-300 ${hupScramblerActive || isStealthMode ? 'bg-cyan-600' : 'bg-slate-700'}`}>
                                <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform duration-300 transform ${hupScramblerActive || isStealthMode ? 'translate-x-6' : 'translate-x-0'}`}></div>
