import * as React from 'react';
import { useState, useEffect, useRef } from 'react';
import { playSystemVoice } from '../services/audioService.ts';

type QKDStatus = 'SYNCHRONIZED' | 'SYNCING' | 'DECOHERENCE_ERROR' | 'EAVESDROP_DETECTED';
interface QuantumEvent {
  id: string;
  timestamp: string;
  type: 'QKD' | 'HUP' | 'TUNNEL' | 'SYSTEM';
  severity: 'NOMINAL' | 'WARNING' | 'CRITICAL';
  message: string;
}

const statusConfig = {
    SYNCHRONIZED: { label: 'SYNCHRONIZED', color: 'text-cyan-400', pulse: true },
    SYNCING: { label: 'SYNCING...', color: 'text-amber-400', pulse: true },
    DECOHERENCE_ERROR: { label: 'DECOHERENCE ERROR', color: 'text-orange-500', pulse: false },
    EAVESDROP_DETECTED: { label: 'EAVESDROPPING DETECTED!', color: 'text-red-500', pulse: true },
};

interface Props {
  isStealthMode: boolean;
  addMissionLog: (detail: string, status: any) => void;
}

export const QuantumDefense: React.FC<Props> = ({ isStealthMode, addMissionLog }) => {
    const [qkdStatus, setQkdStatus] = useState<QKDStatus>('SYNCHRONIZED');
    const [hupScramblerActive, setHupScramblerActive] = useState(false);
    const [entanglementTunnelActive, setEntanglementTunnelActive] = useState(false);
    const [eventLog, setEventLog] = useState<QuantumEvent[]>([]);
    const [syncPhase, setSyncPhase] = useState<string | null>(null);
    const breachTriggeredRef = useRef(false);

    // Force SYNCHRONIZED status if Stealth Mode is active
    const effectiveQkdStatus = isStealthMode ? 'SYNCHRONIZED' : qkdStatus;
    const isCritical = effectiveQkdStatus === 'EAVESDROP_DETECTED';

    const addLocalLog = (type: QuantumEvent['type'], severity: QuantumEvent['severity'], message: string) => {
        const newEvent: QuantumEvent = {
            id: `qe-${Date.now()}-${Math.random()}`,
            timestamp: new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' }),
            type,
            severity,
            message,
        };
        setEventLog(prev => [newEvent, ...prev].slice(0, 50));
    };

    const handleQkdSync = (forceBreach = false) => {
        if (effectiveQkdStatus === 'SYNCING' || isStealthMode) return;

        breachTriggeredRef.current = false;
        setQkdStatus('SYNCING');
        setSyncPhase('PHASE_1: PHOTON_EMISSION');
        addLocalLog('QKD', 'NOMINAL', 'Photon stream initiated for key exchange.');
        playSystemVoice('Initiating quantum key exchange.');

        // Stage 2: Parity Check (Detection point)
        setTimeout(() => {
            if (forceBreach) {
                setQkdStatus('EAVESDROP_DETECTED');
                setSyncPhase('PHASE_2: PARITY_FAILURE [COLLAPSE]');
                breachTriggeredRef.current = true;

                const breachMsg = 'QUANTUM_BREACH: Photon state collapse detected during parity check. External measurement detected on link path!';
                addLocalLog('QKD', 'CRITICAL', breachMsg);

                // DISPATCH TO GLOBAL MISSION LOG
                addMissionLog(`CRITICAL: Eavesdropping attempt detected on Quantum Channel. Polarization error > 25%.`, 'BREACH');
                playSystemVoice('Critical alert. Measurement attempt detected on quantum channel. Encryption integrity compromised.');
            } else {
                setSyncPhase('PHASE_2: PARITY_CHECK');
                addLocalLog('QKD', 'NOMINAL', 'Executing Bell-state measurement on inbound pulse.');
            }
        }, 1200);

        // Stage 3: Verification
        setTimeout(() => {
            if (!breachTriggeredRef.current) {
                setSyncPhase('PHASE_3: VERIFICATION');
                addLocalLog('QKD', 'NOMINAL', 'Validating entanglement coefficients...');
            }
        }, 2400);

        // Final Outcome
        setTimeout(() => {
            setSyncPhase(null);
            if (breachTriggeredRef.current) return;

            const outcome = Math.random();
            if (outcome < 0.8) {
                setQkdStatus('SYNCHRONIZED');
                addLocalLog('QKD', 'NOMINAL', 'Key synchronization successful. Entanglement verified.');
            } else {
                setQkdStatus('DECOHERENCE_ERROR');
                addLocalLog('QKD', 'WARNING', 'Decoherence threshold exceeded due to atmospheric turbulence.');
            }
        }, 3600);
    };

    const toggleHupScrambler = () => {
        const newState = !hupScramblerActive;
        setHupScramblerActive(newState);
        addLocalLog('HUP', 'NOMINAL', `Heisenberg Uncertainty Protocol ${newState ? 'ENGAGED' : 'DISENGAGED'}.`);
        playSystemVoice(`Uncertainty scrambler ${newState ? 'active' : 'inactive'}.`);
    };

    const toggleEntanglementTunnel = () => {
        const newState = !entanglementTunnelActive;
        setEntanglementTunnelActive(newState);
        if (newState) {
            addLocalLog('TUNNEL', 'NOMINAL', 'Establishing FTL entanglement data tunnel...');
            setTimeout(() => addLocalLog('TUNNEL', 'NOMINAL', 'Tunnel established. Non-local data parity confirmed.'), 1500);
        } else {
            addLocalLog('TUNNEL', 'NOMINAL', 'Collapsing entanglement tunnel.');
        }
        playSystemVoice(`Entanglement tunnel ${newState ? 'engaged' : 'disengaged'}.`);
    };

    return (
        <div className={`grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4 duration-700 ${isCritical ? 'breach-active' : ''}`}>
            {/* LEFT COLUMN */}
            <div className="lg:col-span-1 space-y-6">
                <div className={`glass p-6 rounded-2xl border transition-all duration-500 ${isCritical ? 'border-red-500 shadow-[0_0_30px_rgba(239,68,68,0.3)] bg-red-950/20' : 'border-slate-800'}`}>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-white mb-4">Quantum Core Monitor</h3>
                    <div className="flex flex-col items-center justify-center space-y-6 py-4">
                        <div className={`text-center font-black mono text-xl uppercase transition-colors ${statusConfig[effectiveQkdStatus].color} ${statusConfig[effectiveQkdStatus].pulse ? 'animate-pulse' : ''}`}>
                           {statusConfig[effectiveQkdStatus].label}
                        </div>

                        {syncPhase && (
                            <div className="w-full space-y-2">
                                <div className="flex justify-between text-[8px] font-black text-amber-500 mono animate-pulse">
                                    <span>{syncPhase}</span>
                                </div>
                                <div className="w-full h-1 bg-slate-900 rounded-full overflow-hidden">
                                    <div className="h-full bg-amber-500 animate-quantum-progress"></div>
                                </div>
                            </div>
                        )}

                        <p className="text-[9px] text-slate-500 text-center mono max-w-xs italic leading-relaxed">
                           Photon polarization mapping ensures 100% data integrity. Waveform collapse detected at junction point alpha-6.
                        </p>
                    </div>
                </div>

                <div className="glass p-6 rounded-2xl border border-slate-800 space-y-3">
                    <h3 className="text-sm font-bold uppercase tracking-widest text-white mb-1">Key Exchange Controls</h3>
                    <button 
                        onClick={() => handleQkdSync()} 
                        disabled={effectiveQkdStatus === 'SYNCING' || isStealthMode}
                        className="w-full bg-cyan-600 hover:bg-cyan-500 disabled:opacity-30 text-slate-950 font-black py-4 rounded-xl uppercase tracking-widest text-xs shadow-lg shadow-cyan-500/10 transition-all active:scale-95"
                    >
                        {effectiveQkdStatus === 'SYNCING' ? 'Transmitting Photons...' : isStealthMode ? 'GHOST_PROTO_ACTIVE' : 'Initiate QKD Sync'}
                    </button>

                    {!isStealthMode && (
                        <button 
                            onClick={() => handleQkdSync(true)}
                            disabled={effectiveQkdStatus === 'SYNCING'}
                            className="w-full border border-red-500/30 bg-red-600/10 hover:bg-red-600/20 text-red-500 font-black py-2 rounded-xl uppercase tracking-widest text-[9px] transition-all"
                        >
                            Simulate Security Breach
                        </button>
                    )}
                </div>
            </div>

            {/* MIDDLE COLUMN */}
            <div className="lg:col-span-1 space-y-6">
                <div className="glass p-6 rounded-2xl border border-slate-800">
                    <h3 className="text-sm font-bold uppercase tracking-widest text-white mb-6">Quantum Countermeasures</h3>
                    <div className="space-y-4">
                        <div className={`p-5 rounded-2xl flex items-center justify-between transition-all border ${hupScramblerActive || isStealthMode ? 'bg-cyan-500/10 border-cyan-500/30' : 'bg-slate-900/50 border-slate-800'}`}>
                            <div>
                                <h4 className={`text-[10px] font-black uppercase tracking-widest ${hupScramblerActive ? 'text-cyan-400' : 'text-slate-200'}`}>Heisenberg Scrambler</h4>
